    # ---------- UNDO / REDO ----------

    def _capture_edit_snapshot(self) -> dict:
        """Captura únicamente el estado editable que todavía puede revertirse.

        No copiamos el guardado binario: los cambios sobre Pokémon se representan en
        ``pending_changes`` y la previsualización se reconstruye a partir del save base.
        Los contadores y preferencias de Run que sí se persisten al instante se incluyen
        para que Ctrl+Z también pueda devolverlas a su valor anterior.

        **Ninguna mitad de un cobro puede viajar sola.** `counters` estaba aquí y
        `saved_drafts` no, así que guardar una tirada costaba un drafteo y Ctrl+Z
        devolvía el contador **dejando el movimiento en MOVIMIENTOS**: drafteos
        infinitos, repetible sin límite. Lo mismo con `pending_faints` y
        `graveyard_pokemon`, que son la contrapartida de las vidas.
        """
        project = self.project
        return {
            "pending_changes": copy.deepcopy(self.run.pending_changes),
            "role_rules_activation_pending": bool(self.run.role_rules_activation_pending),
            "counters": copy.deepcopy(project.counters) if project else {},
            "saved_drafts": copy.deepcopy(project.saved_drafts) if project else [],
            "pending_faints": copy.deepcopy(project.pending_faints) if project else [],
            "graveyard_pokemon": copy.deepcopy(project.graveyard_pokemon) if project else [],
            "role_overrides": copy.deepcopy(project.role_overrides) if project else {},
            "managed_pokemon_roles": copy.deepcopy(project.managed_pokemon_roles) if project else {},
            "hidden_roles": copy.deepcopy(project.hidden_roles) if project else {},
            "role_rules_active": bool(project.role_rules_active) if project else False,
        }

    def _asumir_estado_del_juego(self) -> None:
        """Da por bueno el estado actual sin convertirlo en un paso deshacible.

        Ctrl+Z deshace **lo que hizo el usuario**. Una muerte detectada en la
        partida o una medalla que el juego acaba de conceder no son decisiones
        suyas, y sin esto entraban en la pila igual: el primer Ctrl+Z que
        pulsara después —para deshacer cualquier otra cosa— le devolvía la vida
        y dejaba la baja registrada pidiendo sustituto, con su evento en el
        historial diciendo 4→3. La contradicción se escribía en disco.

        No se vacía la pila: los pasos legítimos anteriores siguen ahí. Solo se
        mueve el punto de referencia, para que el siguiente cambio se compare
        contra lo que hay ahora.
        """
        self._edit_last_snapshot = self._capture_edit_snapshot()

    def _reset_edit_history(self) -> None:
        self._edit_undo_stack.clear()
        self._edit_redo_stack.clear()
        self._edit_last_snapshot = self._capture_edit_snapshot()

    def _record_edit_transition(self) -> None:
        """Registra un único paso si el estado editable cambió desde el último punto.

        Esta comparación permite que acciones compuestas (por ejemplo confirmar un
        drafteo = movimiento pendiente + -1 drafteo) formen UN solo Ctrl+Z.
        """
        current = self._capture_edit_snapshot()
        if self._restoring_edit_snapshot:
            self._edit_last_snapshot = current
            return
        previous = self._edit_last_snapshot
        if previous is None:
            self._edit_last_snapshot = current
            return
        if current == previous:
            return
        self._edit_undo_stack.append(copy.deepcopy(previous))
        if len(self._edit_undo_stack) > 100:
            del self._edit_undo_stack[:-100]
        self._edit_redo_stack.clear()
        self._edit_last_snapshot = current

    def _restore_edit_snapshot(self, snapshot: dict) -> None:
        if not self.project:
            return
        self._restoring_edit_snapshot = True
        try:
            self.run.pending_changes = copy.deepcopy(snapshot.get("pending_changes", []))
            self.run.role_rules_activation_pending = bool(snapshot.get("role_rules_activation_pending", False))
            self.project.counters = copy.deepcopy(snapshot.get("counters", self.project.counters))
            self.project.saved_drafts = copy.deepcopy(
                snapshot.get("saved_drafts", self.project.saved_drafts))
            self.project.pending_faints = copy.deepcopy(
                snapshot.get("pending_faints", self.project.pending_faints))
            self.project.graveyard_pokemon = copy.deepcopy(
                snapshot.get("graveyard_pokemon", self.project.graveyard_pokemon))
            self.project.role_overrides = copy.deepcopy(snapshot.get("role_overrides", self.project.role_overrides))
            self.project.managed_pokemon_roles = copy.deepcopy(snapshot.get("managed_pokemon_roles", self.project.managed_pokemon_roles))
            self.project.hidden_roles = copy.deepcopy(snapshot.get("hidden_roles", self.project.hidden_roles))
            self.project.role_rules_active = bool(snapshot.get("role_rules_active", self.project.role_rules_active))
            self.project_service.save(self.project)

            # Relee el save base y vuelve a proyectar solo las decisiones restauradas.
            # Así deshacer un cambio Equipo↔PC, rol, MT o drafteo nunca depende del
            # objeto SavePokemon que estuviera vivo antes del Ctrl+Z.
            if self.current_save:
                try:
                    self._reload_preview_from_saved_state()
                except Exception:
                    pass
            self._pc_cache = None
            self._pc_cache_signature = None
            self._sync_live_layout(refresh_floating=True)
            self._edit_last_snapshot = self._capture_edit_snapshot()
            self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
        finally:
            self._restoring_edit_snapshot = False
            self._edit_last_snapshot = self._capture_edit_snapshot()

    def _on_undo_shortcut(self, _event=None):
        if self._capturing_hotkey_action or not self.project:
            return None
        # Captura cualquier cambio localizado que no haya requerido render completo.
        self._record_edit_transition()
        if not self._edit_undo_stack:
            return "break"
        current = self._capture_edit_snapshot()
        target = self._edit_undo_stack.pop()
        self._edit_redo_stack.append(copy.deepcopy(current))
        self._restore_edit_snapshot(target)
        self._show_edit_history_toast("↶  CAMBIO DESHECHO")
        return "break"

    def _on_redo_shortcut(self, _event=None):
        if self._capturing_hotkey_action or not self.project:
            return None
        self._record_edit_transition()
        if not self._edit_redo_stack:
            return "break"
        current = self._capture_edit_snapshot()
        target = self._edit_redo_stack.pop()
        self._edit_undo_stack.append(copy.deepcopy(current))
        self._restore_edit_snapshot(target)
        self._show_edit_history_toast("↷  CAMBIO REHECHO")
        return "break"

    def _show_edit_history_toast(self, text: str) -> None:
        try:
            toast = ctk.CTkFrame(self, fg_color="#151515", corner_radius=12, border_width=1, border_color=GOLD)
            toast.place(relx=0.56, rely=0.12, anchor="center")
            ctk.CTkLabel(
                toast, text=text, text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).pack(padx=18, pady=9)
            toast.lift()
            self.after(850, lambda: toast.destroy() if toast.winfo_exists() else None)
        except Exception:
            pass

    def _apply_window_icon(self, window) -> None:
        """Aplica el icono de RoleRun también a ventanas secundarias de Tk/CTk.

        En Windows algunas Toplevel se crean primero con el icono genérico de Tk;
        se aplica una vez al crearla y otra al entrar en el bucle de eventos para
        cubrir ese comportamiento sin afectar a otras plataformas.
        """
        icon = RESOURCES_DIR / "icono_sin_fondo.ico"
        if not icon.exists():
            return

        def apply() -> None:
            try:
                if window.winfo_exists():
                    window.iconbitmap(str(icon))
            except Exception:
                pass

        apply()
        try:
            window.after(80, apply)
        except Exception:
            pass

    # ---------- FLOATING BAR ----------

    def _projected_game_for_live_layout(self) -> SaveGameData | None:
        """Snapshot visual del estado pendiente, sin tocar el archivo de guardado.

        OBS y la barra flotante deben reaccionar a cambios de rol/equipo antes de
        GUARDAR CAMBIOS. Para ello horneamos el rol efectivo en una copia de la
        party proyectada y conservamos el resto de metadatos de la partida leída.
        """
        if not self.current_game:
            return None
        party = self._projected_party()
        for pokemon in party:
            role, symbol = self._effective_role(pokemon)
            pokemon.role = role
            pokemon.role_symbol = symbol
        return SaveGameData(
            game=self.current_game.game,
            save_type=self.current_game.save_type,
            generation=self.current_game.generation,
            trainer=self.current_game.trainer,
            party=party,
            raw=self.current_game.raw,
        )

    def _floating_bar_is_visible(self) -> bool:
        try:
            return bool(
                self.floating_bar
                and self.floating_bar.winfo_exists()
                and str(self.floating_bar.state()) != "withdrawn"
            )
        except Exception:
            return False

    def _sync_live_layout(self, refresh_floating: bool = True) -> None:
        """Refresca OBS/barra con el estado pendiente, nunca con slots antiguos.

        ``refresh_floating=False`` permite terminar primero un evento de drag de la
        propia barra y reconstruirla en el siguiente idle de Tk. Destruir la tarjeta
        que está procesando ButtonRelease dentro del mismo callback puede dejar a Tk
        en un estado visual intermedio en Windows.
        """
        projected = self._projected_game_for_live_layout()
        if projected is not None and self.project:
            try:
                self._sync_obs_state(projected)
            except Exception:
                # La edición de la Run no debe bloquearse si OBS no puede escribir
                # temporalmente sus archivos (por ejemplo, antivirus/backup).
                pass
        if refresh_floating:
            # Solo invalidamos la barra cuando realmente cambió algo que ella
            # representa (equipo/rol/contadores). Los movimientos no aparecen en
            # la barra y forzar aquí un rebuild completo provocaba un pestañeo
            # innecesario cada vez que ORAS enseñaba o borraba un ataque.
            self._floating_bar_last_signature = None
            if self.floating_bar and self.floating_bar.winfo_exists():
                try:
                    if str(self.floating_bar.state()) != "withdrawn":
                        self._render_floating_bar(force=True)
                except Exception:
                    pass

    def _find_projected_pokemon_by_identity(self, identity: str) -> SavePokemon | None:
        return next((p for p in self._projected_party() if self._pokemon_identity(p) == identity), None)

    def _role_slot_occupants(self, party: list[SavePokemon] | None = None) -> tuple[dict[str, SavePokemon], list[SavePokemon]]:
        """Devuelve las seis casillas RoleRun fijas y los Pokémon no colocados.

        La posición pertenece al ROL, nunca al Pokémon. Por eso un intercambio de
        Líbero ↔ Tanque mueve los Pokémon entre casillas mientras los rótulos se
        mantienen exactamente en el mismo lugar.
        """
        party = list(party if party is not None else self._projected_party())
        occupants: dict[str, SavePokemon] = {}
        extras: list[SavePokemon] = []
        for pokemon in party:
            role, _ = self._effective_role(pokemon)
            if role in ROLE_ORDER and role not in occupants:
                occupants[role] = pokemon
            else:
                # SIN ROL y conflictos importados se conservan visibles aparte.
                extras.append(pokemon)
        return occupants, extras

    def _roles_reserved_by_pending_faints(self) -> set[str]:
        """Roles cuya casilla debe quedar visiblemente vacía por una baja pendiente.

        La casilla pertenece al rol, y el sustituto heredará exactamente ese rol.
        Dejar que un miembro SIN ROL se deslizara hasta ella movía el hueco a otro
        rol distinto: el usuario veía vacío el puesto de Support cuando quien
        había caído era el Asesino, y un Pokémon sin rol ocupando el del Asesino.
        """
        project = getattr(self, "project", None)
        if project is None:
            return set()
        reservados: set[str] = set()
        for evento in list(getattr(project, "pending_faints", ()) or ()):
            role = str(evento.get("role", "") or "")
            if role in ROLE_TO_KEY:
                reservados.add(role)
        return reservados

    def _team_role_grid_layout(
        self, party: list[SavePokemon] | None = None,
    ) -> tuple[dict[str, SavePokemon], list[SavePokemon], dict[str, int], set[int]]:
        """Coloca toda party física de hasta seis miembros en seis celdas.

        Las casillas continúan perteneciendo a los roles. Si una captura importada
        contiene SIN ROL o un marcador duplicado, ese miembro ocupa visualmente una
        de las casillas que ha quedado libre en vez de crear una séptima fila. El
        rol real y el conflicto se conservan: solo desaparece la falsa posición
        física adicional.
        """
        party = list(party if party is not None else self._projected_party())
        occupants, extras = self._role_slot_occupants(party)
        # Una baja pendiente reserva su casilla: es la que heredará el sustituto.
        reservados = self._roles_reserved_by_pending_faints()
        positions: dict[str, int] = {}
        free_indices: list[int] = []
        for role_index, role_name in enumerate(ROLE_ORDER):
            member = occupants.get(role_name)
            if member is None:
                if role_name not in reservados:
                    free_indices.append(role_index)
            else:
                positions[self._pokemon_identity(member)] = role_index

        extra_indices: set[int] = set()
        for member, role_index in zip(extras, free_indices):
            positions[self._pokemon_identity(member)] = role_index
            extra_indices.add(role_index)
        return occupants, extras, positions, extra_indices

    def _drop_target_role_at(self, x_root: int, y_root: int, context: str) -> str | None:
        targets = self._floating_role_drop_targets if context == "floating" else self._main_role_drop_targets
        for widget, role in list(targets):
            try:
                if not widget.winfo_exists():
                    continue
                left, top = widget.winfo_rootx(), widget.winfo_rooty()
                right = left + widget.winfo_width()
                bottom = top + widget.winfo_height()
                if left <= x_root <= right and top <= y_root <= bottom:
                    return role
            except Exception:
                continue
        return None

    def _destroy_role_drag_visuals(self) -> None:
        placeholder = self._role_drag_placeholder
        self._role_drag_placeholder = None
        if placeholder is not None:
            try:
                if placeholder.winfo_exists():
                    placeholder.destroy()
            except Exception:
                pass
        ghost = self._role_drag_ghost
        self._role_drag_ghost = None
        self._role_drag_ghost_image = None
        if ghost is not None:
            try:
                if ghost.winfo_exists():
                    ghost.destroy()
            except Exception:
                pass

    def _show_role_drag_placeholder(self, container, role: str) -> None:
        """Vacía visualmente la casilla desde el instante en que se coge el Pokémon."""
        if container is None:
            return
        try:
            if not container.winfo_exists():
                return
            placeholder = ctk.CTkFrame(
                container, fg_color="#151515", corner_radius=10,
                border_width=1, border_color="#4A4A4A",
            )
            placeholder.place(relx=0, rely=0, relwidth=1, relheight=1)
            ctk.CTkLabel(
                placeholder, text="—", text_color="#595959",
                font=ctk.CTkFont("Segoe UI", 34, "bold"),
            ).place(relx=0.5, rely=0.42, anchor="center")
            ctk.CTkLabel(
                placeholder, text=role.upper() if role in ROLE_ORDER else "SIN ROL",
                text_color=GOLD if role in ROLE_ORDER else MUTED,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).place(relx=0.5, rely=0.78, anchor="center")
            placeholder.lift()
            self._role_drag_placeholder = placeholder
        except Exception:
            self._role_drag_placeholder = None

    def _create_role_drag_ghost(self, pokemon: SavePokemon, event) -> None:
        """Crea un sprite flotante que queda visualmente agarrado al cursor."""
        source = self._sprite_source(pokemon)
        try:
            ghost = ctk.CTkToplevel(self)
            ghost.overrideredirect(True)
            ghost.attributes("-topmost", True)
            ghost.configure(fg_color="#101010")
            frame = ctk.CTkFrame(ghost, fg_color="#151515", corner_radius=14, border_width=2, border_color=GOLD)
            frame.pack(fill="both", expand=True)
            if source is not None:
                source.thumbnail((92, 92), Image.Resampling.LANCZOS)
                image = ctk.CTkImage(light_image=source, dark_image=source, size=source.size)
                ctk.CTkLabel(frame, text="", image=image, fg_color="transparent").pack(padx=8, pady=6)
                self._role_drag_ghost_image = image
            else:
                ctk.CTkLabel(
                    frame, text=pokemon.nickname or pokemon.species, text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 12, "bold"),
                ).pack(padx=12, pady=10)
                self._role_drag_ghost_image = None
            ghost.geometry(f"+{int(event.x_root) + 12}+{int(event.y_root) + 12}")
            self._role_drag_ghost = ghost
        except Exception:
            self._role_drag_ghost = None
            self._role_drag_ghost_image = None

    def _cancel_role_drag(self) -> None:
        """Cancela cualquier gesto de rol sin modificar el equipo.

        Es importante al abrir/cerrar ventanas modales: un click sobre un botón no
        debe dejar un placeholder ni un sprite fantasma si la pulsación no terminó
        como drag.
        """
        self._role_drag_source_identity = None
        self._role_drag_source_role = None
        self._role_drag_context = None
        self._role_drag_origin = None
        self._role_drag_moved = False
        self._role_drag_started = False
        self._role_drag_container = None
        self._floating_role_drag_consumed = False
        self._destroy_role_drag_visuals()

    def _begin_role_drag(self, event, pokemon: SavePokemon, context: str, container=None, slot_role: str | None = None) -> str | None:
        # Un click normal NO vacía la casilla. Solo preparamos el posible gesto y
        # esperamos a ver si realmente hay movimiento del ratón.
        self._cancel_role_drag()
        self._role_drag_source_identity = self._pokemon_identity(pokemon)
        effective_role, _ = self._effective_role(pokemon)
        self._role_drag_source_role = slot_role or effective_role
        self._role_drag_context = context
        self._role_drag_origin = (int(event.x_root), int(event.y_root))
        self._role_drag_moved = False
        self._role_drag_started = False
        self._role_drag_container = container
        return None

    def _move_role_drag(self, event) -> str | None:
        if not self._role_drag_source_identity or not self._role_drag_origin:
            return None
        dx = int(event.x_root) - self._role_drag_origin[0]
        dy = int(event.y_root) - self._role_drag_origin[1]

        # Diferenciamos inequívocamente click de drag. Hasta superar el umbral no
        # se toca nada visual, evitando que un pequeño click "agarre" al Pokémon.
        if not self._role_drag_started and abs(dx) + abs(dy) >= 7:
            self._role_drag_started = True
            self._role_drag_moved = True
            if self._role_drag_context == "floating":
                self._floating_role_drag_consumed = True
            source = self._find_projected_pokemon_by_identity(self._role_drag_source_identity)
            if source is not None:
                self._show_role_drag_placeholder(
                    self._role_drag_container,
                    self._role_drag_source_role or self._effective_role(source)[0],
                )
                self._create_role_drag_ghost(source, event)

        if self._role_drag_started and self._role_drag_ghost is not None:
            try:
                if self._role_drag_ghost.winfo_exists():
                    self._role_drag_ghost.geometry(f"+{int(event.x_root) + 12}+{int(event.y_root) + 12}")
            except Exception:
                pass
        return "break" if self._role_drag_started and self._role_drag_context == "floating" else None

    def _end_role_drag(self, event) -> str | None:
        source_identity = self._role_drag_source_identity
        source_role = self._role_drag_source_role or "SIN ROL"
        context = self._role_drag_context or "main"
        moved = bool(self._role_drag_started and self._role_drag_moved)
        target_role = self._drop_target_role_at(int(event.x_root), int(event.y_root), context) if moved else None

        # Limpiamos SIEMPRE antes de ejecutar la acción; así ni los diálogos ni un
        # rerender posterior pueden dejar sprites fantasma sobre otras páginas.
        self._role_drag_source_identity = None
        self._role_drag_source_role = None
        self._role_drag_context = None
        self._role_drag_origin = None
        self._role_drag_moved = False
        self._role_drag_started = False
        self._role_drag_container = None
        self._destroy_role_drag_visuals()

        if moved:
            if source_identity and target_role and target_role != source_role:
                if context == "floating":
                    # La barra es un Toplevel NOACTIVATE con handlers propios de
                    # ButtonRelease. A diferencia del Dashboard, no mutamos la Run
                    # mientras Tk sigue propagando ese mismo release por el árbol.
                    # El gesto se resuelve en el siguiente idle y desde ahí entra
                    # por EXACTAMENTE la misma ruta de cambios + writer vivo.
                    bar = self.floating_bar

                    def finish_drop(
                        identity=source_identity, destination=target_role, ctx=context,
                    ) -> None:
                        source = self._find_projected_pokemon_by_identity(identity)
                        if source is not None:
                            self._move_pokemon_to_role_by_drag(source, destination, context=ctx)

                    try:
                        scheduler = bar if bar and bar.winfo_exists() else self
                        scheduler.after_idle(finish_drop)
                    except Exception:
                        self.after(0, finish_drop)
                else:
                    source = self._find_projected_pokemon_by_identity(source_identity)
                    if source is not None:
                        self._move_pokemon_to_role_by_drag(source, target_role, context=context)
        elif context == "floating" and source_role in ROLE_ORDER:
            # Click corto = mostrar/ocultar. Drag = mover. Son gestos separados.
            self._floating_role_drag_consumed = False
            self._floating_role_click(source_role)

        if context == "floating":
            self.after(90, lambda: setattr(self, "_floating_role_drag_consumed", False))
            return "break"
        return None

    def _register_role_drag_surface(
        self, widget, pokemon: SavePokemon, context: str = "main", container=None, slot_role: str | None = None,
    ) -> None:
        try:
            root = container or widget
            widget.bind(
                "<ButtonPress-1>",
                lambda e, p=pokemon, c=context, r=root, sr=slot_role: self._begin_role_drag(e, p, c, r, sr),
                add="+",
            )
            widget.bind("<B1-Motion>", self._move_role_drag, add="+")
            widget.bind("<ButtonRelease-1>", self._end_role_drag, add="+")
        except Exception:
            pass

    def _register_role_drag_tree(
        self, widget, pokemon: SavePokemon, context: str = "main", container=None, slot_role: str | None = None,
    ) -> None:
        # Los botones y TODOS sus widgets internos quedan fuera del drag. En
        # CustomTkinter un CTkButton contiene canvas/labels hijos; recorrerlos era
        # la causa de que CAMBIAR CON PC iniciase un "agarre" fantasma.
        try:
            if isinstance(widget, ctk.CTkButton):
                return
            root = container or widget
            self._register_role_drag_surface(widget, pokemon, context, root, slot_role)
            for child in widget.winfo_children():
                self._register_role_drag_tree(child, pokemon, context, root, slot_role)
        except Exception:
            pass

    @perf.timed("ui.drop.mover_rol")
    def _move_pokemon_to_role_by_drag(
        self, source: SavePokemon, target_role: str, context: str = "main",
        libero_assignments: dict[str, tuple[str, ...]] | None = None,
    ) -> None:
        """Mueve Pokémon entre casillas fijas de rol, no mueve los rótulos."""
        source_role, _ = self._effective_role(source)
        if target_role not in ROLE_ORDER or source_role == target_role:
            return
        pending_ids_before = {id(change) for change in self.run.pending_changes}
        party = self._projected_party()
        target = next((p for p in party if p is not source and self._effective_role(p)[0] == target_role), None)
        libero_assignments = dict(libero_assignments or {})
        libero_recipient = source if target_role == "Líbero" else (target if source_role == "Líbero" else None)
        if libero_recipient is not None:
            recipient_identity = self._pokemon_identity(libero_recipient)
            if len(libero_assignments.get(recipient_identity, ())) != 2:
                self._prompt_libero_ev_stats(
                    libero_recipient,
                    lambda stats, src=source, dst=target_role, ctx=context, known=libero_assignments: self._move_pokemon_to_role_by_drag(
                        src, dst, context=ctx,
                        libero_assignments={**known, self._pokemon_identity(libero_recipient): stats},
                    ),
                    context=context,
                )
                return

        # Primero desplazamos al ocupante del destino a la casilla que deja libre
        # el Pokémon cogido; después colocamos el Pokémon cogido en el destino.
        # No se borran movimientos: su compatibilidad se recalcula con el nuevo rol.
        if target is not None:
            self._set_projected_member_role(
                target, source_role if source_role in ROLE_ORDER else "SIN ROL",
                libero_stats=libero_assignments.get(self._pokemon_identity(target), ()),
            )
        self._set_projected_member_role(
            source, target_role,
            libero_stats=libero_assignments.get(self._pokemon_identity(source), ()),
        )

        # Sin esto, un cambio de rol solo llegaba a la tabla de aprendizajes
        # de ORAS en el siguiente sondeo pasivo (hasta ~950ms después,
        # _finish_oras_live_reconciliation). Con el juego acelerado (varios
        # cientos por ciento de velocidad, confirmado el 2026-09-03) ese
        # margen le sobraba de tiempo para subir de nivel con el rol
        # anterior todavía escrito. _effective_role ya lee el cambio de rol
        # pendiente antes de que se confirme en la RAM, así que no hace
        # falta esperar a releer la partida. Validado físicamente el
        # 2026-09-03: un intercambio de roles entre dos Pokémon ya se refleja
        # de inmediato.
        self._sync_oras_levelup_moves_mod(self.current_game)
        self._sync_usum_levelup_moves_mod(self.current_game)
        self._sync_usum_levelup_moves_backup(self.current_game)
        self._sync_sm_levelup_moves_mod(self.current_game)
        self._sync_sm_levelup_moves_backup(self.current_game)
        self._sync_xy_levelup_moves_mod(self.current_game)
        self._sync_xy_levelup_moves_backup(self.current_game)
        self._sync_gen5_levelup_moves(self.current_game)
        self._sync_hgss_levelup_moves(self.current_game)

        left = source.nickname or source.species
        if target is not None:
            right = target.nickname or target.species
            detail = f"{left} → {target_role} · {right} → {source_role}"
        else:
            detail = f"{left} → {target_role}"

        if context == "floating":
            # La ventana principal está retirada mientras se usa la barra. No hay
            # motivo para reconstruirla aquí: hacerlo disparaba WM_SETREDRAW sobre
            # un HWND oculto y Windows podía mostrar durante unos frames la shell
            # principal incompleta (franjas blancas). Actualizamos solo estado,
            # cabecera oculta/OBS y la propia barra. Al volver al Dashboard se hará
            # el render completo una única vez.
            self._floating_role_reordered = True
            self._update_top_status()
            # OBS se actualiza ya, pero la barra espera a que termine el evento
            # ButtonRelease actual. Así no destruimos la tarjeta fuente mientras
            # Tk todavía está despachando el gesto de arrastre.
            self._sync_live_layout(refresh_floating=False)
            bar = self.floating_bar

            def finish_floating_role_refresh() -> None:
                if not bar or not bar.winfo_exists() or str(bar.state()) == "withdrawn":
                    return
                # El intercambio en la barra es deliberadamente silencioso: el
                # nuevo orden de sprites ya es confirmación visual suficiente.
                self._render_floating_bar(force=True)

            if bar and bar.winfo_exists():
                bar.after_idle(finish_floating_role_refresh)
            self._record_edit_transition()
            # Se programa después de terminar el gesto: la barra conserva su
            # refresco localizado y la escritura se confirma sin que el drag
            # destruya la tarjeta origen durante ButtonRelease.
            self._request_oras_live_auto_apply_since(pending_ids_before)
            return

        self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
        self._sync_live_layout()
        self._show_team_management_toast("POKÉMON REORGANIZADOS", detail)
        self._request_oras_live_auto_apply_since(pending_ids_before)

    # Compatibilidad interna con llamadas antiguas de 1.12.12.
    def _swap_roles_by_drag(self, source: SavePokemon, target: SavePokemon) -> None:
        target_role, _ = self._effective_role(target)
        self._move_pokemon_to_role_by_drag(source, target_role, context=self._role_drag_context or "main")

    def _show_floating_management_toast(self, title: str, subtitle: str) -> None:
        """Confirma una reorganización sin tocar ni despertar la ventana principal."""
        bar = self.floating_bar
        if not bar or not bar.winfo_exists() or str(bar.state()) == "withdrawn":
            return
        try:
            toast = ctk.CTkFrame(
                bar, fg_color="#151515", corner_radius=10,
                border_width=1, border_color=GOLD,
            )
            toast.place(relx=0.5, rely=0.5, anchor="center")
            ctk.CTkLabel(
                toast, text=f"✓  {title}", text_color=SUCCESS,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).pack(padx=16, pady=(7, 0))
            ctk.CTkLabel(
                toast, text=subtitle, text_color=TEXT,
                font=ctk.CTkFont("Segoe UI", 9, "bold"),
            ).pack(padx=16, pady=(1, 7))
            toast.lift()
            bar.after(900, lambda: toast.destroy() if toast.winfo_exists() else None)
        except Exception:
            pass

    def _floating_role_click(self, role: str) -> None:
        if self._floating_role_drag_consumed:
            return
        self.toggle_role_visibility(role)

    _DEFAULT_EMULATOR_PROCESS_TOKENS = (
        "ryujinx", "azahar", "citra", "lime3ds", "desmume", "melonds",
        "yuzu", "suyu", "sudachi", "eden", "torzu",
        "retroarch", "bizhawk", "nogba", "no$gba",
    )

    @staticmethod
    def _floating_noactivate_exstyle(style: int) -> int:
        """Añade WS_EX_NOACTIVATE sin destruir otros estilos extendidos."""
        return int(style) | 0x08000000

    def _apply_floating_bar_noactivate(self, bar=None) -> bool:
        """Hace la barra clicable sin convertirla en la ventana activa de Windows.

        ``WS_EX_NOACTIVATE`` está pensado para paletas/overlays: reciben ratón pero
        no toman el foco de teclado al hacer click. Se aplica tanto al HWND que
        expone Tk como a su wrapper nativo cuando existe, porque distintas builds
        de Tk pueden devolver uno u otro desde ``winfo_id``.
        """
        if os.name != "nt":
            return False
        bar = bar or self.floating_bar
        if bar is None:
            return False
        try:
            bar.update_idletasks()
            hwnd = int(bar.winfo_id())
            if not hwnd:
                return False
            user32 = ctypes.windll.user32
            get_parent = user32.GetParent
            get_parent.argtypes = [ctypes.c_void_p]
            get_parent.restype = ctypes.c_void_p
            targets = [hwnd]
            parent = int(get_parent(ctypes.c_void_p(hwnd)) or 0)
            if parent and parent not in targets:
                targets.append(parent)

            get_long = getattr(user32, "GetWindowLongPtrW", user32.GetWindowLongW)
            set_long = getattr(user32, "SetWindowLongPtrW", user32.SetWindowLongW)
            get_long.argtypes = [ctypes.c_void_p, ctypes.c_int]
            set_long.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_ssize_t]
            get_long.restype = ctypes.c_ssize_t
            set_long.restype = ctypes.c_ssize_t
            GWL_EXSTYLE = -20
            changed = False
            for target in targets:
                current = int(get_long(ctypes.c_void_p(target), GWL_EXSTYLE))
                desired = self._floating_noactivate_exstyle(current)
                if desired != current:
                    set_long(ctypes.c_void_p(target), GWL_EXSTYLE, ctypes.c_ssize_t(desired))
                # No dependemos del valor de retorno de SetWindowLongPtrW: cero
                # también puede ser un valor previo válido. Releemos el estilo.
                applied = int(get_long(ctypes.c_void_p(target), GWL_EXSTYLE))
                changed = changed or bool(applied & 0x08000000)
            return changed
        except Exception:
            return False


    def _restore_last_emulator_focus_from_bar(self, bar=None) -> None:
        """Fallback: devuelve el foreground al emulador si Tk llegó a activarse."""
        if os.name != "nt" or not self._last_supported_emulator_hwnd:
            return
        bar = bar or self.floating_bar
        try:
            if bar is None or not bar.winfo_exists() or str(bar.state()) == "withdrawn":
                return
        except Exception:
            return
        try:
            user32 = ctypes.windll.user32
            hwnd = int(self._last_supported_emulator_hwnd)
            user32.IsWindow.argtypes = [ctypes.c_void_p]
            user32.IsWindow.restype = ctypes.c_int
            if not user32.IsWindow(ctypes.c_void_p(hwnd)):
                self._last_supported_emulator_hwnd = 0
                return
            user32.SetForegroundWindow.argtypes = [ctypes.c_void_p]
            user32.SetForegroundWindow.restype = ctypes.c_int
            user32.SetForegroundWindow(ctypes.c_void_p(hwnd))
        except Exception:
            pass

    def _schedule_emulator_focus_restore_from_bar(self, bar=None) -> None:
        bar = bar or self.floating_bar
        try:
            self.after(35, lambda: self._restore_last_emulator_focus_from_bar(bar))
        except Exception:
            pass

    def _foreground_window_info(self) -> tuple[int, str, str]:
        """Devuelve pid, ejecutable y título de la ventana activa en Windows."""
        if os.name != "nt":
            return 0, "", ""
        try:
            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32
            user32.GetForegroundWindow.restype = ctypes.c_void_p
            kernel32.OpenProcess.restype = ctypes.c_void_p
            hwnd = user32.GetForegroundWindow()
            if not hwnd:
                return 0, "", ""
            pid = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))

            title_len = user32.GetWindowTextLengthW(hwnd)
            title_buf = ctypes.create_unicode_buffer(max(2, int(title_len) + 1))
            user32.GetWindowTextW(hwnd, title_buf, len(title_buf))
            title = title_buf.value or ""

            process_name = ""
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            handle = kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid.value))
            if handle:
                try:
                    size = ctypes.c_ulong(32768)
                    path_buf = ctypes.create_unicode_buffer(size.value)
                    if kernel32.QueryFullProcessImageNameW(handle, 0, path_buf, ctypes.byref(size)):
                        process_name = Path(path_buf.value).name
                finally:
                    kernel32.CloseHandle(handle)
            return int(pid.value), process_name, title
        except Exception:
            return 0, "", ""

    def _foreground_belongs_to_this_process(self) -> bool:
        """Evita interpretar diálogos del propio programa como un cambio a juego."""
        if os.name == "nt":
            pid, _process, _title = self._foreground_window_info()
            if pid:
                return pid == os.getpid()
        try:
            focus = self.focus_displayof()
            if focus is None:
                return False
            current = focus
            while current is not None:
                if current is self:
                    return True
                current = getattr(current, "master", None)
        except Exception:
            pass
        return False

    def _on_role_run_focus_in(self, _event=None) -> None:
        """Reserva Ryujinx antes de que el primer control llegue a RoleRun."""
        try:
            self._sync_role_run_foreground_input_gate()
            self.after_idle(self._sync_role_run_foreground_input_gate)
        except Exception:
            pass

    def _sync_role_run_foreground_input_gate(self) -> bool:
        """Mantiene un único bloqueo mientras RoleRun posee el primer plano.

        Ryujinx SDL2 está configurado para aceptar mando sin foco. Consumir el
        control en Tk/SDL no evita por sí solo que el emulador lo consuma también;
        la frontera segura es retener su proceso durante la interacción con la UI.
        """
        # Retener el emulador **para el juego entero**: 0,0% de CPU, el reloj
        # parado y la música cortada. Medido en la máquina del usuario, era lo
        # que cortaba el sonido cada vez que pinchaba en RoleRun.
        #
        # La retención existe por una razón buena —Ryujinx acepta mando sin
        # foco, así que el flanco que navega RoleRun movería también al
        # personaje— pero esa razón **solo existe si hay un mando enchufado**.
        # Sin mando no hay flanco posible, y parar el juego es coste sin
        # beneficio.
        should_hold = bool(
            getattr(getattr(self, "save_engine", None), "key", "") == "bdsp"
            and getattr(self, "current_game", None) is not None
            and getattr(self, "_hay_mando", False)
            # Y solo si el emulador no se protege ya solo. Ryujinx tiene la
            # opción `disable_input_when_out_of_focus`: con ella puesta no lee el
            # mando sin el foco, así que RoleRun puede navegar sus menús sin que
            # el flanco llegue al personaje **y sin parar el juego**. Es la
            # solución buena, y la que hay que preferir sobre suspender nada.
            and not ryujinx_ignora_el_mando_sin_foco()
            and self._foreground_belongs_to_this_process()
        )
        gate = self._ryujinx_input_gate
        if should_hold:
            if self._role_run_foreground_gate_held and gate.active:
                return True
            self._role_run_foreground_gate_held = False
            if gate.active or gate.acquire():
                self._role_run_foreground_gate_held = True
                return True
            return False

        if self._role_run_foreground_gate_held:
            self._role_run_foreground_gate_held = False
            if (
                not self._gamepad_reserved_buttons
                and not self._widget_alive(self._floating_launcher)
            ):
                gate.release(all_levels=True)
        return False

    def _configured_emulator_process_tokens(self) -> tuple[str, ...]:
        """Lista ampliable sin recompilar: floating_bar.json puede añadir procesos."""
        tokens = list(self._DEFAULT_EMULATOR_PROCESS_TOKENS)
        try:
            import json
            raw = json.loads(self._floating_bar_config_path.read_text(encoding="utf-8-sig"))
            extra = raw.get("emulator_processes", [])
            if isinstance(extra, list):
                tokens.extend(str(value).strip().lower() for value in extra if str(value).strip())
        except Exception:
            pass
        return tuple(dict.fromkeys(tokens))

    def _foreground_is_supported_emulator(self) -> bool:
        """Detecta el emulador por proceso y recuerda su HWND para la barra."""
        if os.name != "nt":
            return False
        try:
            ctypes.windll.user32.GetForegroundWindow.restype = ctypes.c_void_p
            foreground_hwnd = int(ctypes.windll.user32.GetForegroundWindow() or 0)
        except Exception:
            foreground_hwnd = 0
        pid, process_name, title = self._foreground_window_info()
        if not pid or pid == os.getpid():
            return False
        process_l = process_name.lower()
        title_l = title.lower()
        for token in self._configured_emulator_process_tokens():
            if not token:
                continue
            # El token se compara contra el NOMBRE DEL PROCESO. Compararlo también
            # contra el título de la ventana convertía cualquier ventana que
            # dijera «Ryujinx» —una pestaña del navegador, una carpeta, un vídeo—
            # en un emulador en primer plano, y RoleRun abría la barra flotante
            # sin que hubiera ningún juego. El título solo vale cuando no se pudo
            # leer el nombre del proceso, que es el único caso en que no hay nada
            # mejor.
            if token in process_l or (not process_l and token in title_l):
                if foreground_hwnd:
                    self._last_supported_emulator_hwnd = foreground_hwnd
                return True
        return False

    def _suspend_modal_for_floating_bar(self) -> None:
        """Libera y oculta el modal activo antes de retirar la ventana principal.

        Tk mantiene el ``grab_set`` aunque su Toplevel quede oculto. Si la barra
        automática aparece en ese estado, todos los eventos de ratón siguen
        dirigidos al modal invisible y la barra parece totalmente bloqueada.
        """
        current = self._floating_suspended_modal
        if current is not None:
            try:
                if current.winfo_exists():
                    return
            except Exception:
                pass
            self._floating_suspended_modal = None
            self._floating_suspended_modal_had_grab = False

        try:
            grabbed = self.grab_current()
        except Exception:
            grabbed = None
        if grabbed is None:
            return
        try:
            modal = grabbed.winfo_toplevel()
        except Exception:
            modal = grabbed
        if modal is self or modal is self.floating_bar:
            return
        try:
            if not modal.winfo_exists():
                return
        except Exception:
            return

        self._cancel_role_drag()
        had_grab = False
        try:
            modal.grab_release()
            had_grab = True
        except Exception:
            pass
        try:
            modal.withdraw()
        except Exception:
            if had_grab:
                try:
                    modal.grab_set()
                except Exception:
                    pass
            return
        self._floating_suspended_modal = modal
        self._floating_suspended_modal_had_grab = had_grab

    def _restore_suspended_modal_after_floating(self) -> None:
        modal = self._floating_suspended_modal
        if modal is None:
            return

        # Si el Manager sigue oculto/minimizado todavía no debemos soltar la
        # referencia: la ventana modal debe reaparecer cuando el usuario vuelva
        # realmente a RoleRun Manager. Limpiar el estado aquí dejaba un modal
        # retirado para siempre y podía mantener el flujo de la UI inconsistente.
        try:
            if not modal.winfo_exists():
                self._floating_suspended_modal = None
                self._floating_suspended_modal_had_grab = False
                return
        except Exception:
            self._floating_suspended_modal = None
            self._floating_suspended_modal_had_grab = False
            return

        try:
            if str(self.state()) in {"withdrawn", "iconic"}:
                return
        except Exception:
            return

        try:
            modal.deiconify()
            modal.lift()
            if self._floating_suspended_modal_had_grab:
                modal.grab_set()
            try:
                modal.focus_force()
            except Exception:
                pass
        except Exception:
            pass

        self._floating_suspended_modal = None
        self._floating_suspended_modal_had_grab = False

    def _on_main_map(self, _event=None) -> None:
        # Si Windows restaura la ventana principal directamente desde la barra de
        # tareas mientras la barra flotante seguía visible, esa acción se interpreta
        # como "volver a RoleRun". Nunca dejamos raíz + barra activas a la vez:
        # esa superposición era especialmente peligrosa cuando había una baja pendiente.
        #
        # Pedido por el usuario el 2026-09-03: abrir la barra flotante ahora pasa
        # por ``deiconify()`` antes de ``iconify()`` (para conservar el icono real
        # en la barra de tareas), y eso dispara este mismo <Map> como efecto
        # colateral de la propia apertura. El guard —ya puesto por
        # ``open_floating_bar``— evita interpretar ese <Map> autoinducido como
        # "el usuario ha vuelto" y deshacer la apertura que se acaba de pedir.
        if self._auto_floating_guard:
            return
        try:
            if self._floating_bar_is_visible():
                # Un <Map> de la raíz no implica necesariamente que el usuario haya
                # vuelto a RoleRun. CTk/Windows puede emitirlo al actualizar widgets
                # ocultos. Si Azahar (u otra app) sigue siendo foreground, conservamos
                # la barra y retiramos de nuevo la raíz en vez de cerrarla.
                main_is_explicitly_visible = False
                try:
                    main_is_explicitly_visible = bool(
                        str(self.state()) in {"normal", "zoomed"}
                        and self.winfo_viewable()
                    )
                except Exception:
                    pass
                if (
                    os.name == "nt"
                    and not main_is_explicitly_visible
                    and not self._foreground_belongs_to_this_process()
                ):
                    try:
                        self.withdraw()
                        if self.floating_bar and self.floating_bar.winfo_exists():
                            self.floating_bar.deiconify()
                            self.floating_bar.lift()
                            self.floating_bar.attributes("-topmost", True)
                    except Exception:
                        pass
                    return
                self._save_floating_bar_position()
                if self._floating_bar_poll_id:
                    try:
                        self.after_cancel(self._floating_bar_poll_id)
                    except Exception:
                        pass
                    self._floating_bar_poll_id = None
                self.floating_bar.withdraw()
                self._floating_role_reordered = False
                self._set_auto_floating_guard_temporarily(650)
                if self._main_ui_dirty_while_floating:
                    self._main_ui_dirty_while_floating = False
                    self.after(40, lambda: self._smooth_render_page(
                        preserve_scroll=(self.active_page == "team")
                    ))
        except Exception:
            pass

        # Si la X de la barra dejó el Manager minimizado, al restaurarlo desde la
        # barra de tareas devolvemos también el modal que estaba abierto.
        if self._floating_suspended_modal is not None:
            try:
                self.after(90, self._restore_suspended_modal_after_floating)
            except Exception:
                pass
        # Una baja detectada mientras se jugaba no roba foco a Azahar. El selector
        # aparece en cuanto el usuario vuelve voluntariamente a RoleRun.
        try:
            # La raíz acaba de mapearse: damos tiempo a Windows/CTk a terminar el
            # layout antes de construir el selector pesado de PC. Volver desde la
            # barra reactiva también un selector que el usuario hubiese cerrado.
            self._schedule_pending_faint_picker(700)
        except Exception:
            pass
        try:
            self._schedule_bdsp_pc_poll(180)
        except Exception:
            pass

    def _poll_emulator_foreground(self) -> None:
        """Observa la ventana foreground para detectar también navegador → emulador.

        Confiar solo en <FocusOut> detectaría únicamente los cambios iniciados
        desde RoleRun Manager. Este poll ligero permite que la barra aparezca si
        el usuario estaba en otra aplicación y después vuelve al emulador.
        """
        self._emulator_focus_poll_id = None
        try:
            should_check = bool(
                self._shell_built and self.current_game and not self._auto_floating_guard
                and not self._faint_picker_blocks_floating()
            )
            if should_check:
                emulator_in_foreground = self._foreground_is_supported_emulator()
                bar_visible = bool(
                    self.floating_bar and self.floating_bar.winfo_exists()
                    and str(self.floating_bar.state()) != "withdrawn"
                )
                # La barra automática solo puede aparecer mientras la ventana principal
                # está realmente abierta (normal/maximizada). Si el usuario la minimiza,
                # ese gesto se respeta y no se sustituye por la barra flotante.
                main_state = str(self.state())
                main_visible = main_state not in {"withdrawn", "iconic"}
                if main_visible and not bar_visible and emulator_in_foreground:
                    self.open_floating_bar()
                # El enlace en vivo se reintenta solo cada 1,6 s mientras el
                # juego está cerrado, pero si esa cadena se rompe por algún
                # motivo (p.ej. un intento invalidado a mitad de vuelo, que no
                # se reprograma), RoleRun podía quedarse sin volver a intentarlo
                # nunca: encender el emulador después no bastaba. Este poll ya
                # vigila el primer plano cada 450 ms; usarlo también para
                # relanzar la sincronización es la red de seguridad — no cuesta
                # nada si ya hay un intento en marcha o si ya está sincronizado.
                if (
                    emulator_in_foreground
                    and not self._oras_live_active
                    and self.current_save
                    and getattr(self.save_engine, "key", "") in REALTIME_READ_GAME_KEYS
                ):
                    self._schedule_oras_initial_auto_sync(150)
        except Exception:
            pass
        try:
            if self.winfo_exists():
                self._emulator_focus_poll_id = self.after(450, self._poll_emulator_foreground)
        except Exception:
            self._emulator_focus_poll_id = None

    def _on_main_unmap(self, _event=None) -> None:
        if self._auto_floating_guard or not self._shell_built or not self.current_game:
            return
        if self._unmap_after_id:
            try:
                self.after_cancel(self._unmap_after_id)
            except Exception:
                pass
        self._unmap_after_id = self.after(70, self._auto_float_if_minimized)

    def _auto_float_if_minimized(self) -> None:
        self._unmap_after_id = None
        if self._barra_oculta_por_tapado:
            # Esa minimización la hizo el propio sondeo para no dejar a RoleRun
            # sin icono. Reabrir la barra aquí la pondría encima de lo que está
            # tapando el juego, que es justo lo que se estaba evitando.
            return
        try:
            minimized = str(self.state()) == "iconic"
        except Exception:
            minimized = False
        if not minimized:
            return
        # Sin Run activa no hay nada que gestionar en segundo plano: no tiene
        # sentido dejar RoleRun escondido en la barra de tareas.
        if not self.current_game:
            self._restore_main_window_maximized()
            return
        if self._faint_picker_blocks_floating():
            # Hay un selector modal pendiente (una baja); minimizar con la
            # barra flotante escondería ese selector sin avisar.
            self._restore_main_window_maximized()
            return
        # La barra flotante solo tiene sentido sobre el emulador: sin él en
        # primer plano no hay nada que sobreponer. Antes se abría igual, y
        # aparecía flotando sobre el escritorio o lo que hubiera detrás.
        if self._foreground_is_supported_emulator():
            self.open_floating_bar()
        # Si no hay emulador en primer plano, se deja minimizado con
        # normalidad: forzar la ventana de vuelta la reabriría al instante,
        # justo tras pulsar minimizar.

    def _on_main_focus_out(self, _event=None) -> None:
        # `_shell_built` deliberadamente NO es una condición aquí (hallazgo del
        # usuario 31-08-2026): mientras BDSP/Sol-Luna validan los PS iniciales,
        # RoleRun puede tardar en soltar la barrera de arranque, y hasta ahora
        # eso bloqueaba también poder mandarlo a segundo plano — la ventana se
        # quedaba en primer plano "un rato" aunque el usuario clicase en el
        # emulador. `_render_floating_bar` solo depende de `_projected_party`/
        # `self.project`, ya disponibles antes de que la shell principal
        # termine de componerse, así que no hace falta esperar a eso.
        if (
            self._auto_floating_guard or not self.current_game
            or self._faint_picker_blocks_floating()
        ):
            return
        if self.floating_bar and self.floating_bar.winfo_exists() and str(self.floating_bar.state()) != "withdrawn":
            return
        if self._focus_out_after_id:
            try:
                self.after_cancel(self._focus_out_after_id)
            except Exception:
                pass
        # Damos tiempo a Windows a cambiar realmente la ventana foreground.
        self._focus_out_after_id = self.after(220, self._auto_float_if_background)

    def _auto_float_if_background(self) -> None:
        self._focus_out_after_id = None
        # Mismo motivo que en `_on_main_focus_out`: no exigir `_shell_built`.
        if (
            self._auto_floating_guard or not self.current_game
            or self._faint_picker_blocks_floating()
        ):
            return
        if self._foreground_belongs_to_this_process():
            return
        try:
            if str(self.state()) in {"withdrawn", "iconic"}:
                return
        except Exception:
            pass
        # 1.12.13: Alt+Tab a Discord/navegador/editor ya NO abre la barra.
        # Solo lo hace si la ventana activa pertenece a un emulador reconocido.
        if self._foreground_is_supported_emulator():
            self.open_floating_bar()

    def _set_auto_floating_guard_temporarily(self, milliseconds: int = 320) -> None:
        self._auto_floating_guard = True
        self.after(milliseconds, lambda: setattr(self, "_auto_floating_guard", False))

    def _ask_save_before_bar_action(self, action: str) -> bool:
        """Pregunta por el guardado antes de salir de la barra flotante.

        Devuelve False si el usuario cancela o si eligió guardar pero el proceso
        no llegó a completarse. Para volver al Dashboard, elegir NO conserva la
        cola pendiente; al cerrar la aplicación simplemente se descarta al salir.
        """
        if not self.run.pending_changes:
            return True
        parent = self.floating_bar if self.floating_bar and self.floating_bar.winfo_exists() else self
        answer = messagebox.askyesnocancel(
            "Cambios sin guardar",
            ("Hay cambios pendientes. ¿Quieres guardarlos antes de volver al Dashboard?"
             if action == "dashboard" else
             "Hay cambios pendientes. ¿Quieres guardarlos antes de cerrar RoleRun Manager?"),
            parent=parent,
        )
        if answer is None:
            return False
        if answer:
            self.save_pending_changes()
            # DeSmuME puede dejar una instalación diferida que exige mantener el
            # Manager abierto; en ese caso no abandonamos la aplicación todavía.
            if self.run.pending_changes or self._pending_ds_install is not None:
                return False
        return True

    def _floating_logo_to_dashboard(self) -> None:
        # La barra es una vista temporal. En ORAS no existe ya el concepto de
        # "guardar antes de volver": los cambios compatibles se aplican en Azahar
        # al momento y el guardado definitivo lo hace el juego. Los motores que
        # todavía dependen del archivo conservan la confirmación antigua.
        is_azahar_live_model = getattr(self.save_engine, "key", "") in INSTANT_REALTIME_UI_GAME_KEYS
        role_reorder_only = bool(
            self._floating_role_reordered
            and self.run.pending_changes
            and all(isinstance(change, PendingRoleChange) for change in self.run.pending_changes)
        )
        if (
            not is_azahar_live_model
            and not role_reorder_only
            and not self._ask_save_before_bar_action("dashboard")
        ):
            return

        # IMPORTANTE: no mostramos primero la ventana principal y la reconstruimos
        # después. Primero retiramos la barra, reconstruimos la última pestaña con
        # la ventana principal todavía invisible y solo entonces la restauramos.
        self._cancel_role_drag()
        self._save_floating_bar_position()
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
            self._floating_bar_poll_id = None
        if self.floating_bar and self.floating_bar.winfo_exists():
            try:
                self.floating_bar.withdraw()
            except Exception:
                pass

        valid_pages = {"dashboard", "drafts", "team", "pc", "history", "settings", "help"}
        self.active_page = (
            self._last_main_page_before_floating
            if self._last_main_page_before_floating in valid_pages
            else "dashboard"
        )
        # Volver de la barra repintaba la página SIEMPRE, y eso cuesta 610 ms de
        # mediana y hasta 2576 medidos, todos en el hilo de Tk. Es la ráfaga que
        # el usuario oye como un corte de dos segundos en la música del juego:
        # un núcleo a tope mientras el emulador también lo necesita.
        #
        # Mientras se estaba en la barra la ventana solo estaba retirada, no
        # destruida: si nadie marcó la página como sucia y se vuelve a la misma,
        # el árbol que hay ya es el bueno.
        reutilizable = (
            getattr(self, "_pagina_del_body", None) == str(self.active_page)
            and self._widget_alive(getattr(self, "body", None))
            and not self._main_ui_dirty_while_floating
        )
        try:
            if not reutilizable:
                # La raíz sigue withdrawn, por lo que aquí no necesitamos WM_SETREDRAW
                # ni overlays: ningún estado intermedio puede llegar al usuario.
                self.render_page()
            self._main_ui_dirty_while_floating = False
            self.update_idletasks()
            self._reset_body_scroll()
            self.update_idletasks()
        finally:
            self._floating_role_reordered = False

        self._restore_main_window_maximized(settle_before_show=True)
        if reutilizable:
            # Red de seguridad barata: si alguna ruta olvidó marcar la página
            # como sucia, esto pone los datos de ahora sin reconstruir nada. Se
            # hace con la ventana ya visible porque exige los paneles mapeados,
            # y cuesta 37 ms medidos frente a los 610 de repintar.
            self.after(0, lambda: self._refrescar_team_pc_en_sitio())
        self._schedule_pending_faint_picker(700)

    def _shutdown_application(self) -> None:
        # Con RoleRun cerrado, ORAS/USUM/SM deben volver a enseñar exactamente
        # lo que diría su propia ROM/randomizer, sin ningún ajuste por rol.
        self._revert_oras_levelup_moves_mod()
        self._revert_usum_levelup_moves_mod()
        self._revert_sm_levelup_moves_mod()
        self._revert_xy_levelup_moves_mod()
        self._revert_gen5_levelup_moves()
        self._revert_hgss_levelup_moves()
        # Si se sale sin guardar, el overlay no debe quedarse mostrando una
        # proyección que nunca llegó al archivo. Restauramos el layout del save.
        if self.run.pending_changes and self.project and self.current_game:
            try:
                self.obs_sync.sync(self.project, self.current_game)
            except Exception:
                pass
        self._cancel_pending_ds_install(restore_changes=False)
        self._clear_oras_live_auto_apply()
        self._clear_oras_live_reconciliation()
        self._reset_faint_picker_runtime()
        if self.floating_bar:
            self._save_floating_bar_position()
            try:
                self.floating_bar.destroy()
            except Exception:
                pass
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
        if self._emulator_focus_poll_id:
            try:
                self.after_cancel(self._emulator_focus_poll_id)
            except Exception:
                pass
            self._emulator_focus_poll_id = None
        self.hotkey_manager.stop()
        self._role_run_foreground_gate_held = False
        self._ryujinx_input_gate.release(all_levels=True)
        if self._gamepad is not None:
            self._gamepad.close()
        self.save_watcher.stop()
        self.destroy()

    def _close_from_floating_bar(self) -> None:
        """Cierra solo la barra y deja RoleRun Manager minimizado.

        La X de la barra ya no representa "salir": el único cierre real de la
        aplicación es la X nativa de la ventana principal, donde se mantiene la
        confirmación de cambios pendientes.
        """
        self._cancel_role_drag()
        self._close_floating_launcher()
        self._save_floating_bar_position()
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
            self._floating_bar_poll_id = None
        if self.floating_bar and self.floating_bar.winfo_exists():
            try:
                self.floating_bar.destroy()
            except Exception:
                pass
        self.floating_bar = None
        self.floating_bar_images.clear()
        self._floating_bar_last_signature = None

        # Hacemos reaparecer la ventana principal únicamente para que Windows la
        # conserve como aplicación normal en la barra de tareas y, acto seguido,
        # la minimizamos. El guard evita que <Unmap>/<FocusOut> vuelvan a abrir
        # automáticamente la barra durante esta transición.
        self._set_auto_floating_guard_temporarily(650)
        try:
            self.deiconify()
            self.update_idletasks()
            self.iconify()
        except Exception:
            try:
                self.state("iconic")
            except Exception:
                pass
        self._floating_role_reordered = False

    @property
    def _floating_bar_config_path(self) -> Path:
        return CONFIG_DIR / "floating_bar.json"

    def _load_floating_enabled(self) -> bool:
        try:
            raw = json.loads((CONFIG_DIR / "floating_bar.json").read_text(encoding="utf-8-sig"))
            return bool(raw.get("enabled", True))
        except Exception:
            return True

    def _save_floating_enabled(self) -> None:
        path = self._floating_bar_config_path
        path.parent.mkdir(parents=True, exist_ok=True)
        try:
            raw = json.loads(path.read_text(encoding="utf-8-sig"))
        except Exception:
            raw = {}
        raw["enabled"] = bool(self._floating_enabled)
        path.write_text(json.dumps(raw, ensure_ascii=False, indent=2), encoding="utf-8")

    def _toggle_floating_enabled(self) -> None:
        self._floating_enabled = not bool(self._floating_enabled)
        self._save_floating_enabled()
        label = f"BARRA FLOTANTE · {'ON' if self._floating_enabled else 'OFF'}"
        label_var = getattr(self, "_floating_button_text", None)
        if label_var is not None:
            label_var.set(label)
        if not self._floating_enabled and self._floating_bar_is_visible():
            self.restore_from_floating_bar()
        elif self._floating_enabled and self.project and self.current_game:
            # ON es una acción explícita: abre la barra ahora, además de permitir
            # que el detector de foreground la muestre en usos posteriores.
            self.after(0, self.open_floating_bar)
        if self._widget_alive(getattr(self, "floating_bar_button", None)):
            self.floating_bar_button.configure(
                text=label,
                fg_color="#292315" if self._floating_enabled else "transparent",
            )
            # CTk conserva el valor inicial de ``text`` cuando se combina con
            # ``textvariable`` durante una reconstrucción de cabecera. Retirar
            # esa asociación hace que el texto recién configurado sea la única
            # autoridad visual.
            try:
                self.floating_bar_button._textvariable = None
                self.floating_bar_button._text_label.configure(text=label)
            except Exception:
                pass
        # El ON abre la barra en el siguiente ciclo. Forzamos antes el repintado
        # del botón para que no quede visualmente con el valor anterior mientras
        # la ventana principal se retira.
        flush = getattr(self, "update_idletasks", None)
        if callable(flush):
            flush()

    def _load_floating_bar_position(self) -> tuple[int, int]:
        try:
            import json
            raw = json.loads(self._floating_bar_config_path.read_text(encoding="utf-8-sig"))
            return int(raw.get("x", 80)), int(raw.get("y", 40))
        except Exception:
            return 80, 40

    def _save_floating_bar_position(self) -> None:
        if not self.floating_bar or not self.floating_bar.winfo_exists():
            return
        try:
            import json
            self._floating_bar_config_path.parent.mkdir(parents=True, exist_ok=True)
            raw = {}
            try:
                candidate = json.loads(self._floating_bar_config_path.read_text(encoding="utf-8-sig"))
                if isinstance(candidate, dict):
                    raw = candidate
            except Exception:
                raw = {}
            raw["x"] = self.floating_bar.winfo_x()
            raw["y"] = self.floating_bar.winfo_y()
            self._floating_bar_config_path.write_text(
                json.dumps(raw, indent=2, ensure_ascii=False) + "\n", encoding="utf-8",
            )
        except Exception:
            pass

    def open_floating_bar(self) -> None:
        if not bool(getattr(self, "_floating_enabled", True)):
            return
        if not self.project or not self.current_game:
            messagebox.showinfo("Sin Run activa", "Abre primero una partida para usar la barra flotante.")
            return
        # Un modal de sustitución se comporta igual que cualquier otro modal: se
        # suspende al volver a Azahar y se restaura al volver a RoleRun. Nunca debe
        # secuestrar la conmutación hacia la barra flotante.
        if self._floating_bar_opening:
            return
        try:
            if self.floating_bar is not None and not self.floating_bar.winfo_exists():
                self.floating_bar = None
        except Exception:
            self.floating_bar = None
        self._floating_bar_opening = True

        def release_opening_guard() -> None:
            self._floating_bar_opening = False

        # Si había un modal abierto, liberamos su grab antes de retirar la raíz.
        # Esto conserva el arreglo de alpha.31 sin mezclarlo con el pintado de la barra.
        self._suspend_modal_for_floating_bar()
        if self.active_page in {"dashboard", "drafts", "team", "tms", "pc", "history", "settings", "help"}:
            self._last_main_page_before_floating = self.active_page
        self._floating_role_reordered = False

        if self.floating_bar and self.floating_bar.winfo_exists():
            # Flujo estable previo al experimento de doble buffer: retirar primero
            # la ventana principal y después mapear/refrescar el Toplevel.
            #
            # Pedido por el usuario el 2026-09-03: un ``withdraw()`` puro deja la
            # raíz sin icono alguno en la barra de tareas de Windows mientras la
            # barra flotante está activa. ``deiconify()``+``iconify()`` —el mismo
            # truco que ya usaba ``_close_from_floating_bar`` al cerrar la
            # barra— conserva el icono real de RoleRun como ventana minimizada, y
            # pulsarlo dispara ``<Map>`` → ``_on_main_map``, que ya sabe volver
            # desde la barra flotante.
            self._set_auto_floating_guard_temporarily()
            self.deiconify()
            self.update_idletasks()
            self.iconify()
            self.floating_bar.deiconify()
            self._floating_bar_last_signature = None
            self._render_floating_bar(force=True)
            try:
                self.floating_bar.update_idletasks()
                self.floating_bar.lift()
                self.floating_bar.attributes("-topmost", True)
                self._apply_floating_bar_noactivate(self.floating_bar)
            except Exception:
                pass
            try:
                self.after(220, release_opening_guard)
            except Exception:
                release_opening_guard()
            return

        try:
            bar = ctk.CTkToplevel(self)
        except Exception:
            release_opening_guard()
            raise
        self.floating_bar = bar
        bar.overrideredirect(True)
        bar.attributes("-topmost", True)
        bar.configure(fg_color="#0F0F0F")
        x, y = self._load_floating_bar_position()
        bar.geometry(f"1380x112+{x}+{y}")
        bar.resizable(False, False)
        try:
            icon = RESOURCES_DIR / "icono_sin_fondo.ico"
            if icon.exists():
                bar.iconbitmap(icon)
        except Exception:
            pass

        def drag_start(event) -> None:
            if self._role_drag_source_identity and self._role_drag_context == "floating":
                return
            self._floating_bar_drag_origin = (event.x_root, event.y_root, bar.winfo_x(), bar.winfo_y())

        def drag_move(event) -> None:
            if self._role_drag_source_identity and self._role_drag_context == "floating":
                return
            if self._floating_bar_drag_origin is None:
                return
            sx, sy, wx, wy = self._floating_bar_drag_origin
            bar.geometry(f"+{wx + event.x_root - sx}+{wy + event.y_root - sy}")

        def drag_end(_event=None) -> None:
            self._floating_bar_drag_origin = None
            self._save_floating_bar_position()

        bar.bind("<ButtonPress-1>", drag_start)
        bar.bind("<B1-Motion>", drag_move)
        bar.bind("<ButtonRelease-1>", drag_end)
        # Los bindtags de un Toplevel reciben también eventos de sus descendientes.
        # Tras cualquier click que mantenga la barra visible, el fallback devuelve
        # el teclado al último emulador por si Windows/Tk ignoró NOACTIVATE.
        bar.bind(
            "<ButtonRelease-1>",
            lambda _event: self._schedule_emulator_focus_restore_from_bar(bar),
            add="+",
        )
        bar.bind(
            "<Map>",
            lambda _event: self.after(0, lambda: self._apply_floating_bar_noactivate(bar)),
            add="+",
        )

        def on_bar_destroy(event_obj) -> None:
            if getattr(event_obj, "widget", None) is not bar:
                return
            if self.floating_bar is bar:
                self.floating_bar = None
                self._floating_bar_last_signature = None
            release_opening_guard()

        bar.bind("<Destroy>", on_bar_destroy, add="+")

        # Este orden es intencionadamente el de la alpha.30: era el último ciclo
        # verificado en Windows que mostraba siempre la barra completa.
        #
        # Pedido por el usuario el 2026-09-03: mismo motivo que en la rama de
        # reutilización — ``deiconify()``+``iconify()`` conserva el icono real
        # de RoleRun en la barra de tareas, y pulsarlo devuelve la aplicación
        # (``_on_main_map`` ya sabe salir de la barra flotante desde ahí).
        self._set_auto_floating_guard_temporarily()
        self.deiconify()
        self.update_idletasks()
        self.iconify()
        self._floating_bar_last_signature = None
        self._render_floating_bar(force=True)
        try:
            bar.update_idletasks()
            bar.deiconify()
            bar.lift()
            bar.attributes("-topmost", True)
            self._apply_floating_bar_noactivate(bar)
        except Exception:
            pass
        try:
            self.after(260, release_opening_guard)
        except Exception:
            release_opening_guard()

    def _force_native_main_maximize(self, *, steal_foreground: bool = True) -> bool:
        """Fuerza SW_MAXIMIZE sobre el HWND real de Tk y su wrapper en Windows.

        ``steal_foreground=False`` (hallazgo del usuario 31-08-2026) hace lo
        mismo pero SIN ``SetForegroundWindow``: cargar una partida puede
        maximizar la raíz varias veces mientras el usuario ya está en el
        emulador, y cada una la traía de vuelta al frente. El tamaño/estado de
        la ventana sigue corrigiéndose igual; solo se deja de arrebatar el
        foco cuando el usuario ya se fue a otra ventana.
        """
        if os.name != "nt":
            return False
        try:
            self.update_idletasks()
            hwnd = int(self.winfo_id())
            if not hwnd:
                return False
            user32 = ctypes.windll.user32
            user32.GetParent.argtypes = [ctypes.c_void_p]
            user32.GetParent.restype = ctypes.c_void_p
            user32.ShowWindow.argtypes = [ctypes.c_void_p, ctypes.c_int]
            user32.ShowWindow.restype = ctypes.c_int
            user32.IsZoomed.argtypes = [ctypes.c_void_p]
            user32.IsZoomed.restype = ctypes.c_int
            user32.SetForegroundWindow.argtypes = [ctypes.c_void_p]
            user32.SetForegroundWindow.restype = ctypes.c_int
            targets = [hwnd]
            parent = int(user32.GetParent(ctypes.c_void_p(hwnd)) or 0)
            if parent and parent not in targets:
                targets.append(parent)
            SW_RESTORE = 9
            SW_MAXIMIZE = 3
            for target in targets:
                # Si la raíz estaba iconic/minimized, maximizar directamente puede
                # dejar al wrapper de Tk en el estado anterior. Restauramos y acto
                # seguido maximizamos ambos HWND.
                user32.ShowWindow(ctypes.c_void_p(target), SW_RESTORE)
                user32.ShowWindow(ctypes.c_void_p(target), SW_MAXIMIZE)
            if steal_foreground:
                foreground = parent or hwnd
                user32.SetForegroundWindow(ctypes.c_void_p(foreground))
            return any(bool(user32.IsZoomed(ctypes.c_void_p(target))) for target in targets)
        except Exception:
            return False

    def _force_native_main_foreground(self) -> bool:
        """Entrega de forma robusta el foreground de Windows a la ventana principal.

        La barra flotante lleva ``WS_EX_NOACTIVATE`` para que los clicks normales
        no quiten el teclado al emulador. Eso implica que, al pulsar el logo para
        volver voluntariamente a RoleRun, un simple ``SetForegroundWindow`` puede
        ser rechazado por las reglas de foreground-lock de Windows mientras Azahar
        sigue siendo la aplicación activa.

        Enlazamos temporalmente las colas de input del thread de RoleRun y del
        foreground actual, restauramos el HWND real/wrapper de Tk y pedimos la
        activación. El enlace se deshace siempre. No se deja TOPMOST permanente.
        """
        if os.name != "nt":
            return False
        attached: list[tuple[int, int]] = []
        try:
            self.update_idletasks()
            hwnd = int(self.winfo_id())
            if not hwnd:
                return False

            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32

            user32.GetParent.argtypes = [ctypes.c_void_p]
            user32.GetParent.restype = ctypes.c_void_p
            user32.GetForegroundWindow.restype = ctypes.c_void_p
            user32.GetWindowThreadProcessId.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            user32.GetWindowThreadProcessId.restype = ctypes.c_ulong
            user32.AttachThreadInput.argtypes = [ctypes.c_ulong, ctypes.c_ulong, ctypes.c_int]
            user32.AttachThreadInput.restype = ctypes.c_int
            user32.ShowWindow.argtypes = [ctypes.c_void_p, ctypes.c_int]
            user32.ShowWindow.restype = ctypes.c_int
            user32.BringWindowToTop.argtypes = [ctypes.c_void_p]
            user32.BringWindowToTop.restype = ctypes.c_int
            user32.SetForegroundWindow.argtypes = [ctypes.c_void_p]
            user32.SetForegroundWindow.restype = ctypes.c_int
            user32.SetActiveWindow.argtypes = [ctypes.c_void_p]
            user32.SetActiveWindow.restype = ctypes.c_void_p
            user32.SetFocus.argtypes = [ctypes.c_void_p]
            user32.SetFocus.restype = ctypes.c_void_p
            user32.SetWindowPos.argtypes = [
                ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int, ctypes.c_int,
                ctypes.c_int, ctypes.c_int, ctypes.c_uint,
            ]
            user32.SetWindowPos.restype = ctypes.c_int
            kernel32.GetCurrentThreadId.restype = ctypes.c_ulong
            kernel32.GetCurrentProcessId.restype = ctypes.c_ulong

            parent = int(user32.GetParent(ctypes.c_void_p(hwnd)) or 0)
            target = parent or hwnd
            foreground = int(user32.GetForegroundWindow() or 0)
            current_tid = int(kernel32.GetCurrentThreadId())
            target_tid = int(user32.GetWindowThreadProcessId(ctypes.c_void_p(target), None) or 0)
            foreground_tid = int(
                user32.GetWindowThreadProcessId(ctypes.c_void_p(foreground), None) or 0
            ) if foreground else 0

            # AttachThreadInput solo cuando los threads son distintos. El par se
            # registra para garantizar el detach aunque falle una API posterior.
            for a, b in ((current_tid, foreground_tid), (target_tid, foreground_tid)):
                if not a or not b or a == b or (a, b) in attached:
                    continue
                if user32.AttachThreadInput(ctypes.c_ulong(a), ctypes.c_ulong(b), 1):
                    attached.append((a, b))

            SW_RESTORE = 9
            SW_MAXIMIZE = 3
            HWND_TOPMOST = ctypes.c_void_p(-1)
            HWND_NOTOPMOST = ctypes.c_void_p(-2)
            SWP_NOSIZE = 0x0001
            SWP_NOMOVE = 0x0002
            SWP_SHOWWINDOW = 0x0040
            flags = SWP_NOSIZE | SWP_NOMOVE | SWP_SHOWWINDOW

            for candidate in (target, hwnd):
                user32.ShowWindow(ctypes.c_void_p(candidate), SW_RESTORE)
                user32.ShowWindow(ctypes.c_void_p(candidate), SW_MAXIMIZE)

            user32.BringWindowToTop(ctypes.c_void_p(target))
            # Pulso TOPMOST -> NOTOPMOST: coloca la ventana por delante sin dejar
            # RoleRun fijado sobre el emulador después de volver.
            user32.SetWindowPos(ctypes.c_void_p(target), HWND_TOPMOST, 0, 0, 0, 0, flags)
            user32.SetWindowPos(ctypes.c_void_p(target), HWND_NOTOPMOST, 0, 0, 0, 0, flags)
            user32.SetActiveWindow(ctypes.c_void_p(target))
            user32.SetForegroundWindow(ctypes.c_void_p(target))
            # El wrapper es el top-level nativo; el HWND de Tk es quien debe
            # recibir finalmente el foco de teclado.
            user32.SetFocus(ctypes.c_void_p(hwnd))

            resulting = int(user32.GetForegroundWindow() or 0)
            if not resulting:
                return False
            pid = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(ctypes.c_void_p(resulting), ctypes.byref(pid))
            return int(pid.value) == int(kernel32.GetCurrentProcessId())
        except Exception:
            return False
        finally:
            if os.name == "nt":
                try:
                    user32 = ctypes.windll.user32
                    for a, b in reversed(attached):
                        try:
                            user32.AttachThreadInput(ctypes.c_ulong(a), ctypes.c_ulong(b), 0)
                        except Exception:
                            pass
                except Exception:
                    pass

    def _retry_native_main_foreground(self) -> None:
        """Reintento corto tras el mapeo de Tk, solo si RoleRun aún no es foreground."""
        if os.name != "nt":
            return
        try:
            if str(self.state()) in {"withdrawn", "iconic"}:
                return
            if self._foreground_belongs_to_this_process():
                return
        except Exception:
            return
        self._force_native_main_foreground()

    def _restore_main_window_maximized(self, settle_before_show: bool = False) -> None:
        """Restaura la ventana principal sin exponer geometrías intermedias.

        ``withdraw()`` + ``state('zoomed')`` puede hacer que Windows enseñe durante
        unos frames el tamaño cliente anterior antes de recalcular grid/canvas. Para
        el retorno desde la barra usamos alpha=0 como cortina nativa: la ventana se
        mapea, maximiza y resuelve por completo antes de volver a ser visible.
        """
        self._set_auto_floating_guard_temporarily(650)
        alpha_hidden = False
        if settle_before_show and sys.platform.startswith("win"):
            try:
                self.attributes("-alpha", 0.0)
                alpha_hidden = True
            except Exception:
                alpha_hidden = False
        try:
            self.deiconify()
            self._force_native_main_maximize()
            try:
                self.state("zoomed")
            except Exception:
                try:
                    self.attributes("-zoomed", True)
                except Exception:
                    pass
            # Dos pasadas síncronas resuelven tamaño del HWND, sidebar, canvas y
            # scrollregion antes de permitir que el compositor muestre la ventana.
            self.update_idletasks()
            if settle_before_show:
                try:
                    self.state("zoomed")
                except Exception:
                    pass
                self.update_idletasks()
            # Última pasada nativa después de que Tk haya procesado geometría.
            self._force_native_main_maximize()
            self.lift()
            try:
                self.focus_force()
            except Exception:
                pass
        finally:
            if alpha_hidden:
                try:
                    self.attributes("-alpha", 1.0)
                except Exception:
                    pass
        if os.name == "nt":
            # El primer intento ocurre con la ventana ya visible. Dos reintentos
            # cortos cubren el intervalo en el que Tk/Windows termina de mapear el
            # wrapper. Cada retry se cancela de facto si RoleRun ya es foreground.
            self._force_native_main_foreground()
            try:
                self.after(60, self._retry_native_main_foreground)
                self.after(180, self._retry_native_main_foreground)
            except Exception:
                pass
        if self._floating_suspended_modal is not None:
            try:
                self.after(70, self._restore_suspended_modal_after_floating)
            except Exception:
                pass

    def close_floating_bar(self) -> None:
        # Cierre explícito de la barra = volver a dejar la aplicación minimizada.
        # Se mantiene como método público interno por compatibilidad con llamadas
        # futuras, delegando en el mismo flujo que usa el botón X.
        self._close_from_floating_bar()

    def restore_from_floating_bar(self) -> None:
        self._close_floating_launcher()
        # Volver a la ventana principal retira la barra a propósito. Sin esto,
        # el sondeo la confundiría con una barra tapada y la traería de vuelta.
        self._barra_oculta_por_tapado = False
        self._save_floating_bar_position()
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
            self._floating_bar_poll_id = None
        if self.floating_bar and self.floating_bar.winfo_exists():
            self.floating_bar.withdraw()
        self._restore_main_window_maximized()
        self._floating_role_reordered = False

    def _counter_is_automatic(self, key: str) -> bool:
        """Contadores cuyo valor lo gobierna el juego en esta Run.

        En los backends con progreso RAM demostrado, MEDALLAS procede del juego
        vivo. Mantener controles manuales crearía dos fuentes de verdad y podría
        desincronizar OBS/RoleRun.
        """
        if key != "medallas":
            return False
        engine_key = getattr(self.save_engine, "key", "")
        if engine_key == "bdsp":
            # Alpha.77 está demostrada exclusivamente para SP 1.3.0. No se
            # deshabilita el control manual de Diamante Brillante por analogía.
            return str(getattr(getattr(self, "current_game", None), "game", "")).upper() == "SP"
        return bool(engine_key in AUTOMATIC_BADGE_GAME_KEYS)

    def _floating_counter_cell(self, parent, key: str, icon: str, column: int, icon_image: ctk.CTkImage | None = None) -> None:
        value = int(self.project.counters.get(key, 0)) if self.project else 0
        cell = ctk.CTkFrame(parent, fg_color="#181818", corner_radius=10, border_width=1, border_color="#343434")
        cell.grid(row=0, column=column, padx=3, pady=7, sticky="nsew")
        # El símbolo ocupa la altura conjunta de los dos botones, pero conserva
        # márgenes suficientes para no salirse de la tarjeta del contador.
        ctk.CTkLabel(
            cell,
            text="" if icon_image else icon,
            image=icon_image,
            text_color=GOLD,
            font=ctk.CTkFont("Segoe UI Symbol", 40, "bold"),
            width=44,
            height=58,
        ).grid(row=0, column=0, rowspan=2, padx=(5, 1), pady=3)
        ctk.CTkLabel(
            cell,
            text=str(value),
            text_color=TEXT,
            font=ctk.CTkFont("Segoe UI", 17, "bold"),
            width=30,
        ).grid(row=0, column=1, rowspan=2, padx=(0, 1))
        if self._counter_is_automatic(key):
            ctk.CTkLabel(
                cell, text="AUTO", width=36, height=50, text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 8, "bold"),
            ).grid(row=0, column=2, rowspan=2, padx=(1, 5), pady=5)
        else:
            ctk.CTkButton(cell, text="+", width=24, height=24, corner_radius=6, fg_color=GOLD, hover_color="#D3AF70", text_color="#111111", command=lambda: self.adjust_run_counter(key, 1, source="barra flotante")).grid(row=0, column=2, padx=(1, 5), pady=(5, 1))
            ctk.CTkButton(cell, text="−", width=24, height=24, corner_radius=6, fg_color="#303030", hover_color="#454545", command=lambda: self.adjust_run_counter(key, -1, source="barra flotante")).grid(row=1, column=2, padx=(1, 5), pady=(1, 5))

    def _floating_bar_signature(self) -> tuple:
        counters = tuple(int(self.project.counters.get(k, 0)) for k in ("vidas", "pociones", "medallas", "drafteos")) if self.project else ()
        # La barra flotante representa siempre el equipo PROYECTADO, no solo el
        # guardado ya escrito. Así una sustitución Equipo ↔ PC se refleja al
        # instante aunque el usuario todavía no haya pulsado GUARDAR CAMBIOS.
        projected_party = self._projected_party()
        if self.project and self.project.pending_faints:
            dead_ids = {str(item.get("identity", "") or "") for item in self.project.pending_faints}
            projected_party = [p for p in projected_party if self._pokemon_identity(p) not in dead_ids]
        _occupants, _extras, positions, _extra_indices = self._team_role_grid_layout(
            projected_party,
        )
        pokemon_by_position = {
            int(positions[self._pokemon_identity(pokemon)]): pokemon
            for pokemon in projected_party
            if self._pokemon_identity(pokemon) in positions
        }
        roles = []
        for role_index, role in enumerate(ROLE_ORDER):
            role_key = ROLE_TO_KEY[role]
            pokemon = pokemon_by_position.get(role_index)
            identity = self._pokemon_visibility_identity(pokemon) if pokemon else None
            actual_role = self._effective_role(pokemon)[0] if pokemon else ""
            hidden = bool(
                pokemon and actual_role == role and self.project
                and self.project.hidden_roles.get(role_key) == identity
            )
            sprite_ready = bool(pokemon and self._sprite_source(pokemon) is not None)
            hp, max_hp, status = self._floating_health_values(pokemon)
            roles.append((
                role_key, identity, hidden, sprite_ready,
                hp, max_hp, status,
            ))
        # Estructurada a propósito: permite distinguir «solo cambiaron los PS»
        # de «cambió la composición», y actualizar en su sitio el primer caso.
        return (counters, tuple(roles))

    def _floating_hp_is_live(self, pokemon: SavePokemon | None) -> bool:
        """¿Los PS que va a pintar la barra son los de AHORA?

        06-09-2026, planteado por el usuario: «si la barra puede dejar de
        mostrar la vida correcta, eso hay que cambiarlo». Durante un combate,
        varios juegos solo miden los PS del Pokémon que está en el campo; los
        demás arrastran los del bloque de equipo, que en quinta está demostrado
        que no se actualiza hasta que el combate acaba. Pintar eso en verde es
        afirmar algo que no se ha medido.

        Se mira el mismo candidato que `_floating_health_values` elige como
        autoridad, para que la marca y el número no puedan discrepar.
        """
        if pokemon is None:
            return True
        snapshot = getattr(self, "_oras_live_health_snapshot", None)
        party = list(getattr(snapshot, "party", []) or [])
        if not party:
            return bool(getattr(pokemon, "hp_is_live", True))
        identity = self._pokemon_identity(pokemon)
        matches = [
            candidate for candidate in party
            if self._pokemon_identity(candidate) == identity
        ]
        if len(matches) != 1:
            return bool(getattr(pokemon, "hp_is_live", True))
        return bool(getattr(matches[0], "hp_is_live", True))

    def _floating_health_values(self, pokemon: SavePokemon | None) -> tuple[int, int, int]:
        """Devuelve salud live demostrada sin convertir una muestra provisional en KO.

        La party proyectada gobierna identidad/roles, pero durante la entrada en
        combate puede recibir temporalmente HP provisionales. La sonda live ya
        publica una party validada por identidad; cuando existe una coincidencia
        única y coherente, esa es la autoridad de salud de la barra flotante.
        """
        if pokemon is None:
            return (0, 0, 0)
        fallback = (
            int(getattr(pokemon, "current_hp", 0) or 0),
            int(getattr(pokemon, "max_hp", 0) or 0),
            int(getattr(pokemon, "status_condition", 0) or 0),
        )
        snapshot = getattr(self, "_oras_live_health_snapshot", None)
        party = list(getattr(snapshot, "party", []) or [])
        if not party:
            return fallback
        identity = self._pokemon_identity(pokemon)
        matches = [candidate for candidate in party if self._pokemon_identity(candidate) == identity]
        if len(matches) != 1:
            return fallback
        candidate = matches[0]
        hp = int(getattr(candidate, "current_hp", 0) or 0)
        max_hp = int(getattr(candidate, "max_hp", 0) or 0)
        if max_hp <= 0 or hp < 0 or hp > max_hp:
            return fallback
        return (
            hp,
            max_hp,
            int(getattr(candidate, "status_condition", 0) or 0),
        )

    @staticmethod
    def _floating_status_style(value: int) -> tuple[str, str] | None:
        """Color y sigla según PKHeX.Core.StatusCondition (PB8 0x94)."""
        status = int(value or 0)
        if 1 <= status <= 7:
            return "#75C8F0", "DOR"
        if status in {8, 128}:
            return "#A45AC7", "ENV"
        if status == 16:
            return "#E85B55", "QUE"
        if status == 32:
            return "#55D7E8", "CON"
        if status == 64:
            return "#E6C84F", "PAR"
        return None

    @staticmethod
    def _ryujinx_window_rect() -> tuple[int, int, int, int, int] | None:
        """Devuelve HWND y rectángulo del Ryujinx BDSP visible en Windows."""
        if os.name != "nt":
            return None
        try:
            user32 = ctypes.windll.user32
            result: list[tuple[int, int, int, int, int]] = []

            class RECT(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                            ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

            callback_type = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

            def inspect(hwnd, _lparam):
                if not user32.IsWindowVisible(hwnd):
                    return True
                length = int(user32.GetWindowTextLengthW(hwnd))
                if length <= 0:
                    return True
                buffer = ctypes.create_unicode_buffer(length + 1)
                user32.GetWindowTextW(hwnd, buffer, length + 1)
                title = buffer.value.casefold()
                if "ryujinx" not in title or "010018e011d92000" not in title:
                    return True
                rect = RECT()
                if user32.GetWindowRect(hwnd, ctypes.byref(rect)):
                    result.append((int(hwnd), int(rect.left), int(rect.top),
                                   int(rect.right), int(rect.bottom)))
                return False

            callback = callback_type(inspect)
            user32.EnumWindows(callback, 0)
            return result[0] if result else None
        except Exception:
            return None

    def _close_floating_launcher(self, *, resume_game: bool = True) -> None:
        launcher, self._floating_launcher = self._floating_launcher, None
        if launcher is not None:
            try:
                if launcher.winfo_exists():
                    try:
                        launcher.grab_release()
                    except Exception:
                        pass
                    launcher.destroy()
            except Exception:
                pass
        self._floating_menu_level = "closed"
        self._floating_launcher_close_button = None
        if resume_game:
            self._ryujinx_input_gate.release(all_levels=True)
        # Cerrar el menu mientras estaba escondido por tapadura no puede
        # devolver la barra encima de la aplicacion que tapa el juego: se le
        # pasa el testigo al sondeo, que ya sabe cuando toca traerla.
        escondido = self._menu_oculto_por_tapado
        self._menu_oculto_por_tapado = False
        if escondido:
            self._barra_oculta_por_tapado = True
            self._schedule_floating_bar_poll()
        bar = getattr(self, "floating_bar", None)
        if not escondido and not self._game_overlay_active and bar is not None:
            try:
                if bar.winfo_exists() and str(bar.state()) == "withdrawn":
                    bar.deiconify()
                    bar.lift()
            except Exception:
                pass
        # El overlay nunca altera pausa, maximizado ni geometría de Ryujinx.
        # Mantener el Toplevel con foco y grab activo basta para que las flechas
        # lleguen a RoleRun y no al juego.

    def _open_page_from_floating_launcher(self, page: str) -> None:
        self._enter_game_overlay(page)

    def _enter_game_overlay(self, page: str) -> None:
        """Muestra únicamente el contenido funcional sobre el juego pausado."""
        window = self._ryujinx_window_rect()
        launcher = self._floating_launcher
        if window is None or launcher is None or not launcher.winfo_exists():
            self.restore_from_floating_bar()
            self.after(80, lambda: self.navigate(page))
            return
        _hwnd, _left, _top, _right, _bottom = window
        self._game_overlay_active = True
        self._floating_menu_level = "page"
        self._game_overlay_previous_page = self.active_page
        self._game_overlay_original_body = self.body

        def compose() -> None:
            if not self._game_overlay_active:
                return
            try:
                for child in launcher.winfo_children():
                    child.destroy()
                overlay_body = ctk.CTkFrame(launcher, fg_color="transparent", corner_radius=0)
                # El rectángulo Win32 incluye barra de título y menú de Ryujinx.
                # Reservarlos evita que la primera fila quede bajo el chrome.
                overlay_body.place(relx=0.02, y=70, relwidth=0.96, relheight=0.88)
                overlay_body.grid_columnconfigure(0, weight=1)
                overlay_body.grid_rowconfigure(0, weight=1)
                launcher.update_idletasks()
                self.body = overlay_body
                self.active_page = normalize_navigation_target(page)
                self.render_page()
                launcher.update_idletasks()
                close = ctk.CTkButton(
                    launcher, text="×", width=48, height=48, corner_radius=14,
                    fg_color="#151515", hover_color=DANGER, border_width=2,
                    border_color=GOLD, text_color=TEXT,
                    font=ctk.CTkFont("Segoe UI", 24, "bold"),
                    command=self._return_to_floating_menu,
                )
                # Fuera de la cabecera de FICHA DEL POKÉMON: antes coincidía
                # físicamente con su flecha derecha y ambos botones se solapaban.
                close.place(relx=1.0, x=-18, y=14, anchor="ne")
                close.lift()
                self._game_overlay_close_button = close
                self._bind_floating_menu_keyboard(launcher)
                try:
                    launcher.grab_set()
                except Exception:
                    pass
                launcher.focus_force()
                launcher.update_idletasks()
            except Exception as exc:
                self._game_overlay_last_error = f"{type(exc).__name__}: {exc}"
                self._exit_game_overlay()

        self.after(160, compose)

    def _exit_game_overlay(self) -> None:
        if not self._game_overlay_active:
            return
        self._game_overlay_active = False
        if self._widget_alive(self._game_overlay_close_button):
            self._game_overlay_close_button.destroy()
        self._game_overlay_close_button = None
        launcher = self._floating_launcher
        for sequence, binding in self._game_overlay_key_bindings:
            try:
                if launcher is not None:
                    launcher.unbind(sequence, binding)
            except Exception:
                pass
        self._game_overlay_key_bindings.clear()
        try:
            if self._draft_view is not None:
                self._draft_view.destroy(); self._draft_view = None
            if self._global_tm_view is not None:
                self._global_tm_view.destroy(); self._global_tm_view = None
            if self._team_pc_view is not None:
                try:
                    destroy = getattr(self._team_pc_view, "destroy", None)
                    if callable(destroy):
                        destroy()
                    elif self._widget_alive(getattr(self._team_pc_view, "frame", None)):
                        self._team_pc_view.frame.destroy()
                finally:
                    self._team_pc_view = None
            if self._game_overlay_original_body is not None:
                self.body = self._game_overlay_original_body
            self._game_overlay_original_body = None
            if self._game_overlay_previous_page:
                self.active_page = self._game_overlay_previous_page
            self._game_overlay_previous_page = None
            self._close_floating_launcher(resume_game=False)
        finally:
            self.open_floating_bar()

    def _return_to_floating_menu(self) -> str:
        """Vuelve desde una sección al selector sin destruir el overlay."""
        launcher = self._floating_launcher
        if launcher is None or not self._widget_alive(launcher):
            self._exit_game_overlay()
            return "break"
        self._game_overlay_active = False
        if self._widget_alive(self._game_overlay_close_button):
            self._game_overlay_close_button.destroy()
        self._game_overlay_close_button = None
        try:
            if self._draft_view is not None:
                self._draft_view.destroy(); self._draft_view = None
            if self._global_tm_view is not None:
                self._global_tm_view.destroy(); self._global_tm_view = None
            if self._team_pc_view is not None:
                destroy = getattr(self._team_pc_view, "destroy", None)
                if callable(destroy):
                    destroy()
                elif self._widget_alive(getattr(self._team_pc_view, "frame", None)):
                    self._team_pc_view.frame.destroy()
                self._team_pc_view = None
        finally:
            if self._game_overlay_original_body is not None:
                self.body = self._game_overlay_original_body
            self._game_overlay_original_body = None
            if self._game_overlay_previous_page:
                self.active_page = self._game_overlay_previous_page
            self._game_overlay_previous_page = None
        self._show_floating_menu_home(launcher)
        return "break"

    def _capa_abierta_bloquea_el_menu(self) -> bool:
        """¿Hay una capa abierta que el menú flotante taparía?

        06-09-2026, reportado por el usuario: con RECUERDA-MOVIMIENTOS abierto,
        pulsar MENÚ en la barra flotante abría el lanzador ENCIMA, dejando el
        selector detrás y sin forma de volver a él. Estas capas se dibujan
        dentro de la ventana principal, así que no pueden competir por el foco
        con un Toplevel `-topmost`: hay que no abrirlo.
        """
        for atributo in (
            "_levelup_history_popover", "_move_info_popover", "_role_info_popover",
        ):
            capa = getattr(self, atributo, None)
            if capa is None:
                continue
            try:
                if capa.winfo_exists():
                    return True
            except Exception:
                # Una capa ya destruida no bloquea nada.
                continue
        return False

    def _toggle_floating_launcher(self) -> None:
        # Cerrar el lanzador siempre se permite; lo que no se permite es
        # ABRIRLO tapando una capa que el usuario todavía tiene delante.
        if self._floating_launcher is None and self._capa_abierta_bloquea_el_menu():
            return
        if self._floating_launcher is not None:
            try:
                if self._floating_launcher.winfo_exists():
                    self._close_floating_launcher()
                    return
            except Exception:
                self._floating_launcher = None
        bar = self.floating_bar
        if not bar or not bar.winfo_exists() or str(bar.state()) == "withdrawn":
            self.open_floating_bar()
            self.after(120, self._toggle_floating_launcher)
            return
        window = self._ryujinx_window_rect()
        launcher = ctk.CTkToplevel(bar)
        # El overlay consume cruceta/botones del mando. Ryujinx queda retenido
        # hasta cerrar la capa, sin cambiar tamaño, foco persistente ni ventana.
        self._ryujinx_input_gate.acquire()
        self._floating_launcher = launcher
        launcher.overrideredirect(True)
        launcher.attributes("-topmost", True)
        launcher.configure(fg_color="#090909")
        if window is not None:
            _hwnd, left, top, right, bottom = window
            launcher.geometry(f"{right-left}x{bottom-top}+{left}+{top}")
        else:
            launcher.geometry("1040x640+240+140")
        launcher.attributes("-alpha", 0.94)
        self._show_floating_menu_home(launcher)
        launcher.after(30, lambda: bar.withdraw() if bar.winfo_exists() else None)
        try:
            launcher.grab_set()
        except Exception:
            pass
        launcher.focus_force()
        # Windows sabe apilar ventanas mucho mejor que un sondeo cada medio
        # segundo: en cuanto el menu deja de ir por delante de todo, la
        # aplicacion a la que se cambia lo tapa ella sola, al instante.
        launcher.bind("<FocusOut>", self._menu_flotante_pierde_el_foco, add="+")
        launcher.bind("<FocusIn>", self._menu_flotante_recupera_el_foco, add="+")
        # El sondeo lo reprograma el repintado de la barra, y la barra acaba
        # de retirarse: sin esto el menu se queda sin nadie que lo vigile.
        self._menu_oculto_por_tapado = False
        self._schedule_floating_bar_poll()

    def _show_floating_menu_home(self, launcher) -> None:
        """Compone el selector raíz y conserva una sola autoridad de teclado."""
        for child in launcher.winfo_children():
            child.destroy()
        self._floating_menu_level = "home"
        shell = ctk.CTkFrame(launcher, width=850, height=430, fg_color="#151515",
                             corner_radius=24, border_width=2, border_color=GOLD)
        shell.place(relx=.5, rely=.5, anchor="center")
        shell.grid_propagate(False)
        shell.grid_columnconfigure((0, 1), weight=1, uniform="floating_menu")
        shell.grid_rowconfigure((1, 2), weight=1, uniform="floating_menu")
        ctk.CTkLabel(shell, text="ROLERUN", text_color=GOLD,
                     font=ctk.CTkFont("Segoe UI", 26, "bold")).grid(
                         row=0, column=0, columnspan=2, pady=(24, 10))
        self._floating_menu_buttons = []
        self._floating_menu_index = 0
        for index, (label, page) in enumerate((("EQUIPO Y PC", "team"), ("MOVIMIENTOS", "tms"),
                                               ("DRAFTEOS", "drafts"), ("BOLSA", "bag"))):
            row, column = 1 + index // 2, index % 2
            button = ctk.CTkButton(
                shell, text=label, height=125, fg_color="#222222", hover_color="#34302A",
                border_width=1, border_color="#4A3D25", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 20, "bold"),
                command=(lambda target=page: self._show_overlay_bag(shell)
                         if target == "bag" else self._open_page_from_floating_launcher(target)),
            )
            button.grid(row=row, column=column, sticky="nsew", padx=10, pady=10)
            self._floating_menu_buttons.append(button)
        settings = ctk.CTkButton(
            shell, text="⚙", width=42, height=42, corner_radius=12,
            fg_color="#222222", hover_color="#34302A", border_width=1,
            border_color="#4A3D25", text_color=GOLD,
            font=ctk.CTkFont("Segoe UI Symbol", 21, "bold"),
            command=self._open_settings_from_floating_launcher,
        )
        settings.place(relx=1.0, x=-18, y=18, anchor="ne")
        self._floating_menu_buttons.append(settings)
        # Un fallo se apunta en el momento o se pierde. Cierra el menú primero
        # para que la captura recoja lo que había debajo, no este panel.
        reportar = ctk.CTkButton(
            shell, text="⚑  GUARDAR FALLO", width=170, height=34, corner_radius=10,
            fg_color="#2A1D1D", hover_color="#3A2222", border_width=1,
            border_color=DANGER, text_color=DANGER,
            font=ctk.CTkFont("Segoe UI", 12, "bold"),
            command=self._reportar_bug_desde_el_menu,
        )
        reportar.place(relx=0.0, x=18, y=18, anchor="nw")
        self._floating_menu_buttons.append(reportar)
        close = ctk.CTkButton(
            launcher, text="×", width=44, height=44, corner_radius=13,
            fg_color="#151515", hover_color=DANGER, border_width=1,
            border_color=GOLD, command=self._close_floating_launcher,
        )
        close.place(relx=1.0, x=-24, y=22, anchor="ne")
        self._floating_launcher_close_button = close
        self._bind_floating_menu_keyboard(launcher)
        self._paint_floating_menu_selection()

    def _bind_floating_menu_keyboard(self, launcher) -> None:
        def move(_event, delta: int):
            if not self._floating_menu_buttons:
                return "break"
            self._floating_menu_index = (self._floating_menu_index + delta) % len(self._floating_menu_buttons)
            self._paint_floating_menu_selection()
            return "break"

        def direction(event, name: str, delta: int):
            if self._floating_menu_level in {"home", "bag"}:
                return move(event, delta)
            return self._dispatch_game_overlay_key(event, name)

        launcher.bind("<KeyPress-Left>", lambda event: direction(event, "left", -1))
        launcher.bind("<KeyPress-Right>", lambda event: direction(event, "right", 1))
        launcher.bind("<KeyPress-Up>", lambda event: direction(event, "up", -2))
        launcher.bind("<KeyPress-Down>", lambda event: direction(event, "down", 2))
        for sequence in self._floating_menu_control_bindings:
            try:
                launcher.unbind(sequence)
            except Exception:
                pass
        self._floating_menu_control_bindings.clear()
        controls = self.project.menu_keys if self.project else {"accept": "z", "back": "x"}
        for control, callback in (
            ("accept", self._accept_floating_overlay_key),
            ("back", self._back_floating_overlay_key),
        ):
            key = str(controls.get(control, "") or "").strip()
            if not key:
                continue
            sequence = f"<KeyPress-{key}>"
            launcher.bind(sequence, callback)
            self._floating_menu_control_bindings.append(sequence)
        launcher.focus_force()

    def _gamepad_discovery_is_due(self, now: float | None = None) -> bool:
        """Limita la búsqueda de Ryujinx a un intento cada pocos segundos.

        ``SDLGamepad.from_ryujinx_process`` enumera la tabla completa de procesos
        de Windows. Sin Ryujinx abierto —es decir, en todos los juegos salvo
        BDSP— eso ocurría en cada tick del bucle de mando, a 60 Hz y en el hilo
        de la interfaz. Medido en esta máquina: 2,36 ms por intento, o **142 ms
        de CPU por segundo (14 % de un núcleo)** dedicados exclusivamente a no
        encontrar nada, desde el splash y durante toda la sesión.

        Con el intervalo, conectar Ryujinx a mitad de sesión sigue detectándose;
        solo tarda unos segundos, que es imperceptible para el usuario.
        """
        moment = time.monotonic() if now is None else float(now)
        last = getattr(self, "_gamepad_discovery_last_attempt", None)
        if last is not None and moment - last < GAMEPAD_DISCOVERY_INTERVAL_SECONDS:
            return False
        self._gamepad_discovery_last_attempt = moment
        return True

    @perf.timed_aggregate("ui.poll_gamepad")
    def _poll_gamepad(self) -> None:
        """Publica flancos SDL2 y reserva automáticamente cada atajo.

        La asignación visible es siempre un solo botón. En su flanco inicial
        RoleRun retiene Ryujinx y mantiene la retención hasta soltarlo; dentro
        del overlay la conserva hasta cerrar el menú.
        """
        self._gamepad_poll_after_id = None
        try:
            # Debe ocurrir antes de leer o despachar el mando. Así el flanco que
            # navega RoleRun nunca alcanza también a Ryujinx en segundo plano.
            role_run_foreground = self._foreground_belongs_to_this_process()
            self._sync_role_run_foreground_input_gate()
            if self._gamepad is None and self._gamepad_discovery_is_due():
                self._gamepad = SDLGamepad.from_ryujinx_process()
            sample = self._gamepad.sample() if self._gamepad is not None else None
            # Sin mando enchufado no hay ningún flanco que pueda alcanzar al
            # emulador, y retenerlo sería coste puro. Se apunta aquí y lo lee la
            # retención en el siguiente ciclo, 16 ms después.
            self._hay_mando = bool(sample is not None and sample.connected)
            current = sample.pressed if sample and sample.connected else frozenset()
            previous = self._gamepad_previous_buttons
            pressed = current - previous
            self._gamepad_previous_buttons = current

            # Un botón está reservado mientras se mantenga pulsado, y ni un
            # ciclo más. Esto se hacía al final, DESPUÉS de los `return` de las
            # ramas «menú abierto» y «RoleRun delante», así que con el atajo de
            # fábrica —el menú flotante abre en milisegundos, mucho antes de que
            # el dedo suelte— el flanco de soltar se perdía y el botón se
            # quedaba reservado para siempre. A partir de ahí, las dos
            # liberaciones automáticas de la retención de Ryujinx exigen que el
            # conjunto esté vacío, y nunca lo estaba: el juego se congelaba cada
            # vez que el usuario volvía a él.
            #
            # Se cruza contra lo que sigue pulsado en vez de restar lo soltado
            # este ciclo: así también se limpia solo si alguna vez se pierde un
            # flanco entero.
            self._gamepad_reserved_buttons.intersection_update(current)

            # SDL entrega estado, no una cola de eventos. Generamos repetición
            # controlada para el D-pad: conserva cada flanco corto y permite
            # recorrer listas largas manteniendo pulsado, sin depender de que
            # Windows o Ryujinx fabriquen repeticiones.
            pressed, repeat_at = self._update_gamepad_navigation_repeat(
                current=current,
                previous=previous,
                repeat_at=getattr(self, "_gamepad_navigation_repeat_at", {}),
                now=time.monotonic(),
            )
            self._gamepad_navigation_repeat_at = repeat_at

            if self._gamepad_capture_action:
                candidate = next((name for name in BUTTON_NAMES if name in pressed), None)
                if candidate:
                    callback, self._gamepad_capture_callback = self._gamepad_capture_callback, None
                    self._gamepad_capture_action = None
                    if callable(callback):
                        callback(candidate)
                return

            launcher_open = self._widget_alive(self._floating_launcher)
            if launcher_open:
                directions = {
                    "dpad left": "left", "dpad right": "right",
                    "dpad up": "up", "dpad down": "down",
                }
                for button, direction in directions.items():
                    if button in pressed:
                        self._dispatch_controller_direction(direction)
                menu_buttons = (
                    self.project.controller_menu_buttons
                    if self.project else {"accept": "a", "back": "b"}
                )
                if menu_buttons.get("accept", "a") in pressed:
                    self._accept_floating_overlay_key()
                if menu_buttons.get("back", "b") in pressed:
                    self._back_floating_overlay_key()
                return

            if role_run_foreground:
                directions = {
                    "dpad left": "left", "dpad right": "right",
                    "dpad up": "up", "dpad down": "down",
                }
                for button, direction in directions.items():
                    if button in pressed:
                        self._dispatch_game_overlay_key(None, direction)
                menu_buttons = (
                    self.project.controller_menu_buttons
                    if self.project else {"accept": "a", "back": "b"}
                )
                if menu_buttons.get("accept", "a") in pressed:
                    self._accept_floating_overlay_key()
                if menu_buttons.get("back", "b") in pressed:
                    self._clear_active_view_selection()
                return

            if self._foreground_is_supported_emulator():
                for button in pressed:
                    action = self._controller_action_for_button(button)
                    if action and self._ryujinx_input_gate.acquire():
                        self._gamepad_reserved_buttons.add(button)
                        self._hotkey_action(action)

            if (
                self._ryujinx_input_gate.active
                and not self._gamepad_reserved_buttons
                and not self._widget_alive(self._floating_launcher)
            ):
                self._ryujinx_input_gate.release(all_levels=True)
        except Exception:
            try:
                if self._gamepad is not None:
                    self._gamepad.close()
            except Exception:
                pass
            self._gamepad = None
            self._gamepad_previous_buttons = frozenset()
            if not self._widget_alive(self._floating_launcher):
                self._ryujinx_input_gate.release(all_levels=True)
        finally:
            if self.winfo_exists():
                self._gamepad_poll_after_id = self.after(16, self._poll_gamepad)

    @staticmethod
    def _update_gamepad_navigation_repeat(
        *, current: frozenset[str], previous: frozenset[str],
        repeat_at: dict[str, float], now: float,
    ) -> tuple[frozenset[str], dict[str, float]]:
        """Convierte estado SDL en un flanco o una repetición inequívoca.

        Un toque humano puede durar algo más de 200 ms. Por eso la repetición no
        comienza hasta 450 ms: todos los taps cortos generan exactamente un
        movimiento, mientras una retención deliberada sigue recorriendo listas.
        """
        pressed = current - previous
        released = previous - current
        updated = dict(repeat_at)
        for button in ("dpad left", "dpad right", "dpad up", "dpad down"):
            if button in pressed:
                updated[button] = float(now) + 0.45
            elif button in current and float(now) >= float(
                updated.get(button, float(now) + 1.0)
            ):
                pressed = frozenset((*pressed, button))
                updated[button] = float(now) + 0.070
            elif button in released:
                updated.pop(button, None)
        return frozenset(pressed), updated

    def _controller_action_for_button(self, button: str) -> str | None:
        if not self.project:
            return None
        for action, configured in self.project.controller_hotkeys.items():
            if configured == button:
                return action
        return None

    def _dispatch_controller_direction(self, direction: str) -> None:
        if self._floating_menu_level in {"home", "bag"}:
            delta = {"left": -1, "right": 1, "up": -2, "down": 2}[direction]
            if self._floating_menu_buttons:
                self._floating_menu_index = (
                    self._floating_menu_index + delta
                ) % len(self._floating_menu_buttons)
                self._paint_floating_menu_selection()
            return
        self._dispatch_game_overlay_key(None, direction)

    def _dispatch_game_overlay_key(self, event, direction: str) -> str:
        view = RoleRunManager._active_navigation_view(self)
        callback = (getattr(view, "_move_direction_key", None)
                    or getattr(view, "_move", None)
                    or getattr(view, "_move_keyboard", None))
        if callable(callback):
            callback(event, direction)
            return "break"
        # Configuración, Ayuda, Registro y Consulta de movimientos no publican
        # ninguna vista navegable, así que aquí no había a quién despachar y el
        # mando se quedaba muerto: sin ratón no se podía ni abrir el menú
        # lateral para salir de esas páginas. El menú lateral es de la ventana,
        # no de la vista, y desde aquí se alcanza siempre.
        if not self._handle_sidebar_navigation(direction) and direction == "left":
            self._select_sidebar_from_content()
        return "break"

    def _accept_floating_overlay_key(self, event=None) -> str:
        if self._floating_menu_level in {"home", "bag"}:
            return self._invoke_floating_menu_selection()
        view = RoleRunManager._active_navigation_view(self)
        callback = (getattr(view, "_accept_keyboard_selection", None)
                    or getattr(view, "_accept", None)
                    or getattr(view, "_accept_keyboard", None))
        if callable(callback):
            callback(event)
            return "break"
        # Sin vista navegable, aceptar es aceptar en el menú lateral: es lo
        # único que hay que confirmar en esas páginas.
        self._accept_sidebar_from_content()
        return "break"

    def _back_floating_overlay_key(self, _event=None) -> str:
        if self._floating_menu_level == "home":
            self._close_floating_launcher()
        elif self._floating_menu_level == "bag":
            launcher = self._floating_launcher
            if launcher is not None:
                self._show_floating_menu_home(launcher)
        else:
            self._return_to_floating_menu()
        return "break"

    def _clear_active_view_selection(self) -> str:
        view = RoleRunManager._active_navigation_view(self)
        callback = (getattr(view, "_clear_keyboard_selection", None)
                    or getattr(view, "_clear", None)
                    or getattr(view, "_clear_keyboard", None))
        if callable(callback):
            callback(None)
        return "break"

    def _active_navigation_view(self):
        """Devuelve la única superficie autorizada para teclado y mando.

        Durante un flujo integrado (por ejemplo, elegir qué movimiento olvida
        una MT) ``active_page`` sigue siendo ``team``. Resolver solo por página
        enviaba el D-pad a la vista Equipo/PC que permanece debajo, mientras el
        teclado sí llegaba al flujo superior mediante sus bindings. La autoridad
        publicada por ``_set_navigation_owner`` es el contrato común real.
        """
        owner = getattr(self, "_navigation_owner", None)
        if owner is not None:
            marco = getattr(owner, "frame", None)
            if marco is None or self._widget_alive(marco):
                return owner
            # Su vista ya no existe. `render_page` la destruye al cambiar de
            # página y nadie soltaba la autoridad, así que el mando se seguía
            # despachando ahí: acababa escribiendo color sobre un canvas muerto,
            # el `TclError` subía hasta el `except` de `_poll_gamepad`, y ese
            # cierra el mando y lo pone a None. Para el usuario el mando se moría
            # al cambiar de sección, revivía a los dos segundos y se volvía a
            # morir en la siguiente pulsación. Sin un solo aviso.
            self._navigation_owner = None
        return (self._team_pc_view if self.active_page == "team" else
                self._global_tm_view if self.active_page == "tms" else
                self._draft_view if self.active_page == "drafts" else None)

    def _paint_floating_menu_selection(self) -> None:
        for index, button in enumerate(self._floating_menu_buttons):
            try:
                selected = index == self._floating_menu_index
                configurar_si_cambia(
                    button,
                    border_color="#73A9FF" if selected else "#4A3D25",
                    border_width=3 if selected else 1,
                )
            except Exception:
                pass

    def _invoke_floating_menu_selection(self):
        if self._floating_menu_buttons:
            self._floating_menu_buttons[self._floating_menu_index].invoke()
        return "break"

    def _reportar_bug_desde_el_menu(self) -> None:
        """Cierra el menú y guarda. La captura debe recoger el juego, no el menú."""
        self._close_floating_launcher()
        self.after(120, self.reportar_bug)

    def _open_settings_from_floating_launcher(self) -> None:
        """Cierra la capa de juego y abre Configuración en la ventana principal."""
        self._last_main_page_before_floating = "settings"
        self._close_floating_launcher(resume_game=False)
        self._floating_logo_to_dashboard()

    def _show_overlay_bag(self, shell) -> None:
        for child in shell.winfo_children():
            child.destroy()
        self._floating_menu_level = "bag"
        if self._widget_alive(self._floating_launcher_close_button):
            self._floating_launcher_close_button.configure(
                command=lambda: self._show_floating_menu_home(self._floating_launcher)
            )
        shell.grid_columnconfigure((0, 1, 2), weight=1, uniform="bag")
        ctk.CTkLabel(shell, text="BOLSA", text_color=GOLD,
                     font=ctk.CTkFont("Segoe UI", 28, "bold")).grid(
                         row=0, column=0, columnspan=3, pady=(38, 18))
        ctk.CTkButton(
            shell, text="←  MENÚ", width=110, height=34, fg_color="transparent",
            hover_color="#30291D", border_width=1, border_color="#4A3D25",
            text_color=GOLD,
            command=lambda: self._show_floating_menu_home(self._floating_launcher),
        ).place(x=22, y=20)
        definitions = (
            ("rare-candy.png", "CARAMELOS RAROS\nx999", "rare-candy", "Caramelo Raro", 999),
            ("max-repel.png", "REPELENTES MÁX.\nx999", "max-repel", "Repelente Máximo", 999),
            (None, "DINERO\n∞", "money-max", "Dinero máximo", 999999),
        )
        self._overlay_bag_images = []
        self._floating_menu_buttons = []
        self._floating_menu_index = 0
        feedback = ctk.CTkLabel(
            shell, text="Selecciona una utilidad.", text_color=MUTED,
            font=ctk.CTkFont("Segoe UI", 13, "bold"),
        )
        feedback.grid(row=2, column=0, columnspan=3, pady=(2, 22))

        def apply_utility(key: str, name: str, amount: int) -> None:
            feedback.configure(
                text=("Aplicando dinero máximo…" if key == "money-max"
                      else f"Aplicando {name} ×{amount}…"),
                text_color=GOLD,
            )
            feedback.update_idletasks()
            self.queue_inventory_change(key, name, amount)
            feedback.configure(
                text=("Dinero máximo enviado al juego."
                      if key == "money-max" else f"{name} ×{amount} enviado a la Bolsa."),
                text_color=SUCCESS,
            )
        for column, (filename, label, key, name, amount) in enumerate(definitions):
            image = None
            if filename:
                try:
                    source = Image.open(RESOURCES_DIR / "item_icons" / filename).convert("RGBA")
                    source.thumbnail((72, 72), Image.Resampling.LANCZOS)
                    image = ctk.CTkImage(light_image=source, dark_image=source, size=source.size)
                    self._overlay_bag_images.append(image)
                except Exception:
                    pass
            button = ctk.CTkButton(
                shell, text=label, image=image, compound="top", height=230,
                fg_color="#222222", hover_color="#34302A", border_width=2,
                border_color="#4A3D25", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 17, "bold"),
                command=lambda k=key, n=name, a=amount: apply_utility(k, n, a),
            )
            button.grid(row=1, column=column, sticky="nsew", padx=12, pady=16)
            self._floating_menu_buttons.append(button)
        self._paint_floating_menu_selection()
        if self._floating_launcher is not None:
            self._bind_floating_menu_keyboard(self._floating_launcher)

    def _schedule_floating_bar_poll(self) -> None:
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
        self._floating_bar_poll_id = self.after(500, self._poll_floating_bar)

    #: Cuánto del juego tiene que tapar otra ventana para retirar la barra. Un
    #: cuarto deja pasar una calculadora en una esquina y no un navegador encima.
    JUEGO_TAPADO = 0.25

    def _el_juego_esta_tapado(self) -> bool:
        """Si hay algo puesto encima del juego, en su misma pantalla.

        Cambiar a otra aplicación **no** basta: con dos monitores, mirar el
        navegador en el segundo deja el juego a la vista y la barra sigue
        haciendo falta.

        Y no se mira la ventana con foco sino la **pila de ventanas**. Con algo
        puesto delante del juego, pinchar en la otra pantalla no destapa el
        juego: el estorbo sigue donde estaba. Preguntar por la ventana activa
        respondía que no, y la barra volvía a aparecer encima de la aplicación
        que tapaba el juego.
        """
        if os.name != "nt":
            return False
        juego = int(getattr(self, "_last_supported_emulator_hwnd", 0) or 0)
        if not juego:
            return False
        # Las ventanas de RoleRun están encima del juego por diseño: la barra
        # flotante es exactamente eso.
        return mayor_tapadura(juego, {os.getpid()}) >= self.JUEGO_TAPADO

    def _menu_flotante_pierde_el_foco(self, _evento=None) -> None:
        """Deja de ir por delante de todo en cuanto se cambia de aplicacion.

        El sondeo tarda hasta medio segundo en enterarse y se nota. Windows no:
        una ventana normal se queda donde estaba y la aplicacion nueva se le
        pone encima sola, en el mismo gesto. El `-topmost` solo hace falta
        mientras el menu es lo que se esta mirando.

        Con dos monitores esto ademas sale gratis: pinchar en la otra pantalla
        no pone nada encima del juego, asi que el menu se queda a la vista sin
        que nadie tenga que decidirlo.
        """
        launcher = self._floating_launcher
        if not self._widget_alive(launcher):
            return
        # Tk tambien manda `FocusOut` cuando el foco salta a un boton de dentro
        # del propio menu. Eso no es cambiar de aplicacion.
        if self._foreground_belongs_to_this_process():
            return
        try:
            launcher.attributes("-topmost", False)
        except Exception:
            pass
        self._sondear_la_barra_ya()

    def _menu_flotante_recupera_el_foco(self, _evento=None) -> None:
        launcher = self._floating_launcher
        if not self._widget_alive(launcher):
            return
        try:
            launcher.attributes("-topmost", True)
            launcher.lift()
        except Exception:
            pass
        self._sondear_la_barra_ya()

    def _sondear_la_barra_ya(self) -> None:
        """Adelanta el sondeo en vez de esperar al siguiente turno de 500 ms."""
        if self._floating_bar_poll_id:
            try:
                self.after_cancel(self._floating_bar_poll_id)
            except Exception:
                pass
            self._floating_bar_poll_id = None
        try:
            self._floating_bar_poll_id = self.after(1, self._poll_floating_bar)
        except Exception:
            self._floating_bar_poll_id = None

    def _vigilar_el_menu_flotante(self) -> bool:
        """Retira el menu flotante cuando el juego deja de verse.

        El menu es un ``Toplevel`` sin marco, del tamano exacto de la ventana
        del juego y en ``-topmost``. Eso esta bien mientras se juega, que es
        para lo que existe, pero al cambiar a otra aplicacion se quedaba pintado
        encima de ella: RoleRun ocupando media pantalla del navegador.

        Se aplica la misma regla que a la barra —y por el mismo motivo, que lo
        que va encima del juego no pinta nada cuando el juego no se ve—, pero
        aqui se esconde en vez de destruirse: al volver, el menu sigue en la
        seccion donde estaba.

        Devuelve si se ha hecho cargo, para que el sondeo no siga con la barra.
        """
        launcher = self._floating_launcher
        if not self._widget_alive(launcher):
            self._menu_oculto_por_tapado = False
            return False
        try:
            oculto = str(launcher.state()) == "withdrawn"
        except Exception:
            self._menu_oculto_por_tapado = False
            return False
        if oculto and not self._menu_oculto_por_tapado:
            # Lo retiro otra cosa. Ese gesto se respeta.
            return True
        if self._el_juego_esta_tapado():
            if not oculto:
                self._esconder_el_menu_flotante(launcher)
            return True
        if oculto:
            self._devolver_el_menu_flotante(launcher)
        return True

    def _esconder_el_menu_flotante(self, launcher) -> None:
        try:
            launcher.grab_release()
        except Exception:
            pass
        try:
            launcher.withdraw()
        except Exception:
            return
        # Con el menu abierto, la barra y la ventana principal estan retiradas.
        # Esconder el menu sin mas dejaria a RoleRun sin ninguna ventana y sin
        # icono en la barra de tareas: desaparecido. Minimizado sigue estando.
        try:
            if str(self.state()) == "withdrawn":
                self.iconify()
        except Exception:
            pass
        # Mientras el menu no se ve no hay cruceta que interceptar, y dejar el
        # emulador retenido lo unico que consigue es congelar la partida
        # mientras el usuario esta en otra aplicacion.
        self._ryujinx_input_gate.release(all_levels=True)
        self._menu_oculto_por_tapado = True

    def _devolver_el_menu_flotante(self, launcher) -> None:
        self._menu_oculto_por_tapado = False
        try:
            launcher.deiconify()
            # Reaparecer no garantiza recuperar el `-topmost`, y un menu por
            # debajo del juego no se ve.
            launcher.attributes("-topmost", True)
            launcher.lift()
        except Exception:
            return
        try:
            if str(self.state()) == "iconic":
                self.withdraw()
        except Exception:
            pass
        self._ryujinx_input_gate.acquire()
        try:
            launcher.grab_set()
        except Exception:
            pass
        try:
            launcher.focus_force()
        except Exception:
            pass

    def _poll_floating_bar(self) -> None:
        self._floating_bar_poll_id = None
        if self._vigilar_el_menu_flotante():
            try:
                self._floating_bar_poll_id = self.after(500, self._poll_floating_bar)
            except Exception:
                self._floating_bar_poll_id = None
            return
        bar = self.floating_bar
        if not bar or not bar.winfo_exists():
            self._barra_oculta_por_tapado = False
            return
        oculta = str(bar.state()) == "withdrawn"
        if oculta and not self._barra_oculta_por_tapado:
            # La retiró otra cosa —volver a la ventana principal, un diálogo—.
            # Ese gesto se respeta.
            return

        if self._el_juego_esta_tapado():
            if not oculta:
                try:
                    self._save_floating_bar_position()
                    bar.withdraw()
                except Exception:
                    pass
                # En modo flotante la ventana principal está retirada, así que
                # esconder la barra dejaba a RoleRun sin ninguna ventana y sin
                # icono en la barra de tareas: desaparecía del todo. Minimizada
                # sigue estando ahí para volver a ella cuando se quiera.
                try:
                    if str(self.state()) == "withdrawn":
                        self.iconify()
                except Exception:
                    pass
                self._barra_oculta_por_tapado = True
            # El sondeo sigue vivo aunque la barra no se vea: en modo flotante la
            # ventana principal está retirada, así que nada más la traería de
            # vuelta cuando el juego vuelva a quedar despejado.
            try:
                self._floating_bar_poll_id = self.after(500, self._poll_floating_bar)
            except Exception:
                self._floating_bar_poll_id = None
            return

        if oculta:
            try:
                bar.deiconify()
                # La ventana principal vuelve a retirarse: en modo flotante solo
                # debe verse la barra, y se había minimizado únicamente para no
                # dejar a RoleRun sin icono mientras estaba escondida.
                if str(self.state()) == "iconic":
                    self.withdraw()
            except Exception:
                pass
            self._barra_oculta_por_tapado = False
        self._render_floating_bar(force=False)

    def _clear_floating_bar_render_children(self, bar) -> None:
        """Retira solo los widgets reconstruibles de la barra flotante.

        Los diálogos visibles pueden ser hijos lógicos del ``Toplevel`` de la
        barra para seguir en pantalla mientras el root principal está retirado.
        Un refresco de contadores/PS no debe destruir esas ventanas auxiliares.
        """
        protected = getattr(self, "_floating_modal_windows", ())
        for child in tuple(bar.winfo_children()):
            if child in protected:
                continue
            child.destroy()

    def _update_floating_bar_health_in_place(self, signature: tuple) -> bool:
        """Refresca solo las barras de PS de la barra flotante.

        Reconstruir la barra destruye todos sus widgets y vuelve a leer dos PNG
        del disco. En combate los PS cambian en cada ciclo del monitor, así que
        hacerlo entero era un parpadeo constante justo cuando el usuario más
        necesita mirarla.

        Devuelve ``False`` —y entonces se reconstruye como siempre— cuando cambia
        cualquier otra cosa: contadores, ocupante de un rol, visibilidad, sprite,
        la aparición o desaparición de un estado, o el cruce por cero de la vida,
        que cambia la barra por un carril neutro.
        """
        previous = self._floating_bar_last_signature
        if previous is None or not signature:
            return False
        try:
            old_counters, old_roles = previous
            new_counters, new_roles = signature
        except (TypeError, ValueError):
            return False
        if old_counters != new_counters or len(old_roles) != len(new_roles):
            return False

        pendientes = []
        for old_role, new_role in zip(old_roles, new_roles):
            # role_key, identidad, oculto y sprite deben ser idénticos: cualquier
            # diferencia ahí es un cambio de composición, no de salud.
            if old_role[:4] != new_role[:4]:
                return False
            if old_role[4:] == new_role[4:]:
                continue
            role_key = new_role[0]
            _identity, _hidden, _sprite, hp, max_hp, status = new_role[1:]
            entry = self._floating_health_widgets.get(role_key)
            if not entry:
                return False
            bar = entry.get("bar")
            fraction = max(0.0, min(1.0, hp / max_hp)) if max_hp > 0 else 0.0
            # Al 0 % la casilla no tiene barra sino un carril neutro, y un estado
            # que aparece o desaparece añade o quita una etiqueta: ninguno de los
            # dos casos se puede resolver moviendo un valor.
            if (bar is None) != (fraction <= 0.0):
                return False
            if bool(entry.get("has_status")) != bool(self._floating_status_style(status)):
                return False
            if bar is not None:
                pendientes.append((bar, fraction))

        if not pendientes:
            return True
        try:
            for bar, fraction in pendientes:
                if not bar.winfo_exists():
                    return False
                color = DANGER if fraction <= .25 else (GOLD if fraction <= .5 else SUCCESS)
                configurar_si_cambia(bar, progress_color=color)
                bar.set(fraction)
        except Exception:
            return False
        return True

    def _render_floating_bar(self, force: bool = False) -> None:
        bar = self.floating_bar
        if not bar or not bar.winfo_exists():
            return
        signature = self._floating_bar_signature()
        if not force and signature == self._floating_bar_last_signature:
            self._schedule_floating_bar_poll()
            return
        with perf.span("ui.floating_bar_health_in_place") as measure:
            en_su_sitio = self._update_floating_bar_health_in_place(signature)
            measure.add(applied=en_su_sitio)
        if en_su_sitio:
            self._floating_bar_last_signature = signature
            self._schedule_floating_bar_poll()
            return
        self._floating_bar_last_signature = signature
        self._floating_health_widgets.clear()
        # Un drag en curso referencia justo los widgets que este redibujo va a
        # destruir; cancelarlo aquí evita el fantasma huérfano (ver el bind_all
        # de respaldo en __init__) tratando la reconstrucción como lo que es
        # para el gesto: una interrupción, no un drop.
        if self._role_drag_context == "floating":
            self._cancel_role_drag()
        self._clear_floating_bar_render_children(bar)
        self.floating_bar_images.clear()
        self._floating_role_drop_targets = []
        shell = ctk.CTkFrame(bar, fg_color="#111111", corner_radius=14, border_width=2, border_color=GOLD)
        shell.pack(fill="both", expand=True, padx=1, pady=1)
        logo_image = None
        logo_source = RESOURCES_DIR / "rolerun_icon.png"
        if logo_source.exists():
            try:
                source = Image.open(logo_source).convert("RGBA")
                source.thumbnail((55, 55), Image.Resampling.LANCZOS)
                logo_image = ctk.CTkImage(light_image=source, dark_image=source, size=source.size)
                self.floating_bar_images["logo"] = logo_image
            except Exception:
                pass
        ctk.CTkButton(shell, text="" if logo_image else "RR", image=logo_image, width=68, height=72, fg_color="transparent", hover_color="#242424", command=self._floating_logo_to_dashboard).grid(row=0, column=0, padx=(7, 3), pady=7)
        self._floating_counter_cell(shell, "vidas", "♥", 1)
        self._floating_counter_cell(shell, "pociones", "⚕", 2)
        self._floating_counter_cell(shell, "medallas", "◆", 3)
        floating_draft_icon = None
        draft_source = RESOURCES_DIR / "draft.png"
        if draft_source.exists():
            try:
                source = Image.open(draft_source).convert("RGBA")
                source.thumbnail((44, 44), Image.Resampling.LANCZOS)
                floating_draft_icon = ctk.CTkImage(light_image=source, dark_image=source, size=source.size)
                self.floating_bar_images["draft_counter"] = floating_draft_icon
            except Exception:
                floating_draft_icon = None
        self._floating_counter_cell(shell, "drafteos", "", 4, icon_image=floating_draft_icon)
        projected_party = self._projected_party()
        if self.project and self.project.pending_faints:
            dead_ids = {str(item.get("identity", "") or "") for item in self.project.pending_faints}
            projected_party = [p for p in projected_party if self._pokemon_identity(p) not in dead_ids]
        _occupants, _extras, positions, extra_indices = self._team_role_grid_layout(
            projected_party,
        )
        pokemon_by_position = {
            int(positions[self._pokemon_identity(pokemon)]): pokemon
            for pokemon in projected_party
            if self._pokemon_identity(pokemon) in positions
        }
        for role_index, role in enumerate(ROLE_ORDER):
            offset = role_index + 5
            role_key = ROLE_TO_KEY[role]
            pokemon = pokemon_by_position.get(role_index)
            is_extra = role_index in extra_indices
            hidden = bool(
                pokemon and not is_extra and self.project
                and self.project.hidden_roles.get(role_key)
                == self._pokemon_visibility_identity(pokemon)
            )
            frame = ctk.CTkFrame(
                shell, width=94, height=86,
                fg_color="#171717" if hidden else "#202020", corner_radius=10,
                border_width=1, border_color="#444444" if hidden else GOLD,
            )
            frame.grid(row=0, column=offset, padx=3, pady=7, sticky="nsew")
            frame.grid_propagate(False)
            image = None
            if pokemon:
                source = self._sprite_source(pokemon)
                if source is not None:
                    source.thumbnail((58, 58), Image.Resampling.LANCZOS)
                    if hidden:
                        gray = source.convert("L").convert("RGBA")
                        gray.putalpha(source.getchannel("A").point(lambda a: int(a * 0.32)))
                        source = gray
                    image = ctk.CTkImage(light_image=source, dark_image=source, size=source.size)
                    self.floating_bar_images[role_key] = image
            # El sprite es una superficie de gesto, no un CTkButton. Así podemos
            # distinguir con precisión click corto (mostrar/ocultar) de drag real
            # (mover entre roles) sin que CustomTkinter ejecute un command al soltar.
            sprite_button = ctk.CTkLabel(
                frame,
                text="" if image else "—",
                image=image,
                width=86,
                height=45,
                fg_color="transparent",
                text_color=MUTED,
                font=ctk.CTkFont("Segoe UI", 22, "bold"),
            )
            sprite_button.pack(padx=2, pady=(2, 0))
            role_label = ctk.CTkLabel(
                frame,
                text="SIN ROL" if pokemon and is_extra else role.upper(),
                text_color=MUTED if hidden else GOLD,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
                height=18,
            )
            role_label.pack(fill="x", padx=3, pady=(0, 0))
            hp, max_hp, status = self._floating_health_values(pokemon)
            hp_fraction = max(0.0, min(1.0, hp / max_hp)) if max_hp > 0 else 0.0
            # El COLOR es la afirmación más fuerte de la barra: verde dice
            # «este está bien». Cuando los PS no están medidos ahora mismo
            # -durante un combate, para los que no están en el campo- se pinta
            # en gris neutro: se sigue viendo la última lectura buena, pero sin
            # afirmar que siga siendo cierta. Ver `_floating_hp_is_live`.
            hp_en_vivo = self._floating_hp_is_live(pokemon)
            hp_color = (
                (DANGER if hp_fraction <= .25 else (GOLD if hp_fraction <= .5 else SUCCESS))
                if hp_en_vivo else "#6E6E6E"
            )
            hp_row = ctk.CTkFrame(
                frame, width=82, height=9, fg_color="transparent", corner_radius=0,
            )
            hp_row.pack(fill="x", padx=6, pady=(0, 4))
            hp_row.pack_propagate(False)
            # CTkProgressBar conserva un cap redondeado del color de progreso aun
            # con valor 0. Eso fabricaba la raya roja visible en roles vacíos y
            # debilitados. Al 0% mostramos solo el carril neutro.
            hp_bar = None
            if pokemon is not None and hp_fraction > 0.0:
                hp_bar = ctk.CTkProgressBar(
                    hp_row, width=54, height=6,
                    fg_color="#383838", progress_color=hp_color,
                )
                hp_bar.pack(side="left", fill="x", expand=True, pady=1)
                hp_bar.set(hp_fraction)
            else:
                ctk.CTkFrame(
                    hp_row, width=54, height=6,
                    fg_color="#383838", corner_radius=3,
                ).pack(side="left", fill="x", expand=True, pady=1)
            status_style = self._floating_status_style(status)
            self._floating_health_widgets[role_key] = {
                "bar": hp_bar, "has_status": bool(status_style),
            }
            if status_style:
                color, short = status_style
                ctk.CTkLabel(
                    hp_row, text=short, width=20, height=8, corner_radius=3,
                    fg_color=color, text_color="#101010",
                    font=ctk.CTkFont("Segoe UI", 6, "bold"),
                ).pack(side="right", padx=(4, 0))
            # Toda casilla, incluso vacía, es un destino de rol. El rótulo nunca
            # cambia de posición; únicamente cambia el Pokémon que la ocupa.
            self._floating_role_drop_targets.append((frame, role))
            if pokemon:
                self._register_role_drag_surface(sprite_button, pokemon, "floating", frame, role)
                self._register_role_drag_surface(role_label, pokemon, "floating", frame, role)
                self._register_role_drag_surface(frame, pokemon, "floating", frame, role)
        # 06-09-2026: MENÚ es solo navegación -abre el lanzador de la app- y no
        # tiene nada que ver con si el backend puede curar en vivo. Estaba
        # enganchado a `_floating_live_actions_available()`, así que cualquier
        # juego sin curación (HeartGold, mientras su escritura siga apagada)
        # se quedaba SIN MENÚ también, aunque no tuviera ninguna relación. Se
        # separan: MENÚ siempre está, CURAR solo si el backend lo demuestra.
        actions = ctk.CTkFrame(shell, width=64, height=86, fg_color="transparent")
        actions.grid(row=0, column=11, padx=3, pady=7, sticky="n")
        actions.grid_propagate(False)
        if self._floating_live_actions_available():
            ctk.CTkButton(
                actions, text="♥ CURAR", width=62, height=38, corner_radius=9,
                fg_color="transparent", hover_color="#303030", text_color=GOLD,
                border_width=1, border_color=GOLD, command=self._heal_bdsp_party,
                font=ctk.CTkFont("Segoe UI", 9, "bold"),
            ).pack(pady=(0, 5))
        ctk.CTkButton(
            actions, text="☰ MENÚ", width=62, height=38, corner_radius=9,
            fg_color="#242424", hover_color="#343434", text_color=GOLD,
            border_width=1, border_color="#4A3D25", command=self._toggle_floating_launcher,
            font=ctk.CTkFont("Segoe UI", 8, "bold"),
        ).pack()
        ctk.CTkButton(shell, text="×", width=30, height=30, corner_radius=8, fg_color="transparent", hover_color=DANGER, text_color=MUTED, command=self._close_from_floating_bar).grid(row=0, column=12, padx=(3, 7), pady=7, sticky="n")
        self._schedule_floating_bar_poll()

    def _floating_live_actions_available(self) -> bool:
        """Expone las acciones que el backend activo puede ejecutar en vivo."""
        return RoleRunManager._live_party_heal_available(self)

    def _live_party_heal_available(self) -> bool:
        """Centraliza los backends con curación completa ya demostrada.

        B2/W2 quedó fuera en alpha.16 porque el botón se renderizaba sin tener
        writer: encolaba seis ``PendingPartyHeal`` que nadie escribía ni retiraba
        y, como el monitor exige la cola vacía para leer, dejaba la sesión viva
        sin lecturas. Vuelve en alpha.26 con su writer transaccional: PS al
        máximo, estado a cero y PP al tope con los Más PP aplicados.
        """
        return self._active_azahar_realtime_key() in (
            {"bdsp", "sm", "usum", "xy", "oras"} | MELONDS_WRITE_GAME_KEYS
        )

    # ---------- WELCOME / GAME SELECTION ----------

    # Cuarta generación no se ofrece en la selección.
    #
    # OCULTOS DE NUEVO el 07-09-2026, a petición explícita del usuario, tras
    # diez rondas seguidas de validación física del carril de combate en vivo
    # de HGSS (PS de combate + detección de desmayo) sin llegar a estabilizar
    # del todo -cada arreglo confirmado dejaba un caso real sin cubrir; ver
    # memoria `rolerun-retomados-hgss-dp-pt.md`-. Antes habían estado ocultos
    # una primera vez por una razón distinta y ya resuelta (`CHANGELOG.md`
    # alpha.87-97): cuatro «Huevo malo» al escribir, el último con una causa
    # que quedó SIN EXPLICAR (un campo `sanity` en un registro que rompió la
    # escritura sin que nadie llegara a identificar qué significa).
    # `MELONDS_GEN4_ESCRIBE` (más abajo) sigue en `False` por esa razón.
    #
    # Diamante/Perla y Platino no comparten ese historial de combate -no hay
    # NINGUNA dirección de RAM medida todavía para ellos, ni siquiera de solo
    # lectura, así que caen en el motor de archivo `.sav`-, pero se ocultan
    # junto con HGSS por la misma petición explícita.
    GAMES_OCULTOS: frozenset[str] = frozenset({"dp", "pt", "hgss"})

    #: Tamaño al que se pinta cada banner en el selector. Las capas del fundido
    #: se componen ya a esta medida: es lo que se ve, y evita nueve copias de
    #: 1040x224 por juego.
    WELCOME_TARJETA = (520, 112)

    #: La capa oscura cubre la tarjeta entera. Tapar solo la mitad de abajo
    #: —como hacía la franja de antes— cruzaba el título que los banners nuevos
    #: llevan dibujado dentro, y a media transición se leían dos superpuestos.
    WELCOME_FRANJA = (2, 2, 518, 110)
    WELCOME_FRANJA_RADIO = 15

    #: Dónde cae cada pieza del menú, en el mismo orden en que se pintan. Sirve
    #: para medir de qué color queda el banner justo debajo de cada una.
