    @staticmethod
    def _game_source_filetypes(game_key: str) -> list[tuple[str, str]]:
        """Filtros claros para el archivo que identifica una edición.

        El archivo se guarda como referencia local para abrir una Run; no se
        copia ni se modifica. Los motores que aún no lo usan directamente lo
        tendrán listo cuando incorporen lectura viva o datos randomizados.
        """
        if game_key in {"oras", "xy", "sm", "usum"}:
            return [
                ("ROM de Nintendo 3DS", "*.cxi *.3ds *.app"),
                ("Todos los archivos", "*.*"),
            ]
        if game_key in {"dp", "pt", "hgss", "bw", "b2w2"}:
            return [
                ("ROM de Nintendo DS", "*.nds"),
                ("Todos los archivos", "*.*"),
            ]
        if game_key == "bdsp":
            return [
                ("Juego de Nintendo Switch", "*.nsp *.xci *.nca"),
                ("Todos los archivos", "*.*"),
            ]
        return [("Archivo de juego", "*.*")]

    @staticmethod
    def _source_initial_dir(path_text: str) -> str:
        try:
            candidate = Path(path_text).expanduser()
            parent = candidate.parent if candidate.name else candidate
            if parent.is_dir():
                return str(parent)
        except OSError:
            pass
        return ""

    def _programar_fotograma(self, ms: int, funcion) -> bool:
        """Agenda un fotograma de animación. Devuelve si lo consiguió.

        No se apunta en `_welcome_animation_ids`, que solo se vacía al repintar
        la pantalla: un fotograma por cada movimiento del ratón la llenaría sin
        parar. Cada fundido se agota solo en diez fotogramas y cada uno
        comprueba que su widget siga vivo.
        """
        try:
            self.after(int(ms), funcion)
            return True
        except Exception:
            return False

    def _colores_bajo_el_menu(self, image_path) -> tuple[str, ...]:
        """El color del banner justo debajo de cada rótulo del menú.

        Es el color desde el que nace cada texto, para que aparezca fundiéndose
        en vez de encenderse de golpe. Se mide en lugar de suponerse porque los
        banners no se parecen entre sí: Sol/Luna es clarísimo y Blanca/Negra
        casi negro, así que un mismo color de partida dejaría un texto fantasma
        en uno de los dos.
        """
        neutro = tuple("#111111" for _sitio in self.WELCOME_SITIOS)
        try:
            if not image_path.exists():
                return neutro
            lienzo = Image.open(image_path).convert("RGB").resize(
                self.WELCOME_TARJETA, Image.LANCZOS,
            )
        except Exception:
            return neutro
        return tuple(
            fundido_de_tarjeta.color_medio(lienzo, sitio)
            for sitio in self.WELCOME_SITIOS
        )

    def _game_source_status(self, profile: GameSourceProfile) -> tuple[str, str]:
        if profile.is_available:
            if profile.start_new_run:
                return f"✓ NUEVA RUN LISTA · {profile.save_name}  ·  {profile.game_name}", GOLD
            return f"✓ {profile.save_name}  ·  {profile.game_name}", SUCCESS
        if profile.has_paths:
            return "⚠ Alguno de los archivos se ha movido", DANGER
        return "CONFIGURA PARTIDA + ARCHIVO DE JUEGO", MUTED

    def _set_selected_game_engine(self, game_key: str) -> bool:
        enabled = next((enabled for key, _label, enabled in self.GAME_OPTIONS if key == game_key), False)
        if not enabled:
            return False
        self.selected_game_key = game_key
        try:
            self.save_engine = self.engine_factory.create(game_key)
        except GameEngineError as exc:
            messagebox.showerror("Juego no disponible", str(exc))
            return False
        registry = getattr(self, "realtime_registry", None)
        if registry is not None:
            core = registry.core_for(game_key)
            if core is not None:
                self.realtime_core = core
        return True

    def _configure_game_sources(self, game_key: str, *, open_after: bool = False) -> None:
        """Pide y persiste la pareja de archivos de una edición concreta."""
        if not self._set_selected_game_engine(game_key):
            return
        profile = self.game_source_profiles.get(game_key)
        game_label = self._game_label(game_key)
        messagebox.showinfo(
            f"Archivos de {game_label}",
            "La primera vez, RoleRun guarda dos rutas locales:\n\n"
            "1. La partida guardada.\n"
            "2. El archivo de juego (ROM, .nds, .cxi, .nsp, etc.).\n\n"
            "No se copia ni se modifica ningún archivo. La próxima vez que elijas este juego se abrirá la partida directamente.\n"
            "Puedes reemplazar ambas rutas cuando empieces una Run distinta.",
            parent=self,
        )
        save_path = filedialog.askopenfilename(
            title=f"1 de 2 · Selecciona la partida de {game_label}",
            initialdir=self._source_initial_dir(profile.save_path),
            filetypes=[
                ("Guardados compatibles", "*.bin *.sav *.dat *.dsv *.main main"),
                ("Todos los archivos", "*.*"),
            ],
        )
        if not save_path:
            return
        game_path = filedialog.askopenfilename(
            title=f"2 de 2 · Selecciona el archivo de {game_label}",
            initialdir=self._source_initial_dir(profile.game_path),
            filetypes=self._game_source_filetypes(game_key),
        )
        if not game_path:
            return
        start_new_run = False
        if profile.has_paths:
            start_new_run = messagebox.askyesno(
                "¿Es una Run nueva?",
                "Has sustituido los archivos asociados a este juego.\n\n"
                "Pulsa SÍ si empiezas una partida/RoleRun distinta: se creará una Run nueva y se conservará la anterior.\n\n"
                "Pulsa NO solo si los mismos archivos se han movido de carpeta o quieres actualizar sus rutas.",
                parent=self,
            )
        try:
            stored = self.game_source_profiles.set(
                game_key, save_path, game_path, start_new_run=start_new_run,
            )
        except (OSError, ValueError) as exc:
            messagebox.showerror(
                "No se pudieron guardar los archivos",
                f"RoleRun no cambió la configuración anterior:\n\n{exc}",
                parent=self,
            )
            return
        if game_key == "oras":
            self._clear_oras_rom_tm_runtime_profile()
        elif game_key == "xy":
            self._clear_xy_rom_tm_runtime_profile()
        elif game_key == "sm":
            self._clear_sm_rom_tm_runtime_profile()
        elif game_key == "usum":
            self._clear_usum_rom_tm_runtime_profile()
        self._bdsp_tm_auto_checked = False
        if open_after:
            self.select_save(stored.save_path, force_new_run=stored.start_new_run)
            return
        if self._shell_built and self.current_game:
            self._smooth_render_page(preserve_scroll=True)
        else:
            self._render_welcome()

    def _open_configured_game(self, game_key: str) -> None:
        if not self._set_selected_game_engine(game_key):
            return
        profile = self.game_source_profiles.get(game_key)
        if not profile.is_available:
            self._configure_game_sources(game_key, open_after=True)
            return
        # Sun/Moon necesita Personal de la ROM efectiva para publicar las
        # estadísticas base y para construir PartyData al mover un PK7 desde
        # cajas. Se carga antes de arrancar el polling: el callback del writer
        # es deliberadamente libre de I/O y no puede descubrirla después desde
        # su hilo. No se usa una tabla genérica si la ROM no valida.
        if game_key == "sm":
            self._get_sm_rom_tm_profile(prompt=False)
        self.select_save(profile.save_path, force_new_run=profile.start_new_run)

    def _clear_root(self) -> None:
        # Invalida referencias a widgets de la pantalla anterior antes de
        # destruirlos. Algunos sprites y refrescos llegan de hilos/callbacks
        # asíncronos y, si conservan un CTkButton ya destruido, Tcl lanza
        # "invalid command name ...ctkbutton" al cambiar de partida.
        self.sprite_buttons.clear()
        self.sprite_images.clear()
        self.step_widgets.clear()
        self.nav_buttons.clear()
        self._sprite_refresh_scheduled = False

        # Las referencias de la shell anterior siguen siendo atributos Python
        # aunque Tcl ya haya destruido sus widgets. Se ponen a None para que
        # ningún callback asíncrono intente configurarlos durante el cambio
        # de partida.
        for attr in (
            "content",
            "sidebar", "sidebar_run", "page_title", "page_subtitle",
            "top_status", "header_actions", "floating_controls", "pending_controls", "review_changes_button",
            "discard_changes_button", "save_changes_button", "section_controls",
            "operation_bar", "body",
        ):
            setattr(self, attr, None)

        self._team_pc_view = None
        self._tm_teach_flow = None
        self._role_info_popover = None
        self._draft_view = None
        # Faltaba, y era la única de las cuatro que sobrevivía aquí. `render_page`
        # empieza destruyendo la vista anterior, así que al abrir otra Run
        # llamaba a `destroy()` sobre un árbol que `_clear_root` ya había
        # arrasado: «bad window path name .!ctkframeN…!ctkscrollableframe».
        self._global_tm_view = None
        self._global_tm_context = None
        self._global_tm_sin_mochila = ""
        self._global_tm_load_requested = False
        # Y la autoridad de teclado no puede apuntar a nada de lo anterior.
        self._navigation_owner = None
        self._team_pc_pending_incoming = None
        self._team_pc_pending_outgoing = None

        protected_overlay = getattr(self, "_loading_overlay", None)
        for child in self.winfo_children():
            # La barrera de apertura es un Toplevel hijo de la raíz. Debe
            # sobrevivir al reemplazo welcome→shell; destruirla aquí obligaba a
            # crear otra captura cuando la shell aún estaba a medio componer.
            if child is protected_overlay and self._widget_alive(protected_overlay):
                continue
            try:
                child.destroy()
            except Exception:
                pass

    @staticmethod
    def _blend_hex(start: str, end: str, amount: float) -> str:
        amount = max(0.0, min(1.0, amount))
        start = start.lstrip("#")
        end = end.lstrip("#")
        values = []
        for index in (0, 2, 4):
            a = int(start[index:index + 2], 16)
            b = int(end[index:index + 2], 16)
            values.append(round(a + (b - a) * amount))
        return "#" + "".join(f"{value:02X}" for value in values)

    def _render_startup_splash(self) -> None:
        """Presentación breve de marca antes del selector de juegos.

        Se construye dentro de la ventana principal para evitar destellos,
        cambios de tamaño o una segunda ventana durante el arranque.
        """
        self._shell_built = False
        self._clear_root()
        self.configure(fg_color=BG)

        splash = ctk.CTkFrame(self, fg_color=BG, corner_radius=0)
        splash.pack(expand=True, fill="both")

        content = ctk.CTkFrame(splash, fg_color="transparent")
        content.place(relx=0.5, rely=0.47, anchor="center")

        logo_label = ctk.CTkLabel(content, text="", fg_color="transparent")
        logo_label.pack(pady=(0, 34))
        title_label = ctk.CTkLabel(
            content, text="R O L E R U N", text_color=BG,
            font=ctk.CTkFont("Segoe UI", 44, "bold"),
        )
        title_label.pack()
        credit_label = ctk.CTkLabel(
            content, text="C R E A D O   P O R   T I M P E R", text_color=BG,
            font=ctk.CTkFont("Segoe UI", 20, "bold"),
        )
        credit_label.pack(pady=(14, 0))

        logo_path = RESOURCES_DIR / "rolerun_icon.png"
        try:
            logo_source = Image.open(logo_path).convert("RGBA")
            logo_source.thumbnail((300, 300), Image.Resampling.LANCZOS)
        except Exception:
            logo_source = None

        start_time = time.perf_counter()
        fade_in_ms = 400
        hold_ms = 1300
        fade_out_ms = 500
        total_ms = fade_in_ms + hold_ms + fade_out_ms

        def animate() -> None:
            if not splash.winfo_exists():
                return
            elapsed = (time.perf_counter() - start_time) * 1000.0
            if elapsed < fade_in_ms:
                opacity = elapsed / fade_in_ms
            elif elapsed < fade_in_ms + hold_ms:
                opacity = 1.0
            elif elapsed < total_ms:
                opacity = 1.0 - ((elapsed - fade_in_ms - hold_ms) / fade_out_ms)
            else:
                self._splash_after_id = None
                self._splash_image = None
                self._render_welcome()
                return

            opacity = max(0.0, min(1.0, opacity))
            title_label.configure(text_color=self._blend_hex(BG, GOLD, opacity))
            credit_label.configure(text_color=self._blend_hex(BG, "#D5D5D5", opacity))

            if logo_source is not None:
                frame = logo_source.copy()
                alpha = frame.getchannel("A").point(lambda value: round(value * opacity))
                frame.putalpha(alpha)
                self._splash_image = ctk.CTkImage(
                    light_image=frame, dark_image=frame, size=frame.size,
                )
                logo_label.configure(image=self._splash_image)

            self._splash_after_id = self.after(33, animate)

        animate()

    def _render_welcome(self) -> None:
        """Muestra un selector de juegos limpio con tarjetas animadas."""
        self._shell_built = False
        self._clear_root()
        self.configure(fg_color=BG)

        # Cancela animaciones de una pantalla anterior y conserva las imágenes
        # mientras los widgets estén vivos.
        for after_id in self._welcome_animation_ids:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._welcome_animation_ids.clear()
        self._welcome_card_images.clear()

        root = ctk.CTkFrame(self, fg_color=BG, corner_radius=0)
        root.pack(expand=True, fill="both")

        header = ctk.CTkFrame(root, fg_color="transparent")
        header.pack(fill="x", padx=58, pady=(30, 14))
        ctk.CTkLabel(
            header,
            text="SELECCIONA TU JUEGO",
            text_color=TEXT,
            font=ctk.CTkFont("Segoe UI", 31, "bold"),
        ).pack(anchor="w")
        ctk.CTkLabel(
            header,
            text="Elige una edición para abrir o crear su Run.",
            text_color=MUTED,
            font=ctk.CTkFont("Segoe UI", 12),
        ).pack(anchor="w", pady=(6, 0))

        grid = ctk.CTkFrame(root, fg_color="transparent")
        grid.pack(expand=True, fill="both", padx=50, pady=(0, 34))
        grid.grid_columnconfigure((0, 1), weight=1, uniform="games")
        # Las filas salen de los juegos que se ven, no de los que hay: con tres
        # ocultos sobraban filas vacías que encogían las tarjetas.
        visibles = [
            opcion for opcion in self.GAME_OPTIONS
            if opcion[0] not in self.GAMES_OCULTOS
        ]
        # +1: el hueco que deja un número impar de juegos lleva la tarjeta de
        # emuladores compatibles, no una fila vacía.
        filas = (len(visibles) + 2) // 2
        grid.grid_rowconfigure(tuple(range(filas)), weight=1, uniform="games")

        cards: list[tuple[ctk.CTkFrame, int, int]] = []

        for index, (key, label, enabled) in enumerate(visibles):
            row, column = divmod(index, 2)
            source_profile = self.game_source_profiles.get(key)
            source_status, source_color = self._game_source_status(source_profile)
            cell = ctk.CTkFrame(grid, fg_color="transparent", corner_radius=0)
            cell.grid(row=row, column=column, sticky="nsew", padx=8, pady=6)
            cell.grid_propagate(False)

            card = ctk.CTkFrame(
                cell,
                width=10,
                height=10,
                fg_color="#171717",
                corner_radius=17,
                border_width=1,
                border_color="#6E5934",
            )
            # CustomTkinter exige width/height en el constructor. Para animar,
            # place() solo recibe posición y dimensiones relativas.
            start_x = -70 if column == 0 else 70
            card.place(x=start_x, y=0, relwidth=1.0, relheight=1.0)

            # Los banners llevan el título dentro, así que en reposo la tarjeta
            # es solo el banner. La franja del menú se compone DENTRO de la
            # imagen —Tk no sabe de transparencias por widget— y el fundido es
            # cambiar de una capa a la siguiente.
            image_path = RESOURCES_DIR / "game_cards" / f"{key}.png"
            capas: list[ctk.CTkImage] = []
            image_label = None
            if image_path.exists():
                try:
                    source = Image.open(image_path).convert("RGBA")
                    # A tamaño de pantalla: es lo que se ve, y evita nueve
                    # copias de 1040x224 por cada juego.
                    lienzo = source.resize(self.WELCOME_TARJETA, Image.LANCZOS)
                    for capa in fundido_de_tarjeta.capas_de_la_franja(
                        lienzo, self.WELCOME_FRANJA,
                        radio=self.WELCOME_FRANJA_RADIO,
                    ):
                        imagen = ctk.CTkImage(
                            light_image=capa, dark_image=capa,
                            size=self.WELCOME_TARJETA,
                        )
                        self._welcome_card_images.append(imagen)
                        capas.append(imagen)
                    image_label = ctk.CTkLabel(
                        card, text="", image=capas[0], fg_color="transparent",
                    )
                    image_label.place(x=0, y=0, relwidth=1.0, relheight=1.0)
                except Exception:
                    capas = []
                    image_label = None

            # De qué color queda el banner justo debajo de cada rótulo. Es el
            # color desde el que nace su texto, y hay que medirlo: Sol/Luna es
            # clarísimo y Blanca/Negra casi negro, así que un mismo color de
            # partida dejaría un fantasma en uno de los dos.
            fondos = self._colores_bajo_el_menu(image_path)

            status = ctk.CTkLabel(
                card, text=source_status, text_color=source_color,
                font=ctk.CTkFont("Segoe UI", 9, "bold"),
            )

            title = ctk.CTkLabel(
                card,
                text=label.upper(),
                text_color=TEXT,
                font=ctk.CTkFont("Segoe UI", 15, "bold"),
            )

            files_button = ctk.CTkButton(
                card,
                text="ARCHIVOS",
                command=lambda game_key=key: self._configure_game_sources(game_key),
                width=94,
                height=30,
                corner_radius=10,
                fg_color="transparent",
                hover_color=PANEL_ALT,
                border_width=1,
                border_color="#6E5934",
                text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 10, "bold"),
            )
            button = ctk.CTkButton(
                card,
                text="ABRIR" if source_profile.is_available else "CONFIGURAR",
                command=lambda game_key=key: self._open_configured_game(game_key),
                width=106,
                height=30,
                corner_radius=10,
                fg_color=GOLD,
                hover_color="#D8B875",
                text_color="#101010",
                font=ctk.CTkFont("Segoe UI", 12, "bold"),
            )

            # (widget, sitio, colores finales). El sitio no se aplica hasta que
            # el texto empieza a revelarse: antes, la franja todavía deja ver el
            # banner y un rótulo encima se leería como suciedad.
            menu = (
                (status, {"relx": 0.5, "rely": 0.22, "anchor": "center"},
                 {"text_color": source_color}),
                (title, {"relx": 0.5, "rely": 0.44, "anchor": "center"},
                 {"text_color": TEXT}),
                (files_button, {"relx": 0.5, "x": -8, "rely": 0.72, "anchor": "e"},
                 {"text_color": GOLD, "border_color": "#6E5934"}),
                (button, {"relx": 0.5, "x": 8, "rely": 0.72, "anchor": "w"},
                 {"text_color": "#101010", "fg_color": GOLD}),
            )

            def pintar_menu(paso: int, piezas=menu, capas=capas,
                            fondos=fondos, lienzo_label=image_label) -> None:
                avance = paso / fundido_de_tarjeta.PASOS
                revelado = fundido_de_tarjeta.avance_del_texto(avance)
                if capas and self._widget_alive(lienzo_label):
                    lienzo_label.configure(image=capas[paso])
                for indice, (widget, sitio, colores) in enumerate(piezas):
                    if not self._widget_alive(widget):
                        continue
                    if revelado <= 0.0:
                        widget.place_forget()
                        continue
                    debajo = fundido_de_tarjeta.color_bajo_la_franja(
                        fondos[indice], avance,
                    )
                    widget.configure(**{
                        opcion: fundido_de_tarjeta.mezclar(debajo, final, revelado)
                        for opcion, final in colores.items()
                    })
                    widget.place(**sitio)

            # Un objeto por tarjeta, y se le pasa a `set_hover` como valor. Con
            # funciones anidadas que se nombraban entre sí, Python resolvía esos
            # nombres al ejecutarlas: al acabar el bucle las siete apuntaban a la
            # última y el menú solo salía en Perla Reluciente.
            animacion = fundido_de_tarjeta.Fundido(
                pintar_menu, self._programar_fotograma,
            )

            def set_hover(active: bool, target=card, fundido=animacion) -> None:
                try:
                    if not target.winfo_exists():
                        return
                    target.configure(
                        border_width=2 if active else 1,
                        border_color=GOLD if active else "#6E5934",
                    )
                    target.place_configure(y=-2 if active else 0)
                except Exception:
                    pass
                fundido.ir(fundido_de_tarjeta.PASOS if active else 0)

            pintar_menu(0)

            hover_widgets = [card, title, status, files_button, button]
            if image_label is not None:
                hover_widgets.append(image_label)
            for widget in hover_widgets:
                widget.bind("<Enter>", lambda _event, fn=set_hover: fn(True), add="+")
                widget.bind("<Leave>", lambda _event, fn=set_hover: fn(False), add="+")

            cards.append((card, column, start_x))

        # Tarjeta informativa: qué emulador usar para cada juego. Cae en el
        # mismo grid, en el hueco que deja un número impar de tarjetas (o en
        # una fila propia si son pares) -así el usuario sabe qué instalar sin
        # tener que adivinarlo juego a juego.
        grupos: dict[str, list[str]] = {}
        for key, label, _enabled in visibles:
            emulador = self.EMULADOR_POR_JUEGO.get(key)
            if emulador:
                grupos.setdefault(emulador, []).append(label)

        info_index = len(visibles)
        info_row, info_column = divmod(info_index, 2)
        info_cell = ctk.CTkFrame(grid, fg_color="transparent", corner_radius=0)
        info_cell.grid(row=info_row, column=info_column, sticky="nsew", padx=8, pady=6)
        info_cell.grid_propagate(False)

        info_card = ctk.CTkFrame(
            info_cell,
            width=10,
            height=10,
            fg_color="#171717",
            corner_radius=17,
            border_width=1,
            border_color="#6E5934",
        )
        info_start_x = -70 if info_column == 0 else 70
        info_card.place(x=info_start_x, y=0, relwidth=1.0, relheight=1.0)

        info_inner = ctk.CTkFrame(info_card, fg_color="transparent")
        info_inner.place(relx=0.5, rely=0.5, anchor="center", relwidth=0.9)

        ctk.CTkLabel(
            info_inner,
            text="EMULADORES COMPATIBLES",
            text_color=GOLD,
            font=ctk.CTkFont("Segoe UI", 12, "bold"),
        ).pack(anchor="w", pady=(0, 6))

        for emulador, etiquetas in grupos.items():
            fila = ctk.CTkFrame(info_inner, fg_color="transparent")
            fila.pack(anchor="w", fill="x", pady=2)
            ctk.CTkLabel(
                fila, text=emulador, text_color=TEXT,
                font=ctk.CTkFont("Segoe UI", 11, "bold"), width=110, anchor="w",
            ).pack(side="left")
            ctk.CTkLabel(
                fila, text=" · ".join(etiquetas), text_color=MUTED,
                font=ctk.CTkFont("Segoe UI", 10), anchor="w", justify="left",
            ).pack(side="left", fill="x", expand=True)

        cards.append((info_card, info_column, info_start_x))

        def animate_card(
            card: ctk.CTkFrame, column: int, origin: int, step: int = 0
        ) -> None:
            try:
                if not card.winfo_exists():
                    return
            except Exception:
                return
            total_steps = 17
            progress = min(1.0, step / total_steps)
            eased = 1.0 - (1.0 - progress) ** 3
            x = round(origin * (1.0 - eased))
            card.place_configure(x=x)
            if progress < 1.0:
                animation_id = self.after(16, lambda: animate_card(
                    card, column, origin, step + 1
                ))
                self._welcome_animation_ids.append(animation_id)

        # Entrada escalonada por filas, desde ambos laterales.
        for index, (card, column, origin) in enumerate(cards):
            delay = 70 + (index // 2) * 90 + column * 28
            animation_id = self.after(
                delay,
                lambda c=card, col=column, start=origin: animate_card(
                    c, col, start
                ),
            )
            self._welcome_animation_ids.append(animation_id)

        ctk.CTkLabel(
            root,
            text=f"Versión {APP_VERSION}",
            text_color=MUTED,
            font=ctk.CTkFont("Segoe UI", 10),
        ).place(relx=0.03, rely=0.972, anchor="sw")


    def _choose_game(self, game_key: str) -> None:
        """Alias para accesos antiguos: ahora abre el perfil persistente."""
        self._open_configured_game(game_key)

    def _enter_app_shell(self) -> None:
        if self._shell_built:
            return
        self._clear_root()
        self._build_layout()
        self._shell_built = True
        self._update_top_status()
        # En Windows abre la interfaz maximizada para aprovechar toda la pantalla
        # y facilitar su captura directa desde OBS.
        if not self._initial_shell_waiting:
            try:
                self.after_idle(lambda: self.state("zoomed"))
            except Exception:
                pass

    def _return_to_welcome(self) -> None:
        if self.run.pending_changes and not messagebox.askyesno(
            "Cambios sin guardar",
            "Hay cambios pendientes. Si cambias de partida se descartarán. ¿Continuar?",
        ):
            return
        self._session_generation += 1
        self._cancel_oras_initial_auto_sync()
        self._clear_oras_live_auto_apply()
        self._clear_oras_live_reconciliation()
        self._reset_faint_picker_runtime()
        self._oras_live_active = False
        self._oras_live_process_name = None
        self._clear_oras_rom_tm_runtime_profile()
        self._clear_sm_rom_tm_runtime_profile()
        self._clear_usum_rom_tm_runtime_profile()
        # Conservar la tabla personal de otra partida sería peor que no tener
        # ninguna: se escribirían estadísticas calculadas con datos ajenos.
        self._forget_b2w2_rom_profile()
        try:
            self.realtime_core.reset()
        except Exception:
            pass
        self._live_write_in_progress = False
        # Los trabajos en cola pertenecen a la partida que se abandona. Su
        # resultado tardio ya no debe cerrar nada ni reabrir la cola.
        self._olvidar_cola_de_cambios()
        self._pc_mostrado_con_datos = False
        self._pc_ultima_matriz_pintada = None
        self.hotkey_manager.stop()
        self.save_watcher.stop()
        self._cancel_pending_ds_install(restore_changes=False)
        self.project = None
        self.current_save = None
        self.current_game = None
        self.run = RunSession()
        self.selected_game_key = None
        self.active_page = DEFAULT_PAGE
        self._render_welcome()

    # ---------- LAYOUT ----------

    def _build_layout(self) -> None:
        self.grid_columnconfigure(0, minsize=76, weight=0)
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(0, weight=1)

        sidebar = ctk.CTkFrame(self, width=76, corner_radius=0, fg_color="#0B0B0B")
        sidebar.grid(row=0, column=0, sticky="nsew")
        sidebar.grid_propagate(False)
        # Los hijos se gestionan con pack. Sin bloquear también esta propagación,
        # el contenido expandido impone 285 px en el primer tick y hace invisible
        # cualquier interpolación de ``width``.
        sidebar.pack_propagate(False)
        self.sidebar = sidebar
        self.sidebar_expanded = False
        self.sidebar_scrim = None
        self.sidebar_scrim_image = None
        self.sidebar_source_capture = None
        self.sidebar_animation_id = None
