    def _toggle_sidebar(self) -> None:
        self._sidebar_navigation_selected = False
        self._set_sidebar_expanded(not bool(getattr(self, "sidebar_expanded", False)))

    def _select_sidebar_from_content(self) -> None:
        """Convierte el chevrón del borde en el destino más a la izquierda."""
        self._sidebar_navigation_selected = True
        self._set_content_navigation_focus(False)
        try:
            self.sidebar_toggle.configure(
                fg_color="#2A2417", border_width=2, border_color="#F2C45E",
            )
        except Exception:
            pass

    def _accept_sidebar_from_content(self) -> bool:
        if bool(getattr(self, "sidebar_expanded", False)):
            RoleRunManager._set_content_navigation_focus(self, False)
            entries = tuple(getattr(self, "_sidebar_keyboard_entries", ()))
            if entries:
                index = int(self._sidebar_keyboard_index) % (len(entries) + 1)
                # Hallazgo del usuario 31-08-2026: no había forma de alcanzar la
                # flecha "‹" de cerrar navegando con flechas/mando, solo con el
                # botón de "back" configurado. La posición extra, al final del
                # ciclo arriba/abajo, la representa: aceptar ahí cierra en vez
                # de navegar.
                if index == len(entries):
                    self._set_sidebar_expanded(False)
                else:
                    self.navigate(entries[index][0])
            return True
        if not bool(getattr(self, "_sidebar_navigation_selected", False)):
            return False
        self._sidebar_navigation_selected = False
        # Hallazgo del usuario 01-09-2026: aceptar aquí abría el drawer pero
        # nunca apagaba el borde dorado del chevrón "›" colapsado (solo lo
        # apagaba la rama "right"/"back" de `_handle_sidebar_navigation`).
        # Si en vez de eso el usuario aceptaba para entrar al drawer y luego
        # navegaba a una página, se quedaban DOS cosas marcadas como
        # seleccionadas a la vez: el chevrón y la tarjeta de la página nueva.
        try:
            self.sidebar_toggle.configure(fg_color="transparent", border_width=0)
        except Exception:
            pass
        self._set_sidebar_expanded(True)
        return True

    def _set_navigation_owner(self, view) -> None:
        """Publica una sola autoridad de teclado aunque sobrevivan vistas debajo."""
        self._navigation_owner = view
        if view is None:
            return
        view.navigation_guard = lambda current=view: self._navigation_owner is current
        if hasattr(view, "navigation_intercept"):
            view.navigation_intercept = self._handle_sidebar_navigation

    def _set_content_navigation_focus(self, active: bool) -> None:
        owner = getattr(self, "_navigation_owner", None)
        setter = getattr(owner, "set_external_navigation_focus", None)
        if callable(setter):
            setter(not bool(active))

    def _paint_sidebar_keyboard_selection(self) -> None:
        entries = tuple(getattr(self, "_sidebar_keyboard_entries", ()))
        selected = int(getattr(self, "_sidebar_keyboard_index", 0)) % (len(entries) + 1) if entries else -1
        for index, (page, button) in enumerate(entries):
            try:
                configurar_si_cambia(
                    button,
                    fg_color="#2A2417" if index == selected else (
                        "#242018" if page == self.active_page else "transparent"
                    ),
                    border_width=2 if index == selected else 0,
                    border_color="#F2C45E",
                    text_color=TEXT if index == selected else MUTED,
                )
            except Exception:
                pass
        drawer_toggle = getattr(self, "sidebar_drawer_toggle", None)
        if drawer_toggle is not None:
            try:
                cerrar_seleccionado = bool(entries) and selected == len(entries)
                configurar_si_cambia(
                    drawer_toggle,
                    fg_color="#2A2417" if cerrar_seleccionado else "transparent",
                    border_width=2 if cerrar_seleccionado else 0,
                    border_color="#F2C45E",
                )
            except Exception:
                pass

    def _handle_sidebar_navigation(self, direction: str) -> bool:
        """Da al drawer foco exclusivo y consume sus flechas."""
        direction = str(direction)
        if bool(getattr(self, "sidebar_expanded", False)):
            # El drawer abierto es un plano vertical exclusivo. Izquierda y
            # derecha no cierran ni devuelven el foco al contenido: hacerlo al
            # comienzo de la animación mostraba simultáneamente ambos cursores.
            RoleRunManager._set_content_navigation_focus(self, False)
            entries = tuple(getattr(self, "_sidebar_keyboard_entries", ()))
            if not entries:
                return True
            # +1: una posición extra al final del ciclo representa la flecha
            # "‹" de cerrar, para poder alcanzarla con arriba/abajo/mando y no
            # solo con el botón de "back" configurado.
            ciclo = len(entries) + 1
            if direction == "up":
                self._sidebar_keyboard_index = (self._sidebar_keyboard_index - 1) % ciclo
            elif direction == "down":
                self._sidebar_keyboard_index = (self._sidebar_keyboard_index + 1) % ciclo
            elif direction == "back":
                self._set_sidebar_expanded(False)
            elif direction == "right":
                # Pedido del usuario 01-09-2026: "derecha" pone el cursor sobre
                # la flecha de cerrar; "derecha" otra vez (ya sobre ella) cierra
                # el drawer y entrega el foco al primer botón de la pestaña.
                if self._sidebar_keyboard_index != len(entries):
                    self._sidebar_keyboard_index = len(entries)
                else:
                    self._set_sidebar_expanded(False)
                    self._focus_first_content_item()
                    return True
            self._paint_sidebar_keyboard_selection()
            return True
        if bool(getattr(self, "_sidebar_navigation_selected", False)):
            if direction == "left":
                # Pedido del usuario 01-09-2026: con el chevrón "›" colapsado
                # ya seleccionado, "izquierda" abre el menú — lo mismo que
                # aceptar sobre él.
                self._accept_sidebar_from_content()
                return True
            if direction in {"right", "back"}:
                self._sidebar_navigation_selected = False
                self._set_content_navigation_focus(True)
                try:
                    self.sidebar_toggle.configure(
                        fg_color="transparent", border_width=0,
                    )
                except Exception:
                    pass
            return True
        return False

    def _focus_first_content_item(self) -> None:
        """Entrega el foco a la pestaña activa, seleccionando su primer ítem.

        Pedido del usuario 01-09-2026: no basta con restaurar lo que
        estuviera marcado antes de abrir el menú — debe ser SIEMPRE el
        primero. `TeamPCSelectionState.move_direction` ya resuelve "primero"
        cuando `active` es `False`, cualquiera que sea la dirección — apagar
        `active` y reenviar un movimiento cualquiera reutiliza esa regla en
        vez de duplicarla aquí.
        """
        self._set_content_navigation_focus(True)
        view = RoleRunManager._active_navigation_view(self)
        selection = getattr(view, "selection", None)
        if selection is not None and hasattr(selection, "active"):
            selection.active = False
        mover = getattr(view, "_move_direction_key", None)
        if callable(mover):
            mover(None, "down")

    def _set_collapsed_sidebar_hover(self, hovered: bool) -> None:
        if bool(getattr(self, "sidebar_expanded", False)):
            return
        try:
            self.sidebar.configure(fg_color="#151515" if hovered else "#0B0B0B")
        except Exception:
            pass

    def _set_sidebar_expanded(self, expanded: bool) -> None:
        sidebar = getattr(self, "sidebar", None)
        drawer = getattr(self, "sidebar_drawer", None)
        if not self._widget_alive(sidebar) or not self._widget_alive(drawer):
            return
        expanded = bool(expanded)
        if expanded == bool(getattr(self, "sidebar_expanded", False)):
            return
        self.sidebar_expanded = expanded
        if expanded:
            # Capturado en vídeo por el usuario el 03-09-2026: durante el cierre,
            # un fotograma suelto dejaba ver el «›» colapsado junto al «‹» del
            # drawer, que técnicamente siguen siendo dos widgets superpuestos
            # hasta que `place_forget()` retira el drawer al terminar. En vez de
            # depender solo del apilado (frágil ante cualquier repintado del
            # compositor de Windows), el «›» deja de tener glifo mientras el
            # drawer exista de cualquier forma -abriendo, abierto o cerrando-, y
            # solo vuelve a dibujarse cuando `place_forget()` ya lo dejó atrás.
            try:
                self.sidebar_toggle.configure(text="")
            except Exception:
                pass
            self._sidebar_navigation_selected = False
            self._set_content_navigation_focus(False)
            entries = tuple(getattr(self, "_sidebar_keyboard_entries", ()))
            for index, (page, _button) in enumerate(entries):
                if page == self.active_page:
                    self._sidebar_keyboard_index = index
                    break
            self._paint_sidebar_keyboard_selection()
        animation_id = getattr(self, "sidebar_animation_id", None)
        if animation_id:
            try:
                self.after_cancel(animation_id)
            except Exception:
                pass
        self.sidebar_animation_id = None

        if expanded and not self._widget_alive(getattr(self, "sidebar_scrim", None)):
            # Tk no ofrece transparencia real entre widgets hermanos. Capturamos
            # únicamente el contenido ya pintado y mostramos una copia oscurecida:
            # la página sigue siendo reconocible, pero la interacción queda
            # inequívocamente detrás del menú y un click la cierra.
            try:
                self.update_idletasks()
                content = self.content
                content_x = int(content.winfo_x())
                content_y = int(content.winfo_y())
                width = max(1, min(
                    int(content.winfo_width()), int(self.winfo_width()) - content_x,
                ))
                height = max(1, min(
                    int(content.winfo_height()), int(self.winfo_height()) - content_y,
                ))
                marca = time.perf_counter() if perf.ENABLED else 0.0
                capture = ImageGrab.grab(bbox=(
                    int(content.winfo_rootx()), int(content.winfo_rooty()),
                    int(content.winfo_rootx()) + width,
                    int(content.winfo_rooty()) + height,
                ), all_screens=True).convert("RGB")
                if capture.size != (width, height):
                    capture = capture.resize((width, height), Image.Resampling.LANCZOS)
                if perf.ENABLED:
                    perf.record(
                        "ui.sidebar.apertura.captura",
                        (time.perf_counter() - marca) * 1000.0,
                        ancho=int(width), alto=int(height),
                    )
                    marca = time.perf_counter()
                # Conservamos también el frame limpio, anterior al oscurecido.
                # Si el usuario navega desde el drawer, esta será la autoridad
                # visual de la transición: recapturar tras retirar el scrim podía
                # mezclar zonas que DWM ya había iluminado con otras todavía oscuras.
                self.sidebar_source_capture = capture.copy()
                capture = ImageEnhance.Brightness(capture).enhance(0.28)
                self.sidebar_scrim_image = ImageTk.PhotoImage(capture)
                if perf.ENABLED:
                    # Lo que costaría UN fotograma de un fundido por imagen:
                    # oscurecer a otro nivel y volver a subirlo a Tk.
                    perf.record(
                        "ui.sidebar.apertura.oscurecer_y_subir",
                        (time.perf_counter() - marca) * 1000.0,
                    )
                scrim = tk.Label(
                    self, image=self.sidebar_scrim_image,
                    borderwidth=0, highlightthickness=0, background="#080808",
                )
            except Exception:
                self.sidebar_source_capture = None
                content = self.content
                content_x = int(content.winfo_x())
                content_y = int(content.winfo_y())
                width = max(1, min(
                    int(content.winfo_width()), int(self.winfo_width()) - content_x,
                ))
                height = max(1, min(
                    int(content.winfo_height()), int(self.winfo_height()) - content_y,
                ))
                scrim = tk.Frame(self, background="#101010", borderwidth=0)
            # El rectángulo debe coincidir exactamente con el contenido capturado.
            # ``x=76`` + ``relwidth=1`` excedía el ancho de la ventana y desplazaba
            # la imagen oscura, percibida como una ampliación repentina.
            scrim.place(x=content_x, y=content_y, width=width, height=height)
            scrim.bind("<Button-1>", lambda _event: self._set_sidebar_expanded(False), add="+")
            self.sidebar_scrim = scrim
            scrim.lift()

        if expanded:
            # El drawer ya está maquetado a 285 px fuera de pantalla. No hay
            # pack/grid ni redibujado estructural durante la interpolación.
            start_x = int(getattr(self, "sidebar_drawer_x", -285))
            drawer.place(x=start_x, y=0, relheight=1.0)
            drawer.lift()
        else:
            start_x = int(getattr(self, "sidebar_drawer_x", 0))
        self._animate_sidebar_drawer(start_x, 0 if expanded else -285, expanded)

    def _animate_sidebar_drawer(self, start_x: int, target_x: int, opening: bool) -> None:
        """Desplaza un drawer ya compuesto; nunca redimensiona sus descendientes."""
        # 260 ms no eran solo animación: al elegir destino desde el menú, la
        # navegación no arranca hasta que el drawer termina de cerrarse -ver
        # `navigate`, que guarda `_pending_sidebar_navigation` y sale-, así que
        # se sumaban enteros al camino más usado para cambiar de sección. A 140
        # el gesto sigue leyéndose como un deslizamiento y son 120 ms menos.
        duration_ms = 140
        started = time.perf_counter()
        drawer = self.sidebar_drawer
        # Instrumentación del tirón al cerrar (01-09-2026). Con `ROLERUN_PERF`
        # apagado —el caso normal— `perf.ENABLED` es False y esto no cuesta
        # nada: ni un `perf_counter` de más.
        ultimo_fotograma = [started]

        def frame() -> None:
            if bool(getattr(self, "sidebar_expanded", False)) != bool(opening):
                return
            ahora = time.perf_counter()
            if perf.ENABLED:
                perf.record(
                    "ui.sidebar.frame", (ahora - ultimo_fotograma[0]) * 1000.0,
                    opening=bool(opening),
                )
                ultimo_fotograma[0] = ahora
            elapsed = (ahora - started) * 1000.0
            progress = max(0.0, min(1.0, elapsed / duration_ms))
            # Ease-out cúbico: respuesta inmediata al click y desaceleración
            # continua al llegar, sin el arranque lento de smoothstep.
            eased = 1.0 - ((1.0 - progress) ** 3)
            x = round(start_x + (target_x - start_x) * eased)
            self.sidebar_drawer_x = x
            self.sidebar_animation_width = max(0, min(285, 285 + x))
            try:
                drawer.place_configure(x=x)
            except Exception:
                return
            if progress < 1.0:
                # ``place_configure`` invalida el canvas y Tk procesa ese pintado
                # después de que termine el callback. Añadir aquí otros 16 ms
                # duplicaba el intervalo real hasta ~31 ms en Windows. Cuatro
                # milisegundos mantienen varias posiciones disponibles por cada
                # refresco de 60 Hz sin saturar el mainloop con ticks duplicados.
                # Un fotograma. A 4 ms se encolaban ~65 callbacks que competían
                # con la construcción de la página en el mismo hilo.
                self.sidebar_animation_id = self.after(12, frame)
                return
            self.sidebar_animation_id = None
            self.sidebar_drawer_x = target_x
            self.sidebar_animation_width = 285 if opening else 0
            if not opening:
                marca = time.perf_counter() if perf.ENABLED else 0.0
                # Sacar el drawer del gestor de geometría elimina también su
                # superficie de dibujo. Dejarlo simplemente en x=-285 conservaba
                # en algunos frames los píxeles del tirador «‹» junto al «›» real.
                try:
                    drawer.place_forget()
                    self.sidebar.configure(fg_color="#0B0B0B")
                    self.sidebar.lift()
                    self.sidebar_toggle.configure(text="›")
                except Exception:
                    pass
                if perf.ENABLED:
                    perf.record(
                        "ui.sidebar.cierre.soltar_drawer",
                        (time.perf_counter() - marca) * 1000.0,
                    )
                    marca = time.perf_counter()
                scrim = getattr(self, "sidebar_scrim", None)
                if self._widget_alive(scrim):
                    scrim.destroy()
                if perf.ENABLED:
                    perf.record(
                        "ui.sidebar.cierre.destruir_velo",
                        (time.perf_counter() - marca) * 1000.0,
                    )
                    # `update_idletasks()` (01-09-2026) no reveló ningún coste
                    # — la cola de Tk está vacía a los 2 ms. El vídeo sigue
                    # mostrando una reconstrucción visible de todos modos, así
                    # que el retraso no está en Tk: puede ser el propio
                    # compositor de Windows (fuera de Python) o del hilo Tk
                    # ejecutando algo que ninguna de las marcas de arriba
                    # cubre. Esto muestrea la pila del hilo Tk cada 5 ms
                    # durante los 400 ms siguientes para ver qué hay
                    # realmente en marcha, en vez de seguir adivinando.
                    self._muestrear_pila_tras_cerrar_menu()
                self.sidebar_scrim = None
                self.sidebar_scrim_image = None
                self._sidebar_navigation_selected = False
                self._set_content_navigation_focus(True)
                pending_page = getattr(self, "_pending_sidebar_navigation", None)
                self._pending_sidebar_navigation = None
                if pending_page is not None:
                    # Publicamos la captura limpia obtenida antes de oscurecer el
                    # menú. La barrera se crea en el mismo callback para que DWM
                    # nunca tenga que recapturar un fondo a medio recomponer.
                    self._navigation_source_capture = self.sidebar_source_capture
                    self.sidebar_source_capture = None
                    self.navigate(pending_page)
                else:
                    self.sidebar_source_capture = None

        frame()

    def _muestrear_pila_tras_cerrar_menu(self) -> None:
        """Diagnóstico temporal (01-09-2026): qué ejecuta el hilo Tk durante
        los ~400 ms en los que el vídeo del usuario muestra Equipo/PC
        reconstruyéndose tras cerrar el menú. Un hilo aparte lee la pila del
        hilo principal desde fuera — no se ejecuta EN el hilo medido, así que
        no puede alterar su tiempo real. Si las muestras no encuentran nada
        (todas caen en el propio `mainloop`), el retraso no está en Python.
        """
        import traceback

        hilo_principal = threading.main_thread().ident
        fin = time.perf_counter() + 0.4

        def muestrear() -> None:
            while time.perf_counter() < fin:
                marco = sys._current_frames().get(hilo_principal)
                if marco is not None:
                    pila = traceback.extract_stack(marco, limit=3)
                    cima = " < ".join(
                        f"{c.name}:{c.lineno}" for c in reversed(pila)
                    )
                    perf.mark("ui.sidebar.cierre.muestra_de_pila", cima=cima)
                time.sleep(0.005)

        threading.Thread(
            target=muestrear, name="RoleRunSidebarCloseSampler", daemon=True,
        ).start()

    def _return_to_welcome_from_sidebar(self) -> None:
        self._set_sidebar_expanded(False)
        self.after(0, self._return_to_welcome)

    def _configure_body_widget(self, body) -> None:
        """Configura cada superficie intercambiable del contenido principal."""
        body_canvas = getattr(body, "_parent_canvas", None)
        if body_canvas is not None:
            try:
                body_canvas.configure(yscrollincrement=1)
            except Exception:
                pass

        body_scrollbar = getattr(body, "_scrollbar", None)
        if body_scrollbar is not None:
            # Interceptar el comando de la barra garantiza que cualquier arrastre
            # manual cancela al instante la animación de la rueda.
            try:
                body_scrollbar.configure(command=self._on_body_scrollbar_command)
            except Exception:
                pass
            bind_targets = [body_scrollbar]
            internal_canvas = getattr(body_scrollbar, "_canvas", None)
            if internal_canvas is not None:
                bind_targets.append(internal_canvas)
            for target in bind_targets:
                for sequence, callback in (
                    ("<ButtonPress-1>", self._on_scrollbar_press),
                    ("<B1-Motion>", self._on_scrollbar_motion),
                    ("<ButtonRelease-1>", self._on_scrollbar_release),
                ):
                    try:
                        target.bind(sequence, callback, add="+")
                    except Exception:
                        pass

    def _create_body_widget(self, below=None):
        """Crea un buffer de página completo sin retirar el que ya ve el usuario.

        Cuando ``below`` existe, ambos cuerpos ocupan la misma celda pero el nuevo
        queda detrás. Tk puede calcular allí todo el árbol, incluido el scrollregion,
        mientras la superficie anterior continúa cubriéndolo.
        """
        content = getattr(self, "content", None)
        if content is None or not self._widget_alive(content):
            raise RuntimeError("La superficie principal de RoleRun Manager no está disponible.")
        body = ctk.CTkScrollableFrame(content, fg_color=BG, corner_radius=0)
        body.grid(row=1, column=0, sticky="nsew", padx=34, pady=(0, 28))
        body.grid_columnconfigure(0, weight=1)
        self._configure_body_widget(body)
        if below is not None and self._widget_alive(below):
            try:
                self._stack_body_surface(body, below, above=False)
            except Exception:
                # Si el sistema de ventanas no permite asegurar que el buffer nuevo
                # quede detrás, no exponemos ni conservamos esa superficie parcial.
                try:
                    body.grid_forget()
                    body.destroy()
                finally:
                    raise
        return body

    @staticmethod
    def _body_stack_surface(body):
        """Devuelve la ventana Tk externa de un CTkScrollableFrame.

        CustomTkinter coloca el frame desplazable real dentro de un canvas y expone
        un ``_parent_frame`` como superficie que participa en el grid del layout.
        El orden visual debe cambiarse sobre ese contenedor externo, no sobre el
        frame interno del canvas.
        """
        return getattr(body, "_parent_frame", body)

    def _stack_body_surface(self, body, reference, above: bool) -> None:
        surface = self._body_stack_surface(body)
        reference_surface = self._body_stack_surface(reference)
        action = "raise" if above else "lower"
        try:
            if above:
                surface.lift(reference_surface)
            else:
                surface.lower(reference_surface)
            return
        except Exception:
            pass
        surface.tk.call(action, surface._w, reference_surface._w)

    def _cancel_navigation_transition_callbacks(self) -> None:
        for after_id in tuple(getattr(self, "_navigation_transition_after_ids", ())):
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._navigation_transition_after_ids.clear()

    @staticmethod
    def _stop_navigation_spinner(overlay) -> None:
        stop_event = getattr(overlay, "_rolerun_spinner_stop", None)
        if stop_event is not None:
            try:
                stop_event.set()
            except Exception:
                pass

    def _start_navigation_spinner(self, overlay, snapshot_label) -> None:
        """Anima el indicador aunque el hilo Tk esté construyendo la página.

        Crear cientos de widgets es necesariamente síncrono en Tk. Un ``after``
        ordinario queda detenido durante ese tramo y produciría justo el spinner
        congelado que queremos evitar. En Windows, un worker dibuja por GDI sobre
        el HWND independiente del snapshot; no toca estado Tk ni la partida.
        """
        if os.name != "nt":
            tk.Label(
                overlay, text="⟳  CARGANDO…", background="#151515",
                foreground=GOLD, font=("Segoe UI", 15, "bold"),
                padx=20, pady=12,
            ).place(relx=0.5, rely=0.5, anchor="center")
            return
        try:
            snapshot_label.update_idletasks()
            hwnd = int(snapshot_label.winfo_id())
        except Exception:
            return
        stop_event = threading.Event()
        overlay._rolerun_spinner_stop = stop_event

        def rgb(red: int, green: int, blue: int) -> int:
            return int(red) | (int(green) << 8) | (int(blue) << 16)

        def animate() -> None:
            class RECT(ctypes.Structure):
                _fields_ = [
                    ("left", ctypes.c_long), ("top", ctypes.c_long),
                    ("right", ctypes.c_long), ("bottom", ctypes.c_long),
                ]

            try:
                user32 = ctypes.windll.user32
                gdi32 = ctypes.windll.gdi32
                user32.GetDC.argtypes = [ctypes.c_void_p]
                user32.GetDC.restype = ctypes.c_void_p
                user32.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
                user32.GetClientRect.argtypes = [ctypes.c_void_p, ctypes.POINTER(RECT)]
                gdi32.CreatePen.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_uint]
                gdi32.CreatePen.restype = ctypes.c_void_p
                gdi32.CreateSolidBrush.argtypes = [ctypes.c_uint]
                gdi32.CreateSolidBrush.restype = ctypes.c_void_p
                gdi32.SelectObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
                gdi32.SelectObject.restype = ctypes.c_void_p
                gdi32.DeleteObject.argtypes = [ctypes.c_void_p]
                gdi32.MoveToEx.argtypes = [
                    ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p,
                ]
                gdi32.LineTo.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int]
                gdi32.Ellipse.argtypes = [
                    ctypes.c_void_p, ctypes.c_int, ctypes.c_int,
                    ctypes.c_int, ctypes.c_int,
                ]
                frame_index = 0
                while not stop_event.is_set():
                    rect = RECT()
                    if not user32.GetClientRect(ctypes.c_void_p(hwnd), ctypes.byref(rect)):
                        break
                    hdc = user32.GetDC(ctypes.c_void_p(hwnd))
                    if not hdc:
                        break
                    try:
                        center_x = max(0, int(rect.right - rect.left)) // 2
                        center_y = max(0, int(rect.bottom - rect.top)) // 2
                        background = rgb(21, 21, 21)
                        background_pen = gdi32.CreatePen(0, 1, background)
                        background_brush = gdi32.CreateSolidBrush(background)
                        old_pen = gdi32.SelectObject(hdc, background_pen)
                        old_brush = gdi32.SelectObject(hdc, background_brush)
                        gdi32.Ellipse(
                            hdc, center_x - 39, center_y - 39,
                            center_x + 39, center_y + 39,
                        )
                        gdi32.SelectObject(hdc, old_brush)
                        gdi32.SelectObject(hdc, old_pen)
                        gdi32.DeleteObject(background_brush)
                        gdi32.DeleteObject(background_pen)

                        shades = (
                            (201, 164, 92), (173, 142, 82), (142, 119, 74),
                            (111, 96, 67), (82, 75, 61),
                        )
                        for spoke in range(12):
                            distance = (spoke - frame_index) % 12
                            color = shades[min(distance, len(shades) - 1)]
                            pen = gdi32.CreatePen(0, 4, rgb(*color))
                            previous_pen = gdi32.SelectObject(hdc, pen)
                            angle = ((2.0 * math.pi * spoke) / 12.0) - (math.pi / 2.0)
                            inner_x = center_x + round(math.cos(angle) * 18)
                            inner_y = center_y + round(math.sin(angle) * 18)
                            outer_x = center_x + round(math.cos(angle) * 30)
                            outer_y = center_y + round(math.sin(angle) * 30)
                            gdi32.MoveToEx(hdc, inner_x, inner_y, None)
                            gdi32.LineTo(hdc, outer_x, outer_y)
                            gdi32.SelectObject(hdc, previous_pen)
                            gdi32.DeleteObject(pen)
                        gdi32.GdiFlush()
                    finally:
                        user32.ReleaseDC(ctypes.c_void_p(hwnd), hdc)
                    frame_index = (frame_index + 1) % 12
                    stop_event.wait(0.055)
            except Exception:
                return

        thread = threading.Thread(
            target=animate, name="RoleRunNavigationSpinner", daemon=True,
        )
        overlay._rolerun_spinner_thread = thread
        thread.start()

    def _destroy_navigation_transition(self, overlay=None) -> None:
        target = overlay or getattr(self, "_navigation_transition_overlay", None)
        if target is not None:
            self._stop_navigation_spinner(target)
        try:
            if target is not None and target.winfo_exists():
                target.destroy()
        except Exception:
            pass
        if getattr(self, "_navigation_transition_overlay", None) is target:
            self._navigation_transition_overlay = None
            self._navigation_transition_image = None

    @perf.timed("ui.navigation_transition")
    def _create_navigation_transition(self):
        """Crea una superficie DWM independiente con el último frame estable.

        Una capa hija de la ventana principal comparte el orden de repintado con
        los canvas internos de CustomTkinter. Al retirarla, Windows podía mostrar
        durante dos frames un mosaico parcialmente reconstruido. Un Toplevel
        transitorio conserva su propia superficie compuesta mientras la ventana
        principal pinta por completo el destino debajo.
        """
        self._cancel_navigation_transition_callbacks()
        self._destroy_navigation_transition()
        content = getattr(self, "content", None)
        if not self._widget_alive(content):
            return None
        self.update_idletasks()
        width = max(1, int(content.winfo_width()))
        height = max(1, int(content.winfo_height()))
        root_x = int(content.winfo_rootx())
        root_y = int(content.winfo_rooty())
        try:
            cached_capture = getattr(self, "_navigation_source_capture", None)
            self._navigation_source_capture = None
            if isinstance(cached_capture, Image.Image):
                capture = cached_capture.copy().convert("RGB")
            else:
                capture = ImageGrab.grab(
                    bbox=(root_x, root_y, root_x + width, root_y + height),
                    all_screens=True,
                ).convert("RGB")
            if capture.size != (width, height):
                capture = capture.resize((width, height), Image.Resampling.LANCZOS)
            # El menú ya comunica que la aplicación entra en un estado modal.
            # Mantener esa misma lectura visual durante la espera resulta más
            # coherente que iluminar de nuevo el origen antes de publicar el
            # destino completo.
            capture = ImageEnhance.Brightness(capture).enhance(0.42)
            overlay = tk.Toplevel(self)
            overlay.withdraw()
            overlay.overrideredirect(True)
            overlay.configure(background=BG)
            try:
                overlay.transient(self)
            except Exception:
                pass
            overlay.geometry(f"{width}x{height}+{root_x}+{root_y}")
            image = ImageTk.PhotoImage(capture, master=overlay)
            snapshot_label = tk.Label(
                overlay, image=image, borderwidth=0, highlightthickness=0,
                background=BG,
            )
            snapshot_label.pack(fill="both", expand=True)
            overlay.attributes("-alpha", 1.0)
            # Hereda el nivel de la ventana principal: en el preview esta es
            # topmost para poder capturarla, mientras que en uso normal la
            # barrera no debe quedar por encima de otra aplicación al hacer Alt+Tab.
            overlay.attributes("-topmost", bool(self.attributes("-topmost")))
            overlay.deiconify()
            overlay.lift()
            self._navigation_transition_image = image
            self._navigation_transition_overlay = overlay
            overlay.update_idletasks()
            self._start_navigation_spinner(overlay, snapshot_label)
            return overlay
        except Exception:
            self._destroy_navigation_transition(locals().get("overlay"))
            return None

    def _fade_navigation_transition(self, overlay, token: int) -> None:
        if (
            token != getattr(self, "_navigation_transition_token", 0)
            or overlay is not getattr(self, "_navigation_transition_overlay", None)
            or not self._widget_alive(overlay)
        ):
            self._destroy_navigation_transition(overlay)
            return
        self._stop_navigation_spinner(overlay)
        # La curva es `(1 - progreso)²`, así que a mitad del fade ya solo queda
        # el 25 % de la captura: 80 ms se leen como un fundido y no como espera.
        duration_ms = 80
        started = time.perf_counter()
        try:
            start_alpha = float(overlay.attributes("-alpha"))
        except Exception:
            start_alpha = 0.992

        def frame() -> None:
            if (
                token != getattr(self, "_navigation_transition_token", 0)
                or overlay is not getattr(self, "_navigation_transition_overlay", None)
                or not self._widget_alive(overlay)
            ):
                self._destroy_navigation_transition(overlay)
                return
            progress = max(0.0, min(
                1.0, ((time.perf_counter() - started) * 1000.0) / duration_ms,
            ))
            # El destino ya está completo debajo. La opacidad es la única
            # propiedad animada, por lo que no hay relayout ni widgets parciales.
            alpha = start_alpha * ((1.0 - progress) ** 2)
            try:
                overlay.attributes("-alpha", alpha)
            except Exception:
                self._destroy_navigation_transition(overlay)
                return
            if progress >= 1.0:
                self._destroy_navigation_transition(overlay)
                return
            after_id = self.after(16, frame)
            self._navigation_transition_after_ids.add(after_id)

        frame()

    def _finish_navigation_transition(self, overlay, token: int) -> None:
        if overlay is None:
            return
        # Una ventana totalmente opaca permite que DWM deje de presentar la
        # superficie que tiene debajo. Al pasarla a 0,992 el destino se compone
        # ya completo con una contribución visual de solo 0,8 %. Esperamos varios
        # frames antes del fade perceptible: cualquier primer repintado queda
        # oculto por el 99,2 % del snapshot estable.
        try:
            overlay.lift()
            overlay.attributes("-alpha", 0.992)
        except Exception:
            self._destroy_navigation_transition(overlay)
            return
        # Tres fotogramas. El comentario de arriba pide «varios frames» y 120 ms
        # son siete y medio: tiempo muerto con el destino ya compuesto debajo.
        after_id = self.after(
            48, lambda: self._fade_navigation_transition(overlay, token),
        )
        self._navigation_transition_after_ids.add(after_id)

    def _commit_page_navigation(
        self, page: str, previous_page: str, overlay, token: int,
    ) -> None:
        if token != getattr(self, "_navigation_transition_token", 0):
            self._destroy_navigation_transition(overlay)
            return
        self.active_page = page
        # "team" y "pc" son la misma pantalla: solo se sale de verdad cuando el
        # destino ya no pertenece a la vista unificada.
        if previous_page in TEAM_PC_PAGES and page not in TEAM_PC_PAGES:
            self._cancel_bdsp_pc_poll()
        try:
            self._smooth_render_page(
                reset_scroll=True,
                _prepared_navigation_overlay=overlay,
                _navigation_token=token,
            )
        except Exception:
            self._destroy_navigation_transition(overlay)
            raise
        if page in TEAM_PC_PAGES and previous_page not in TEAM_PC_PAGES:
            # Al abrir Equipo y PC hay que mirar el PC del juego, no la copia
            # anterior. Comprobar solo "pc" hacía que esto no ocurriera nunca.
            try:
                self.after(90, self._schedule_gen6_live_pc_refresh)
            except Exception:
                pass

    def _begin_page_navigation(self, page: str, previous_page: str) -> None:
        self._navigation_transition_token += 1
        token = self._navigation_transition_token
        overlay = self._create_navigation_transition()
        if overlay is None:
            self._commit_page_navigation(page, previous_page, None, token)
            return
        # Devolvemos el control a Tk para que el Toplevel llegue al compositor
        # antes del trabajo síncrono de construcción de widgets. Un fotograma es
        # exactamente lo que hace falta para eso; los 34 ms de antes eran el
        # doble, y se sumaban a los otros dos plazos fijos de la barrera.
        after_id = self.after(
            16,
            lambda: self._commit_page_navigation(page, previous_page, overlay, token),
        )
        self._navigation_transition_after_ids.add(after_id)

    def _create_page_transition_overlay(self):
        """Congela visualmente la página completa mientras nace el árbol nuevo.

        Un ``CTkScrollableFrame`` se compone de varias ventanas Tk internas. Su
        orden de apilado no forma una transacción: Windows puede pintar canvas y
        frames nuevos antes de que todos sus hijos estén listos. Esta captura
        nativa es la barrera atómica; no cambia estado y se destruye tras el
        primer repintado estable de la página de destino.
        """
        previous = getattr(self, "_page_transition_overlay", None)
        if self._widget_alive(previous):
            previous.destroy()
        self._page_transition_overlay = None
        self._page_transition_image = None
        content = getattr(self, "content", None)
        if not self._widget_alive(content):
            return None
        self.update_idletasks()
        content_x = int(content.winfo_x())
        content_y = int(content.winfo_y())
        width = max(1, min(
            int(content.winfo_width()), int(self.winfo_width()) - content_x,
        ))
        height = max(1, min(
            int(content.winfo_height()), int(self.winfo_height()) - content_y,
        ))
        # Pedido del usuario 02-09-2026: «al hacer un reroll, se quedan los
        # iconos de categoría fijos en la pantalla» -y seguían apareciendo
        # tras ocultarlos antes en el desvanecido (ver `IntegratedDraftFlow.
        # _run_fade`). La causa real estaba aquí: esta captura es una foto
        # NATIVA de Windows (`ImageGrab.grab`), no un estado interno de Tk;
        # `update_idletasks()` solo garantiza que Tk emitió sus órdenes de
        # dibujo, no que el compositor de Windows (DWM) ya las haya volcado
        # de verdad al framebuffer que lee `ImageGrab`. Sin ese margen, la
        # foto podía llevarse un fotograma todavía viejo -con los iconos que
        # el desvanecido ya había ocultado por dentro, pero que la pantalla
        # aún no había terminado de repintar- y esa foto vieja se queda fija
        # de fondo durante toda la transición.
        time.sleep(0.02)
        try:
            capture = ImageGrab.grab(bbox=(
                int(content.winfo_rootx()), int(content.winfo_rooty()),
                int(content.winfo_rootx()) + width,
                int(content.winfo_rooty()) + height,
            ), all_screens=True).convert("RGB")
            if capture.size != (width, height):
                capture = capture.resize((width, height), Image.Resampling.LANCZOS)
            self._page_transition_image = ImageTk.PhotoImage(capture)
            overlay = tk.Label(
                self, image=self._page_transition_image,
                borderwidth=0, highlightthickness=0, background=BG,
            )
            con_rueda = True
        except Exception:
            con_rueda = False
            overlay = tk.Frame(self, background=BG, borderwidth=0)
            tk.Label(
                overlay, text="CARGANDO…", background=BG, foreground=GOLD,
                font=("Segoe UI", 14, "bold"),
            ).place(relx=0.5, rely=0.5, anchor="center")
        overlay.place(x=content_x, y=content_y, width=width, height=height)
        overlay.lift()
        self._page_transition_overlay = overlay
        # Resuelve la geometría sin reentrar en el bucle completo de eventos.
        # ``update()`` podía ejecutar navegación, resize y temporizadores dentro
        # del propio intercambio de página, dejando viva una captura antigua o
        # reconstruyendo la vista dos veces. Los idles bastan para mapear y pintar
        # esta superficie antes de comenzar el render síncrono.
        self.update_idletasks()
        # LA RUEDA, QUE AQUÍ NO ESTABA
        #
        # De los sesenta y un repintados que pasan por `_smooth_render_page`,
        # **uno solo** recibía la superficie de navegación con rueda; los demás
        # recibían esta, que es una foto congelada y muda. De ahí la queja de
        # que «muchas veces está repintando algo y no aparece»: aparecía, pero
        # sin nada que se moviera, y una imagen quieta durante 300 ms se lee
        # como que el programa se ha colgado, no como que está trabajando.
        #
        # El worker pinta por GDI sobre el HWND del propio Label, que es
        # independiente del de la ventana -comprobado: son distintos-, así que
        # sigue girando mientras Tk construye el árbol nuevo.
        if con_rueda:
            self._start_navigation_spinner(overlay, overlay)
        return overlay

    def _retire_page_transition_overlay(self, overlay) -> None:
        try:
            if overlay is not None and overlay.winfo_exists():
                # Primero se para el worker: destruir el Label deja su HWND
                # inválido y el hilo estaría pintando sobre nada.
                self._stop_navigation_spinner(overlay)
                overlay.destroy()
        except Exception:
            pass
        if getattr(self, "_page_transition_overlay", None) is overlay:
            self._page_transition_overlay = None
            self._page_transition_image = None

    def _cancel_help_animations(self) -> None:
        for after_id in list(self._help_animation_ids):
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._help_animation_ids.clear()

    def _pin_body_scrollregion_to_viewport(self) -> None:
        """Deja a ``self.body`` sin ningún recorrido de scroll propio.

        Pedido por el usuario el 2026-09-03, tercer intento: en MOVIMIENTOS
        (y páginas parecidas) todo el scroll real vive en paneles propios
        —la lista de MT/drafteos, el equipo, el selector de MT—, nunca en
        ``self.body``. Pero ``self.body`` es también un
        ``CTkScrollableFrame``, y CustomTkinter le liga su propio manejador
        de rueda con ``bind_all`` (independiente del nuestro, ver
        ``_on_smooth_mousewheel``): mientras su canvas tenga scrollregion
        real por encima de su viewport, esa rueda global sigue moviendo la
        página entera, sin que la exclusión de página la pueda evitar.

        Calcular el alto exacto de cada panel para que nunca se pase del
        viewport es fragil -depende de medir un ``winfo_height()`` que en el
        primer render vale 200 (el tamaño por defecto de CustomTkinter,
        antes de que Tk resuelva la geometría real)-. Más simple y más
        fiable: fijar el propio scrollregion de ``self.body`` a su viewport
        real, directamente.

        Cuarto intento, el mismo día: fijar SOLO el scrollregion sin tocar
        el marco de la vista activa recortaba lo que sobrara del marco sin
        ninguna forma de alcanzarlo -ni con el scroll propio de sus paneles
        de dentro-, peor que el scroll doble que se pretendía arreglar.

        Quinto intento, el mismo día: forzar el alto del marco a la misma
        medida seguía sobrando por abajo -el marco cerraba en dorado por
        arriba pero no por abajo, señal de que seguía pasándose-. La causa:
        ``canvas.winfo_height()`` da píxeles FÍSICOS, pero ``configure(
        height=...)`` de un widget CTk espera unidades LÓGICAS -sin
        convertir, con el escalado de CTk (``set_widget_scaling(1.12)``,
        ver ``app/ui.py`` cerca del arranque) puesto encima, el marco salía
        un 12% más alto que el viewport real. ``UnifiedTeamPCView`` (Equipo
        y PC, que nunca tuvo este fallo) ya convertía con
        ``frame._reverse_widget_scaling(...)`` antes de fijar el alto; aquí
        faltaba exactamente ese paso.
        """
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None or not self._widget_alive(self.body):
            return
        try:
            if not canvas.winfo_exists():
                return
            width = int(canvas.winfo_width())
            height = int(canvas.winfo_height())
            if width <= 1 or height <= 1:
                return
            for view in (getattr(self, "_global_tm_view", None), getattr(self, "_tm_teach_flow", None)):
                frame = getattr(view, "frame", None)
                if frame is not None and self._widget_alive(frame):
                    try:
                        logical_height = int(frame._reverse_widget_scaling(height))
                        configurar_si_cambia(frame, height=logical_height)
                    except Exception:
                        pass
            canvas.configure(scrollregion=(0, 0, width, height))
        except Exception:
            pass

    def _pin_body_scrollregion_soon(self) -> None:
        """Reintenta fijar el scrollregion mientras Tk asienta la geometría."""
        for delay in (0, 30, 80, 180, 400):
            try:
                self.after(delay, self._pin_body_scrollregion_to_viewport)
            except Exception:
                pass

    def _body_scroll_metrics(self):
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None:
            return None
        try:
            if not canvas.winfo_exists():
                return None
            region = canvas.bbox("all")
            if not region:
                return None
            total_height = max(1.0, float(region[3] - region[1]))
            visible_height = max(1.0, float(canvas.winfo_height()))
            max_scroll = max(0.0, total_height - visible_height)
            # ``canvasy(0)`` no es fiable en todas las versiones de Tk cuando
            # CustomTkinter acaba de relayoutar el canvas. ``yview`` sí expone
            # directamente la fracción real que ve el usuario.
            try:
                first, _last = canvas.yview()
                current = float(first) * total_height
            except Exception:
                current = float(canvas.canvasy(0))
            current = max(0.0, min(current, max_scroll))
            return canvas, total_height, max_scroll, current
        except Exception:
            return None

    def _schedule_body_scroll_redraw(self) -> None:
        # No forzamos update_idletasks durante el desplazamiento. En Windows,
        # obligar a repintar un CTkScrollableFrame mientras su canvas se mueve
        # puede dejar estelas verticales (sprites y tarjetas "estirados"). Tk
        # repinta por sí solo en el siguiente ciclo del event loop.
        return

    def _reset_body_scroll(self) -> None:
        self._cancel_smooth_scroll(sync_target=False)
        self._smooth_scroll_target_px = 0.0
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None:
            return
        try:
            if canvas.winfo_exists():
                canvas.yview_moveto(0.0)
                self._schedule_body_scroll_redraw()
        except Exception:
            return

    def _capture_body_scroll_px(self) -> float:
        """Guarda la posición vertical real antes de reconstruir la página."""
        metrics = self._body_scroll_metrics()
        return float(metrics[3]) if metrics is not None else 0.0

    def _capture_body_scroll_fraction(self) -> float:
        """Captura la fracción visible del canvas para restaurarla sin un flash arriba."""
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None:
            return 0.0
        try:
            first, _last = canvas.yview()
            return max(0.0, min(1.0, float(first)))
        except Exception:
            return 0.0

    def _restore_body_scroll_fraction_immediate(self, fraction: float) -> None:
        """Reposiciona el canvas en el mismo ciclo de render, antes de devolver control a Tk.

        La restauración en píxeles posterior sigue afinando el resultado cuando cambia
        la altura de las tarjetas, pero esta primera aplicación evita que el usuario
        llegue a ver el fotograma intermedio situado en la parte superior.
        """
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None:
            return
        try:
            if canvas.winfo_exists():
                canvas.yview_moveto(max(0.0, min(1.0, float(fraction))))
                self._smooth_scroll_target_px = None
        except Exception:
            pass

    def _restore_body_scroll_px(self, offset_px: float) -> None:
        """Restaura el scroll tras un render sin saltar al principio de Equipo.

        CustomTkinter recalcula el ``scrollregion`` del canvas en varios ciclos de
        geometría. Una única restauración en ``after_idle`` podía ejecutarse antes
        de que la nueva cuadrícula de Equipo tuviera su altura definitiva y Tk
        terminaba dejando la vista en 0. Reintentamos durante unos pocos frames y
        forzamos únicamente el cálculo de geometría (no una animación de scroll).
        """
        target_px = max(0.0, float(offset_px))

        def apply(attempt: int = 0) -> None:
            try:
                self.update_idletasks()
            except Exception:
                pass
            metrics = self._body_scroll_metrics()
            if metrics is None:
                if attempt < 4:
                    self.after(25, lambda: apply(attempt + 1))
                return
            canvas, total_height, max_scroll, _current = metrics
            target = min(target_px, max_scroll)
            self._smooth_scroll_target_px = target
            try:
                # yview_moveto usa una fracción del scrollregion total, no del
                # recorrido máximo del pulgar. target/total_height mantiene el
                # desplazamiento en píxeles que tenía el usuario antes del render.
                fraction = 0.0 if total_height <= 0 else max(0.0, min(target / total_height, 1.0))
                canvas.yview_moveto(fraction)
                self._schedule_body_scroll_redraw()
            except Exception:
                return

            # Algunos widgets (sobre todo sprites) terminan de fijar su altura un
            # instante después. Reaplicamos la misma coordenada unas veces para
            # impedir que ese segundo relayout vuelva a llevar Equipo al inicio.
            if attempt < 4:
                self.after(35, lambda: apply(attempt + 1))

        self.after_idle(lambda: apply(0))

    def _cancel_smooth_scroll(self, sync_target: bool = True) -> None:
        if self._smooth_scroll_after_id is not None:
            try:
                self.after_cancel(self._smooth_scroll_after_id)
            except Exception:
                pass
            self._smooth_scroll_after_id = None
        if sync_target:
            metrics = self._body_scroll_metrics()
            self._smooth_scroll_target_px = metrics[3] if metrics is not None else None

    def _apply_pending_manual_scroll(self) -> None:
        self._manual_scroll_after_id = None
        fraction = self._manual_scroll_pending_fraction
        self._manual_scroll_pending_fraction = None
        if fraction is None:
            return
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None:
            return
        try:
            if canvas.winfo_exists():
                canvas.yview_moveto(max(0.0, min(1.0, float(fraction))))
        except Exception:
            return

    def _on_body_scrollbar_command(self, *args) -> None:
        # El thumb puede enviar decenas/cientos de eventos por segundo al
        # arrastrarlo. Coalescemos los `moveto` y aplicamos como máximo uno por
        # frame (~60 Hz), evitando el artefacto de estiramiento de widgets CTk.
        self._cancel_smooth_scroll(sync_target=False)
        canvas = getattr(self.body, "_parent_canvas", None)
        if canvas is None or not args:
            return
        try:
            if args[0] == "moveto" and len(args) >= 2:
                self._manual_scroll_pending_fraction = float(args[1])
                if self._manual_scroll_after_id is None:
                    self._manual_scroll_after_id = self.after(16, self._apply_pending_manual_scroll)
                return
            # Clics en la pista/flechas: son eventos discretos y pueden aplicarse
            # inmediatamente.
            canvas.yview(*args)
            metrics = self._body_scroll_metrics()
            if metrics is not None:
                self._smooth_scroll_target_px = metrics[3]
        except Exception:
            pass

    def _on_scrollbar_press(self, _event=None):
        self._manual_scrollbar_dragging = True
        self._cancel_smooth_scroll(sync_target=True)
        return None

    def _on_scrollbar_motion(self, _event=None):
        self._manual_scrollbar_dragging = True
        self._cancel_smooth_scroll(sync_target=False)
        return None

    def _on_scrollbar_release(self, _event=None):
        # Aplicar la última posición inmediatamente para que el thumb y el
        # contenido terminen exactamente en el mismo sitio.
        if self._manual_scroll_after_id is not None:
            try:
                self.after_cancel(self._manual_scroll_after_id)
            except Exception:
                pass
            self._manual_scroll_after_id = None
        self._apply_pending_manual_scroll()
        self._manual_scrollbar_dragging = False
        self._cancel_smooth_scroll(sync_target=True)
        return None

    def _set_body_scrollbar_visible(self, visible: bool) -> None:
        """Oculta la barra cuando la página no necesita desplazamiento vertical."""
        scrollbar = getattr(self.body, "_scrollbar", None)
        if scrollbar is None:
            return
        try:
            if visible:
                scrollbar.grid()
            else:
                scrollbar.grid_remove()
        except Exception:
            pass

    def _ensure_smooth_scroll_animation(self) -> None:
        if self._smooth_scroll_after_id is not None or self._manual_scrollbar_dragging:
            return

        def animate() -> None:
            self._smooth_scroll_after_id = None
            if self._manual_scrollbar_dragging:
                return
            metrics = self._body_scroll_metrics()
            if metrics is None:
                return
            canvas, total_height, max_scroll, current = metrics
            target = max(0.0, min(float(self._smooth_scroll_target_px or 0.0), max_scroll))
            distance = target - current
            if abs(distance) <= 1.0:
                next_px = target
            else:
                # Interpolación directa en píxeles: evita los saltos de
                # yview_scroll y mantiene una sensación suave con la rueda.
                step = max(2.0, min(34.0, abs(distance) * 0.24))
                next_px = current + (step if distance > 0 else -step)

            try:
                canvas.yview_moveto(0.0 if total_height <= 0 else next_px / total_height)
            except Exception:
                return

            if abs(target - next_px) > 1.0:
                self._smooth_scroll_after_id = self.after(16, animate)
            else:
                self._smooth_scroll_target_px = target

        self._smooth_scroll_after_id = self.after(1, animate)

    def _on_smooth_mousewheel(self, event):
        # CAJAS PC contiene sus propios scrolls (cajas y ficha). No interceptamos
        # la rueda desde el scroll general de la aplicación para que el panel bajo
        # el puntero reciba el desplazamiento de forma natural.
        #
        # Pedido por el usuario el 2026-09-03: MOVIMIENTOS tiene el mismo caso
        # —lista de MT/drafteos a la izquierda, equipo a la derecha, y el
        # selector de MT superpuesto llevan cada uno su propio scroll—, y el
        # scroll de la página entera (con la barra escondida, pero el canvas
        # sigue siendo desplazable) se comía la rueda antes de que llegara al
        # panel bajo el puntero.
        if self.active_page in {"pc", "tms"}:
            return None
        metrics = self._body_scroll_metrics()
        if metrics is None:
            return None
        canvas, _total_height, max_scroll, current = metrics
        try:
            pointer_x = self.winfo_pointerx()
            pointer_y = self.winfo_pointery()
            left = canvas.winfo_rootx()
            top = canvas.winfo_rooty()
            right = left + canvas.winfo_width()
            bottom = top + canvas.winfo_height()
            if not (left <= pointer_x <= right and top <= pointer_y <= bottom):
                return None
            if self._manual_scrollbar_dragging:
                return "break"

            if self._smooth_scroll_target_px is None or self._smooth_scroll_after_id is None:
                # Si no hay animación activa, arrancamos desde la posición real.
                self._smooth_scroll_target_px = current

            notches = -float(event.delta) / 120.0 if event.delta else 0.0
            # Acumular rueda sin reiniciar la animación elimina el pequeño
            # retroceso que se producía al encadenar varios ticks seguidos.
            self._smooth_scroll_target_px = max(
                0.0,
                min(float(self._smooth_scroll_target_px) + notches * 104.0, max_scroll),
            )
            self._ensure_smooth_scroll_animation()
            return "break"
        except Exception:
            return None

    def _clear(self, parent) -> None:
        for child in parent.winfo_children():
            child.destroy()

    def _step_card(self, parent, row: int, number: int, title: str, complete: bool, active: bool):
        border = GOLD if active else (SUCCESS if complete else PANEL_ALT)
        frame = ctk.CTkFrame(
            parent, fg_color=PANEL, corner_radius=14,
            border_width=2 if active else 1, border_color=border,
        )
        frame.grid(row=row, column=0, sticky="ew", pady=8)
        self.step_widgets[number] = frame
        frame.grid_columnconfigure(1, weight=1)
        badge_text = "✓" if complete else str(number)
        badge_color = SUCCESS if complete else (GOLD if active else PANEL_ALT)
        ctk.CTkLabel(
            frame, text=badge_text, width=36, height=36, corner_radius=18,
            fg_color=badge_color, text_color="#111111" if (complete or active) else MUTED,
            font=ctk.CTkFont("Segoe UI", 16, "bold"),
        ).grid(row=0, column=0, padx=(16, 12), pady=14)
        ctk.CTkLabel(
            frame, text=title, text_color=TEXT if (complete or active) else MUTED,
            font=ctk.CTkFont("Segoe UI", 17, "bold"),
        ).grid(row=0, column=1, sticky="w", pady=14)
        return frame

    def _render_sidebar(self) -> None:
        if self.current_game and self.project:
            counters = self.project.counters
            pending_faints = len(self.project.pending_faints)
            pending_text = f" · {pending_faints} baja(s)" if pending_faints else ""
            self.sidebar_run.configure(
                text=(
                    f"RUN ACTIVA\n{self.project.name}\n"
                    f"♥ {int(counters.get('vidas', 0))}  ·  ◆ {int(counters.get('medallas', 0))}"
                    f"{pending_text}"
                ),
                text_color=GOLD,
                state="normal",
            )
        else:
            self.sidebar_run.configure(text="SIN RUN ACTIVA", text_color=MUTED, state="disabled")
        for page, button in self.nav_buttons.items():
            selected = page == primary_page_for(self.active_page)
            configurar_si_cambia(
                button,
                fg_color=PANEL_ALT if selected else "transparent",
                text_color=GOLD if selected else MUTED,
                border_width=1 if selected else 0,
                border_color=GOLD,
            )

    def _render_context_navigation(self) -> None:
        controls = getattr(self, "section_controls", None)
        if not self._widget_alive(controls):
            return
        self._clear(controls)
        if self.active_page in {"team", "pc"}:
            controls.grid_remove()
            return
        elif self.active_page in {"settings", "history"}:
            items = (("settings", "GENERAL"), ("history", "REGISTRO Y RECUPERACIÓN"))
        elif self.active_page in {"tms", "moves"}:
            items = (
                ("tms", "MOVIMIENTOS"),
                ("moves", "CONSULTA DE MOVIMIENTOS"),
            )
        else:
            controls.grid_remove()
            return
        controls.grid()
        if self.active_page == "moves" and self._moves_return_page == "drafts":
            ctk.CTkButton(
                controls,
                text="← VOLVER AL DRAFTEO",
                command=self._return_to_draft_from_moves,
                height=32,
                fg_color="#2A2419",
                hover_color=PANEL_ALT,
                border_width=1,
                border_color=GOLD,
                text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 12, "bold"),
            ).pack(side="left", padx=(0, 14))
        for page, label in items:
            selected = self.active_page == page
            ctk.CTkButton(
                controls,
                text=label,
                command=lambda target=page: self.navigate(target),
                height=32,
                fg_color="#2A2419" if selected else "transparent",
                hover_color=PANEL_ALT,
                border_width=1,
                border_color=GOLD if selected else "#3A3A3A",
                text_color=GOLD if selected else MUTED,
                font=ctk.CTkFont("Segoe UI", 12, "bold"),
            ).pack(side="left", padx=(0, 8))

    def _set_operation_status(
        self,
        kind: str,
        title: str,
        detail: str,
        *,
        actions: tuple[str, ...] = (),
        persistent: bool | None = None,
    ) -> None:
        store = getattr(self, "operation_status_store", None)
        if store is None:
            return
        if kind in ("applying", "verifying"):
            # 2026-09-05: distintos puntos de la escritura en vivo publicaban
            # su propio texto de "en curso" (qué operación, cuántas, en qué
            # fase de verificación...). Cada uno es, técnicamente, un mensaje
            # distinto del anterior, y publicar dos veces algo distinto
            # reinicia la barra letra a letra (OperationStatusStore.publish).
            # En una escritura normal eso son 4 o 5 avisos pisándose entre sí
            # antes de que el usuario llegue a leer ninguno. Un texto FIJO
            # para toda la fase "en curso" -sea cual sea el origen de la
            # llamada- hace que las repúblicas sean idénticas: publish() las
            # descarta sin tocar la barra, y el usuario ve un único
            # "Cargando…" estable hasta el resultado final (confirmado o
            # error), que sí conserva su texto real.
            #
            # El propio "verifying" también tenía que normalizarse a
            # "applying": OperationStatusBar.show_message decide si retipea
            # letra a letra comparando (kind, título), no solo el texto, y
            # OperationStatusStore.publish descarta una república solo si
            # kind/título/detalle son TODOS iguales. Igualar título y
            # detalle sin igualar el kind seguía contando como "otro aviso":
            # la barra borraba el detalle y lo volvía a teclear desde cero
            # -y hasta cambiaba de color/icono- aunque el texto fuera idéntico.
            kind = "applying"
            title = LOADING_STATUS_TITLE
            detail = LOADING_STATUS_DETAIL
            actions = ()
        # El reloj del usuario para cuando el rótulo deja de decir «aplicando».
        perf.mark("ui.estado", estado=str(kind), titulo=str(title)[:60])
        self._sonar_por_el_estado(str(kind), str(title))
        message = store.publish(
            kind, title, detail, actions=actions, persistent=persistent,
        )
        bar = getattr(self, "operation_bar", None)
        if self._widget_alive(bar):
            bar.show_message(message)
        if self._operation_autocollapse_after_id is not None:
            try:
                self.after_cancel(self._operation_autocollapse_after_id)
            except Exception:
                pass
            self._operation_autocollapse_after_id = None
        if message.may_auto_collapse:
            revision = message.revision

            def collapse() -> None:
                self._operation_autocollapse_after_id = None
                if self.operation_status_store.collapse_if_current(revision):
                    current_bar = getattr(self, "operation_bar", None)
                    if self._widget_alive(current_bar):
                        current_bar.show_message(self.operation_status_store.message)

            self._operation_autocollapse_after_id = self.after(4200, collapse)

    def _handle_operation_bar_action(self, action: str) -> None:
        key = str(action).strip().casefold()
        if self._accion_de_cola(action):
            return
        if key in {"reintentar", "resincronizar"}:
            self.sync_oras_live()
        elif key in {"revisar", "revisar cambios"}:
            self.show_pending_changes()
        elif key == "elegir sustituto":
            self._reopen_pending_faint_picker()
        elif key in {"no sustituir", "dejar hueco libre"}:
            self._decline_pending_faint_replacement()
        elif key == "cerrar selector":
            self._dismiss_integrated_faint_picker()
        elif key == "cancelar":
            if self._team_pc_pending_incoming is not None or self._team_pc_pending_outgoing is not None:
                self._cancel_team_pc_pending_selection()
            elif self.run.pending_changes:
                self.discard_pending_changes()

    def _sync_operation_status_from_runtime(self) -> None:
        store = getattr(self, "operation_status_store", None)
        if store is None:
            return
        current = store.message
        if current.stays_visible and current.kind in {"failed", "intervention"}:
            return
        # Barrera defensiva: la recuperación de una sesión anterior (y los
        # fixtures previos a la cola) pueden llegar aquí sin ella montada.
        cola = getattr(self, "cola_de_cambios", None)
        estado_cola = cola.estado() if cola is not None else EstadoCola()
        if self._live_write_in_progress or estado_cola.hay_trabajo:
            if estado_cola.hay_trabajo:
                # Con cola, el mensaje tiene que decir CUÁNTO queda; si no, el
                # usuario no sabe si puede irse a otra pantalla o no.
                self._publicar_estado_de_cola()
            elif current.kind not in {"applying", "verifying"}:
                self._set_operation_status(
                    "applying",
                    "APLICANDO CAMBIO",
                    "RoleRun está enviando la operación al juego. Puedes seguir usando la aplicación.",
                )
            return
        ready_faint = self._pending_faint_for_reopen()
        if ready_faint is not None and self._faint_replacement_mode is None:
            if current.title != "BAJA PENDIENTE":
                self._set_operation_status(
                    "warning",
                    "BAJA PENDIENTE",
                    (
                        f"{ready_faint.get('pokemon', 'Un Pokémon')} necesita sustituto. "
                        "La vida perdida y la baja ya están guardadas."
                    ),
                    actions=("Elegir sustituto", "No sustituir"),
                    persistent=True,
                )
            return
        pending = len(self.run.pending_changes)
        sync_text = str(self.sync_status or "")
        if sync_text.startswith("⚠"):
            # Las otras ramas comprueban antes si ya está puesto; esta no, y por
            # eso republicaba el mismo aviso en cada ciclo del monitor.
            detalle = sync_text.lstrip("⚠ ")
            if current.kind != "warning" or current.detail != detalle:
                self._set_operation_status(
                    "warning", "REVISIÓN NECESARIA", detalle,
                    # Igual que BAJA PENDIENTE: es una condición que sigue
                    # siendo cierta, no un resultado puntual. Sin esto, el
                    # autocolapso de 4,2 s la borraba y el siguiente ciclo del
                    # monitor —a 1,6 s— la volvía a publicar: la barra
                    # reiniciaba su escritura letra a letra sin parar mientras
                    # el juego siguiera cerrado.
                    persistent=True,
                )
        elif pending and current.kind not in {"pending", "prepared"}:
            self._set_operation_status(
                "pending",
                "CAMBIOS PENDIENTES",
                f"Hay {pending} cambio(s) que todavía no están confirmados en el juego.",
                actions=("Revisar cambios",),
            )
        elif sync_text.startswith(("✓", "☠")) and current.kind in {"applying", "verifying", "pending"}:
            self._set_operation_status(
                "confirmed",
                "CAMBIO REALIZADO",
                sync_text.lstrip("✓☠ "),
            )
        elif (
            current.kind == "warning" and current.title == "REVISIÓN NECESARIA"
            and not sync_text.startswith("⚠")
        ):
            # Persistente, así que no se retira sola: la condición que la
            # motivó ya no es cierta (el juego volvió a responder) y hay que
            # decirlo explícitamente o se queda colgada para siempre.
            if sync_text.startswith(("✓", "☠")):
                self._set_operation_status(
                    "confirmed", "CAMBIO REALIZADO", sync_text.lstrip("✓☠ "),
                )
            else:
                self._set_operation_status(
                    "neutral", "ROLERUN PREPARADO",
                    "Selecciona una acción para continuar.",
                )

    def _widget_alive(self, widget) -> bool:
        if widget is None:
            return False
        try:
            return bool(widget.winfo_exists())
        except Exception:
            return False

    def _game_label(self, game_key: str | None = None) -> str:
        key = game_key or self.selected_game_key
        for current_key, label, _enabled in self.GAME_OPTIONS:
            if current_key == key:
                return label
        return (key or "").upper()

    def _trainer_label(self) -> str:
        if self.current_game and self.current_game.trainer:
            return self.current_game.trainer
        if self.project:
            return self.project.name
        return "Jugador"

    def _update_top_status(self) -> None:
        # Durante el cambio de partida la shell anterior ya está destruida y
        # la nueva aún no existe. No se debe configurar ningún widget en esa
        # ventana intermedia.
        top_status = getattr(self, "top_status", None)
        if not self._shell_built or not self._widget_alive(top_status):
            return

        counter_surface = getattr(self, "header_run_counters", None)
        if self._widget_alive(counter_surface):
            counters = self.project.counters if self.project and self.current_game else {}
            for key, label in getattr(self, "header_counter_labels", {}).items():
                configurar_si_cambia(
                    label,
                    text=str(int(counters.get(key, 0))) if counters else "—",
                    text_color=GOLD if counters else MUTED,
                )
            for key, controls in getattr(self, "header_counter_controls", {}).items():
                if controls is None:
                    continue
                automatic = bool(counters) and self._counter_is_automatic(key)
                enabled = bool(counters) and not automatic
                for button in controls:
                    button.configure(state="normal" if enabled else "disabled")

        count = len(self.run.pending_changes)
        live_review_count = sum(len(batch) for batch in self._oras_live_review_batches)
        # Revisar solo lee. Bloquearlo durante una escritura era justo lo
        # contrario de lo que hace falta: es cuando más quiere el usuario ver
        # qué se está enviando y qué queda esperando en la cola.
        review_state = "normal" if (count or live_review_count) else "disabled"
        review_button = getattr(self, "review_changes_button", None)
        if self._widget_alive(review_button):
            review_button.configure(state=review_state)

        discard_button = getattr(self, "discard_changes_button", None)
        if self._widget_alive(discard_button):
            discard_button.configure(
                state="normal" if count and not self._live_write_in_progress else "disabled"
            )

        save_button = getattr(self, "save_changes_button", None)
        if self._widget_alive(save_button):
            if count and not self._live_write_in_progress:
                save_button.configure(
                    state="normal", fg_color=GOLD, hover_color="#D3AF70",
                    text_color="#111111", border_width=0,
                )
            else:
                save_button.configure(
                    state="disabled", fg_color="#292929", hover_color="#292929",
                    text_color_disabled="#858585", border_width=1, border_color="#3B3B3B",
                )

        if self.project and self.current_game:
            if self._live_write_in_progress:
                # 2026-09-05: el resumen de la cola («2/5», «restan 3»...)
                # cambia con cada elemento que se procesa, y este texto se
                # reconfigura sin ninguna protección contra republicar lo
                # mismo (a diferencia de la barra de estado, que sí evita
                # reescribirse cuando el mensaje no cambia). En una ráfaga de
                # varios cambios pequeños, esta línea parpadeaba ilegible justo
                # debajo del "CARGANDO…" ya estabilizado de la barra. Un texto
                # fijo mientras dura la escritura evita ese segundo parpadeo.
                top_status.configure(
                    text=f"RUN: {self.project.name}\n◷ Aplicando cambios en Azahar…",
                    text_color=GOLD,
                )
            elif self._pending_ds_install is not None:
                top_status.configure(
                    text=f"RUN: {self.project.name}\n◷ Cambios preparados\nEsperando al reinicio del juego…",
                    text_color=GOLD,
                )
            elif count:
                suffix = "cambio pendiente" if count == 1 else "cambios pendientes"
                if self._uses_instant_realtime_ui():
                    top_status.configure(
                        text=f"RUN: {self.project.name}\n⚠ {count} {suffix} sin confirmar en el juego\n{self.sync_status}",
                        text_color=GOLD,
                    )
                else:
                    top_status.configure(
                        text=f"RUN: {self.project.name}\n⚠ {count} {suffix} de guardar",
                        text_color=GOLD,
                    )
            else:
                persisted_label = (
                    "✓ Cambios en Azahar"
                    if bool(self.current_game.raw.get("liveWrite"))
                    else "✓ Cambios guardados"
                )
                sync_text = str(self.sync_status or "")
                sync_color = (
                    DANGER if sync_text.startswith("⚠")
                    else GOLD if sync_text.startswith("◷") or sync_text.startswith("◌")
                    else SUCCESS
                )
                top_status.configure(
                    text=f"RUN: {self.project.name}\n{persisted_label}\n{self.sync_status}",
                    text_color=sync_color,
                )
        else:
            top_status.configure(text="Sin Run activa", text_color=MUTED)
        sync_operation_status = getattr(self, "_sync_operation_status_from_runtime", None)
        if callable(sync_operation_status):
            sync_operation_status()

    def _update_header_counter_visibility(self, event=None) -> None:
        """Reserva el resumen completo para cabeceras donde realmente cabe."""
        widget = getattr(self, "header_run_counters", None)
        if not self._widget_alive(widget):
            return
        width = int(getattr(event, "width", 0) or 0)
        if width <= 0:
            try:
                width = int(widget.master.winfo_width())
            except Exception:
                return
        if width >= 1380:
            widget.grid()
        else:
            widget.grid_remove()

    def _pending_role_change_for(self, pokemon: SavePokemon) -> PendingRoleChange | None:
        """El ``PendingRoleChange`` más reciente que afecta a ``pokemon``.

        Extraído de ``_effective_role``: los cambios de rol siguen al
        Pokémon por identidad (desde 1.12.5), con el número de slot como
        único fallback -y solo fuera de una proyección ya compactada
        (``box in {-1, -2}``)-. Reutilizado también por ``_projected_party``
        para saber si hay ``new_evs`` con los que proyectar stats.

        Corta antes de calcular la identidad si no hay ningún
        ``PendingRoleChange`` en la cola: evita depender de
        ``_pokemon_identity``/``project_service`` cuando no hay nada que
        pudiera coincidir -importa para dobles de prueba mínimos que no los
        implementan-.
        """
        pending_changes = self.run.pending_changes
        if not any(isinstance(change, PendingRoleChange) for change in pending_changes):
            return None
        identity = self._pokemon_identity(pokemon)
        return next((
            change for change in reversed(pending_changes)
            if isinstance(change, PendingRoleChange)
            and (
                (change.pokemon_identity and change.pokemon_identity == identity)
                or (not change.pokemon_identity and pokemon.box not in {-1, -2} and change.pokemon_slot == pokemon.slot)
            )
        ), None)

    def _effective_role(self, pokemon: SavePokemon) -> tuple[str, str]:
        symbols = ROLE_SYMBOLS

        pending = self._pending_role_change_for(pokemon)
        if pending:
            role = canonical_role(pending.new_role)
            return role, symbols.get(role, "")

        # Los Pokémon de la proyección llevan ya horneado el rol que tenían al
        # entrar en esa proyección. Si no hay un cambio pendiente por identidad,
        # ese valor es el que corresponde mostrar.
        if pokemon.box in {-1, -2}:
            role = canonical_role(pokemon.role)
            return role, symbols.get(role, pokemon.role_symbol)

        if not self.project:
            role = canonical_role(pokemon.role)
            return role, symbols.get(role, pokemon.role_symbol)
        key = self.project_service.pokemon_key(pokemon.slot, pokemon.species_id, pokemon.nickname)
        override = self.project.role_overrides.get(key)
        if override:
            role = canonical_role(override)
            return role, symbols.get(role, "")
        role = canonical_role(pokemon.role)
        return role, symbols.get(role, pokemon.role_symbol)

    @staticmethod
    def _role_symbol(role: str) -> str:
        return ROLE_SYMBOLS.get(canonical_role(role), "")

    def _pokemon_identity(self, pokemon: SavePokemon) -> str:
        return self.project_service.pokemon_identity_key(
            pokemon.species_id, pokemon.pid, pokemon.tid, pokemon.sid, pokemon.nickname or pokemon.species,
        )

    def _schedule_oras_external_pc_reconcile(
        self, before: SaveGameData, after: SaveGameData, *, force: bool = False,
    ) -> None:
        """Reconcilia el PC vivo 3DS contra el último ``main`` conocido.

        ORAS/X-Y usan PK6 y Sol/Luna mantiene en alpha.30 la lectura live PK7 coherente con la party publicada. La UI no
        conoce ni inventa direcciones RAM: RealTimeCore delega en el adaptador
        activo y toda lectura completa se hace en background. Hay dos
        motivos para lanzar la lectura completa en background:

        - un cambio de composición detectado en el propio juego (Mover/Sacar/Dejar),
        - una apertura explícita de CAJAS PC (``force=True``), aunque la party no
          haya cambiado, para que la página no dependa de un ``main`` antiguo.

        La matriz viva solo se acepta cuando el adaptador activo la demuestra con
        identidades conocidas. Si falla, no se inventa una dirección: para los
        cambios de party se conserva únicamente la inferencia antigua que ya era
        segura; una actualización forzada mantiene la última vista conocida.
        """
        if not self.project or not self.current_save:
            return
        # Las instancias completas de la UI siempre exponen este selector. El
        # fallback a ORAS mantiene compatibles pruebas/objetos parciales que usan
        # directamente este reconciliador histórico sin construir toda la ventana.
        live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
        live_key = live_key_getter() if callable(live_key_getter) else "oras"
        if live_key not in LIVE_PC_READ_GAME_KEYS:
            return
        if live_key == "oras":
            # El adaptador completa naturaleza, IV/EV, estadísticas finales y
            # stats base con el Personal de la ROM efectiva. Prepararlo antes
            # de lanzar el worker evita publicar una lectura PK6 válida pero
            # incompleta durante el arranque o tras F5.
            prepare_metadata = getattr(self, "_prepare_oras_live_metadata_profile", None)
            if callable(prepare_metadata):
                prepare_metadata()

        def record_bdsp(event: str, **fields: object) -> None:
            recorder = getattr(self, "_record_bdsp_ui_event", None)
            if callable(recorder):
                recorder(event, **fields)

        before_by_id = {self._pokemon_identity(p): p for p in before.party}
        after_by_id = {self._pokemon_identity(p): p for p in after.party}
        incoming_ids = [identity for identity in after_by_id if identity not in before_by_id]
        outgoing_ids = [identity for identity in before_by_id if identity not in after_by_id]
        if not incoming_ids and not outgoing_ids and not force:
            return

        record_bdsp(
            "pc-reconcile-scheduled",
            force=bool(force),
            incoming_count=len(incoming_ids),
            outgoing_count=len(outgoing_ids),
            before_party=len(before.party),
            after_party=len(after.party),
        )

        key = (
            live_key, bool(force),
            tuple(sorted(incoming_ids)), tuple(sorted(outgoing_ids)),
            len(before.party), len(after.party),
        )
        if key == self._oras_pc_reconcile_last_key and self._oras_pc_reconcile_in_progress:
            return
        self._oras_pc_reconcile_last_key = key
        self._oras_pc_reconcile_token += 1
        token = self._oras_pc_reconcile_token
        generation = self._session_generation
        project_slug = self.project.slug
        save_path = Path(self.current_save.path)
        signature = self._save_file_signature(save_path)

        def clone_for_box(source: SavePokemon, live: SavePokemon, box: int, slot: int) -> SavePokemon:
            # El reader vivo ORAS ya publica el PK6 almacenado enriquecido con la
            # tabla Personal exacta de la ROM. Partimos de él para no perder
            # naturaleza, stats, base stats, IV ni EV al proyectar un movimiento.
            clone = copy.deepcopy(live)
            # Un PK6 almacenado no guarda el nivel de party ni garantiza etiquetas
            # localizadas. Conservamos únicamente esos fallbacks del objeto conocido.
            if not str(clone.species or "").strip():
                clone.species = source.species
            if not str(clone.nickname or "").strip():
                clone.nickname = source.nickname
            if int(clone.level or 0) <= 0:
                clone.level = source.level
            clone.box, clone.box_slot, clone.slot = int(box), int(slot), int(slot)
            return clone

        def fallback_inference(pc_data: SavePCData) -> None:
            """Mantiene Mover/Sacar aunque una lectura viva completa falle."""
            if len(incoming_ids) != 1 or len(outgoing_ids) > 1:
                return
            incoming_id = incoming_ids[0]
            outgoing_id = outgoing_ids[0] if outgoing_ids else ""
            source: SavePokemon | None = None
            for box_no in range(1, int(pc_data.box_count) + 1):
                for candidate in self._project_pc_box_pokemon(
                    pc_data, box_no, solo_confirmado=True,
                ):
                    if self._pokemon_identity(candidate) == incoming_id:
                        source = candidate
                        break
                if source is not None:
                    break
            if source is None or source.box is None or source.box_slot is None:
                return
            pos = (int(source.box), int(source.box_slot))
            if not outgoing_id:
                self._oras_live_pc_overrides.pop(pos, None)
                self._oras_live_pc_empty_overrides.add(pos)
            else:
                outgoing = copy.deepcopy(before_by_id.get(outgoing_id))
                if outgoing is None:
                    return
                outgoing.box, outgoing.box_slot, outgoing.slot = pos[0], pos[1], pos[1]
                self._oras_live_pc_empty_overrides.discard(pos)
                self._oras_live_pc_overrides[pos] = outgoing

        def finish(pc_data: SavePCData | None, live_slots, error: str | None) -> None:
            if token != self._oras_pc_reconcile_token:
                return
            self._oras_pc_reconcile_in_progress = False
            if (
                generation != self._session_generation
                or not self.project or self.project.slug != project_slug
                or pc_data is None
            ):
                return

            projection_changed = False
            if error or live_slots is None:
                record_bdsp(
                    "pc-reconcile-error", force=bool(force),
                    error=str(error or "sin slots"),
                )
                if not force:
                    fallback_inference(pc_data)
                elif error:
                    intentos = int(getattr(self, "_oras_pc_read_retries", 0))
                    if intentos < len(LIVE_PC_READ_RETRY_DELAYS_MS):
                        # La matriz no se deja localizar mientras el juego
                        # reconstruye sus cajas. Volver a leer un momento después
                        # es exactamente lo que hacía el botón REINTENTAR.
                        self._oras_pc_read_retries = intentos + 1
                        record_bdsp(
                            "pc-reconcile-reread",
                            intento=intentos + 1, error=str(error),
                        )
                        self.sync_status = (
                            f"◌ {self._active_azahar_realtime_label()} · reintentando la "
                            "lectura del PC…"
                        )
                        self._update_top_status()
                        try:
                            self.after(
                                LIVE_PC_READ_RETRY_DELAYS_MS[intentos],
                                lambda: self._schedule_oras_external_pc_reconcile(
                                    self.current_game, self.current_game, force=True,
                                ),
                            )
                        except Exception:
                            self._oras_pc_read_retries = 0
                        else:
                            return
                    # Alpha.13: una lectura fallida al abrir CAJAS PC ya no se
                    # disfraza visualmente de "caja vacía". Conservamos la última
                    # vista conocida y exponemos el motivo técnico al usuario.
                    self._oras_pc_read_retries = 0
                    show_toast = getattr(self, "_show_live_sync_toast", None)
                    if callable(show_toast):
                        show_toast(
                            f"NO SE PUDO LEER EL PC DE {self._active_azahar_realtime_label()}",
                            str(error)
                            + "\n\nRoleRun no ha publicado una caja vacía como si fuera el estado real."
                            + PISTA_GUARDAR_PARA_LOCALIZAR_EL_PC,
                            False,
                        )
            else:
                self._oras_pc_read_retries = 0
                # Alpha.28: barrera de coherencia entre dos lecturas asíncronas.
                # La party y el PC se capturan en workers distintos; si el usuario
                # mueve un Pokémon justo entre ambas dobles lecturas, una captura
                # individual puede ser válida pero pertenecer al instante anterior.
                # Nunca publicamos entonces la misma identidad fuerte a la vez en
                # Equipo y PC: conservamos la última vista de cajas y repetimos una
                # lectura completa contra la party que está publicada AHORA.
                if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                    published_game = getattr(self, "current_game", None)
                    party_ids = {
                        self._pokemon_identity(pokemon)
                        for pokemon in tuple(getattr(published_game, "party", ()) or ())
                        if self._pokemon_identity(pokemon)
                    }
                    live_pc_ids = {
                        self._pokemon_identity(pokemon)
                        for pokemon in live_slots.values()
                        if pokemon is not None and self._pokemon_identity(pokemon)
                    }
                    overlap_ids = party_ids & live_pc_ids
                    if overlap_ids:
                        record_bdsp(
                            "pc-reconcile-retry", overlap_count=len(overlap_ids),
                        )
                        self.sync_status = (
                            f"◌ {self._active_azahar_realtime_label()} · releyendo Equipo/PC tras transición…"
                        )
                        self._update_top_status()
                        try:
                            self.after(220, lambda: self._schedule_oras_external_pc_reconcile(
                                self.current_game, self.current_game, force=True,
                            ))
                        except Exception:
                            pass
                        return

                if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                    # BDSP aporta el PB8 completo y USUM el PK7 completo,
                    # incluidos naturaleza, IV y EV. Comparar solo
                    # identidad/posición contra el save descarta justamente
                    # esos metadatos cuando el Pokémon no se ha movido.
                    live_pc_data = RoleRunManager._pc_data_from_live_slots(
                        pc_data, live_slots,
                    )
                    projection_changed = (
                        RoleRunManager._pc_presentation_signature(self._pc_cache)
                        != RoleRunManager._pc_presentation_signature(live_pc_data)
                    )
                    pc_data = live_pc_data
                    self._oras_live_pc_overrides.clear()
                    self._oras_live_pc_empty_overrides.clear()
                    recordar = getattr(self, "_recordar_anclas_del_pc_vivo", None)
                    if callable(recordar):
                        recordar(live_pc_data)
                    new_overrides: dict[tuple[int, int], SavePokemon] = {}
                    new_empty: set[tuple[int, int]] = set()
                else:
                    # Base física del último guardado. Los overrides resultantes son
                    # exactamente la diferencia entre ese main y las cajas vivas.
                    base_by_pos: dict[tuple[int, int], SavePokemon] = {}
                    known_by_identity: dict[str, SavePokemon] = {}
                    for box in pc_data.boxes:
                        for pokemon in box.pokemon:
                            if pokemon.box is None or pokemon.box_slot is None:
                                continue
                            pos = (int(pokemon.box), int(pokemon.box_slot))
                            base_by_pos[pos] = pokemon
                            known_by_identity[self._pokemon_identity(pokemon)] = pokemon
                    # Incluimos lo que RoleRun ya sabía de operaciones vivas anteriores
                    # y ambos estados de party para conservar nombres/niveles localizados.
                    for pokemon in self._oras_live_pc_overrides.values():
                        known_by_identity[self._pokemon_identity(pokemon)] = pokemon
                    for pokemon in (*before.party, *after.party):
                        known_by_identity[self._pokemon_identity(pokemon)] = pokemon

                    new_overrides = {}
                    new_empty = set()
                    max_box = int(pc_data.box_count)
                    max_slot = int(pc_data.box_slot_count or ORAS_PC_BOX_SLOT_COUNT)
                    for box_no in range(1, max_box + 1):
                        for box_slot in range(1, max_slot + 1):
                            pos = (box_no, box_slot)
                            live = live_slots.get(pos)
                            base = base_by_pos.get(pos)
                            live_id = self._pokemon_identity(live) if live is not None else ""
                            base_id = self._pokemon_identity(base) if base is not None else ""
                            if live_id == base_id:
                                continue
                            if live is None:
                                if base is not None:
                                    new_empty.add(pos)
                                continue
                            source = known_by_identity.get(live_id, live)
                            new_overrides[pos] = clone_for_box(source, live, box_no, box_slot)

                    projection_changed = bool(
                        new_overrides != self._oras_live_pc_overrides
                        or new_empty != self._oras_live_pc_empty_overrides
                    )
                    self._oras_live_pc_overrides = new_overrides
                    self._oras_live_pc_empty_overrides = new_empty
                    if live_key == "oras":
                        # La rama histórica de ORAS calcula diferencias físicas
                        # respecto al save. Cuando identidad y posición coinciden no
                        # hay override, pero sí deben publicarse los metadatos ricos
                        # que solo aporta el reader vivo.
                        enriched_pc_data = self._pc_data_with_live_presentation(
                            pc_data, live_slots,
                        )
                        projection_changed = bool(
                            projection_changed
                            or self._pc_presentation_signature(self._pc_cache)
                            != self._pc_presentation_signature(enriched_pc_data)
                        )
                        pc_data = enriched_pc_data
                record_bdsp(
                    "pc-reconcile-applied",
                    occupied_slots=len(live_slots),
                    override_slots=len(new_overrides),
                    emptied_slots=len(new_empty),
                    before_party=len(before.party),
                    after_party=len(after.party),
                    changed=projection_changed,
                )

            # El sondeo se espacia mientras el PC no se mueva. Leerlo cuesta 400
            # KB de la memoria de Ryujinx cada vez, y esa lectura compite con el
            # emulador: medido, 57 segundos de lectura del PC en una sesión de 22
            # minutos. Un cambio hecho dentro del juego vuelve a acelerarlo.
            self._pc_poll_delay = (
                BDSP_PC_POLL_MIN_MS if projection_changed
                else min(BDSP_PC_POLL_MAX_MS, int(self._pc_poll_delay) * 2)
            )

            self._pc_cache = pc_data
            self._pc_cache_signature = signature

            # Alpha.29: solo una lectura PC SM completa y coherente habilita la
            # escritura automática del rol heredado. El reader acaba de demostrar
            # aquí host↔guest para la matriz actual y ha refrescado la ancla de
            # party asociada; por tanto ya no competimos con el buffer anterior.
            if live_key in GEN7_REALTIME_GAME_KEYS and not error and live_slots is not None:
                self._flush_sm_role_transition_after_pc_proof()

            should_render = bool(
                live_key not in PC_LIVE_POLL_GAME_KEYS
                or error
                or live_slots is None
                or projection_changed
            )
            if should_render:
                if self._floating_bar_is_visible():
                    self._main_ui_dirty_while_floating = True
                elif self.active_page in {"pc", "team"}:
                    self._smooth_render_page(preserve_scroll=False)

            # Un poll no se solapa con otro: el siguiente solo nace cuando la
            # lectura anterior ya terminó y publicó (o rechazó) su captura. Ante
            # error detenemos el bucle para no castigar el emulador ni repetir avisos;
            # volver a entrar en CAJAS PC permite rearmarlo explícitamente.
            if live_key in PC_LIVE_POLL_GAME_KEYS and not error and live_slots is not None:
                scheduler = getattr(self, "_schedule_bdsp_pc_poll", None)
                if callable(scheduler):
                    scheduler()

        self._oras_pc_reconcile_in_progress = True

        def worker() -> None:
            try:
                pc_data = (
                    self._pc_cache
                    if self._pc_cache is not None and signature == self._pc_cache_signature
                    else self.save_engine.read_boxes(save_path)
                )
                anchors: list[SavePokemon] = []
                if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                    # Los Pokémon guardados aportan nombre/nivel localizados cuando
                    # coinciden por identidad fuerte, pero no localizan ni validan
                    # por sí solos la matriz viva.
                    for box in pc_data.boxes:
                        anchors.extend(list(box.pokemon))
                else:
                    for box_no in range(1, int(pc_data.box_count) + 1):
                        # Un traslado aún sin escribir apuntaría a un hueco que
                        # la RAM no tiene, y entonces la matriz viva no se
                        # localiza: la lectura entera se rechaza.
                        anchors.extend(self._project_pc_box_pokemon(
                            pc_data, box_no, solo_confirmado=True,
                        ))
                # Sirven en las dos ramas: son coordenadas que la RAM ya
                # demostró y que el ``main`` puede haber dejado de reflejar.
                recordadas = getattr(self, "_anclas_del_pc_recordadas", None)
                if callable(recordadas):
                    anchors.extend(recordadas())

                # Si la party acaba de perder un Pokémon, esa
                # identidad constituye evidencia adicional de presencia en el PC
                # aunque el último ``main`` tuviera todas las cajas vacías. Se
                # pasa sin box/slot: sirve para validar una matriz viva ya
                # localizada, nunca para inventar su posición.
                if live_key in ({"xy"} | FULL_MATRIX_LIVE_PC_GAME_KEYS):
                    known_anchor_ids = {self._pokemon_identity(pokemon) for pokemon in anchors}
                    for identity in outgoing_ids:
                        source = before_by_id.get(identity)
                        if source is None or identity in known_anchor_ids:
                            continue
                        anchors.append(replace(source, box=None, box_slot=None))
                        known_anchor_ids.add(identity)

                realtime_core = getattr(self, "realtime_core", None)
                pc_kwargs = {
                    "box_count": int(pc_data.box_count),
                    "box_slot_count": int(pc_data.box_slot_count),
                }
                if realtime_core is not None:
                    if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                        _process, _pc_base, live_slots = realtime_core.read_pc(anchors, **pc_kwargs)
                    else:
                        _process, _pc_base, live_slots = realtime_core.read_pc(anchors)
                else:
                    # Compatibilidad con pruebas/instancias parciales de la UI.
                    if live_key == "xy":
                        reader = getattr(self, "xy_live_reader", None)
                    elif live_key in GEN7_REALTIME_GAME_KEYS:
                        reader = getattr(self, "usum_realtime_adapter" if live_key == "usum" else "sm_realtime_adapter", None)
                    elif live_key == "bdsp":
                        reader = getattr(self, "bdsp_realtime_adapter", None)
                    elif live_key in MELONDS_REALTIME_GAME_KEYS:
                        reader = getattr(self, f"{live_key}_realtime_adapter", None)
                    else:
                        reader = getattr(self, "oras_live_reader", None)
                    if reader is None:
                        raise RuntimeError(f"No hay lector vivo de PC disponible para {live_key}.")
                    if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                        _process, _pc_base, live_slots = reader.read_pc(anchors, **pc_kwargs)
                    else:
                        _process, _pc_base, live_slots = reader.read_pc(anchors)
                error = None
            except Exception as exc:
                try:
                    pc_data
                except UnboundLocalError:
                    pc_data = None
                live_slots = None
                error = str(exc)
            try:
                self.after(0, lambda: finish(pc_data, live_slots, error))
            except Exception:
                pass

        threading.Thread(
            target=worker, daemon=True, name="RoleRunLivePCReconcile",
        ).start()

    def _schedule_gen6_live_pc_refresh(self) -> None:
        """Actualiza CAJAS PC live al entrar en la pestaña, sin bloquear Tk."""
        live_key = self._active_azahar_realtime_key()
        recorder = getattr(self, "_record_bdsp_ui_event", None)
        if callable(recorder):
            recorder(
                "pc-refresh-requested",
                live_key=live_key,
                has_game=bool(self.current_game),
                live_active=bool(self._oras_live_active),
                active_page=str(getattr(self, "active_page", "")),
            )
        if (
            not self.current_game
            or not self._oras_live_active
            or live_key not in LIVE_PC_READ_GAME_KEYS
            or (live_key not in ({"bdsp"} | MELONDS_REALTIME_GAME_KEYS) and not self._oras_live_auto_apply_available())
        ):
            return
        self._schedule_oras_external_pc_reconcile(
            self.current_game, self.current_game, force=True,
        )

    def _cancel_bdsp_pc_poll(self) -> None:
        after_id = getattr(self, "_bdsp_pc_poll_after_id", None)
        self._bdsp_pc_poll_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass

    def _bdsp_pc_poll_is_active(self) -> bool:
        if (
            getattr(self, "active_page", "") not in TEAM_PC_PAGES
            or not getattr(self, "_oras_live_active", False)
            or not getattr(self, "current_game", None)
            or self._active_azahar_realtime_key() not in PC_LIVE_POLL_GAME_KEYS
            or self._floating_bar_is_visible()
        ):
            return False
        state_getter = getattr(self, "state", None)
        if callable(state_getter):
            try:
                if str(state_getter()) in {"withdrawn", "iconic"}:
                    return False
            except Exception:
                return False
        return True

    def _schedule_bdsp_pc_poll(self, delay: int | None = None) -> None:
        """Sondea PC↔PC solo mientras la página live compatible está visible.

        No hay escaneo: reutiliza la matriz completa y el doble read demostrados
        por el backend activo (BDSP 40×30, B2/W2 24×30 u ORAS 31×30).
        El siguiente tick se programa al terminar el anterior, por lo que nunca
        se acumulan workers aunque el emulador tarde más de lo habitual.
        """
        self._cancel_bdsp_pc_poll()
        if not self._bdsp_pc_poll_is_active():
            return
        generation = self._session_generation

        def poll() -> None:
            self._bdsp_pc_poll_after_id = None
            if generation != self._session_generation or not self._bdsp_pc_poll_is_active():
                return
            if self._oras_pc_reconcile_in_progress:
                self._schedule_bdsp_pc_poll(350)
                return
            # Un traslado hecho DESDE RoleRun se ve al instante en pantalla antes
            # de que el juego lo confirme (ver `move-box-slot`). Si el sondeo
            # leyera la RAM justo en ese hueco, traía el estado ANTERIOR y
            # deshacía ese adelanto visual un instante, para que la escritura lo
            # volviera a corregir enseguida: el mismo parpadeo que ya se arregló
            # una vez, solo que por otra puerta. Mientras haya una escritura o un
            # traslado esperando turno, el sondeo se aplaza sin gastar el ciclo.
            cola = getattr(self, "cola_de_cambios", None)
            if getattr(self, "_live_write_in_progress", False) or (
                cola is not None and cola.estado().hay_trabajo
            ):
                self._schedule_bdsp_pc_poll(350)
                return
            self._record_bdsp_ui_event("pc-poll")
            self._schedule_oras_external_pc_reconcile(
                self.current_game, self.current_game, force=True,
            )

        espera = int(self._pc_poll_delay) if delay is None else int(delay)
        self._bdsp_pc_poll_after_id = self.after(max(150, espera), poll)

    def _apply_project_marker_layout(self, data: SaveGameData | None) -> None:
        """Reinterpreta las seis marcas según el contrato persistido de la Run."""
        if data is None or not self.project:
            return
        layout = 2 if int(getattr(self.project, "role_marker_layout", 1) or 1) >= 2 else 1
        self.native_save_engine.set_role_marker_layout(layout)
        for pokemon in data.party:
            role, symbol = role_from_markings(pokemon.markings, layout=layout)
            pokemon.role = role
            pokemon.role_symbol = symbol

    def _oras_marker_layout_migration_changes(self, game: SaveGameData) -> list[PendingRoleChange]:
        """Conserva el rol semántico al mover una Run <=alpha.42 al layout alpha.43.

        El snapshot vivo ya se interpreta con el layout nuevo. Para saber qué rol
        tenía realmente el usuario antes de actualizar, releemos exactamente los
        mismos seis bits con el layout histórico y escribimos ese rol en su nueva
        posición física.
        """
        if not self.project or int(getattr(self.project, "role_marker_layout", 1) or 1) >= 2:
            return []
        result: list[PendingRoleChange] = []
        for pokemon in game.party:
            target_role, _ = role_from_markings(pokemon.markings, layout=1)
            current_role, _ = role_from_markings(pokemon.markings, layout=2)
            if target_role == current_role:
                continue
            result.append(PendingRoleChange(
                pokemon_slot=int(pokemon.slot),
                pokemon=pokemon.nickname or pokemon.species,
                species=pokemon.species,
                old_role=current_role,
                new_role=target_role,
                pokemon_identity=self._pokemon_identity(pokemon),
            ))
        return result

    def _complete_role_marker_layout_migration(self) -> None:
        if not self.project:
            return
        self.project.role_marker_layout = 2
        self.native_save_engine.set_role_marker_layout(2)
        self.project_service.save(self.project)

    def _prepare_bdsp_marker_layout_migration(self, game: SaveGameData) -> list[PendingRoleChange]:
        """Prepara la migración física para el writer runtime de una Run BDSP antigua."""
        self._bdsp_marker_migration_change_ids.clear()
        self._bdsp_marker_migration_expected.clear()
        if (
            getattr(self.save_engine, "key", "") != "bdsp"
            or not self.project
            or int(getattr(self.project, "role_marker_layout", 1) or 1) >= 2
        ):
            return []
        changes = self._oras_marker_layout_migration_changes(game)
        if not changes:
            # SIN ROL y Líbero ocupan los mismos bits en ambos contratos.
            self._complete_role_marker_layout_migration()
            return []
        self.run.pending_changes.extend(changes)
        self._bdsp_marker_migration_change_ids.update(id(change) for change in changes)
        self._bdsp_marker_migration_expected.update({
            str(change.pokemon_identity): str(change.new_role) for change in changes
        })
        return changes

    def _verify_bdsp_marker_layout_migration(
        self, game: SaveGameData, changes: list[object],
    ) -> None:
        """Demuestra que el archivo preparado contiene los bits del layout 2."""
        if not self._bdsp_marker_migration_expected:
            return
        expected = dict(self._bdsp_marker_migration_expected)
        # Un cambio de rol posterior y explícito sobre el mismo Pokémon prevalece
        # sobre el rol semántico que tenía al iniciar la migración.
        for change in changes:
            if isinstance(change, PendingRoleChange):
                identity = str(change.pokemon_identity or "")
                if identity in expected:
                    expected[identity] = str(change.new_role)
        by_identity = {
            self._pokemon_identity(pokemon): pokemon for pokemon in game.party
        }
        for identity, target_role in expected.items():
            pokemon = by_identity.get(identity)
            if pokemon is None:
                raise ValueError(
                    "La verificación del layout de marcadores no encontró uno de los Pokémon migrados."
                )
            actual_role, _symbol = role_from_markings(pokemon.markings, layout=2)
            if actual_role != target_role:
                raise ValueError(
                    f"La migración de marcadores esperaba {target_role} para "
                    f"{pokemon.nickname or pokemon.species}, pero el readback físico devolvió {actual_role}."
                )

    def _register_party_roles(self, data: SaveGameData | None = None) -> None:
        """Registra como intencionales únicamente los roles de Pokémon activos.

        Las marcas de los Pokémon que ya estaban en el PC antes de usar el Manager
        no se interpretan automáticamente como roles RoleRun. Así una marca casual
        del propio juego nunca convierte un Aron, por ejemplo, en Tanque sin que el
        usuario lo haya decidido.
        """
        if not self.project:
            return
        changed = False
        for pokemon in (data.party if data is not None else (self.current_game.party if self.current_game else [])):
            identity = self._pokemon_identity(pokemon)
            role = pokemon.role if pokemon.role in ROLE_TO_KEY else "SIN ROL"
            if role == "SIN ROL":
                if identity in self.project.managed_pokemon_roles:
                    self.project.managed_pokemon_roles.pop(identity, None)
                    changed = True
            elif self.project.managed_pokemon_roles.get(identity) != role:
                self.project.managed_pokemon_roles[identity] = role
                changed = True
        if changed:
            self.project_service.save(self.project)

    def _pending_pc_role_change(self, pokemon: SavePokemon) -> PendingPCRoleChange | None:
        if pokemon.box is None or pokemon.box_slot is None:
            return None
        return next((
            change for change in reversed(self.run.pending_changes)
            if isinstance(change, PendingPCRoleChange)
            and change.box == pokemon.box and change.box_slot == pokemon.box_slot
        ), None)

    def _pc_effective_role(self, pokemon: SavePokemon) -> tuple[str, str]:
        pending = self._pending_pc_role_change(pokemon)
        if pending is not None:
            role = pending.new_role
            return role, self._role_symbol(role)
        # Si el Pokémon aparece en el PC solo como resultado provisional de un
        # movimiento del equipo, su snapshot ya contiene el rol efectivo (incluido
        # cualquier cambio de rol preparado antes de empezar a reorganizar).
        if pokemon.box is not None and pokemon.box_slot is not None:
            for change in reversed(RoleRunManager._projectable_team_changes(self)):
                if (
                    change.operation in {"party-to-box", "swap-party-box"}
                    and change.box == pokemon.box and change.box_slot == pokemon.box_slot
                    and change.outgoing_snapshot
                ):
                    outgoing = self._pokemon_from_snapshot(change.outgoing_snapshot)
                    if self._pokemon_identity(outgoing) == self._pokemon_identity(pokemon):
                        role = pokemon.role if pokemon.role in ROLE_TO_KEY else "SIN ROL"
                        return role, self._role_symbol(role)
        if not self.project:
            return "SIN ROL", ""
        role = self.project.managed_pokemon_roles.get(self._pokemon_identity(pokemon), "SIN ROL")
        if role not in ROLE_TO_KEY:
            role = "SIN ROL"
        return role, self._role_symbol(role)

    def _pending_team_changes(self) -> list[PendingTeamChange]:
        return [c for c in self.run.pending_changes if isinstance(c, PendingTeamChange)]

    def _pending_team_change(self) -> PendingTeamChange | None:
        """Compatibilidad interna: devuelve el último movimiento Equipo ↔ PC."""
        changes = self._pending_team_changes()
        return changes[-1] if changes else None

    def _projectable_team_changes(self) -> list[PendingTeamChange]:
        """Cambios Equipo↔PC que pueden adelantarse visualmente.

        En los backends live que escriben inmediatamente (Gen 7 y BDSP), estas
        operaciones no se proyectan nunca antes de la verificación real. Esto evita
        repetir el falso positivo de alpha.30: Dashboard, barra y PC siguen
        mostrando el último estado confirmado hasta que el writer devuelve una
        captura viva validada. En motores clásicos conserva la proyección previa.
        """
        pending_getter = getattr(self, "_pending_team_changes", None)
        changes = list(pending_getter() if callable(pending_getter) else [])
        key_getter = getattr(self, "_active_azahar_realtime_key", None)
        auto_getter = getattr(self, "_oras_live_auto_apply_available", None)
        live_key = key_getter() if callable(key_getter) else None
        live_auto = bool(auto_getter()) if callable(auto_getter) else False
        if live_key in (GEN7_REALTIME_GAME_KEYS | {"bdsp"}) and live_auto:
            # Un traslado PC→PC sí se adelanta incluso aquí: no afirma nada del
            # equipo, de los PS ni de la mochila —solo que el Pokémon ocupa otro
            # hueco de la misma tabla de cajas— y si la escritura falla, retirar
            # el cambio pendiente lo devuelve solo a su hueco original.
            return [
                change for change in changes
                if change.operation == "move-box-slot"
            ]
        return changes

    def _project_pc_box_pokemon(
        self, pc_data: SavePCData, box_number: int, *, solo_confirmado: bool = False,
    ) -> list[SavePokemon]:
        """Proyecta una caja aplicando, en orden, todos los cambios Equipo ↔ PC.

        ``solo_confirmado`` distingue los dos usos, que dejaron de coincidir en
        cuanto un traslado PC→PC empezó a adelantarse en pantalla:

        - **Pintar** (por defecto): lo que el usuario debe ver, adelanto incluido.
        - **Demostrar la RAM** (``True``): lo que el juego tiene AHORA. Los
          testigos que localizan la matriz viva salen de aquí, y un traslado
          todavía sin escribir apuntaría a un hueco que la RAM no tiene: el
          lector no encontraría la matriz y la operación se rechazaría entera.
        """
        original = [replace(p) for p in pc_data.boxes[box_number - 1].pokemon]
        for pokemon in original:
            pokemon.moves = list(pokemon.moves)
            pokemon.move_ids = list(pokemon.move_ids)
            pokemon.markings = list(pokemon.markings)
        by_slot = {int(p.box_slot or p.slot or 0): p for p in original}

        for override_box, override_slot in self._oras_live_pc_empty_overrides:
            if int(override_box) == int(box_number):
                by_slot.pop(int(override_slot), None)

        for (override_box, override_slot), pokemon in self._oras_live_pc_overrides.items():
            if int(override_box) != int(box_number):
                continue
            replacement = replace(pokemon)
            replacement.moves = list(pokemon.moves)
            replacement.move_ids = list(pokemon.move_ids)
            replacement.markings = list(pokemon.markings)
            replacement.box = int(override_box)
            replacement.box_slot = int(override_slot)
            replacement.slot = int(override_slot)
            by_slot[int(override_slot)] = replacement

        for team_change in RoleRunManager._projectable_team_changes(self):
            if team_change.operation == "move-box-slot":
                if solo_confirmado:
                    # Sin escribir todavía: para la RAM, este Pokémon sigue en
                    # su hueco de origen.
                    continue
                # Adelanto visual del traslado dentro del PC. El hueco de origen
                # se vacía y el de destino se ocupa en cuanto el usuario suelta,
                # sin esperar a que el juego confirme; así puede volver a mover
                # al mismo Pokémon sin quedarse mirando el hueco viejo.
                origen = (int(team_change.box or 0), int(team_change.box_slot or 0))
                destino = (
                    int(team_change.destination_box or 0),
                    int(team_change.destination_box_slot or 0),
                )
                if min(origen[1], destino[0], destino[1]) <= 0:
                    continue
                if origen[0] == box_number:
                    by_slot.pop(origen[1], None)
                if destino[0] == box_number and team_change.incoming_snapshot:
                    movido = self._pokemon_from_snapshot(
                        team_change.incoming_snapshot, slot=destino[1], projected=False,
                    )
                    movido.box = destino[0]
                    movido.box_slot = destino[1]
                    movido.slot = destino[1]
                    by_slot[destino[1]] = movido
                continue
            if team_change.box != box_number or not team_change.box_slot:
                continue
            target = int(team_change.box_slot)
            if team_change.operation in {"box-to-party", "replace-fainted"}:
                by_slot.pop(target, None)
            elif team_change.operation in {"party-to-box", "swap-party-box"}:
                if not team_change.outgoing_snapshot:
                    continue
                outgoing = self._pokemon_from_snapshot(team_change.outgoing_snapshot, slot=target, projected=False)
                outgoing.box = box_number
                outgoing.box_slot = target
                outgoing.slot = target
                by_slot[target] = outgoing

            if (
                team_change.operation == "replace-fainted"
                and team_change.graveyard_box == box_number
                and team_change.graveyard_box_slot
                and team_change.outgoing_snapshot
            ):
                grave_slot = int(team_change.graveyard_box_slot)
                outgoing = self._pokemon_from_snapshot(
                    team_change.outgoing_snapshot, slot=grave_slot, projected=False,
                )
                outgoing.box = box_number
                outgoing.box_slot = grave_slot
                outgoing.slot = grave_slot
                by_slot[grave_slot] = outgoing

        return [by_slot[key] for key in sorted(by_slot)]

    def _projected_pc_occupied_positions(self, pc_data: SavePCData) -> set[tuple[int, int]]:
        occupied: set[tuple[int, int]] = set()
        for box in pc_data.boxes:
            for pokemon in box.pokemon:
                if pokemon.box is not None and pokemon.box_slot is not None:
                    occupied.add((int(pokemon.box), int(pokemon.box_slot)))
        occupied.difference_update(self._oras_live_pc_empty_overrides)
        occupied.update(self._oras_live_pc_overrides)
        for change in RoleRunManager._projectable_team_changes(self):
            if change.operation == "move-box-slot":
                if change.box is not None and change.box_slot:
                    occupied.discard((int(change.box), int(change.box_slot)))
                if change.destination_box is not None and change.destination_box_slot:
                    occupied.add(
                        (int(change.destination_box), int(change.destination_box_slot))
                    )
                continue
            if change.box is None or change.box_slot is None:
                continue
            pos = (int(change.box), int(change.box_slot))
            if change.operation in {"box-to-party", "replace-fainted"}:
                occupied.discard(pos)
            elif change.operation in {"party-to-box", "swap-party-box"}:
                occupied.add(pos)
            if (
                change.operation == "replace-fainted"
                and change.graveyard_box is not None
                and change.graveyard_box_slot is not None
            ):
                occupied.add((int(change.graveyard_box), int(change.graveyard_box_slot)))
        return occupied

    def _projected_open_pc_slots(self, pc_data: SavePCData) -> list[tuple[int, int]]:
        occupied = self._projected_pc_occupied_positions(pc_data)
        candidates: list[tuple[int, int]] = list(pc_data.open_slots)
        # Las lecturas vivas pueden haber liberado una casilla que en el último
        # ``main`` seguía ocupada. Debe convertirse también en destino válido.
        max_box = int(pc_data.box_count or 0)
        max_slot = int(pc_data.box_slot_count or ORAS_PC_BOX_SLOT_COUNT)
        candidates.extend(
            (int(box), int(slot))
            for box, slot in self._oras_live_pc_empty_overrides
            if 1 <= int(box) <= max_box and 1 <= int(slot) <= max_slot
        )
        # Un Pokémon que sale del PC libera un hueco seguro y reutilizable durante
        # la misma tanda de cambios, aunque originalmente estuviera ocupado.
        for change in RoleRunManager._projectable_team_changes(self):
            if change.operation == "box-to-party" and change.box is not None and change.box_slot is not None:
                candidates.append((int(change.box), int(change.box_slot)))
        seen: set[tuple[int, int]] = set()
        result: list[tuple[int, int]] = []
        for pos in candidates:
            if pos in seen or pos in occupied:
                continue
            seen.add(pos)
            result.append(pos)
        return sorted(result)

    def _next_projected_open_pc_slot(self, pc_data: SavePCData) -> tuple[int, int] | None:
        slots = self._projected_open_pc_slots(pc_data)
        return slots[0] if slots else None

    def _pokemon_snapshot(self, pokemon: SavePokemon) -> dict[str, object]:
        return {
            "slot": pokemon.slot, "species_id": pokemon.species_id, "species": pokemon.species,
            "nickname": pokemon.nickname, "level": pokemon.level, "held_item": pokemon.held_item,
            "ability": pokemon.ability, "moves": list(pokemon.moves), "move_ids": list(pokemon.move_ids),
            "is_egg": pokemon.is_egg, "markings": list(pokemon.markings), "role": pokemon.role,
            "role_symbol": pokemon.role_symbol, "box": pokemon.box, "box_slot": pokemon.box_slot,
            "pid": pokemon.pid, "tid": pokemon.tid, "sid": pokemon.sid, "form": pokemon.form,
            "current_hp": pokemon.current_hp, "max_hp": pokemon.max_hp,
            "nature_id": pokemon.nature_id, "stat_nature_id": pokemon.stat_nature_id,
            "nature": pokemon.nature, "stat_nature": pokemon.stat_nature,
            "nature_increased": pokemon.nature_increased,
            "nature_decreased": pokemon.nature_decreased,
            "stats": dict(pokemon.stats), "ivs": dict(pokemon.ivs), "evs": dict(pokemon.evs),
        }

    def _pokemon_from_snapshot(self, raw: dict[str, object], slot: int | None = None, projected: bool = False) -> SavePokemon:
        role = str(raw.get("role", "SIN ROL"))
        return SavePokemon(
            slot=int(slot if slot is not None else raw.get("slot", 1)),
            species_id=int(raw.get("species_id", 0)), species=str(raw.get("species", "Desconocido")),
            nickname=str(raw.get("nickname", "")), level=int(raw.get("level", 0)),
            held_item=str(raw.get("held_item", "Ninguno")), ability=str(raw.get("ability", "Desconocida")),
            moves=[str(v) for v in raw.get("moves", [])], move_ids=[int(v) for v in raw.get("move_ids", [])],
            is_egg=bool(raw.get("is_egg", False)), markings=[bool(v) for v in raw.get("markings", [])],
            role=role, role_symbol=self._role_symbol(role),
            box=-1 if projected else (int(raw["box"]) if raw.get("box") is not None else None),
            box_slot=-1 if projected else (int(raw["box_slot"]) if raw.get("box_slot") is not None else None),
            pid=int(raw.get("pid", 0)), tid=int(raw.get("tid", 0)), sid=int(raw.get("sid", 0)),
            form=int(raw.get("form", 0)), current_hp=int(raw.get("current_hp", 0) or 0),
            max_hp=int(raw.get("max_hp", 0) or 0),
            nature_id=(int(raw["nature_id"]) if raw.get("nature_id") is not None else None),
            stat_nature_id=(
                int(raw["stat_nature_id"]) if raw.get("stat_nature_id") is not None else None
            ),
            nature=str(raw.get("nature", "") or ""),
            stat_nature=str(raw.get("stat_nature", "") or ""),
            nature_increased=(
                str(raw["nature_increased"]) if raw.get("nature_increased") else None
            ),
            nature_decreased=(
                str(raw["nature_decreased"]) if raw.get("nature_decreased") else None
            ),
            stats={str(k): int(v) for k, v in dict(raw.get("stats", {}) or {}).items()},
            ivs={str(k): int(v) for k, v in dict(raw.get("ivs", {}) or {}).items()},
            evs={str(k): int(v) for k, v in dict(raw.get("evs", {}) or {}).items()},
        )

    def _incoming_snapshot_for_role(
        self, pokemon: SavePokemon, role: str, remove_move_slots: list[int] | None = None,
    ) -> dict[str, object]:
        clone = replace(pokemon)
        clone.moves = list(pokemon.moves)
        clone.move_ids = list(pokemon.move_ids)
        clone.markings = list(pokemon.markings)
        clone.role = role
        clone.role_symbol = self._role_symbol(role)
        for one_based in sorted(set(remove_move_slots or []), reverse=True):
            idx = one_based - 1
            if 0 <= idx < len(clone.moves):
                clone.moves.pop(idx)
                clone.move_ids.pop(idx)
        while len(clone.moves) < 4:
            clone.moves.append("—")
            clone.move_ids.append(0)
        return self._pokemon_snapshot(clone)

    def _projected_party(self) -> list[SavePokemon]:
        if not self.current_game:
            return []
        party = [replace(p) for p in self.current_game.party]
        for p in party:
            p.moves = list(p.moves)
            p.move_ids = list(p.move_ids)
            p.markings = list(p.markings)

        # Un cambio de rol pendiente ya calcula sus EV al instante
        # (``_apply_role_assignment``), pero las stats numéricas que trae el
        # Pokémon siguen siendo las del último guardado leído hasta que la
        # escritura en vivo confirma -~2s de diferencia, medido en vídeo el
        # 2026-09-04-. Se proyectan aquí, sobre esta copia, con la misma
        # fórmula que ya usa cada escritor en vivo para verificar bytes
        # (``project_stats``); si falta cualquier dato (``base_stats``/``ivs``
        # todavía no publicados por ese backend) no se toca nada y la tarjeta
        # se comporta exactamente igual que hoy. Va antes de mirar
        # ``team_changes``: un simple cambio de rol entre miembros activos no
        # genera ningún cambio de equipo↔PC y no debe depender de esa rama.
        # ``getattr`` como ya hace ``_projectable_team_changes`` con
        # ``_pending_team_changes``: tolera dobles de prueba mínimos que no
        # implementan el helper.
        pending_role_change_for = getattr(self, "_pending_role_change_for", None)
        for p in party if callable(pending_role_change_for) else ():
            pending = pending_role_change_for(p)
            if pending is None or pending.new_evs is None:
                continue
            projected = project_stats(
                p.base_stats, p.ivs, dict(zip(STAT_KEYS, pending.new_evs)),
                p.level, p.nature_id,
            )
            if not projected:
                continue
            p.stats = projected
            p.evs = dict(zip(STAT_KEYS, pending.new_evs))
            if p.max_hp > 0:
                p.current_hp = project_current_hp(p.current_hp, p.max_hp, projected["hp"])
                p.max_hp = projected["hp"]

        team_changes = RoleRunManager._projectable_team_changes(self)
        if not team_changes:
            if self.project and self.project.pending_faints:
                dead_ids = {str(item.get("identity", "") or "") for item in self.project.pending_faints}
                party = [p for p in party if self._pokemon_identity(p) not in dead_ids]
            return party

        # Horneamos el rol efectivo antes de empezar a mover slots. Los cambios de
        # rol siguen la identidad del Pokémon y pueden editarse libremente durante
        # toda la reorganización; la proyección preserva esa intención al compactar.
        for p in party:
            role, symbol = self._effective_role(p)
            p.role = role
            p.role_symbol = symbol
            p.box = -2  # Pokémon original del equipo dentro de una proyección.

        for change in team_changes:
            if change.operation == "party-to-box":
                idx = int(change.party_slot) - 1
                if 0 <= idx < len(party):
                    party.pop(idx)
            elif change.operation == "box-to-party" and change.incoming_snapshot:
                party.append(self._pokemon_from_snapshot(change.incoming_snapshot, projected=True))
            elif change.operation == "swap-party-box" and change.incoming_snapshot:
                idx = int(change.party_slot) - 1
                if 0 <= idx < len(party):
                    party[idx] = self._pokemon_from_snapshot(change.incoming_snapshot, projected=True)
            elif change.operation == "replace-fainted":
                # Una sustitución por baja nunca se adelanta visualmente a Azahar.
                # El Pokémon entrante aparecerá en RoleRun/OBS/barra únicamente
                # después de que el escritor vivo confirme party + PC + cementerio.
                continue
            for current_slot, member in enumerate(party, start=1):
                member.slot = current_slot
        # Una baja pendiente representa un slot RoleRun fuera de combate aunque
        # ORAS mantenga temporalmente el PK6 dentro de la party hasta sustituirlo.
        # Esta misma proyección alimenta Dashboard, Equipo, OBS y Barra Flotante,
        # evitando que cada vista tenga una verdad distinta.
        if self.project and self.project.pending_faints:
            dead_ids = {str(item.get("identity", "") or "") for item in self.project.pending_faints}
            party = [p for p in party if self._pokemon_identity(p) not in dead_ids]
            for current_slot, member in enumerate(party, start=1):
                member.slot = current_slot
        return party

    @staticmethod
    def _party_training_presentation_changed(
        before: SaveGameData, after: SaveGameData,
    ) -> bool:
        """Detecta datos vivos que no forman parte de la huella funcional.

        ``diff_live_party`` omite deliberadamente naturaleza, stats, IV y EV:
        esos campos no deben parecer un cambio de equipo ni disparar escritores.
        La UI de BDSP sí los necesita. Si una Run se abrió primero desde el save,
        un snapshot vivo con la misma identidad podía descartarse y Drafteos
        recibía para siempre diccionarios vacíos.
        """
        def presentation(game: SaveGameData) -> tuple:
            return tuple(
                (
                    (
                        int(getattr(pokemon, "species_id", 0) or 0),
                        int(getattr(pokemon, "pid", 0) or 0),
                        int(getattr(pokemon, "tid", 0) or 0),
                        int(getattr(pokemon, "sid", 0) or 0),
                        str(getattr(pokemon, "nickname", "") or getattr(pokemon, "species", "")),
                    ),
                    getattr(pokemon, "nature_id", None),
                    getattr(pokemon, "stat_nature_id", None),
                    str(getattr(pokemon, "nature", "") or ""),
                    str(getattr(pokemon, "stat_nature", "") or ""),
                    tuple(sorted(dict(getattr(pokemon, "stats", {}) or {}).items())),
                    tuple(sorted(dict(getattr(pokemon, "base_stats", {}) or {}).items())),
                    tuple(sorted(dict(getattr(pokemon, "ivs", {}) or {}).items())),
                    tuple(sorted(dict(getattr(pokemon, "evs", {}) or {}).items())),
                )
                for pokemon in game.party
            )

        return presentation(before) != presentation(after)

    def _team_role_conflicts(self, party: list[SavePokemon] | None = None) -> dict[str, list[SavePokemon]]:
        party = party if party is not None else self._projected_party()
        grouped: dict[str, list[SavePokemon]] = {}
        for pokemon in party:
            role, _ = self._effective_role(pokemon)
            if role == "SIN ROL":
                continue
            grouped.setdefault(role, []).append(pokemon)
        return {role: mons for role, mons in grouped.items() if len(mons) > 1}

    def _unassigned_active_pokemon(self, party: list[SavePokemon] | None = None) -> list[SavePokemon]:
        party = party if party is not None else self._projected_party()
        return [p for p in party if self._effective_role(p)[0] == "SIN ROL"]

    def _free_roles(self, party: list[SavePokemon] | None = None, exclude_slots: set[int] | None = None) -> list[str]:
        party = party if party is not None else self._projected_party()
        exclude_slots = exclude_slots or set()
        occupied = {
            self._effective_role(p)[0] for p in party
            if p.slot not in exclude_slots and self._effective_role(p)[0] != "SIN ROL"
        }
        return [role for role, _symbol in ROLE_OPTIONS[:6] if role not in occupied]

    def _resolve_party_slot_by_identity(self, save_path: Path, pokemon_identity: str, fallback_slot: int) -> int:
        """Localiza al Pokémon en la party actual de un guardado intermedio.

        Los cambios se aplican secuencialmente. Tras mover Pokémon entre Equipo y
        PC, el número de slot puede variar, pero PID/TID/SID/especie/apodo siguen
        identificando al mismo Pokémon. Si la identidad no está disponible (cambio
        legado), conserva el slot guardado como compatibilidad.
        """
        if not pokemon_identity:
            return int(fallback_slot)
        data = self.save_engine.read(save_path)
        for member in data.party:
            if self._pokemon_identity(member) == pokemon_identity:
                return int(member.slot)
        raise ValueError(
            "El Pokémon cuyo rol querías cambiar ya no está en el equipo proyectado. "
            "Revisa los cambios pendientes antes de guardar."
        )

    def _team_change_is_locked(self, show_warning: bool = False) -> bool:
        """Protección exclusiva del flujo de drafteo legado basado en slots.

        La gestión de roles NO usa este bloqueo desde 1.12.5: los roles siguen la
        identidad del Pokémon y son totalmente editables durante una reorganización.
        """
        locked = bool(self._pending_team_changes())
        if locked and show_warning:
            # Corregido 04-09-2026: el texto anterior hablaba de "sustituir un
            # movimiento de un slot concreto", una descripción de un diseño
            # previo de Drafteo. Este bloqueo ya no toca movimientos -eso vive
            # en SUSTITUIR/ELIMINAR de la ficha, que no pasa por aquí-: impide
            # elegir un Pokémon o rol de Drafteo mientras haya movimientos de
            # Equipo/PC en cola sin confirmar, para no mezclar dos
            # reorganizaciones a la vez.
            messagebox.showinfo(
                "Drafteo durante reorganización",
                "Puedes seguir moviendo Pokémon y cambiando roles libremente. "
                "Elegir un Pokémon o rol de Drafteo todavía necesita que fijes primero "
                "la reorganización de Equipo/PC (botón REVISAR CAMBIOS).",
            )
        return locked

    def _refresh_dashboard_counter(self, counter: str) -> None:
        if not self.project:
            return
        label = self.dashboard_counter_labels.get(counter)
        try:
            if label is not None and label.winfo_exists():
                label.configure(text=str(int(self.project.counters.get(counter, 0))))
        except Exception:
            pass

    def _refresh_dashboard_role_visibility(self, role: str) -> None:
        if not self.project or not self.current_game:
            return
        role_key = ROLE_TO_KEY.get(role)
        if not role_key:
            return
        assigned = [p for p in self._projected_party() if self._effective_role(p)[0] == role]
        if len(assigned) != 1:
            return
        widgets = self.dashboard_role_widgets.get(role_key)
        if not widgets:
            return
        card, eye = widgets
        pokemon = assigned[0]
        identity = self._pokemon_visibility_identity(pokemon)
        hidden = self.project.hidden_roles.get(role_key) == identity
        try:
            if card.winfo_exists():
                card.configure(fg_color="#141414" if hidden else "#1D1D1D")
            if eye.winfo_exists():
                eye.configure(
                    text="⊘" if hidden else "👁",
                    fg_color="#333333" if hidden else "transparent",
                    text_color=GOLD,
                )
        except Exception:
            pass

    def adjust_run_counter(self, counter: str, delta: int, source: str = "manual") -> None:
        if not self.project:
            return
        # MEDALLAS en los backends live tiene una única fuente de verdad: el
        # juego. Se ignoran botones/atajos antiguos aunque una Run migrada aún
        # los tenga; solo el propio reconciliador live puede ajustar el valor.
        expected_live_source = f"{self._active_azahar_realtime_label()} en vivo"
        if self._counter_is_automatic(counter) and not str(source).startswith(expected_live_source):
            return
        previous_value = int(self.project.counters.get(counter, 0))
        self.project_service.adjust_counter(self.project, counter, delta, source=source)
        self.project = self.project_service.load(self.project.slug) or self.project
        current_value = int(self.project.counters.get(counter, 0))
        if self._counter_is_automatic(counter):
            # Solo el juego mueve este contador, y llegar aquí ya demuestra que
            # la fuente es la viva. No es un paso que el usuario pueda deshacer.
            self._asumir_estado_del_juego()
        self._sync_obs_state(self.current_game)
        if self.active_page == "dashboard":
            self._refresh_dashboard_counter(counter)
            self._update_top_status()
        elif self.active_page == "drafts" and counter == "drafteos":
            # Cada tarjeta decide al construirse si su botón está encendido
            # (`eligible = role != "SIN ROL" and draft_count > 0`), así que
            # cruzar el cero —en cualquier dirección— obliga a rehacer la
            # página. Refrescar solo los botones dejaría seis tarjetas diciendo
            # «EN PREPARACIÓN» con drafteos disponibles.
            #
            # Antes esto dibujaba el paso de rol del diseño antiguo dentro del
            # body actual, encima del flujo visual: salía un panel «Elige el rol
            # del drafteo» flotando sobre unas tarjetas que seguían apagadas.
            if (previous_value <= 0) != (current_value <= 0):
                self._smooth_render_page(preserve_scroll=True)
            else:
                self._refresh_draft_role_buttons()
                self._update_top_status()
        if self._shell_built:
            self._render_sidebar()
            self._update_top_status()
        if current_value != previous_value:
            counter_names = {
                "vidas": "VIDAS", "pociones": "CURACIONES",
                "medallas": "PROGRESO", "drafteos": "DRAFTEOS",
            }
            self._set_operation_status(
                "confirmed",
                "CONTADOR ACTUALIZADO",
                f"{counter_names.get(counter, counter.upper())}: {previous_value} → {current_value}",
            )
        self._record_edit_transition()
        if source == "barra flotante":
            # La escritura ya era inmediata, pero la barra conservaba el texto
            # anterior hasta el siguiente poll. Repintar fuera del callback
            # evita destruir el propio botón mientras Tk procesa el clic.
            self._floating_bar_last_signature = None
            self.after(0, lambda: self._render_floating_bar(force=True))

    def run_quick_action(self, action: str) -> None:
        if not self.project:
            return
        result = self.project_service.apply_quick_action(self.project, action)
        self.project = self.project_service.load(self.project.slug) or self.project
        if not result.get("changed"):
            messagebox.showinfo("Sin cambios", "El contador ya está en cero y no puede reducirse más.")
            return
        self._smooth_render_page()
        self._show_quick_action_toast(str(result.get("label", "Evento registrado")))

    def undo_last_run_event(self) -> None:
        if not self.project:
            return
        result = self.project_service.undo_last_counter_event(self.project)
        if result is None:
            messagebox.showinfo("Nada que deshacer", "No hay eventos de contador que se puedan deshacer.")
            return
        self.project = self.project_service.load(self.project.slug) or self.project
        self._smooth_render_page()
        self._show_quick_action_toast("ÚLTIMO EVENTO DESHECHO")

    def _show_quick_action_toast(self, text: str) -> None:
        toast = ctk.CTkFrame(self, fg_color="#151515", corner_radius=16, border_width=2, border_color=GOLD)
        toast.place(relx=0.58, rely=0.5, anchor="center")
        ctk.CTkLabel(toast, text="✓  EVENTO REGISTRADO", text_color=SUCCESS,
                     font=ctk.CTkFont("Segoe UI", 16, "bold")).pack(padx=28, pady=(17, 3))
        ctk.CTkLabel(toast, text=text, text_color=TEXT,
                     font=ctk.CTkFont("Segoe UI", 12, "bold")).pack(padx=28, pady=(0, 17))
        toast.lift()
        self.after(1100, toast.destroy)

    def begin_hotkey_capture(self, action: str) -> None:
        if not self.project:
            return
        self._capturing_hotkey_action = action
        overlay = IntegratedWindowSurface(self)
        self._apply_window_icon(overlay)
        overlay.title("Asignar atajo")
        overlay.geometry("470x205")
        overlay.resizable(False, False)
        overlay.transient(self)
        overlay.grab_set()
        overlay.configure(fg_color=BG)
        ctk.CTkLabel(overlay, text="PULSA LA TECLA QUE QUIERES ASIGNAR", text_color=GOLD,
                     font=ctk.CTkFont("Segoe UI", 15, "bold")).pack(pady=(32, 8))
        status = ctk.CTkLabel(
            overlay,
            text=(
                "Puedes usar una tecla individual o una combinación.\n"
                "Los atajos solo se activan mientras el emulador tiene el foco. ESC cancela."
            ),
            text_color=MUTED,
            justify="center",
        )
        status.pack()

        cancelled = {"value": False}
        previous = WindowsHotkeyManager.pressed_supported_keys()

        def commit(name: str) -> bool:
            normalized = WindowsHotkeyManager.normalize_key_name(name)
            if normalized is None:
                status.configure(
                    text=(
                        f"{name.upper()} no es una tecla compatible.\n"
                        "Prueba con una letra, F1–F12, teclado numérico o una combinación."
                    ),
                    text_color=DANGER,
                )
                return False
            for existing_action, existing_key in self.project.hotkeys.items():
                normalized_existing = WindowsHotkeyManager.normalize_key_name(existing_key)
                if normalized_existing == normalized and existing_action != action:
                    configurar_si_cambia(
                        status,
                        text=f"{normalized.upper()} ya está asignada a otra acción.",
                        text_color=DANGER,
                    )
                    return False
            self.project.hotkeys[action] = normalized
            self.project_service.set_hotkeys(self.project, self.project.hotkeys)
            self._register_global_hotkeys(show_error=True)
            cancelled["value"] = True
            overlay.destroy()
            self._smooth_render_page()
            return True

        def capture_event(event):
            if cancelled["value"]:
                return "break"
            keysym = str(getattr(event, "keysym", "") or "").casefold()
            if keysym == "escape":
                return cancel(event)
            aliases = {
                "return": "enter", "prior": "page up", "next": "page down",
                "kp_add": "add", "kp_subtract": "subtract",
                "kp_multiply": "multiply", "kp_divide": "divide",
                "kp_decimal": "decimal",
            }
            key = aliases.get(keysym, keysym)
            modifiers = []
            state = int(getattr(event, "state", 0) or 0)
            if state & 0x0004:
                modifiers.append("ctrl")
            if state & 0x0008:
                modifiers.append("alt")
            if state & 0x0001:
                modifiers.append("shift")
            name = "+".join([*modifiers, key]) if modifiers else key
            commit(name)
            return "break"

        def cancel(_event=None):
            cancelled["value"] = True
            overlay.destroy()
            return "break"

        def poll_key() -> None:
            nonlocal previous
            if cancelled["value"] or not overlay.winfo_exists():
                return
            current = WindowsHotkeyManager.pressed_supported_keys()
            newly_pressed = current - previous
            previous = current
            if newly_pressed:
                name = sorted(newly_pressed)[0]
                if not commit(name):
                    overlay.after(250, poll_key)
                return
            overlay.after(25, poll_key)

        overlay.bind("<Escape>", cancel)
        overlay.bind("<KeyPress>", capture_event)
        overlay.protocol("WM_DELETE_WINDOW", cancel)
        overlay.after(180, poll_key)
        overlay.after(100, overlay.focus_force)

    def begin_controller_capture(self, action: str) -> None:
        if not self.project:
            return
        overlay = IntegratedWindowSurface(self)
        self._apply_window_icon(overlay)
        overlay.title("Asignar botón de mando")
        overlay.geometry("500x230")
        overlay.resizable(False, False)
        overlay.transient(self)
        overlay.grab_set()
        overlay.configure(fg_color=BG)
        ctk.CTkLabel(
            overlay, text="PULSA EL BOTÓN QUE QUIERES ASIGNAR",
            text_color=GOLD, font=ctk.CTkFont("Segoe UI", 15, "bold"),
        ).pack(pady=(34, 8))
        status = ctk.CTkLabel(
            overlay,
            text=(
                "Pulsa ahora el botón que prefieras. Se usará en todas las\n"
                "pantallas de RoleRun donde corresponda esa acción."
            ),
            text_color=MUTED, justify="center",
        )
        status.pack()

        def finish(button: str) -> None:
            if not overlay.winfo_exists():
                return
            assigned = dict(self.project.controller_hotkeys)
            assigned.update({f"menu_{key}": value for key, value in self.project.controller_menu_buttons.items()})
            for existing_action, existing in assigned.items():
                if existing_action != action and existing == button:
                    configurar_si_cambia(
                        status,
                        text=f"{button.upper()} ya está asignado a otra acción.",
                        text_color=DANGER,
                    )
                    self._gamepad_capture_action = action
                    self._gamepad_capture_callback = finish
                    return
            if action.startswith("menu_"):
                self.project.controller_menu_buttons[action.removeprefix("menu_")] = button
                self.project_service.set_menu_controls(
                    self.project, self.project.menu_keys,
                    self.project.controller_menu_buttons,
                )
            else:
                self.project.controller_hotkeys[action] = button
                self.project_service.set_controller_hotkeys(
                    self.project, self.project.controller_hotkeys,
                )
            overlay.destroy()
            self._smooth_render_page()

        def cancel(_event=None):
            self._gamepad_capture_action = None
            self._gamepad_capture_callback = None
            if overlay.winfo_exists():
                overlay.destroy()
            return "break"

        self._gamepad_capture_action = action
        self._gamepad_capture_callback = finish
        overlay.bind("<Escape>", cancel)
        overlay.protocol("WM_DELETE_WINDOW", cancel)
        overlay.after(100, overlay.focus_force)

    def begin_menu_key_capture(self, control: str) -> None:
        if not self.project:
            return
        overlay = IntegratedWindowSurface(self)
        self._apply_window_icon(overlay)
        overlay.title("Asignar control de menú")
        overlay.geometry("460x190")
        overlay.resizable(False, False)
        overlay.transient(self)
        overlay.grab_set()
        overlay.configure(fg_color=BG)
        ctk.CTkLabel(
            overlay, text="PULSA LA TECLA QUE QUIERES USAR EN ROLERUN",
            text_color=GOLD, font=ctk.CTkFont("Segoe UI", 15, "bold"),
        ).pack(pady=(38, 8))
        ctk.CTkLabel(
            overlay, text="Se aplicará a la navegación de la aplicación y del menú sobre el juego. ESC cancela.",
            text_color=MUTED,
        ).pack()

        def capture(event):
            keysym = str(getattr(event, "keysym", "") or "").casefold()
            if keysym == "escape":
                overlay.destroy()
                return "break"
            aliases = {"return": "enter", "prior": "page up", "next": "page down"}
            key = aliases.get(keysym, keysym)
            other = "back" if control == "accept" else "accept"
            if key and key != self.project.menu_keys.get(other):
                self.project.menu_keys[control] = key
                self.project_service.set_menu_controls(
                    self.project, self.project.menu_keys,
                    self.project.controller_menu_buttons,
                )
                overlay.destroy()
                self._smooth_render_page()
            return "break"

        overlay.bind("<KeyPress>", capture)
        overlay.protocol("WM_DELETE_WINDOW", overlay.destroy)
        overlay.after(100, overlay.focus_force)

    def _hotkey_action(self, action: str) -> None:
        # Segunda barrera contra carreras de foco: el registro Win32 se retira
        # al abandonar el emulador, pero un WM_HOTKEY ya encolado no debe poder
        # ejecutar ninguna acción después de volver a RoleRun u otra aplicación.
        if not self._foreground_is_supported_emulator():
            return
        if action == "reportar_bug":
            self.after(0, self.reportar_bug)
            return
        if action in {"heal_party", "floating_menu"}:
            if action == "heal_party":
                self.after(0, self._heal_bdsp_party)
            else:
                self.after(0, self._toggle_floating_launcher)
            return
        if action == "open_full_app":
            # Botón de mando con dos cuadrados apilados (View/"back" en SDL),
            # a la izquierda del botón central. Pedido del usuario
            # 31-08-2026: abre RoleRun completo, lo mismo que pulsar el logo
            # de la barra flotante con el ratón. "guide" (el botón central)
            # sigue siendo el menú flotante, sin tocar.
            self.after(0, self._floating_logo_to_dashboard)
            return
        if action == "sync_live_game":
            self.after(0, self.sync_oras_live)
            return
        mapping = {
            "vidas_mas": ("vidas", 1), "vidas_menos": ("vidas", -1),
            "pociones_mas": ("pociones", 1), "pociones_menos": ("pociones", -1),
            "medallas_mas": ("medallas", 1), "medallas_menos": ("medallas", -1),
            "drafteos_mas": ("drafteos", 1), "drafteos_menos": ("drafteos", -1),
        }
        visibility = {
            "toggle_libero": "Líbero", "toggle_asesino": "Asesino",
            "toggle_mago": "Mago", "toggle_tanque": "Tanque",
            "toggle_prisma": "Prisma", "toggle_support": "Support",
        }
        if action in visibility:
            self.after(0, lambda role=visibility[action]: self.toggle_role_visibility(role))
            return
        if action not in mapping:
            return
        counter, delta = mapping[action]
        if self._counter_is_automatic(counter):
            return
        key = self.project.hotkeys.get(action, "") if self.project else ""
        self.after(0, lambda: self.adjust_run_counter(counter, delta, source=f"atajo {key}"))

    def reportar_bug(self) -> Path | None:
        """Guarda lo que hay alrededor de este instante. Una pulsación, nada más.

        Durante un directo no se puede parar a escribir qué ha pasado, así que
        esto no pregunta nada: deja la carpeta y avisa. La captura de pantalla
        es lo primero que se mira después y lo que menos hay que explicar.
        """
        try:
            carpeta = guardar_reporte(self._contexto_para_un_bug)
        except Exception as error:
            self._set_operation_status(
                "failed", "NO SE PUDO GUARDAR EL FALLO", str(error), persistent=True,
            )
            return None
        cuantos = len(informes())
        self._set_operation_status(
            "done",
            "FALLO GUARDADO",
            f"{carpeta.name} · {cuantos} guardado{'s' if cuantos != 1 else ''} "
            "en Documentos\\RoleRun Manager\\Bugs.",
        )
        return carpeta

    def _contexto_para_un_bug(self) -> dict[str, object]:
        """Lo que RoleRun sabe de sí mismo ahora mismo.

        Cada campo va por separado y protegido: si uno no se puede leer, el
        informe se guarda igual sin él. Un informe incompleto sirve.
        """
        datos: dict[str, object] = {}

        def anotar(nombre: str, obtener) -> None:
            try:
                datos[nombre] = obtener()
            except Exception as error:
                datos[nombre] = f"<no se pudo: {type(error).__name__}>"

        anotar("pagina", lambda: str(self.active_page))
        anotar("run", lambda: self.project.name if self.project else None)
        anotar("juego", lambda: self._active_azahar_realtime_label())
        anotar("juego_clave", lambda: self._active_azahar_realtime_key())
        anotar("estado_sync", lambda: str(self.sync_status))
        anotar("cambios_pendientes", lambda: len(self.run.pending_changes))
        anotar("barra_flotante", lambda: bool(self._floating_bar_is_visible()))
        anotar(
            "equipo",
            lambda: [
                {
                    "slot": int(getattr(p, "slot", 0) or 0),
                    "especie": str(getattr(p, "species", "")),
                    "mote": str(getattr(p, "nickname", "")),
                    "nivel": int(getattr(p, "level", 0) or 0),
                    "ps": f"{getattr(p, 'current_hp', '?')}/{getattr(p, 'max_hp', '?')}",
                    "rol": str(getattr(p, "role", "")),
                    "movimientos": list(getattr(p, "moves", None) or []),
                }
                for p in self._projected_party()
            ],
        )
        return datos

    def _show_live_sync_toast(self, title: str, detail: str, success: bool) -> None:
        """Traduce los avisos heredados al estado persistente de la shell."""
        normalized = str(title or "").strip().upper()
        if any(word in normalized for word in ("APLICANDO", "EN CURSO", "LEYENDO")):
            kind = "applying"
            persistent = False
        elif any(word in normalized for word in ("PREPARADO", "PENDIENTE")):
            kind = "pending"
            persistent = False
        elif success:
            kind = "confirmed"
            persistent = False
        elif any(word in normalized for word in ("NO ESTÁ SINCRONIZADO", "NO DETECTADO", "DESCONECT")):
            kind = "disconnected"
            persistent = True
        elif any(word in normalized for word in ("ESPERA", "PAUSAD")):
            kind = "warning"
            persistent = False
        else:
            kind = "failed"
            persistent = True
        actions = ("Reintentar",) if kind in {"failed", "disconnected"} else ()
        set_operation_status = getattr(self, "_set_operation_status", None)
        if callable(set_operation_status):
            set_operation_status(
                kind, title, detail, actions=actions, persistent=persistent,
            )
        if str(self.state()) in {"withdrawn", "iconic"}:
            # La barra es una HUD de juego, no un panel de diagnóstico. Los avisos
            # verdes de sincronización/recuperación distraen y pueden solaparse con
            # cambios legítimos de PC. En modo barra solo mostramos errores reales.
            if not success:
                self._show_floating_live_sync_feedback(title, detail, success)
            return

    def _show_floating_live_sync_feedback(self, title: str, detail: str, success: bool) -> None:
        """Muestra únicamente errores útiles dentro de la HUD flotante."""
        # La barra debe limitarse al estado de la Run. Los mensajes de éxito o de
        # reconciliación (p. ej. "ESTADO DE ORAS RECUPERADO") son diagnóstico
        # interno y no deben aparecer encima del juego.
        if success:
            return
        bar = self.floating_bar
        if not bar or not bar.winfo_exists() or str(bar.state()) == "withdrawn":
            return

        previous = self._floating_live_feedback
        if previous is not None:
            try:
                if previous.winfo_exists():
                    previous.destroy()
            except Exception:
                pass

        self._floating_live_feedback_generation += 1
        generation = self._floating_live_feedback_generation
        color = SUCCESS if success else DANGER
        feedback = ctk.CTkFrame(
            bar,
            fg_color="#153023" if success else "#2A1717",
            corner_radius=12,
            border_width=2,
            border_color=color,
        )
        self._floating_live_feedback = feedback
        if success and title == "ESTADO DE ORAS RECUPERADO":
            compact_title = "↺  ESTADO DE ORAS RECUPERADO"
        elif success and title == "CAMBIO APLICADO AL MOMENTO":
            compact_title = "✓  CAMBIO APLICADO AL MOMENTO"
        else:
            if success:
                compact_title = f"✓  {self._active_azahar_realtime_label()} SINCRONIZADO"
            else:
                compact_title = f"⚠  {title or ('NO SE PUDO LEER ' + self._active_azahar_realtime_label())}"
        ctk.CTkLabel(
            feedback,
            text=compact_title,
            text_color=color,
            font=ctk.CTkFont("Segoe UI", 12, "bold"),
        ).pack(padx=18, pady=(7, 0))
        ctk.CTkLabel(
            feedback,
            text=detail,
            text_color=TEXT,
            wraplength=430,
            justify="center",
            font=ctk.CTkFont("Segoe UI", 10, "bold"),
        ).pack(padx=18, pady=(0, 7))
        # Superposición breve y localizada: no toca los widgets de roles, la
        # geometría de la barra ni el ciclo de refresco que evita el flicker.
        feedback.place(relx=0.5, rely=0.5, anchor="center")
        try:
            feedback.lift()
            bar.lift()
        except Exception:
            pass

        def clear_feedback() -> None:
            if generation != self._floating_live_feedback_generation:
                return
            self._floating_live_feedback = None
            try:
                if feedback.winfo_exists():
                    feedback.destroy()
            except Exception:
                pass

        try:
            bar.after(1300 if success else 2600, clear_feedback)
        except Exception:
            clear_feedback()

    def _active_azahar_realtime_key(self) -> str:
        key = str(getattr(self.save_engine, "key", "") or "").casefold()
        return key if key in REALTIME_READ_GAME_KEYS else ""

    def _record_bdsp_ui_event(self, event: str, **fields: object) -> None:
        if self._active_azahar_realtime_key() != "bdsp":
            return
        recorder = getattr(
            getattr(self, "bdsp_realtime_adapter", None), "record_ui_event", None,
        )
        if callable(recorder):
            recorder(str(event), **fields)

    def _active_azahar_realtime_label(self) -> str:
        return {
            "xy": "X/Y", "sm": "Sol/Luna", "usum": "UltraSol/UltraLuna",
            "bdsp": "Perla Reluciente", "b2w2": "Negro 2/Blanco 2",
            "bw": "Negro/Blanco", "hgss": "Oro HeartGold/Plata SoulSilver",
        }.get(self._active_azahar_realtime_key(), "ORAS")

    def _active_azahar_realtime_display_name(self) -> str:
        return {
            "xy": "Pokémon X/Y",
            "sm": "Pokémon Sol/Luna",
            "usum": "Pokémon UltraSol/UltraLuna",
            "bdsp": "Pokémon Perla Reluciente",
            "b2w2": "Pokémon Negro 2/Blanco 2",
            "bw": "Pokémon Negro/Blanco",
            "hgss": "Pokémon Oro HeartGold / Plata SoulSilver",
        }.get(self._active_azahar_realtime_key(), "Omega Rubí/Zafiro Alfa")

