    def _uses_instant_realtime_ui(self) -> bool:
        """Indica que la Run usa la experiencia visible del Real-Time Core 3DS.

        Esto no promete que todas las escrituras estén implementadas. Una
        capacidad no demostrada se bloquea, pero nunca reabre el flujo antiguo
        GUARDAR/DESCARTAR de archivo.
        """
        return bool(
            str(getattr(self.save_engine, "key", "") or "").casefold()
            in INSTANT_REALTIME_UI_GAME_KEYS
        )

    def _pending_changes_block_live_capture(self) -> bool:
        """Una cola local de alpha.1 no debe impedir demostrar la RAM de SM.

        ORAS/X/Y conservan la barrera histórica durante operaciones vivas. En
        Sol/Luna la captura/monitor no depende de esas decisiones locales; las
        escrituras compatibles se validan aparte antes de tocar RAM.
        """
        return bool(
            self.run.pending_changes
            and self._active_azahar_realtime_key() not in (
                {"sm", "usum", "bdsp"} | MELONDS_WRITE_GAME_KEYS
            )
        )

    def _cancel_oras_initial_auto_sync(self) -> None:
        """Cancela el próximo intento de enlace automático con Azahar."""
        after_id = self._oras_auto_sync_after_id
        self._oras_auto_sync_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        # Un worker RPC ya iniciado no se puede interrumpir con seguridad. El
        # token hace que su callback quede obsoleto y no publique otra Run.
        self._oras_auto_sync_token += 1

    def _schedule_oras_initial_auto_sync(self, delay_ms: int = 300) -> None:
        """Busca la Run 3DS activa en Azahar hasta conseguir una captura estable.

        El usuario no tiene que pulsar F5: abrir la Run basta. Mientras Azahar
        no haya entrado realmente en la partida, los fallos son silenciosos y
        se reintentan en segundo plano.
        """
        if (
            self._oras_live_active
            or self._oras_auto_sync_after_id
            or not self.project
            or not self.current_game
            or not self.current_save
            or getattr(self.save_engine, "key", "") not in REALTIME_READ_GAME_KEYS
        ):
            return
        generation = self._session_generation
        project_slug = self.project.slug
        token = self._oras_auto_sync_token
        try:
            self._oras_auto_sync_after_id = self.after(
                max(150, int(delay_ms)),
                lambda: self._start_oras_initial_auto_sync(
                    generation, project_slug, token,
                ),
            )
        except Exception:
            self._oras_auto_sync_after_id = None

    def _start_oras_initial_auto_sync(
        self, generation: int, project_slug: str, token: int,
    ) -> None:
        self._oras_auto_sync_after_id = None
        if (
            token != self._oras_auto_sync_token
            or generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self.current_game
            or not self.current_save
            or getattr(self.save_engine, "key", "") not in REALTIME_READ_GAME_KEYS
            or self._oras_live_active
        ):
            return
        # No competimos con una escritura, un F5 manual ni una verificación.
        if (
            self._oras_auto_sync_in_progress
            or self._live_write_in_progress
            or self._live_sync_in_progress
            or self._oras_live_monitor_in_progress
            or self._pending_changes_block_live_capture()
        ):
            self._schedule_oras_initial_auto_sync(450)
            return

        current = self.current_game
        if self._active_azahar_realtime_key() == "sm":
            self.sm_live_reader.set_resume_identity_witnesses(
                tuple(self.project.managed_pokemon_roles)
            )
        elif self._active_azahar_realtime_key() == "usum":
            self.usum_live_reader.set_resume_identity_witnesses(
                tuple(self.project.managed_pokemon_roles)
            )
        self._prepare_oras_live_metadata_profile()
        memory_requests = self._oras_live_memory_requests()
        self._oras_auto_sync_in_progress = True
        live_key = self._active_azahar_realtime_key()
        if live_key == "sm":
            try:
                LOG_DIR.mkdir(parents=True, exist_ok=True)
                (LOG_DIR / "sm_initial_sync_latest.json").write_text(json.dumps({
                    "stage": "capture-started",
                    "created_at": datetime.now().isoformat(timespec="milliseconds"),
                    "generation": int(generation),
                    "project": str(project_slug),
                    "party": [
                        {
                            "slot": int(pokemon.slot),
                            "species_id": int(pokemon.species_id),
                            "pid": int(pokemon.pid or 0),
                            "tid": int(pokemon.tid or 0),
                            "sid": int(pokemon.sid or 0),
                        }
                        for pokemon in tuple(getattr(current, "party", ()) or ())
                    ],
                }, ensure_ascii=False, indent=2), encoding="utf-8")
            except OSError:
                pass
        transport_label = (
            "Ryujinx" if live_key == "bdsp" else
            "melonDS" if live_key in MELONDS_REALTIME_GAME_KEYS else
            "AzaharPlus" if live_key in GEN7_REALTIME_GAME_KEYS else "Azahar"
        )
        current_operation = getattr(self, "operation_status_store", None)
        current_operation = current_operation.message if current_operation else None
        # Con el juego cerrado este placeholder se publica cada 1,6 s, ANTES de
        # saber si el intento va a fallar otra vez. Si REVISIÓN NECESARIA ya
        # está activa no aporta nada nuevo, y sobreescribirla la hace pasar por
        # "neutral" un instante (no empieza por "⚠") para volver a "warning" en
        # cuanto el intento falla: ese vaivén de categoría es lo que reiniciaba
        # el tecleo letra a letra sin parar. Sólo el resultado real del
        # intento (éxito o fallo) debe tocar el aviso persistente.
        if not (
            current_operation is not None
            and current_operation.kind == "warning"
            and current_operation.title == "REVISIÓN NECESARIA"
        ):
            self.sync_status = f"◌ Esperando {self._active_azahar_realtime_label()} en {transport_label}…"
            self._update_top_status()

        def worker() -> None:
            try:
                snapshot = self.realtime_core.capture_full(
                    current, save_path=self.current_save.path, memory_requests=memory_requests,
                )
                error = None
            except Exception as exc:
                snapshot = None
                error = str(exc)
            self.after(0, lambda: self._finish_oras_initial_auto_sync(
                generation, project_slug, token, snapshot, error,
            ))

        threading.Thread(
            target=worker, daemon=True, name="RoleRunAzaharAutoConnect",
        ).start()

    def _finish_oras_initial_auto_sync(
        self, generation: int, project_slug: str, token: int, snapshot, error: str | None,
    ) -> None:
        self._oras_auto_sync_in_progress = False
        if self._active_azahar_realtime_key() == "sm":
            try:
                LOG_DIR.mkdir(parents=True, exist_ok=True)
                reader = getattr(self, "sm_live_reader", None)
                (LOG_DIR / "sm_initial_sync_latest.json").write_text(json.dumps({
                    "stage": "capture-finished",
                    "created_at": datetime.now().isoformat(timespec="milliseconds"),
                    "generation": int(generation),
                    "project": str(project_slug),
                    "error": str(error or ""),
                    "snapshot": snapshot is not None,
                    "party": [
                        {
                            "slot": int(pokemon.slot),
                            "species_id": int(pokemon.species_id),
                            "pid": int(pokemon.pid or 0),
                            "tid": int(pokemon.tid or 0),
                            "sid": int(pokemon.sid or 0),
                        }
                        for pokemon in tuple(getattr(self.current_game, "party", ()) or ())
                    ],
                    "resolution": dict(getattr(reader, "_last_resolution", {}) or {}),
                }, ensure_ascii=False, indent=2), encoding="utf-8")
            except OSError:
                pass
        if (
            token != self._oras_auto_sync_token
            or generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self.current_game
            or getattr(self.save_engine, "key", "") not in REALTIME_READ_GAME_KEYS
            or self._oras_live_active
        ):
            return
        if error or snapshot is None:
            # Menús, arranque del emulador o transporte desactivado se reintentan
            # automáticamente. Para SM alpha.3 conservamos además el error REAL en
            # la cabecera: necesitamos distinguir RPC, proceso y calibración RAM
            # durante la primera validación en una partida física del usuario.
            detail = str(error or "")
            live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
            live_key = live_key_getter() if callable(live_key_getter) else "oras"
            if live_key in GEN7_REALTIME_GAME_KEYS and detail:
                self.sync_status = f"⚠ {self._active_azahar_realtime_label()} · {detail}"
            elif live_key == "oras" and detail:
                # ORAS también debe enseñar el diagnóstico real. Esto permite
                # distinguir RPC apagado de un proceso cuyo nombre interno haya
                # cambiado, especialmente en builds oficiales antiguas de Azahar.
                self.sync_status = f"⚠ ORAS · {detail}"
            elif live_key == "bdsp" and detail:
                self.sync_status = f"⚠ Perla Reluciente · {detail}"
            else:
                self.sync_status = f"◌ Esperando entrada a {self._active_azahar_realtime_label()}…"
            self._update_top_status()
            # BDSP necesita una captura live para conocer PS fiables. En el
            # primer enlace con Ryujinx es normal que el transporte todavía no
            # esté preparado; retirar aquí la barrera enseñaba durante varios
            # segundos los ceros provisionales procedentes del save. Otros
            # backends conservan su contrato histórico de poder abrir en modo
            # no conectado.
            if live_key in {"bdsp", "sm"} and self._initial_shell_waiting:
                self._initial_shell_live_probe_complete = False
                self._show_busy_indicator(
                    "initial-shell",
                    (
                        "Conectando con Ryujinx y validando los PS del equipo…"
                        if live_key == "bdsp" else
                        "Conectando con Azahar y validando el equipo de Sol/Luna…"
                    ),
                )
            else:
                self._initial_shell_live_probe_complete = True
                if self._initial_shell_waiting:
                    self.after(0, self._retire_initial_shell_when_ready)
            self._schedule_oras_initial_auto_sync(1600)
            return

        # La misma validación y publicación que antes exigía F5. El perfil
        # ORAS ya se preparó antes de capturar y debe sobrevivir para que la
        # lectura viva del PC use exactamente la misma tabla Personal.
        self._finish_oras_live_sync(
            generation, project_slug, snapshot, None, automatic=True,
        )
        live_key = self._active_azahar_realtime_key()
        if live_key in {"xy", "oras"} and self._oras_live_active:
            # X/Y conserva una proyección diferencial sobre las cajas del save,
            # por lo que no entra en FULL_MATRIX_LIVE_PC_GAME_KEYS. Si la party
            # inicial coincide con la ya proyectada, _finish_oras_live_sync no
            # observa una transición Equipo↔PC y antes nunca solicitaba la matriz
            # viva: una caja vacía del último main permanecía visible aunque el
            # reader hubiese demostrado Pokémon en RAM. La captura inicial ya
            # validada es la frontera correcta para lanzar UNA reconciliación
            # explícita, después de que _publish_oras_live_snapshot haya marcado
            # el enlace como activo.
            self.after(0, self._schedule_gen6_live_pc_refresh)
        if live_key in {"bdsp", "sm"}:
            # Terminar capture_full no implica necesariamente que el snapshot
            # haya sido publicado: una migración de marcadores o una herencia
            # de rol puede abrir antes una escritura transaccional. La shell
            # solo queda lista cuando la fuente live es ya autoritativa y cada
            # miembro declara un par HP/Max HP coherente.
            self._initial_shell_live_probe_complete = bool(
                self._oras_live_active
                and self._party_has_resolved_health(self.current_game)
            )
            if not self._initial_shell_live_probe_complete:
                self._show_busy_indicator(
                    "initial-shell",
                    (
                        "Aplicando la sincronización inicial y verificando los PS…"
                        if live_key == "bdsp" else
                        "Componiendo el equipo vivo de Sol/Luna y verificando sus PS…"
                    ),
                )
                self._schedule_oras_initial_auto_sync(250)
        else:
            self._initial_shell_live_probe_complete = True
        if self._initial_shell_waiting:
            self.after(0, self._retire_initial_shell_when_ready)

    @staticmethod
    def _party_has_resolved_health(game: SaveGameData | None) -> bool:
        """Demuestra que toda la party publica pares HP/Max HP utilizables."""
        party = list(getattr(game, "party", ()) or ())
        if not party:
            return False
        for pokemon in party:
            try:
                current_hp = int(getattr(pokemon, "current_hp"))
                max_hp = int(getattr(pokemon, "max_hp"))
            except (AttributeError, TypeError, ValueError):
                return False
            if max_hp <= 0 or current_hp < 0 or current_hp > max_hp:
                return False
        return True

    def _clear_oras_live_auto_apply(self) -> None:
        """Cancela la pequeña cola de aplicación inmediata al cambiar de Run."""
        after_id = self._oras_live_auto_apply_after_id
        self._oras_live_auto_apply_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._oras_live_auto_apply_ids.clear()

    def _discard_b2w2_ghost_team_changes(self) -> int:
        """Retira proyecciones que B2/W2 nunca pudo escribir en la partida."""
        if (
            self._active_azahar_realtime_key() not in MELONDS_REALTIME_GAME_KEYS
            or not self.project
        ):
            return 0
        pending = list(self.run.pending_changes)
        ghosts = [change for change in pending if isinstance(change, PendingTeamChange)]
        if not ghosts:
            return 0
        self.run.pending_changes = [
            change for change in pending if not isinstance(change, PendingTeamChange)
        ]
        self.project_service.save(self.project)
        return len(ghosts)

    def _oras_live_auto_apply_available(self) -> bool:
        return bool(
            self.project
            and self.current_save
            and self.current_game
            and self._oras_live_active
            and getattr(self.save_engine, "key", "") in INSTANT_REALTIME_UI_GAME_KEYS
        )

    def _request_oras_live_auto_apply(self, changes) -> None:
        """Solicita aplicar solo los cambios nuevos y seguros de una acción UI.

        No se toma toda la cola a ciegas: así un traslado de PC o una operación
        antigua nunca termina escrita parcialmente en la RAM por haber cambiado
        después un rol, un objeto o una marca de caja.
        """
        live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
        live_key = live_key_getter() if callable(live_key_getter) else "oras"
        if not self._oras_live_auto_apply_available():
            if getattr(getattr(self, "save_engine", None), "key", "") == "bdsp":
                rejected_ids = {id(change) for change in changes}
                self.run.pending_changes = [
                    change for change in self.run.pending_changes
                    if id(change) not in rejected_ids
                ]
                refresh = getattr(self, "_smooth_render_page", None)
                if callable(refresh):
                    refresh(preserve_scroll=(getattr(self, "active_page", "") == "team"))
                toast = getattr(self, "_show_live_sync_toast", None)
                if callable(toast):
                    toast(
                        "RYUJINX NO ESTÁ SINCRONIZADO",
                        "No se aplicó el cambio y no quedó pendiente para el guardado. "
                        "Espera a que la cabecera indique Perla Reluciente en vivo y vuelve a intentarlo.",
                        False,
                    )
            return
        current_ids = {id(change) for change in self.run.pending_changes}
        supported_ids: set[int] = set()
        for change in changes:
            if id(change) not in current_ids:
                continue
            if live_key == "bdsp":
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingChange, PendingTMTeach,
                    PendingInventoryChange,
                )):
                    supported_ids.add(id(change))
                elif isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party", "replace-fainted",
                    # Mover dentro del PC son las dos escrituras de caja que
                    # `party-to-box` y `box-to-party` ya hacen. Sin esta entrada
                    # el cambio se creaba, el rótulo decía «MOVIENDO EN EL PC» y
                    # ahí se quedaba para siempre: nadie llegaba a escribirlo.
                    "move-box-slot",
                    # Intercambio de dos huecos ocupados (`_apply_box_swap`,
                    # 05-09-2026): las mismas dos escrituras de caja, cruzadas.
                    "swap-box-slots",
                }:
                    # El writer BDSP 1↔1 ya valida las identidades party/PC,
                    # hace readback semántico y rollback. Debe atravesar también
                    # esta compuerta UI; alpha.80 lo aceptaba más abajo pero lo
                    # descartaba aquí antes de llegar al writer.
                    supported_ids.add(id(change))
                continue
            if live_key in MELONDS_GEN4_REALTIME_GAME_KEYS and live_key not in MELONDS_WRITE_GAME_KEYS:
                # HeartGold sin `MELONDS_GEN4_ESCRIBE`: solo mochila/dinero, que
                # no tocan ningún PK4. Ver el mismo razonamiento en
                # `_oras_live_unsupported_changes`.
                if isinstance(change, PendingInventoryChange):
                    supported_ids.add(id(change))
                continue
            if live_key in MELONDS_REALTIME_GAME_KEYS:
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingInventoryChange,
                    PendingTMTeach, PendingChange,
                )):
                    # alpha.24: el writer de roles B2/W2 escribe marcas y EV en el
                    # PK5 vivo, recalcula las estadísticas con la tabla personal y
                    # verifica el resultado con el parser de producción.
                    # alpha.39: las utilidades de la cabecera escriben la mochila
                    # y el dinero en direcciones demostradas con el mismo contrato.
                    supported_ids.add(id(change))
                elif (
                    isinstance(change, PendingTeamChange)
                    and change.operation in {
                        "move-box-slot", "swap-box-slots", "swap-party-box",
                        "party-to-box", "box-to-party", "replace-fainted",
                    }
                ):
                    supported_ids.add(id(change))
                continue
            if live_key in GEN7_REALTIME_GAME_KEYS:
                # Alpha.17 omitía PendingTMTeach aquí: la UI proyectaba la MT
                # pero nunca se lanzaba el writer SM. Alpha.18 la trata igual
                # que cualquier movimiento live ya soportado por SMLiveWriter.
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingChange,
                    PendingTMTeach, PendingInventoryChange,
                )):
                    supported_ids.add(id(change))
                elif isinstance(change, PendingTeamChange) and (
                    change.operation in {"swap-party-box", "party-to-box", "box-to-party", "replace-fainted"}
                    # `SMLiveWriter._apply_pc_move`/`USUMLiveWriter._apply_pc_move`
                    # (04-09-2026 para SM): mover dentro del PC a un hueco vacío.
                    # Y `_apply_pc_swap` (05-09-2026): intercambiar dos huecos
                    # ocupados, misma matriz, dos escrituras cruzadas. El resto
                    # de Gen 7 sin writer PC→PC sigue sin entrar aquí, así que
                    # esas operaciones se quedarían proyectadas para siempre.
                    or (
                        live_key in {"sm", "usum"}
                        and change.operation in {"move-box-slot", "swap-box-slots"}
                    )
                ):
                    supported_ids.add(id(change))
                continue
            if live_key == "xy":
                if isinstance(change, (
                    PendingChange, PendingRoleChange, PendingPCRoleChange,
                    PendingPartyHeal, PendingTMTeach, PendingInventoryChange,
                )):
                    supported_ids.add(id(change))
                elif isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party",
                    "replace-fainted", "move-box-slot", "swap-box-slots",
                }:
                    # X/Y ya valida las variaciones 5↔6 de la party dentro de
                    # XYLiveWriter (identidades, testigos de caja, count-last,
                    # readback y rollback). Esta compuerta debe enviarlas al
                    # writer igual que los swaps 1↔1: de lo contrario la UI
                    # proyecta el traslado sin escribir RAM y una operación PC
                    # posterior parte de un origen que nunca existió.
                    supported_ids.add(id(change))
                continue
            if live_key == "oras":
                if isinstance(change, (
                    PendingChange, PendingRoleChange, PendingInventoryChange,
                    PendingPCRoleChange, PendingTMTeach, PendingPartyHeal,
                )):
                    supported_ids.add(id(change))
                elif isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party", "replace-fainted",
                    # PC→PC (`ORASLiveWriter._apply_pc_move`): el origen ocupado
                    # es el ancla, el destino se exige vacío, se escribe destino
                    # antes que origen y hay readback asentado con rollback.
                    "move-box-slot",
                    # Intercambio entre dos casillas ocupadas
                    # (`ORASLiveWriter._apply_pc_swap`): las dos identidades se
                    # conocen, así que ambas son ancla y ninguna casilla vacía
                    # interviene en la calibración.
                    "swap-box-slots",
                }:
                    # ORASLiveWriter._apply_party_resize (30-08-2026) ya valida
                    # el cambio de tamaño 5↔6 (contador, identidades, testigos
                    # de caja, commit del contador al final, rollback). Sin
                    # esta entrada el cambio se quedaba proyectado para
                    # siempre como "pendiente": esta compuerta nunca llegaba a
                    # pedir la escritura.
                    supported_ids.add(id(change))
                continue
            if isinstance(change, (
                PendingChange, PendingRoleChange, PendingInventoryChange,
                PendingPCRoleChange, PendingTMTeach, PendingPartyHeal,
            )):
                supported_ids.add(id(change))
            elif isinstance(change, PendingTeamChange) and change.operation in {"swap-party-box", "replace-fainted"}:
                supported_ids.add(id(change))
        if not supported_ids:
            return
        self._oras_live_auto_apply_ids.update(supported_ids)
        self._schedule_oras_live_auto_apply()

    def _request_oras_live_auto_apply_since(self, pending_ids_before: set[int]) -> None:
        self._request_oras_live_auto_apply([
            change for change in self.run.pending_changes
            if id(change) not in pending_ids_before
        ])

    def _schedule_oras_live_auto_apply(self, delay_ms: int = 110) -> None:
        if (
            not self._oras_live_auto_apply_ids
            or not self._oras_live_auto_apply_available()
            or self._oras_live_auto_apply_after_id
        ):
            return
        generation = self._session_generation
        project_slug = self.project.slug if self.project else ""
        try:
            self._oras_live_auto_apply_after_id = self.after(
                max(50, int(delay_ms)),
                lambda: self._flush_oras_live_auto_apply(generation, project_slug),
            )
        except Exception:
            self._oras_live_auto_apply_after_id = None

    def _stop_oras_live_auto_apply_for(self, changes) -> None:
        self._oras_live_auto_apply_ids.difference_update(id(change) for change in changes)

    @perf.timed("ui.live.flush_auto")
    def _flush_oras_live_auto_apply(self, generation: int, project_slug: str) -> None:
        self._oras_live_auto_apply_after_id = None
        if (
            generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self._oras_live_auto_apply_available()
        ):
            return

        pending = list(self.run.pending_changes)
        pending_ids = {id(change) for change in pending}
        self._oras_live_auto_apply_ids.intersection_update(pending_ids)
        if not self._oras_live_auto_apply_ids:
            return
        requested = [
            change for change in pending
            if id(change) in self._oras_live_auto_apply_ids
        ]
        if not requested:
            return

        # Alpha.36: una acción nueva y compatible no queda secuestrada por
        # otras entradas pendientes. Aplicamos únicamente el subconjunto que
        # solicitó la ruta inmediata. Si un lote automático falla, además se
        # retira de la proyección en ``_finish_oras_live_write``. Esto evita el
        # antiguo bucle de "requiere flujo manual" tras un error transitorio.

        if getattr(self, "_sm_tm_inventory_load_in_progress", False):
            # La carga de la mochila de Gen 7 sí es un requisito previo del
            # propio lote, no una simple ocupación del canal de escritura.
            perf.mark("ui.live.reprogramado", mts=True)
            self._schedule_oras_live_auto_apply(220)
            return
        debe_esperar = getattr(self, "_cola_debe_esperar", None)
        ocupado = bool(debe_esperar()) if callable(debe_esperar) else bool(
            self._live_write_in_progress
            or self._live_sync_in_progress
            or self._oras_live_monitor_in_progress
        )
        if ocupado and not RoleRunManager._solo_son_movimientos_de_caja(requested):
            # Un movimiento dentro del PC entra en la cola más abajo. Lo demás
            # sigue reprogramándose hasta que el canal quede libre.
            perf.mark(
                "ui.live.reprogramado",
                escritura=bool(self._live_write_in_progress),
                sincronizacion=bool(self._live_sync_in_progress),
                monitor=bool(self._oras_live_monitor_in_progress),
            )
            self._schedule_oras_live_auto_apply(220)
            return

        structural_requested = any(
            isinstance(change, (PendingRoleChange, PendingTeamChange))
            for change in requested
        )
        projected_party = self._projected_party()
        if structural_requested and (self._role_rules_are_active() or self.run.role_rules_activation_pending):
            if self._team_role_conflicts(projected_party):
                self._stop_oras_live_auto_apply_for(requested)
                self.sync_status = "⚠ Aplicación inmediata pausada: roles duplicados"
                self._update_top_status()
                self._show_live_sync_toast(
                    "EQUIPO IRREGULAR",
                    "Hay roles duplicados. RoleRun ha conservado los cambios pendientes sin escribirlos.",
                    False,
                )
                return

        self._save_oras_live_changes(requested, automatic=True)

    def _cancel_oras_live_reconciliation_timer(self) -> None:
        """Detiene únicamente el siguiente sondeo, sin olvidar su estado vivo."""
        after_id = self._oras_live_monitor_after_id
        self._oras_live_monitor_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass

    def _clear_oras_live_reconciliation(self) -> None:
        """Olvida una escritura de RAM que ya no debe reconciliarse.

        Esta frontera ocurre al guardar ``main``, recargar/resetear ORAS o cambiar
        de Run. En todos esos casos el historial de acciones vivas deja de ser una
        base segura para DESHACER y se limpia junto con las huellas de RAM.
        """
        self._cancel_oras_live_reconciliation_timer()
        self._oras_live_monitor_token += 1
        self._oras_live_changes_unpersisted = False
        self._oras_live_expected_fingerprint = None
        self._oras_live_expected_memory_watches = ()
        self._oras_live_pc_overrides.clear()
        self._oras_live_pc_empty_overrides.clear()
        self._oras_pc_reconcile_token += 1
        self._oras_pc_reconcile_in_progress = False
        self._oras_pc_reconcile_last_key = None
        self._oras_pc_read_retries = 0
        self._cancel_bdsp_pc_poll()
        self._sm_pending_role_transition = None
        self._cancel_delayed_faint_callbacks()
        self._oras_live_health_snapshot = None
        self._oras_badge_inventory_witnesses = ()
        self._oras_badge_live_source = None
        self._oras_badge_live_value = None
        self._oras_battle_probe_last_state = "unknown"
        self._oras_live_death_replacement_ids.clear()
        self._oras_live_role_marker_migration_ids.clear()
        self._oras_live_review_batches.clear()
        self._oras_live_undo_batch = None
        self._oras_live_undo_inverse_ids.clear()
        self._oras_live_monitor_failures = 0
        # El Core no debe comparar un state-load/reinicio con la captura anterior,
        # pero conservamos las direcciones vivas ya calibradas para reconectar rápido.
        if hasattr(self, "realtime_core"):
            self.realtime_core.reset_history()

    @staticmethod
    def _merge_oras_live_memory_watches(previous, current):
        """Conserva los bloques aún vivos y deja que la última escritura gane."""
        merged = {}
        for watch in (*tuple(previous or ()), *tuple(current or ())):
            merged[int(watch.address)] = watch
        return tuple(merged[address] for address in sorted(merged))

    def _begin_oras_live_reconciliation(self, game: SaveGameData, memory_watches=()) -> None:
        """Vigila solo los cambios de RAM que aún no llegaron a ``main``."""
        self._cancel_oras_live_reconciliation_timer()
        self._oras_live_monitor_token += 1
        self._oras_live_changes_unpersisted = True
        self._oras_live_expected_fingerprint = live_party_fingerprint(game)
        self._oras_live_expected_memory_watches = tuple(memory_watches or ())
        self._schedule_oras_live_reconciliation()

    def _oras_live_memory_requests(self):
        # Alpha.34: las medallas ya NO se leen desde una dirección estática. ORAS
        # conserva varias copias de Misc en RAM y esa dirección podía apuntar a
        # una copia secundaria con 0. La sonda de medallas calibra la misma copia
        # viva de mochila/dinero que usan las utilidades verificadas.
        requests = {}
        # Alpha.33: NUNCA metemos memoria de batalla en la doble captura estable.
        # HP/PP/oponente cambian durante la animación y podían invalidar el tick
        # entero, llevándose por delante incluso el fallback post-combate. La
        # batalla se lee en una sonda independiente de solo lectura.
        for watch in self._oras_live_expected_memory_watches:
            expected = getattr(watch, "expected", b"")
            if expected:
                requests[int(watch.address)] = len(expected)
        return [(address, requests[address]) for address in sorted(requests)]

    def _process_oras_battle_state(self, state: str | None) -> None:
        """Abre la compuerta de sustitución sin depender del monitor estable.

        Las bajas detectadas desde la party overworld ya implican que ORAS ha
        volcado el resultado del combate; esas pueden contar muestras de salida
        incluso si la sonda de batalla no respondió. Las detectadas dentro de
        batalla sí esperan a ver ``none`` antes de abrir el selector.
        """
        if not self.project or not self.project.pending_faints:
            return
        normalized_state = state if state in {"wild", "trainer", "none"} else None
        became_ready = False
        for event in list(self.project.pending_faints):
            if bool(event.get("prompt_shown", False)) or bool(event.get("battle_ended", False)):
                continue
            identity = str(event.get("identity", "") or "")
            if not identity:
                continue
            source = str(event.get("detected_source", "unknown") or "unknown")
            if source == "overworld":
                in_battle = False
            elif normalized_state is None:
                continue
            else:
                in_battle = normalized_state in {"wild", "trainer"}
            if self.project_service.update_detected_faint_battle_state(
                self.project, identity, in_battle=in_battle, exit_samples_required=2,
            ):
                became_ready = True
        if became_ready:
            self._schedule_pending_faint_picker(180)

    def _process_oras_battle_snapshot(self, snapshot) -> None:
        # Compatibilidad con tests/rutas antiguas; alpha.33 usa la sonda separada.
        if snapshot is None:
            return
        self._process_oras_battle_state(
            parse_oras_battle_state(tuple(getattr(snapshot, "memory_blocks", ()) or ()))
        )

    def _process_oras_badge_value(
        self, badges: int | None, *, source: str | None = None,
    ) -> bool:
        """Sincroniza MEDALLAS sin convertir un ``main`` stale en rollback.

        El guardado sigue siendo evidencia suficiente para recuperar progreso
        hacia arriba. Solo una lectura RAM validada puede reducir el contador,
        porque ese descenso representa una carga de state/partida anterior.
        """
        live_key = self._active_azahar_realtime_key()
        max_badges = 4 if live_key in GEN7_REALTIME_GAME_KEYS else 8
        if not self.project or badges is None or not 0 <= int(badges) <= max_badges:
            return False
        badges = int(badges)
        old = max(0, int(self.project.counters.get("medallas", 0)))
        if old == badges:
            return False
        if badges < old and not badge_source_is_live(source):
            return False
        self.project_service.adjust_counter(
            self.project, "medallas", badges - old,
            source=(
                f"{self._active_azahar_realtime_label()} en vivo · medallas"
                + (f" · {source}" if source else "")
            ),
        )
        self.project = self.project_service.load(self.project.slug) or self.project
        self.run.history = self.project_service.history(self.project)
        self._sync_obs_state(self.current_game)
        if self.active_page == "dashboard":
            self._refresh_dashboard_counter("medallas")
        self._floating_bar_last_signature = None
        if self._floating_bar_is_visible():
            self._render_floating_bar(force=True)
        return True

    def _process_oras_badge_snapshot(self, snapshot) -> bool:
        """Compatibilidad de tests antiguos; la ruta real de alpha.34 usa valor calibrado."""
        if snapshot is None:
            return False
        raw = next((
            bytes(block.data) for block in getattr(snapshot, "memory_blocks", ())
            if int(block.address) == int(ORAS_BADGES_ADDRESS)
        ), None)
        return self._process_oras_badge_value(
            parse_oras_badges(raw) if raw is not None else None,
            source="Misc vivo · contador",
        )

    def _oras_live_memory_watches_match(self, snapshot) -> bool:
        if not self._oras_live_expected_memory_watches:
            return True
        received = {int(block.address): bytes(block.data) for block in snapshot.memory_blocks}
        return all(
            received.get(int(watch.address)) == bytes(watch.expected)
            for watch in self._oras_live_expected_memory_watches
        )

    def _reconcile_oras_live_memory_watches(self, snapshot) -> None:
        """Corrige solo metadatos locales que dependían de RAM auxiliar.

        Las cajas siguen leyéndose desde el guardado para no convertir el F5 en
        una transferencia de 215 KiB. Para una marca de rol concreta sí tenemos
        el PK6 vivo que acabamos de vigilar, así que podemos recuperar ese rol
        sin inventar el contenido completo del PC.
        """
        if not self.project:
            return
        received = {int(block.address): bytes(block.data) for block in snapshot.memory_blocks}
        changed = False
        for watch in self._oras_live_expected_memory_watches:
            if watch.kind not in {"pc-role", "pc-team"}:
                continue
            raw = received.get(int(watch.address))
            if raw is None:
                continue
            # La detección viva puede haber calibrado la base de cajas para una
            # ROM modificada. La posición viaja junto al watch; mantenemos el
            # cálculo antiguo solo para watches de versiones previas.
            box = getattr(watch, "box", None)
            box_slot = getattr(watch, "box_slot", None)
            if box is None or box_slot is None:
                offset = int(watch.address) - ORAS_PC_ADDRESS
                if offset < 0 or offset % PK6_STORED_SIZE:
                    continue
                index = offset // PK6_STORED_SIZE
                box, box_slot = divmod(index, ORAS_PC_BOX_SLOT_COUNT)
                box += 1
                box_slot += 1
            try:
                pokemon = parse_pk6_boxed(raw, int(box), int(box_slot), self.oras_live_reader.move_names)
            except Exception:
                pokemon = None
            if watch.kind == "pc-team":
                # Tras Reset la casilla vuelve a contener el Pokémon que había
                # entrado al equipo. Su marcador real vuelve a ser la fuente de
                # verdad; el saliente se reconciliará desde la party capturada.
                if pokemon is None:
                    continue
                actual_identity = self._pokemon_identity(pokemon)
                if pokemon.role in ROLE_TO_KEY:
                    if self.project.managed_pokemon_roles.get(actual_identity) != pokemon.role:
                        self.project.managed_pokemon_roles[actual_identity] = pokemon.role
                        changed = True
                elif actual_identity in self.project.managed_pokemon_roles:
                    self.project.managed_pokemon_roles.pop(actual_identity, None)
                    changed = True
                continue
            if not watch.pokemon_identity:
                continue
            if pokemon is None or self._pokemon_identity(pokemon) != watch.pokemon_identity:
                if watch.pokemon_identity in self.project.managed_pokemon_roles:
                    self.project.managed_pokemon_roles.pop(watch.pokemon_identity, None)
                    changed = True
                continue
            if pokemon.role in ROLE_TO_KEY:
                if self.project.managed_pokemon_roles.get(watch.pokemon_identity) != pokemon.role:
                    self.project.managed_pokemon_roles[watch.pokemon_identity] = pokemon.role
                    changed = True
            elif watch.pokemon_identity in self.project.managed_pokemon_roles:
                self.project.managed_pokemon_roles.pop(watch.pokemon_identity, None)
                changed = True
        if changed:
            self.project_service.save(self.project)

    def _oras_live_reconciliation_is_active(self) -> bool:
        """Indica si el monitor permanente juego → RoleRun puede seguir vivo."""
        return bool(
            self._oras_live_active
            and self.project
            and self.current_game
            and self.current_save
            and getattr(self.save_engine, "key", "") in REALTIME_READ_GAME_KEYS
        )

    def _oras_live_pending_changes_block_reads(self) -> bool:
        """¿Hay en cola algo que este backend vivo pueda llegar a escribir?

        El monitor no lee mientras el usuario tiene cambios preparados, para no
        sustituir su vista por una lectura del juego a medio camino. Pero esperar
        a un cambio que el adaptador activo **no sabe aplicar** es esperar para
        siempre: la partida deja de actualizarse y el usuario no tiene forma de
        saber por qué.

        Eso fue exactamente lo que pasó con la curación en alpha.16 y con los
        roles en alpha.23. La red de seguridad es esta: solo bloquean la lectura
        los cambios que de verdad tienen writer.
        """
        pendientes = list(getattr(getattr(self, "run", None), "pending_changes", ()) or ())
        if not pendientes:
            return False
        return any(
            not self._oras_live_unsupported_changes([cambio]) for cambio in pendientes
        )

    def _oras_live_reconciliation_can_read(self) -> bool:
        return bool(
            self._oras_live_reconciliation_is_active()
            and not self._oras_live_pending_changes_block_reads()
            and not self._live_sync_in_progress
            and not self._live_write_in_progress
            and not self._oras_live_monitor_in_progress
            and not self._oras_auto_sync_in_progress
            and not getattr(self, "_sm_tm_inventory_load_in_progress", False)
        )

    def _schedule_oras_live_reconciliation(self, delay_ms: int = 950) -> None:
        """Programa el sondeo permanente de Equipo sin bloquear la interfaz."""
        if (
            not self._oras_live_reconciliation_is_active()
            or self._oras_live_monitor_after_id
            or self._oras_live_monitor_in_progress
        ):
            return
        # Justo después de una muerte necesitamos observar que seguimos dentro
        # del combate antes de que desaparezca la estructura del rival. Aceleramos
        # únicamente esa primera sonda; el monitor vuelve después a su cadencia
        # normal y no añade carga durante el resto de la partida.
        if self.project and any(
            not bool(item.get("prompt_shown", False))
            and not bool(item.get("battle_ended", False))
            and not bool(item.get("battle_seen", False))
            for item in self.project.pending_faints
        ):
            delay_ms = min(int(delay_ms), 300)
        generation = self._session_generation
        project_slug = self.project.slug if self.project else ""
        token = self._oras_live_monitor_token
        try:
            self._oras_live_monitor_after_id = self.after(
                max(250, int(delay_ms)),
                lambda: self._start_oras_live_reconciliation(
                    generation, project_slug, token,
                ),
            )
        except Exception:
            self._oras_live_monitor_after_id = None

    def _start_oras_live_reconciliation(self, generation: int, project_slug: str, token: int) -> None:
        self._oras_live_monitor_after_id = None
        if token != self._oras_live_monitor_token or not self._oras_live_reconciliation_is_active():
            return
        # La cola editable siempre gana: mientras el usuario prepara algo, no
        # sustituimos su vista por una lectura de Azahar. Reintentamos más tarde
        # sin abrir conexiones RPC repetidas.
        if not self._oras_live_reconciliation_can_read():
            self._schedule_oras_live_reconciliation(900)
            return
        current = self.current_game
        expected = self._oras_live_expected_fingerprint
        # Las sondas de lectura (medallas/fin de combate) son independientes de
        # que existan escrituras RoleRun aún no persistidas. Los memory watches sí
        # se validan después únicamente cuando corresponde.
        memory_requests = self._oras_live_memory_requests()
        if current is None:
            return
        self._oras_live_monitor_in_progress = True

        def worker() -> None:
            battle_probe = None
            badge_value = None
            badge_source = None
            try:
                # Real-Time Core: un único snapshot lógico encapsula el carril
                # principal y las sondas opcionales de batalla/medallas. Un fallo
                # opcional queda registrado como diagnóstico y no invalida party.
                snapshot = self.realtime_core.capture_monitor(
                    current, save_path=self.current_save.path, memory_requests=memory_requests,
                )
                error = None
                battle_probe = snapshot.battle
                badge_value = snapshot.badges
                badge_source = snapshot.badge_source
            except Exception as exc:
                snapshot = None
                error = str(exc)
            self.after(0, lambda: self._finish_oras_live_reconciliation(
                generation, project_slug, token, expected, snapshot, error, battle_probe, badge_value, badge_source,
            ))

        threading.Thread(
            target=worker, daemon=True, name="RoleRunAzaharReconcile",
        ).start()

    def _incoming_oras_role_changes(
        self, before: SaveGameData, after: SaveGameData,
    ) -> list[PendingRoleChange]:
        """Convierte un cambio de party hecho en ORAS en asignaciones de rol seguras.

        Un reemplazo uno-a-uno hereda el rol del Pokémon saliente. Si simplemente
        crece el equipo, se usa el primer rol libre de izquierda a derecha. Como
        red de seguridad, cualquier miembro activo que siga SIN ROL recibe también
        el primer rol libre. El escritor vivo comprobará después que el Pokémon y
        su rol actual siguen siendo exactamente los observados antes de tocar RAM.
        """
        incoming_assignments = infer_incoming_role_assignments(before, after, ROLE_ORDER)
        unassigned_assignments = infer_unassigned_role_assignments(
            after, ROLE_ORDER, reserved_assignments=incoming_assignments,
        )
        assignments = (*incoming_assignments, *unassigned_assignments)
        result: list[PendingRoleChange] = []
        for assignment in assignments:
            pokemon = next((
                member for member in after.party
                if int(member.slot) == int(assignment.slot)
                and (
                    int(member.species_id), int(member.pid or 0),
                    int(member.tid or 0), int(member.sid or 0),
                ) == assignment.identity
            ), None)
            if pokemon is None:
                continue
            current_role = pokemon.role if pokemon.role in ROLE_TO_KEY else "SIN ROL"
            if current_role == assignment.new_role:
                continue
            old_evs = tuple(int(pokemon.evs.get(key, 0)) for key in STAT_KEYS)
            new_evs = None
            if (
                self._active_azahar_realtime_key() in ROLE_EV_WRITER_GAME_KEYS
                and pokemon.evs
            ):
                # Los cinco roles fijos pueden normalizarse sin interacción. En
                # Líbero la ausencia de ``new_evs`` es deliberada: la frontera
                # común de escritura detendrá la operación y pedirá al jugador
                # sus dos estadísticas antes de tocar RAM.
                new_evs = RoleRunManager._bdsp_role_evs(assignment.new_role)
            result.append(PendingRoleChange(
                pokemon_slot=int(pokemon.slot),
                pokemon=pokemon.nickname or pokemon.species,
                species=pokemon.species,
                old_role=current_role,
                new_role=assignment.new_role,
                pokemon_identity=self._pokemon_identity(pokemon),
                old_evs=old_evs if new_evs is not None else None,
                new_evs=new_evs,
            ))
        return result

    def _defer_automatic_libero_role_until_ev_choice(
        self,
        changes,
        *,
        base_game: SaveGameData | None,
    ) -> bool:
        """Impide asignar Líbero automáticamente sin dos EV elegidos.

        Las entradas hechas desde el PC del propio juego convergen aquí desde
        BDSP, X/Y, SM y USUM. El monitor ya ha demostrado identidad y rol heredado,
        pero Líbero no tiene una distribución determinista: abrir el selector
        es por tanto una precondición de la escritura, no un efecto posterior.
        """
        if self._active_azahar_realtime_key() not in ROLE_EV_WRITER_GAME_KEYS:
            return False
        pending = next((
            change for change in changes
            if isinstance(change, PendingRoleChange)
            and canonical_role(change.new_role) == "Líbero"
            and change.new_evs is None
        ), None)
        if pending is None:
            return False

        game = base_game if base_game is not None else self.current_game
        if game is None:
            return False
        pokemon = next((
            member for member in game.party
            if self._pokemon_identity(member) == str(pending.pokemon_identity or "")
        ), None)
        if pokemon is None:
            return False

        prompt_key = (
            int(self._session_generation),
            str(pending.pokemon_identity or ""),
            int(pending.pokemon_slot),
        )
        if getattr(self, "_automatic_libero_ev_prompt_key", None) == prompt_key:
            return True
        self._automatic_libero_ev_prompt_key = prompt_key
        generation = int(self._session_generation)
        project_slug = self.project.slug if self.project else ""
        batch = list(changes)
        captured_game = game

        def apply_choice(selected_stats: tuple[str, ...]) -> None:
            self._automatic_libero_ev_prompt_key = None
            if (
                generation != self._session_generation
                or not self.project
                or self.project.slug != project_slug
            ):
                return
            desired = self._bdsp_role_evs("Líbero", selected_stats)
            if desired is None:
                return
            pending.old_evs = tuple(int(pokemon.evs.get(key, 0)) for key in STAT_KEYS)
            pending.new_evs = desired
            self._save_oras_live_changes(batch, automatic=True, base_game=captured_game)

        context = "floating" if self._floating_bar_is_visible() else "main"
        self.sync_status = f"◌ Elige los EV de Líbero para {pokemon.nickname or pokemon.species}"
        self._update_top_status()
        self._prompt_libero_ev_stats(pokemon, apply_choice, context=context)
        return True

    def _sm_role_transition_key(self, game: SaveGameData) -> tuple:
        """Huella fuerte del equipo usada mientras se demuestra PC↔party en SM.

        No incluye EXP/PS ni otros campos volátiles. Sí incluye slot, identidad y
        rol observado porque una asignación automática solo es válida para esa
        composición exacta.
        """
        return tuple(
            (
                int(pokemon.slot), int(pokemon.species_id), int(pokemon.pid or 0),
                int(pokemon.tid or 0), int(pokemon.sid or 0),
                str(pokemon.role or "SIN ROL"),
            )
            for pokemon in sorted(game.party, key=lambda item: int(item.slot))
        )

    def _queue_sm_role_transition(
        self, game: SaveGameData, changes: list[PendingRoleChange] | tuple[PendingRoleChange, ...],
    ) -> bool:
        """Retiene una normalización de rol hasta disponer de prueba PC fresca.

        La regla semántica se decide con ``before``/``after`` en el instante en
        que el monitor ve la transición. Para una sustitución uno-a-uno esto
        conserva exactamente el rol del saliente; no se recalcula después como
        un simple "primer rol libre".
        """
        batch = list(changes or ())
        if not batch:
            return False
        self._sm_pending_role_transition = (self._sm_role_transition_key(game), batch)
        return True

    def _flush_sm_role_transition_after_pc_proof(self) -> bool:
        """Aplica la asignación SM solo tras una lectura PC host↔guest válida.

        Devuelve ``True`` cuando se inició una escritura. Si la party cambió
        mientras se leía el PC, descarta la intención obsoleta y deja que el
        siguiente tick vuelva a inferirla desde un nuevo before/after real.
        """
        pending = getattr(self, "_sm_pending_role_transition", None)
        if pending is None or not self.current_game:
            return False
        if self._active_azahar_realtime_key() not in GEN7_REALTIME_GAME_KEYS:
            self._sm_pending_role_transition = None
            return False

        expected_key, changes = pending
        if self._sm_role_transition_key(self.current_game) != expected_key:
            self._sm_pending_role_transition = None
            self._schedule_oras_live_reconciliation(250)
            return False

        current_by_identity = {self._pokemon_identity(pokemon): pokemon for pokemon in self.current_game.party}
        validated: list[PendingRoleChange] = []
        for change in changes:
            pokemon = current_by_identity.get(str(change.pokemon_identity or ""))
            if pokemon is None:
                continue
            current_role = pokemon.role if pokemon.role in ROLE_TO_KEY else "SIN ROL"
            if current_role == change.new_role:
                continue
            if current_role != change.old_role:
                # El jugador cambió el marcador mientras se demostraba el PC. No
                # pisamos esa decisión; el monitor resolverá el nuevo estado.
                continue
            validated.append(change)

        if not validated:
            self._sm_pending_role_transition = None
            return False

        generated_ids = {id(change) for change in validated}
        self._oras_live_system_role_assignment_ids.update(generated_ids)
        label_fn = getattr(self, "_active_azahar_realtime_label", None)
        live_label = (
            str(label_fn()) if callable(label_fn) else
            ("UltraSol/UltraLuna" if self._active_azahar_realtime_key() == "usum" else "Sol/Luna")
        )
        if self._save_oras_live_changes(validated, automatic=True, base_game=self.current_game):
            self._sm_pending_role_transition = None
            self.sync_status = f"◷ {live_label} · aplicando rol heredado tras validar Equipo↔PC…"
            self._update_top_status()
            return True

        self._oras_live_system_role_assignment_ids.difference_update(generated_ids)
        # No hacemos un write-loop. Conservamos la intención y pedimos una nueva
        # prueba PC; el siguiente intento solo ocurrirá después de otra lectura
        # completa host↔guest.
        self.sync_status = f"◌ {live_label} · esperando nueva prueba Equipo↔PC para asignar rol…"
        self._update_top_status()
        try:
            self.after(250, lambda: self._schedule_oras_external_pc_reconcile(
                self.current_game, self.current_game, force=True,
            ))
        except Exception:
            pass
        return False

    def _cancel_pending_faint_picker_request(self) -> None:
        after_id = self._oras_faint_picker_after_id
        self._oras_faint_picker_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass

    def _next_unshown_pending_faint(self) -> dict | None:
        if not self.project:
            return None
        return next((
            item for item in self.project.pending_faints
            if not bool(item.get("prompt_shown", False))
        ), None)

    def _next_ready_pending_faint(self) -> dict | None:
        """Primera baja cuyo combate ya terminó y cuyo selector no se mostró."""
        if not self.project:
            return None
        return next((
            item for item in self.project.pending_faints
            if not bool(item.get("prompt_shown", False))
            and bool(item.get("battle_ended", False))
        ), None)

    def _schedule_pending_faint_picker(self, delay_ms: int = 450) -> None:
        """Programa como máximo la primera notificación de baja aún no mostrada.

        ``prompt_shown`` se persiste en la Run al crear la ventana. Por tanto una
        baja nunca vuelve a lanzar el modal después de cerrar/reabrir RoleRun.
        """
        self._cancel_pending_faint_picker_request()
        if self._next_ready_pending_faint() is None:
            return
        try:
            self._oras_faint_picker_after_id = self.after(
                max(80, int(delay_ms)), self._maybe_open_pending_faint_picker,
            )
        except Exception:
            self._oras_faint_picker_after_id = None

    def _faint_picker_window_exists(self) -> bool:
        mode = getattr(self, "_faint_replacement_mode", None)
        if mode is not None:
            identity = str(mode.get("identity", "") or "")
            if identity and self.project and any(
                str(item.get("identity", "") or "") == identity
                for item in self.project.pending_faints
            ):
                return True
            self._faint_replacement_mode = None
            self._oras_faint_picker_event_identity = None
        window = self._oras_faint_replacement_window
        if window is None:
            return False
        try:
            return bool(window.winfo_exists())
        except Exception:
            self._oras_faint_replacement_window = None
            self._oras_faint_picker_event_identity = None
            return False

    def _faint_picker_blocks_floating(self) -> bool:
        """Alpha.37: una baja nunca bloquea la barra flotante.

        Si el selector está abierto, ``_suspend_modal_for_floating_bar`` libera su
        grab y lo oculta. Al volver a RoleRun se restaura ESA MISMA ventana, en vez
        de crear otra. Esto evita cierres aparentes y Toplevel duplicados.
        """
        return False

    @staticmethod
    def _save_file_signature(path: Path) -> tuple[int, int] | None:
        try:
            stat = path.stat()
            return int(stat.st_mtime_ns), int(stat.st_size)
        except OSError:
            return None

    def _prime_pending_faint_pc_data(self) -> None:
        """Precarga el PC fuera del hilo de Tk cuando hay una baja pendiente.

        El motor ``read-boxes`` puede tardar lo bastante para que Windows pinte la
        raíz en blanco al volver desde la barra. Se ejecuta en background; el modal
        solo se construye cuando el resultado ya está disponible.
        """
        if (
            not self.project or self._next_unshown_pending_faint() is None or not self.current_save
            or self._oras_faint_picker_loading
        ):
            return
        save_path = Path(self.current_save.path)
        signature = self._save_file_signature(save_path)
        live_key = self._active_azahar_realtime_key() if self._oras_live_active else ""
        # Los backends de matriz completa refrescan el PC live antes del selector. Una
        # caché válida por firma solo demuestra el mismo ``main`` en disco, no que
        # las cajas en RAM sigan iguales tras capturas/movimientos hechos jugando.
        if live_key not in FULL_MATRIX_LIVE_PC_GAME_KEYS and self._pc_cache is not None and signature == self._pc_cache_signature:
            return

        self._oras_faint_picker_loading = True
        self._oras_faint_picker_loading_token += 1
        token = self._oras_faint_picker_loading_token
        generation = self._session_generation
        project_slug = self.project.slug

        def worker() -> None:
            try:
                data = self.save_engine.read_boxes(save_path)
                live_key = self._active_azahar_realtime_key() if self._oras_live_active else ""
                if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS:
                    anchors = [pokemon for box in data.boxes for pokemon in box.pokemon]
                    realtime_core = getattr(self, "realtime_core", None)
                    kwargs = {"box_count": int(data.box_count), "box_slot_count": int(data.box_slot_count)}
                    if realtime_core is not None:
                        _process, _base, live_slots = realtime_core.read_pc(anchors, **kwargs)
                    else:
                        adapter = getattr(
                            self,
                            "bdsp_realtime_adapter" if live_key == "bdsp"
                            else f"{live_key}_realtime_adapter" if live_key in MELONDS_REALTIME_GAME_KEYS
                            else "usum_realtime_adapter" if live_key == "usum"
                            else "sm_realtime_adapter",
                            None,
                        )
                        if adapter is None:
                            raise RuntimeError(f"No hay lector vivo de PC disponible para {self._active_azahar_realtime_label()}.")
                        _process, _base, live_slots = adapter.read_pc(anchors, **kwargs)

                    boxes: list[SaveBox] = []
                    open_slots: list[tuple[int, int]] = []
                    base_names = {int(box.index): str(box.name) for box in data.boxes}
                    for box_no in range(1, int(data.box_count) + 1):
                        members: list[SavePokemon] = []
                        for slot_no in range(1, int(data.box_slot_count) + 1):
                            mon = live_slots.get((box_no, slot_no))
                            if mon is None:
                                open_slots.append((box_no, slot_no))
                                continue
                            clone = copy.deepcopy(mon)
                            clone.box = box_no
                            clone.box_slot = slot_no
                            clone.slot = slot_no
                            members.append(clone)
                        boxes.append(SaveBox(
                            index=box_no, name=base_names.get(box_no, f"Caja {box_no}"), pokemon=members,
                        ))
                    first_open = open_slots[0] if open_slots else (None, None)
                    data = SavePCData(
                        game=data.game, box_count=int(data.box_count), box_slot_count=int(data.box_slot_count),
                        current_box=int(data.current_box or 1), boxes=boxes,
                        next_open_box=first_open[0], next_open_box_slot=first_open[1],
                        open_slots=open_slots, raw=dict(data.raw or {}),
                    )
                error = None
            except Exception as exc:
                data = None
                error = str(exc)
            try:
                self.after(0, lambda: self._finish_pending_faint_pc_preload(
                    generation, project_slug, token, signature, data, error,
                ))
            except Exception:
                pass

        threading.Thread(
            target=worker, daemon=True, name="RoleRunFaintPCPreload",
        ).start()

    def _finish_pending_faint_pc_preload(
        self, generation: int, project_slug: str, token: int, signature,
        data: SavePCData | None, error: str | None,
    ) -> None:
        if token != self._oras_faint_picker_loading_token:
            return
        self._oras_faint_picker_loading = False
        if (
            generation != self._session_generation or not self.project
            or self.project.slug != project_slug
        ):
            return
        if error or data is None:
            # No abrimos messageboxes desde un callback que puede coincidir con el
            # retorno de la barra. Mostramos el error una sola vez cuando la raíz
            # esté estable y el selector realmente vaya a abrirse.
            pending = self._next_unshown_pending_faint()
            identity = str(pending.get("identity", "")) if pending else None
            self._oras_faint_picker_error_identity = identity or None
            self.sync_status = f"⚠ No se pudo preparar el PC para la sustitución: {error or 'lectura fallida'}"
            self._update_top_status()
            return
        self._pc_cache = data
        self._pc_cache_signature = signature
        self._oras_faint_picker_error_identity = None
        # Si el usuario ya volvió a RoleRun, la única solicitud debounced abrirá
        # el selector. Si sigue jugando, los datos quedan listos sin robar foco.
        self._schedule_pending_faint_picker(180)

    def _reset_faint_picker_runtime(self) -> None:
        """Limpia únicamente el estado UI/thread del selector, no la baja persistida."""
        self._cancel_pending_faint_picker_request()
        self._oras_faint_picker_loading_token += 1
        self._oras_faint_picker_loading = False
        self._oras_faint_picker_event_identity = None
        self._faint_replacement_mode = None
        self._faint_reopen_requested_identity = None
        self._oras_faint_picker_suppressed_identity = None
        self._oras_faint_picker_error_identity = None
        window = self._oras_faint_replacement_window
        self._oras_faint_replacement_window = None
        if window is not None:
            try:
                if window.winfo_exists():
                    try:
                        window.grab_release()
                    except Exception:
                        pass
                    window.destroy()
            except Exception:
                pass

    def _cancel_delayed_faint_callbacks(self) -> None:
        for after_id in tuple(self._oras_delayed_faint_after_ids.values()):
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._oras_delayed_faint_after_ids.clear()
        self._oras_delayed_faint_payloads.clear()

    def _publish_registered_faint(self, names: list[str], registered: int) -> None:
        if not self.project or registered <= 0:
            return
        # El servicio ya ha persistido proyecto + historial. OBS debe usar la
        # MISMA proyección que Dashboard/Equipo/Barra: el Pokémon pendiente de
        # sustitución ya no está disponible aunque ORAS conserve todavía su PK6.
        self.run.history = self.project_service.history(self.project)
        # La muerte la ha decidido el juego, no el usuario.
        self._asumir_estado_del_juego()
        self._sync_live_layout(refresh_floating=False)
        self._refresh_dashboard_counter("vidas")
        self._floating_bar_last_signature = None
        joined = ", ".join(names)
        self.sync_status = (
            f"☠ {joined} debilitado" + ("s" if registered > 1 else "")
            + f" · -{registered} vida" + ("s" if registered > 1 else "")
            + " · sustitución pendiente"
        )
        self._update_top_status()
        self._prime_pending_faint_pc_data()
        if self._floating_bar_is_visible():
            self._render_floating_bar(force=True)
            self._main_ui_dirty_while_floating = True
        elif self.active_page in {"dashboard", "team"}:
            self._smooth_render_page(preserve_scroll=(self.active_page == "team"))

    def _commit_delayed_faint(self, identity: str) -> None:
        self._oras_delayed_faint_after_ids.pop(identity, None)
        payload = self._oras_delayed_faint_payloads.pop(identity, None)
        if payload is None or not self.project:
            return
        pokemon, source = payload
        # Si el Pokémon volvió a tener PS antes del segundo visual, no registramos
        # una falsa baja. Lo normal es que continúe a 0 hasta salir del combate.
        latest = self._oras_live_health_snapshot
        if latest is not None:
            current = next((
                member for member in latest.party
                if self._pokemon_identity(member) == identity
            ), None)
            if current is not None and int(getattr(current, "current_hp", 0) or 0) > 0:
                return
        role, _symbol = self._effective_role(pokemon)
        if not self.project_service.register_detected_faint(self.project, {
            "identity": identity,
            "pokemon": pokemon.nickname or pokemon.species,
            "species": pokemon.species,
            "slot": int(pokemon.slot),
            "role": role,
            "detected_source": source,
            "source_label": f"{self._active_azahar_realtime_label()} en vivo",
        }):
            return
        self._publish_registered_faint([pokemon.nickname or pokemon.species], 1)

    def _schedule_delayed_faint(self, pokemon: SavePokemon, *, source: str) -> None:
        identity = self._pokemon_identity(pokemon)
        if not identity or identity in self._oras_delayed_faint_after_ids:
            return
        self._oras_delayed_faint_payloads[identity] = (pokemon, source)
        try:
            self._oras_delayed_faint_after_ids[identity] = self.after(
                1000, lambda ident=identity: self._commit_delayed_faint(ident),
            )
        except Exception:
            self._oras_delayed_faint_payloads.pop(identity, None)

    def _publish_live_health(self, game: SaveGameData | None) -> bool:
        """Fusiona la salud viva y refresca **solo si algo cambió de verdad**.

        Es la parte de ``_process_oras_health_snapshot`` que no decide bajas.
        B2/W2 la necesita exactamente así: publica PS pero su maquinaria de KO
        sigue cerrada porque todavía no tiene writer de sustitución seguro.

        El «solo si cambió» no es un detalle de rendimiento. Refrescar la barra
        flotante la destruye y la reconstruye entera —incluidas dos imágenes
        releídas del disco—, así que hacerlo en cada ciclo del monitor produce un
        parpadeo visible una vez por segundo.
        """
        changed = RoleRunManager._merge_live_health_fields(self.current_game, game)
        if not changed:
            return False
        if self._floating_bar_is_visible():
            # La firma anterior NO se anula aquí. `force=True` ya se salta por su
            # cuenta la comparación de igualdad, y la ruta rápida —mover solo las
            # barritas de PS— necesita esa firma para saber qué ha cambiado:
            # anulándola devolvía False siempre. Resultado medido en el log del
            # usuario: las nueve muestras de la sesión con `applied: False`. La
            # optimización no se había aplicado ni una sola vez, y cada cambio de
            # PS en combate reconstruía la barra entera, con dos PNG releídos del
            # disco y unos cuarenta widgets, en el hilo de Tk.
            self._render_floating_bar(force=True)
            self._main_ui_dirty_while_floating = True
        else:
            # Oculta no hay nada que repintar, pero su firma queda vieja: se
            # anula para que al volver a mostrarse se recomponga entera.
            self._floating_bar_last_signature = None
            if (
                self.active_page in TEAM_PC_PAGES
                and self._live_health_render_after_id is None
            ):
                self._live_health_render_after_id = self.after(
                    90, self._refresh_live_health_page,
                )
        return True

    def _process_oras_health_snapshot(self, game: SaveGameData, *, source: str = "overworld") -> None:
        """Publica salud viva y observa PS > 0 -> 0.

        En ORAS (``source="battle"``) la detección se difiere 1 segundo para
        acompasar la animación. Sol/Luna alpha.41 usa ``battle-visible`` basado
        directamente en Displayed HP, por lo que registra en el mismo tick en que
        la barra visible llega a 0. El fallback overworld sigue siendo inmediato.
        """
        previous = self._oras_live_health_snapshot
        self._oras_live_health_snapshot = game
        self._publish_live_health(game)
        if not self.project:
            return

        if source == "overworld":
            for member in game.party:
                if int(getattr(member, "current_hp", 0) or 0) <= 0:
                    continue
                identity = self._pokemon_identity(member)
                if self.project_service.clear_stale_detected_faint_for_alive_party(self.project, identity):
                    self._close_faint_picker_for_identity(identity)

        if previous is None:
            return
        transitions = detect_fainted_transitions(previous, game)
        if not transitions:
            return
        self._record_bdsp_ui_event(
            "health-transition",
            source=source,
            transitions=[
                {
                    "slot": int(item.slot),
                    "species": int(item.identity[0]),
                    "previous_hp": int(item.previous_hp),
                    "current_hp": int(item.current_hp),
                }
                for item in transitions
            ],
        )

        immediate_names: list[str] = []
        immediate_registered = 0
        for transition in transitions:
            pokemon = next((
                member for member in game.party
                if (
                    int(member.species_id), int(member.pid or 0),
                    int(member.tid or 0), int(member.sid or 0),
                ) == transition.identity
            ), None)
            if pokemon is None:
                continue
            identity = self._pokemon_identity(pokemon)
            if source == "battle":
                self._schedule_delayed_faint(pokemon, source=source)
                continue

            # El fallback post-combate gana sobre cualquier callback pendiente.
            after_id = self._oras_delayed_faint_after_ids.pop(identity, None)
            if after_id:
                try:
                    self.after_cancel(after_id)
                except Exception:
                    pass
            self._oras_delayed_faint_payloads.pop(identity, None)
            role, _symbol = self._effective_role(pokemon)
            if self.project_service.register_detected_faint(self.project, {
                "identity": identity,
                "pokemon": pokemon.nickname or pokemon.species,
                "species": pokemon.species,
                "slot": int(pokemon.slot),
                "role": role,
                "detected_source": source,
                "source_label": f"{self._active_azahar_realtime_label()} en vivo",
            }):
                immediate_registered += 1
                immediate_names.append(pokemon.nickname or pokemon.species)

        if immediate_registered:
            self._record_bdsp_ui_event(
                "faint-registered",
                source=source,
                count=int(immediate_registered),
                pokemon=list(immediate_names),
            )
            self._publish_registered_faint(immediate_names, immediate_registered)

    @staticmethod
    def _merge_live_health_fields(target: SaveGameData | None, health: SaveGameData | None) -> bool:
        """Fusiona solo salud de una identidad fuerte única; nunca mueve slots."""
        if target is None or health is None:
            return False
        samples: dict[tuple[int, int, int, int], SavePokemon] = {}
        duplicates: set[tuple[int, int, int, int]] = set()
        for pokemon in health.party:
            identity = (
                int(pokemon.species_id), int(pokemon.pid or 0),
                int(pokemon.tid or 0), int(pokemon.sid or 0),
            )
            if identity in samples:
                duplicates.add(identity)
            samples[identity] = pokemon
        changed = False
        for pokemon in target.party:
            identity = (
                int(pokemon.species_id), int(pokemon.pid or 0),
                int(pokemon.tid or 0), int(pokemon.sid or 0),
            )
            sample = None if identity in duplicates else samples.get(identity)
            if sample is None:
                continue
            current_hp = int(getattr(sample, "current_hp", 0) or 0)
            max_hp = int(getattr(sample, "max_hp", 0) or 0)
            if max_hp <= 0 or not 0 <= current_hp <= max_hp:
                continue
            status = int(getattr(sample, "status_condition", 0) or 0)
            if (
                int(getattr(pokemon, "current_hp", 0) or 0) != current_hp
                or int(getattr(pokemon, "max_hp", 0) or 0) != max_hp
                or int(getattr(pokemon, "status_condition", 0) or 0) != status
            ):
                pokemon.current_hp = current_hp
                pokemon.max_hp = max_hp
                pokemon.status_condition = status
                changed = True
        return changed

    @staticmethod
    def _live_metadata_is_missing(current, live) -> bool:
        """¿La vista actual carece de datos que la captura viva sí trae?

        ``diff_live_party`` solo compara composición, orden, roles, movimientos y
        nivel: ignora estadísticas, IV, EV y naturaleza. Por eso, cuando algo
        repone ``current_game`` desde el guardado —recargar tras guardar dentro
        del juego, o abrir la Run—, un backend que solo republica ante cambios de
        composición se quedaba **para siempre** sin esos datos, y la ficha
        mostraba «—» en todas las características.

        Se comprueba por identidad fuerte y solo en un sentido: si la captura
        viva tiene el dato y la vista actual no, hay que publicar.
        """
        if current is None or live is None:
            return False
        def identidad(pokemon):
            return (
                int(getattr(pokemon, "species_id", 0) or 0),
                int(getattr(pokemon, "pid", 0) or 0),
                int(getattr(pokemon, "tid", 0) or 0),
                int(getattr(pokemon, "sid", 0) or 0),
            )
        actuales = {identidad(pokemon): pokemon for pokemon in getattr(current, "party", ())}
        for vivo in getattr(live, "party", ()):
            actual = actuales.get(identidad(vivo))
            if actual is None:
                continue
            for campo in ("stats", "ivs", "evs", "base_stats"):
                if getattr(vivo, campo, None) and not getattr(actual, campo, None):
                    return True
            if getattr(vivo, "nature", "") and not getattr(actual, "nature", ""):
                return True
        return False

    def _apply_live_health_incrementally(self) -> bool:
        """Refresca solo las barras de PS. ``False`` si hay que reconstruir.

        Medido en Windows sobre la vista real: reconstruir Equipo y PC cuesta
        **845 ms** de hilo Tk y 642 widgets. Durante un combate el monitor lee
        cada 250-450 ms, así que cada cambio de PS pagaba esa reconstrucción
        entera para mover unas barras.

        Es una ruta de aceleración, no de decisión: ante cualquier duda devuelve
        ``False`` y el render completo mantiene su comportamiento anterior.
        """
        view = getattr(self, "_team_pc_view", None)
        if view is None or view is not getattr(self, "_presented_team_pc_view", None):
            return False
        updater = getattr(view, "update_team_health", None)
        identities_getter = getattr(view, "rendered_team_identities", None)
        if not callable(updater) or not callable(identities_getter):
            return False
        party = list(self._projected_party())
        if not party:
            return False
        identities = [self._pokemon_identity(member) for member in party]
        # Si el equipo ya no está compuesto por los mismos Pokémon —una baja, una
        # sustitución, una entrada desde el PC— mover barras no basta.
        if set(identities) != set(identities_getter()):
            return False
        with perf.span("ui.live_health_incremental", members=len(party)):
            for member, identity in zip(party, identities):
                if not updater(
                    identity,
                    getattr(member, "current_hp", None),
                    int(getattr(member, "max_hp", 0) or 0),
                    # La comprobación de arriba es de conjunto, así que los
                    # mismos seis reordenados llegan hasta aquí. La firma de PS
                    # de la vista se ordena por posición física: sin decirle la
                    # de ahora, quedaría permutada aunque cada barra sea la
                    # correcta, y las barreras que la comparan no cerrarían.
                    slot=int(getattr(member, "slot", 0) or 0),
                ):
                    return False
        return True

    def _refresh_live_health_page(self) -> None:
        self._live_health_render_after_id = None
        if self.active_page not in TEAM_PC_PAGES or self._floating_bar_is_visible():
            return
        if self._apply_live_health_incrementally():
            return
        self._smooth_render_page(preserve_scroll=True)

    def _pending_faint_party_member(self, event: dict) -> SavePokemon | None:
        if not self.current_game:
            return None
        identity = str(event.get("identity", "") or "")
        return next((
            pokemon for pokemon in self.current_game.party
            if self._pokemon_identity(pokemon) == identity
        ), None)

    def _close_faint_picker_for_identity(self, identity: str) -> None:
        """Cierra la presentación de esa baja sin alterar el evento persistido."""
        identity = str(identity or "")
        mode = getattr(self, "_faint_replacement_mode", None)
        if mode is not None and str(mode.get("identity", "") or "") == identity:
            self._faint_replacement_mode = None
            self._oras_faint_picker_event_identity = None
            if self.active_page in {"team", "pc"}:
                self._smooth_render_page(preserve_scroll=True)
        window = self._oras_faint_replacement_window
        if window is None or self._oras_faint_picker_event_identity != identity:
            return
        if self._floating_suspended_modal is window:
            self._floating_suspended_modal = None
            self._floating_suspended_modal_had_grab = False
        self._oras_faint_replacement_window = None
        self._oras_faint_picker_event_identity = None
        try:
            if window.winfo_exists():
                try:
                    window.grab_release()
                except Exception:
                    pass
                window.destroy()
        except Exception:
            pass

    def _reconcile_pending_faints_against_party(self, game: SaveGameData) -> None:
        """Resuelve una baja si el jugador ya retiró al debilitado desde ORAS.

        Esto es esencial cuando el usuario ignora/cierra el selector y hace el
        cambio desde el PC del propio juego: el modal se cierra y deja de impedir
        que la nueva party se convierta en la fuente de verdad de RoleRun.
        """
        if not self.project or not self.project.pending_faints:
            return
        live_ids = {self._pokemon_identity(pokemon) for pokemon in game.party}
        role_run_replacing = {
            str(getattr(change, "outgoing_identity", "") or "")
            for change in self.run.pending_changes
            if isinstance(change, PendingTeamChange)
            and getattr(change, "operation", "") == "replace-fainted"
        }
        resolved = []
        for event in list(self.project.pending_faints):
            identity = str(event.get("identity", "") or "")
            if not identity or identity in live_ids or identity in role_run_replacing:
                continue
            self._close_faint_picker_for_identity(identity)
            if self.project_service.resolve_detected_faint_external(self.project, identity):
                resolved.append(str(event.get("pokemon", "Pokémon")))

        if not resolved:
            return
        self.run.history = self.project_service.history(self.project)
        self._sync_obs_state(game)
        self.sync_status = "✓ Baja resuelta desde el juego · " + ", ".join(resolved)
        self._update_top_status()

    def _maybe_open_pending_faint_picker(self) -> None:
        """Abre como máximo un selector cuando RoleRun ya está estable.

        No lee las cajas aquí: esa operación se precarga en background. Tampoco
        intenta abrir mientras la barra sigue visible, la raíz se está restaurando
        o existe cualquier otro grab modal.
        """
        self._oras_faint_picker_after_id = None
        if not self.project or not self.project.pending_faints or not self.current_game:
            return
        event = self._next_ready_pending_faint()
        if event is None:
            return
        if self.run.pending_changes:
            # El selector anterior puede haber iniciado una sustitución que aún
            # se está aplicando. No perder el turno del siguiente KO de la cola:
            # volver a comprobarlo cuando esa escritura haya terminado.
            self._schedule_pending_faint_picker(450)
            return
        if self._live_write_in_progress or self._live_sync_in_progress or self._oras_live_monitor_in_progress:
            self._schedule_pending_faint_picker(450)
            return
        if self._auto_floating_guard or self._body_swap_in_progress:
            self._schedule_pending_faint_picker(450)
            return
        # Fin de combate + barra activa: esta es la única ocasión en la que una
        # baja puede sacar automáticamente al usuario de la barra. Reutilizamos el
        # retorno estable existente (oculta barra, pinta la última pestaña todavía
        # retirada y luego muestra RoleRun) y el mismo debounce abrirá el modal.
        if self._floating_bar_is_visible():
            self._floating_logo_to_dashboard()
            return
        try:
            if str(self.state()) in {"withdrawn", "iconic"}:
                return
        except Exception:
            return
        if self._faint_picker_window_exists():
            return
        identity = str(event.get("identity", "") or "")

        try:
            grabbed = self.grab_current()
            if grabbed is not None:
                # Esperamos a que REVISAR CAMBIOS u otro modal termine. Al ser un
                # debounce, solo queda un callback vivo aunque el modal dure rato.
                self._schedule_pending_faint_picker(800)
                return
        except Exception:
            pass

        dead = self._pending_faint_party_member(event)
        if dead is None:
            # El monitor puede haber visto la salida del debilitado entre el último
            # snapshot y este callback. Se resuelve como cambio hecho desde ORAS.
            self._reconcile_pending_faints_against_party(self.current_game)
            return

        if not self.current_save:
            return
        signature = self._save_file_signature(Path(self.current_save.path))
        pc_data = self._pc_cache if self._pc_cache is not None and signature == self._pc_cache_signature else None
        if pc_data is None:
            if self._oras_faint_picker_error_identity == identity:
                self._oras_faint_picker_error_identity = None
                messagebox.showwarning(
                    "No se pudo preparar el PC",
                    "RoleRun no pudo leer las cajas para elegir sustituto. La baja y la vida perdida siguen guardadas. Intenta volver a abrir la Run o pulsa F5 antes de reintentarlo.",
                    parent=self,
                )
                return
            self._prime_pending_faint_pc_data()
            return

        self._open_faint_replacement_picker(event, dead, pc_data=pc_data)

    def _pending_faint_for_reopen(self) -> dict | None:
        if not self.project:
            return None
        run = getattr(self, "run", None)
        replacing = {
            str(getattr(change, "outgoing_identity", "") or "")
            for change in list(getattr(run, "pending_changes", ()) or ())
            if isinstance(change, PendingTeamChange)
            and str(getattr(change, "operation", "") or "") == "replace-fainted"
        }
        return next((
            item for item in self.project.pending_faints
            if bool(item.get("battle_ended", False))
            and str(item.get("identity", "") or "") not in replacing
        ), None)

    def _reopen_pending_faint_picker(self) -> None:
        """Reabre una baja persistida sin volver a registrar vida ni muerte."""
        event = self._pending_faint_for_reopen()
        if event is None:
            self._set_operation_status(
                "neutral", "SIN BAJAS PENDIENTES",
                "No hay ningún sustituto pendiente de elegir.",
            )
            return
        dead = self._pending_faint_party_member(event)
        if dead is None:
            if self.current_game is not None:
                self._reconcile_pending_faints_against_party(self.current_game)
            return
        live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
        live_key = live_key_getter() if callable(live_key_getter) else ""
        if live_key not in FULL_MATRIX_LIVE_PC_GAME_KEYS:
            # Salía por un `return False` mudo —en una función `-> None`, huella
            # de un copiar y pegar—. La barra ofrece este botón sin mirar el
            # juego, así que en ORAS y X/Y el usuario lo pulsaba y no pasaba
            # absolutamente nada: ni selector, ni cambio de estado, ni aviso. Y
            # es la única reentrada posible una vez cerrado el selector.
            self._set_operation_status(
                "warning", "AQUÍ NO SE PUEDE ELEGIR SUSTITUTO",
                f"{self._active_azahar_realtime_label()} todavía no lee las cajas "
                "completas, que es lo que hace falta para elegir el sustituto "
                "desde RoleRun. Hazlo dentro del juego: al volver, RoleRun lo "
                "reconoce solo.",
                persistent=False,
            )
            return
        pc_data = self._team_pc_cached_data()
        if pc_data is None:
            self._faint_reopen_requested_identity = str(event.get("identity", "") or "")
            if self.active_page not in {"team", "pc"}:
                self.navigate(DEFAULT_PAGE)
            else:
                self._smooth_render_page(preserve_scroll=True)
            self._set_operation_status(
                "applying",
                "PREPARANDO SUSTITUCIÓN",
                "RoleRun está cargando las cajas sin bloquear la ventana.",
            )
            self.after(20, self._start_team_pc_load)
            return
        self._open_faint_replacement_picker(event, dead, pc_data=pc_data)

    def _dismiss_integrated_faint_picker(self) -> None:
        """Cierra solo la vista; la baja, la vida y el Cementerio no cambian."""
        mode = self._faint_replacement_mode
        if mode is None:
            return
        identity = str(mode.get("identity", "") or "")
        self._faint_replacement_mode = None
        if self._oras_faint_picker_event_identity == identity:
            self._oras_faint_picker_event_identity = None
        self._set_auto_floating_guard_temporarily(500)
        if self.active_page in {"team", "pc"}:
            self._smooth_render_page(preserve_scroll=True)
        self._set_operation_status(
            "warning",
            "BAJA PENDIENTE",
            "La vida perdida sigue registrada. Puedes elegir el sustituto cuando estés preparado.",
            actions=("Elegir sustituto", "No sustituir"),
            persistent=True,
        )
        self._schedule_pending_faint_picker(650)

    def _decline_pending_faint_replacement(self) -> None:
        """Deja libre el rol sin deshacer la muerte ni el contador de vidas."""
        mode = getattr(self, "_faint_replacement_mode", None)
        event = mode if isinstance(mode, dict) else self._pending_faint_for_reopen()
        if event is None or not self.project:
            self._set_operation_status(
                "neutral", "SIN BAJAS PENDIENTES",
                "No hay ninguna sustitución pendiente que descartar.",
            )
            return
        identity = str(event.get("identity", "") or "")
        if not self.project_service.decline_detected_faint_replacement(self.project, identity):
            return
        self._cancel_pending_faint_picker_request()
        self._faint_replacement_mode = None
        if self._oras_faint_picker_event_identity == identity:
            self._oras_faint_picker_event_identity = None
        self._set_auto_floating_guard_temporarily(500)
        if self.active_page in {"team", "pc"}:
            self._smooth_render_page(preserve_scroll=True)
        self._set_operation_status(
            "confirmed",
            "SUSTITUCIÓN DESCARTADA",
            "La baja y la vida perdida siguen registradas. Ese rol queda libre.",
        )
        if self._pending_faint_for_reopen() is not None:
            self._schedule_pending_faint_picker(650)

    def _open_faint_replacement_picker(
        self, event: dict, dead: SavePokemon, *, pc_data: SavePCData | None = None,
    ) -> None:
        """Presenta la baja dentro de Equipo y PC; no altera su lógica funcional."""
        if pc_data is None:
            self._prime_pending_faint_pc_data()
            return
        if int(pc_data.box_count) < ORAS_GRAVEYARD_BOX:
            self._set_operation_status(
                "intervention",
                "NO EXISTE EL CEMENTERIO",
                "RoleRun necesita que la Caja 4 esté desbloqueada antes de sustituir la baja.",
                persistent=True,
            )
            return

        dead_identity = str(event.get("identity", "") or self._pokemon_identity(dead))
        active = self._faint_replacement_mode
        if active is not None and str(active.get("identity", "") or "") != dead_identity:
            return

        self._cancel_pending_faint_picker_request()
        if not bool(event.get("prompt_shown", False)) and self.project:
            self.project_service.mark_detected_faint_prompt_shown(self.project, dead_identity)
        event["prompt_shown"] = True
        self._oras_faint_picker_event_identity = dead_identity

        dead_role, dead_symbol = self._effective_role(dead)
        if dead_role not in ROLE_ORDER:
            stored_role = str(event.get("role", "SIN ROL") or "SIN ROL")
            dead_role = stored_role if stored_role in ROLE_ORDER else "SIN ROL"
            dead_symbol = self._role_symbol(dead_role)

        self._pc_cache = pc_data
        source_boxes = [
            box for box in range(1, int(pc_data.box_count) + 1)
            if box != ORAS_GRAVEYARD_BOX
        ]
        if not source_boxes:
            self._set_operation_status(
                "intervention",
                "NO HAY CAJAS DISPONIBLES",
                "El Cementerio es la única caja disponible y no puede usarse como origen.",
                persistent=True,
            )
            return
        requested_box = int(self._pc_page_box or pc_data.current_box or source_boxes[0])
        self._pc_page_box = (
            requested_box if requested_box in source_boxes
            else min(source_boxes, key=lambda value: (abs(value - requested_box), value))
        )
        self._faint_replacement_mode = {
            "identity": dead_identity,
            "event": event,
            "dead": dead,
            "pc_data": pc_data,
            "role": dead_role,
            "symbol": dead_symbol,
        }
        self._set_operation_status(
            "warning",
            "SUSTITUCIÓN DE BAJA",
            (
                f"Elige en el PC quién heredará {dead_symbol + ' ' if dead_symbol else ''}{dead_role}. "
                f"{dead.nickname or dead.species} irá al Cementerio (Caja {ORAS_GRAVEYARD_BOX})."
            ),
            actions=("Cerrar selector", "No sustituir"),
            persistent=True,
        )
        if self.active_page not in {"team", "pc"}:
            self.navigate(DEFAULT_PAGE)
        else:
            self._smooth_render_page(reset_scroll=True)

    def _prepare_faint_replacement(
        self, incoming: SavePokemon, *, libero_stats: tuple[str, ...] = (),
    ) -> bool:
        """Construye exactamente el PendingTeamChange histórico del selector."""
        mode = self._faint_replacement_mode
        if mode is None or not self.project or not self.current_game:
            return False
        event = mode["event"]
        dead_identity = str(mode.get("identity", "") or "")
        live_dead = self._pending_faint_party_member(event)
        if live_dead is None:
            self._set_operation_status(
                "intervention",
                "EL EQUIPO HA CAMBIADO",
                (
                    f"{event.get('pokemon', 'Ese Pokémon')} ya no está en el equipo vivo. "
                    "La baja continúa registrada, pero RoleRun no moverá datos sin verificar."
                ),
                persistent=True,
            )
            return False
        if incoming.box is None or incoming.box_slot is None:
            return False
        if int(incoming.box) == ORAS_GRAVEYARD_BOX:
            self._set_operation_status(
                "warning",
                "DESTINO RESERVADO",
                "La Caja 4 es el Cementerio y no puede aportar el sustituto.",
                persistent=True,
            )
            return False

        pc_data = mode.get("pc_data") or self._team_pc_cached_data()
        if pc_data is None:
            self._set_operation_status(
                "failed",
                "EL PC YA NO ESTÁ DISPONIBLE",
                "La matriz de cajas dejó de estar validada. No se preparó ningún cambio.",
                actions=("Elegir sustituto",),
                persistent=True,
            )
            return False
        graveyard_slots = [
            position for position in self._projected_open_pc_slots(pc_data)
            if int(position[0]) == ORAS_GRAVEYARD_BOX
        ]
        if not graveyard_slots:
            self._set_operation_status(
                "intervention",
                "CEMENTERIO LLENO",
                (
                    f"La Caja {ORAS_GRAVEYARD_BOX} no tiene ningún hueco libre. "
                    f"Libera uno antes de sustituir a {live_dead.nickname or live_dead.species}."
                ),
                persistent=True,
            )
            return False
        graveyard_slot = int(graveyard_slots[0][1])

        role, symbol = self._effective_role(live_dead)
        if role not in ROLE_ORDER:
            fallback_role = str(mode.get("role", "SIN ROL") or "SIN ROL")
            role = fallback_role if fallback_role in ROLE_ORDER else "SIN ROL"
            symbol = self._role_symbol(role)
        live_key = str(getattr(getattr(self, "save_engine", None), "key", ""))
        if live_key in ROLE_EV_WRITER_GAME_KEYS and role == "Líbero" and len(libero_stats) != 2:
            context = "floating" if self._floating_bar_is_visible() else "main"
            self._prompt_libero_ev_stats(
                incoming,
                lambda stats, pokemon=incoming: self._prepare_faint_replacement(
                    pokemon, libero_stats=stats,
                ),
                context=context,
            )
            return True
        incoming_snapshot = self._incoming_snapshot_for_role(incoming, role, [])
        if live_key in ROLE_EV_WRITER_GAME_KEYS:
            desired_evs = self._bdsp_role_evs(role, libero_stats)
            if desired_evs is not None:
                incoming_snapshot["evs"] = dict(zip(STAT_KEYS, desired_evs))
        outgoing_snapshot = self._pokemon_snapshot(live_dead)
        outgoing_snapshot["role"] = role
        outgoing_snapshot["role_symbol"] = symbol

        pending_before = {id(change) for change in self.run.pending_changes}
        change = PendingTeamChange(
            operation="replace-fainted",
            party_slot=int(live_dead.slot),
            box=int(incoming.box),
            box_slot=int(incoming.box_slot),
            outgoing_pokemon=live_dead.nickname or live_dead.species,
            outgoing_species=live_dead.species,
            incoming_pokemon=incoming.nickname or incoming.species,
            incoming_species=incoming.species,
            incoming_role=role,
            remove_move_slots=[],
            incoming_snapshot=incoming_snapshot,
            outgoing_snapshot=outgoing_snapshot,
            incoming_identity=self._pokemon_identity(incoming),
            outgoing_identity=dead_identity,
            box_witnesses=self._pc_role_witnesses(incoming),
            graveyard_box=ORAS_GRAVEYARD_BOX,
            graveyard_box_slot=graveyard_slot,
        )
        self.run.pending_changes.append(change)
        self._oras_live_death_replacement_ids.add(id(change))
        self._faint_replacement_mode = None
        self._oras_faint_picker_event_identity = None
        self.sync_status = (
            f"◷ Sustituyendo a {live_dead.nickname or live_dead.species} por "
            f"{incoming.nickname or incoming.species}…"
        )
        self._set_operation_status(
            "applying",
            "APLICANDO SUSTITUCIÓN",
            (
                f"{incoming.nickname or incoming.species} heredará {symbol + ' ' if symbol else ''}{role}; "
                "RoleRun espera la confirmación independiente del juego."
            ),
        )
        self._update_top_status()
        if self.active_page in {"team", "pc"}:
            self._smooth_render_page(preserve_scroll=True)
        self._request_oras_live_auto_apply_since(pending_before)
        return True

    def _publish_oras_live_snapshot(self, snapshot, difference=None) -> None:
        """Publica una captura ya validada en una sola pasada visual.

        Si el único cambio son movimientos, la barra flotante no se reconstruye:
        no muestra ataques y hacerlo era puro trabajo visual que causaba flicker.
        """
        self.current_game = snapshot.game
        self._oras_live_active = True
        process_name = str(getattr(snapshot.process, "name", "") or "").casefold() or None
        # Medido el 2026-09-03: una lectura vacía/puntual de `snapshot.process`
        # (un hipo transitorio del RPC, ya visto por separado en
        # `realtime.capture_monitor`) se leía aquí igual que un cambio real de
        # proceso, invalidaba la caché de ROM/TM y forzaba redescubrirla entera
        # (~5 s de lectura de ROM) en el siguiente sondeo -aunque el proceso
        # real nunca hubiera cambiado-, y esa pausa coincidía a veces con un
        # cambio de rol o un repintado, viéndose como un lag con la pantalla
        # rota. Ahora una lectura vacía no cuenta como cambio de proceso: se
        # ignora y se conserva el último nombre real conocido.
        if process_name is not None and process_name != self._oras_live_process_name:
            live_key = self._active_azahar_realtime_key()
            # La primera identificación del proceso no es un cambio de
            # proceso: invalidar aquí el perfil SM que acabamos de precargar
            # dejaba toda la sesión sin Personal hasta la primera escritura.
            # Los cambios posteriores sí conservan la invalidación existente.
            first_process_identification = self._oras_live_process_name is None
            if live_key == "oras":
                # Cambiar de OR a AS (o reiniciar otro proceso) invalida cualquier
                # caché de tablas aunque su ruta tenga el mismo nombre.
                self._clear_oras_rom_tm_runtime_profile()
            elif live_key == "xy":
                self._clear_xy_rom_tm_runtime_profile()
            elif live_key == "sm" and not first_process_identification:
                self._clear_sm_rom_tm_runtime_profile()
            elif live_key == "usum":
                self._clear_usum_rom_tm_runtime_profile()
            self._oras_live_process_name = process_name
        self._register_party_roles(snapshot.game)
        RoleRunManager._ensure_live_pc_matrix_loaded(self)
        for pokemon in snapshot.game.party:
            if pokemon.species_id not in self.sprite_pil_cache:
                self._load_sprite_async(pokemon)

        display_only = bool(
            difference is not None
            and (
                getattr(difference, "moves_changed", False)
                or getattr(difference, "levels_changed", False)
            )
            and not getattr(difference, "party_changed", False)
            and not getattr(difference, "order_changed", False)
            and not getattr(difference, "roles_changed", False)
        )
        # El carril de salud se actualiza en _finish_oras_live_reconciliation.
        # No lo sobrescribimos aquí: durante un combate puede estar leyendo la
        # party de batalla, cuyos PS sí son actuales aunque la party overworld no.
        # PRIORIDAD BARRA (alpha.38): mientras la barra está visible la raíz de Tk
        # permanece retirada. Reconstruir Dashboard/Equipo en ese estado puede hacer
        # que Windows vuelva a mapear la raíz y dispare _on_main_map, ocultando la
        # barra. Actualizamos únicamente OBS y, si cambió equipo/rol, la propia barra.
        # La ventana principal se marca como sucia y se pinta con el último snapshot
        # únicamente cuando el usuario vuelve a RoleRun.
        floating_visible = self._floating_bar_is_visible()
        self._sync_live_layout(refresh_floating=not display_only)
        if floating_visible:
            self._main_ui_dirty_while_floating = True
        elif display_only:
            if self.active_page in {"dashboard", "team"}:
                self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
        else:
            self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
        self._schedule_team_integrity_check()

    def _oras_live_snapshot_matches_disk(self, snapshot) -> bool | None:
        """Comprueba un posible Reset solo cuando la party viva realmente cambió.

        Leer ``main`` en cada tick sería innecesario. Esta comparación se hace
        únicamente ante una diferencia respecto a la vista actual y permite
        distinguir un Reset/state-load de una edición normal realizada jugando.

        Devuelve ``None`` cuando **no se pudo comprobar**: sin partida asociada o
        con el motor fallando al leer ``main``. Antes ese caso se confundía con
        un ``False`` demostrado, de modo que un error transitorio del motor se
        interpretaba como «el usuario editó dentro del juego» y RoleRun daba por
        buena una huella que nunca llegó a verificar. Un desconocido no es un
        dato: quien pregunte debe reintentar, no decidir.
        """
        if not self.current_save:
            return None
        try:
            saved = self.save_engine.read(self.current_save.path)
        except Exception as exc:
            # El fallo deja de ser invisible: sin este rastro, una comparación
            # que nunca llega a hacerse parece una comparación negativa.
            self._oras_live_disk_compare_error = (
                f"{datetime.now().isoformat(timespec='seconds')} · {exc}"
            )
            return None
        self._oras_live_disk_compare_error = None
        return live_party_fingerprint(saved) == live_party_fingerprint(snapshot.game)

    def _finish_oras_live_reconciliation(
        self, generation: int, project_slug: str, token: int, expected, snapshot, error: str | None,
        battle_probe=None, badge_value: int | None = None, badge_source: str | None = None,
    ) -> None:
        # Aunque una partida nueva invalide el token mientras esta lectura RPC
        # termina, liberamos el cerrojo. El resultado viejo seguirá ignorándose.
        self._oras_live_monitor_in_progress = False
        if token != self._oras_live_monitor_token:
            # R1: el token queda obsoleto cuando algo reinicia la reconciliación
            # con este worker en vuelo, típicamente el SaveFileWatcher al
            # detectar el guardado del propio juego. Quien invalidó el token ya
            # intentó reprogramar el monitor, pero se encontró el cerrojo puesto
            # y retornó sin dejar nada armado. Si soltáramos aquí el cerrojo sin
            # más, la sesión quedaría con _oras_live_active=True y sin nadie
            # leyendo hasta el siguiente guardado.
            #
            # Se rearma aquí, y no limpiando el cerrojo en
            # _clear_oras_live_reconciliation, porque esto último permitiría que
            # arrancara una captura nueva mientras esta sigue en vuelo, sobre
            # readers con estado mutable y sin lock.
            if self._oras_live_reconciliation_is_active():
                self._schedule_oras_live_reconciliation(650)
            return
        if (
            generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self.current_game
            or not self._oras_live_reconciliation_is_active()
        ):
            return

        if error or snapshot is None:
            self._oras_live_monitor_failures += 1
            if self._oras_live_monitor_failures >= 3:
                # Si Azahar se cerró, cambió de proceso o RPC dejó de responder,
                # dejamos de fingir que la conexión sigue viva y volvemos al
                # detector automático de entrada a partida de alpha.19.
                self._oras_live_active = False
                backend = {
                    "bdsp": "Ryujinx",
                    "b2w2": "melonDS",
                    "bw": "melonDS",
                    "hgss": "melonDS",
                }.get(self._active_azahar_realtime_key(), "Azahar")
                self.sync_status = (
                    f"◌ Reconectando {self._active_azahar_realtime_label()} en {backend}…"
                )
                self._update_top_status()
                self._schedule_oras_initial_auto_sync(900)
                return
            self._schedule_oras_live_reconciliation(1400)
            return

        self._oras_live_monitor_failures = 0
        if self._active_azahar_realtime_key() == "oras":
            self._sync_oras_levelup_moves_mod(snapshot.game if snapshot else None)
        if self._active_azahar_realtime_key() == "usum":
            self._sync_usum_levelup_moves_mod(snapshot.game if snapshot else None)
            self._sync_usum_levelup_moves_backup(snapshot.game if snapshot else None)
        if self._active_azahar_realtime_key() == "sm":
            self._sync_sm_levelup_moves_mod(snapshot.game if snapshot else None)
            self._sync_sm_levelup_moves_backup(snapshot.game if snapshot else None)
        if self._active_azahar_realtime_key() == "xy":
            self._sync_xy_levelup_moves_mod(snapshot.game if snapshot else None)
            self._sync_xy_levelup_moves_backup(snapshot.game if snapshot else None)
        if self._active_azahar_realtime_key() in MELONDS_GEN5_REALTIME_GAME_KEYS:
            self._sync_gen5_levelup_moves(snapshot.game if snapshot else None)
        if self._active_azahar_realtime_key() in MELONDS_GEN4_REALTIME_GAME_KEYS:
            self._sync_hgss_levelup_moves(snapshot.game if snapshot else None)

        if self._active_azahar_realtime_key() in MELONDS_REALTIME_GAME_KEYS:
            # B2/W2 publica party, PC y el carril de presentación de combate.
            # KO permanece cerrado: todavía no hay writer de sustitución seguro.
            before_game = self.current_game
            # alpha.51: sin esto la medalla se leía de la RAM y se tiraba. Va
            # antes de cualquier return por herencia de rol o cambio de equipo,
            # igual que en BDSP: una transición de party no puede retrasarla.
            # El valor es absoluto 0..8 y su procedencia RAM autoriza también
            # una carga de estado anterior, que en melonDS es de un clic.
            if badge_value is not None:
                badge_changed = self._process_oras_badge_value(
                    badge_value, source=badge_source,
                )
                if (
                    0 <= int(badge_value) <= 8
                    and (
                        badge_changed
                        or int(badge_value) == int(
                            self.project.counters.get("medallas", 0)
                        )
                    )
                ):
                    self._oras_badge_live_value = int(badge_value)
                    self._oras_badge_live_source = str(
                        badge_source or "desconocida"
                    )
            probe_state = getattr(battle_probe, "state", "unknown")
            probe_health = getattr(battle_probe, "health_game", None)
            if probe_state == "battle" and probe_health is not None:
                # Combate confirmado: manda la copia de presentación, que es la
                # que no adelanta el daño a la animación. Validada en alpha.5.
                self._oras_battle_probe_last_state = "battle"
                published_health = probe_health
                # La copia de presentación ya converge con la animación, así que
                # el KO se registra en cuanto la barra visible llega a cero, sin
                # el retraso extra que ORAS necesita.
                health_source = "battle-visible"
            elif probe_state == "none":
                self._oras_battle_probe_last_state = "none"
                published_health = snapshot.game
                health_source = "overworld"
            elif (
                self._active_azahar_realtime_key() in MELONDS_GEN4_REALTIME_GAME_KEYS
                and self._oras_battle_probe_last_state == "battle"
            ):
                # HeartGold/SoulSilver -a diferencia de ORAS/B2W2, que sí
                # tienen una tabla con una fila por miembro- no trae PS en
                # vivo de NADIE en `snapshot.game` salvo en un sondeo
                # "battle" confirmado: ni siquiera del propio combatiente
                # activo, que fuera de ese instante conserva el valor de
                # antes de entrar en combate (`_capture` en
                # `hgss_adapter.py` solo mete el PS medido cuando
                # `lectura_batalla.state == "battle"`). Caer aquí al de
                # reserva -aunque sea un solo sondeo- publica un salto a PS
                # completo que se corrige él solo en el siguiente sondeo:
                # el parpadeo "se llena y luego se corrige" que el usuario
                # grabó en vídeo el 07-09-2026, con Totodile en pleno
                # combate (un `(0, 0)` suelto en la dirección ya
                # confirmada, ver `HgssMelonDSReader.read_battle_probe`).
                # No se publica nada nuevo: se conserva la última
                # publicación en vivo hasta que el sondeo vuelva a
                # confirmar "battle" o de verdad confirme "sin combate".
                #
                # EXCEPTO cuando lo nuevo es un desmayo real: comprobado
                # con el usuario el mismo día -un Rattata rematado en dos
                # golpes apareció a 0/14 en el bloque de equipo mientras la
                # pantalla seguía pidiendo sustituto, ANTES de que el
                # combate terminara-. El bloque de equipo SÍ se escribe al
                # instante en cuanto alguien se desmaya, aunque no se
                # actualice para nada más durante el combate. Suprimir
                # TODA publicación durante el margen tapaba también esa
                # transición real, dejando el desmayo sin detectar hasta
                # que el combate terminaba del todo. Se deja pasar
                # específicamente cuando el bloque de equipo acaba de bajar
                # a 0 al combatiente que se venía siguiendo -eso nunca es
                # el salto a PS completo que hay que evitar, siempre es una
                # muerte real recién escrita-.
                published_health = None
                health_source = "battle-visible"
                ultimo_snapshot = getattr(self, "_oras_live_health_snapshot", None)
                ultimo_vivo = next(
                    (
                        member for member in getattr(ultimo_snapshot, "party", []) or []
                        if getattr(member, "hp_is_live", False)
                    ),
                    None,
                )
                if (
                    ultimo_vivo is not None
                    and int(getattr(ultimo_vivo, "current_hp", 0) or 0) > 0
                ):
                    identidad_seguida = self._pokemon_identity(ultimo_vivo)
                    desmayo_real = next(
                        (
                            member for member in snapshot.game.party
                            if self._pokemon_identity(member) == identidad_seguida
                            and int(getattr(member, "current_hp", 0) or 0) <= 0
                        ),
                        None,
                    )
                    if desmayo_real is not None:
                        published_health = snapshot.game
                        health_source = "overworld"
            else:
                # La lane de presentación no se pudo validar: cambio de Pokémon
                # con las dos copias describiendo miembros distintos, animación a
                # medias, o un estado runtime todavía no demostrado.
                #
                # Esa lane gobierna **solo** los PS del Pokémon activo; los otros
                # cinco ya se publican desde el bloque de party incluso en un
                # combate confirmado, y ahí no hay nada que destripar. Congelar a
                # los seis por un fallo que afecta a uno dejaba un debilitado
                # pintado al máximo de vida durante todo el combate, que es peor
                # que adelantar unos segundos el daño de uno.
                #
                # No se toca ``_oras_battle_probe_last_state``: seguimos sin
                # saber si esto es un combate.
                published_health = snapshot.game
                health_source = "overworld"
            # ``diff_live_party`` ignora los PS a propósito: su trabajo es la
            # composición del equipo. B2/W2 era el único backend que no llamaba
            # después a la publicación de salud, así que un cambio de PS no
            # llegaba nunca ni a ``current_game`` ni a la vista principal.
            if published_health is not None:
                # alpha.28: B2/W2 entra en el camino común de salud, que además
                # de publicar detecta las bajas. Su writer de sustitución ya
                # existe, así que abrirlo ya no deja al usuario a medio flujo.
                self._process_oras_health_snapshot(published_health, source=health_source)
            # alpha.29: sin estas dos llamadas la baja quedaba en un limbo del que
            # no se podía salir. El selector de sustituto exige ``battle_ended``, y
            # la limpieza de una baja obsoleta exige ``battle_ended`` o
            # ``prompt_shown``; B2/W2 no marcaba ninguno de los dos, así que el
            # debilitado desaparecía de la vista para siempre: ni sustituible, ni
            # recuperable curándolo, ni al reiniciar.
            self._process_oras_battle_state(
                "trainer" if probe_state == "battle"
                else "none" if probe_state == "none"
                else None
            )
            # Y si el usuario resuelve la baja desde el PC del propio juego,
            # RoleRun debe enterarse en lugar de seguir esperando.
            self._reconcile_pending_faints_against_party(snapshot.game)
            difference = diff_live_party(before_game, snapshot.game)
            # Publicar solo ante cambios de composición dejaba la ficha sin
            # estadísticas, IV, EV ni naturaleza en cuanto algo reponía la vista
            # desde el guardado, porque ese diff ignora precisamente esos datos.
            faltan_metadatos = self._live_metadata_is_missing(before_game, snapshot.game)
            if difference.changed or faltan_metadatos:
                self._publish_oras_live_snapshot(snapshot, difference=difference)
            if difference.changed:
                self.sync_status = (
                    f"✓ Negro 2/Blanco 2 → RoleRun · {difference.label()} "
                    "· solo lectura"
                )
                self._update_top_status()
            elif not faltan_metadatos:
                # Antes se forzaba aquí una reconstrucción completa de la barra
                # flotante en CADA ciclo del monitor, es decir una vez por
                # segundo, aunque no hubiera cambiado absolutamente nada. Ese era
                # el parpadeo. La barra la refresca ahora quien tiene algo nuevo
                # que contar, y su propio sondeo de 500 ms recoge el resto.
                self._sync_live_layout(refresh_floating=False)
            # 07-09-2026: al ritmo lento (950 ms) tras un solo "unknown", un
            # parpadeo real de HeartGold que dura más de un sondeo tenía
            # margen de sobra para que la SEGUNDA comprobación de
            # `read_battle_probe` -la que decide si el combate terminó de
            # verdad, ver `COMBATE_SEGUNDOS_DE_CERO_PARA_CONFIRMAR_FIN`- caiga
            # TAMBIÉN dentro de la ventana mala, confirmando un final que
            # no era real. Se sigue al ritmo rápido mientras se siga
            # considerando que hay combate (`_oras_battle_probe_last_state`,
            # que un "unknown" no toca), no solo cuando ESTE sondeo lo
            # confirma -así la segunda comprobación llega antes-.
            self._schedule_oras_live_reconciliation(
                250 if self._oras_battle_probe_last_state == "battle" else 950
            )
            return

        if self._active_azahar_realtime_key() == "bdsp":
            # BDSP reproduce el contrato de salud de Gen7 sin compartir ningún
            # offset: PlayerWork es la party estable y BTL_PARTY la autoridad de
            # HP durante combate. Una muestra de batalla inválida nunca se
            # sustituye por los HP stale de PlayerWork.
            before_game = self.current_game
            # Alpha.77: se procesa antes de cualquier return por herencia de rol
            # o cambio de party. El valor es absoluto 0..8 y su procedencia RAM
            # autoriza también una carga de estado anterior sin mezclar el save.
            if badge_value is not None:
                badge_changed = self._process_oras_badge_value(
                    badge_value, source=badge_source,
                )
                if (
                    0 <= int(badge_value) <= 8
                    and (
                        badge_changed
                        or int(badge_value) == int(
                            self.project.counters.get("medallas", 0)
                        )
                    )
                ):
                    self._oras_badge_live_value = int(badge_value)
                    self._oras_badge_live_source = str(
                        badge_source or "desconocida"
                    )
            # Aprendizajes por rol (2026-09-03): Enfoque A (parche proactivo
            # de la tabla en vivo, ver ``_sync_bdsp_levelup_table_patch``)
            # primero, para que el diálogo del juego ya muestre el
            # movimiento correcto; Enfoque B (``_sync_bdsp_levelup_moves``,
            # sustitución posterior) se queda como red de seguridad. Después
            # de las medallas (alpha.77 exige que se comprometan antes que
            # cualquier otra cosa de este sondeo) y antes de publicar la
            # party, para que un cambio de hueco recién escrito llegue ya
            # reflejado.
            self._sync_bdsp_levelup_table_patch(snapshot.game if snapshot else None)
            self._sync_bdsp_levelup_moves(snapshot.game if snapshot else None)
            probe_state = (
                getattr(battle_probe, "state", None)
                if battle_probe is not None else None
            )
            probe_health = (
                getattr(battle_probe, "health_game", None)
                if battle_probe is not None else None
            )
            previous_probe_state = self._oras_battle_probe_last_state
            if probe_state == "battle":
                self._oras_battle_probe_last_state = "battle"
                if probe_health is not None:
                    if previous_probe_state == "unknown":
                        self._oras_live_health_snapshot = probe_health
                    else:
                        self._process_oras_health_snapshot(
                            probe_health, source="battle-visible",
                        )
                self._process_oras_battle_state("trainer")
            elif probe_state == "none":
                self._oras_battle_probe_last_state = "none"
                self._process_oras_health_snapshot(snapshot.game, source="overworld")
                self._process_oras_battle_state("none")
            else:
                if previous_probe_state != "battle":
                    self._process_oras_health_snapshot(snapshot.game, source="overworld")
                self._process_oras_battle_state(None)

            # PlayerWork aporta identidad/party; durante combate BTL_PARTY aporta
            # los PS visibles. Publicamos una sola fotografía coherente para que
            # _publish_oras_live_snapshot no restaure después el HP stale.
            RoleRunManager._merge_live_health_fields(
                snapshot.game, self._oras_live_health_snapshot,
            )

            self._reconcile_pending_faints_against_party(snapshot.game)
            difference = diff_live_party(before_game, snapshot.game)
            if difference.changed:
                # Alpha.76: una sustitución hecha dentro del PC de BDSP puede
                # introducir temporalmente el marcador que el Pokémon tenía en
                # caja. Publicar esa captura antes de heredar el rol saliente
                # convierte el conflicto en una séptima tarjeta visual, aunque el
                # reader haya demostrado exactamente seis miembros. Igual que el
                # flujo ORAS/X-Y, escribimos y verificamos primero el marcador del
                # entrante; hasta entonces conservamos la última party confirmada.
                role_changes = self._incoming_oras_role_changes(before_game, snapshot.game)
                if role_changes:
                    generated_ids = {id(change) for change in role_changes}
                    self._oras_live_system_role_assignment_ids.update(generated_ids)
                    started = self._save_oras_live_changes(
                        role_changes, automatic=True, base_game=snapshot.game,
                    )
                    if getattr(difference, "party_changed", False):
                        # El reconciliador PC usa before/after como anclas y su
                        # barrera de solapamiento repetirá la lectura si termina
                        # antes que el readback del marcador.
                        self._schedule_oras_external_pc_reconcile(
                            before_game, snapshot.game,
                        )
                    if started:
                        self.sync_status = (
                            "◷ Perla Reluciente · heredando el rol antes de publicar el equipo…"
                        )
                        self._update_top_status()
                        return
                    self._oras_live_system_role_assignment_ids.difference_update(generated_ids)
                    self.sync_status = (
                        "◌ Perla Reluciente · esperando una captura estable para heredar el rol…"
                    )
                    self._update_top_status()
                    self._schedule_oras_live_reconciliation(250)
                    return
                self._publish_oras_live_snapshot(snapshot, difference=difference)
                self.sync_status = f"✓ Perla Reluciente → RoleRun · {difference.label()}"
                self._update_top_status()
                # La lectura completa de cajas necesita ambos lados de la
                # transición. En particular, un Pokémon recién depositado todavía
                # no existe en el ``main`` guardado: el objeto saliente de la party
                # es la única ancla demostrada que conserva su nivel. Programamos
                # después de publicar la nueva party para que la barrera PC↔Equipo
                # la contraste con el estado visible actual, pero pasamos las dos
                # capturas originales al worker.
                if (
                    getattr(difference, "party_changed", False)
                    and self._active_azahar_realtime_key() in LIVE_PC_READ_GAME_KEYS
                ):
                    self._schedule_oras_external_pc_reconcile(
                        before_game, snapshot.game,
                    )
            self._schedule_oras_live_reconciliation(
                250 if probe_state == "battle" else 750
            )
            return

        if self._active_azahar_realtime_key() == "sm":
            before_game = self.current_game
        elif self._active_azahar_realtime_key() == "usum":
            before_game = self.current_game
        else:
            before_game = None

        if before_game is not None:

            # Alpha.42: el progreso de Kahunas es un valor absoluto 0..4. Se
            # procesa antes de cualquier return por herencia de rol/PC para que
            # una transición de equipo no pueda retrasar la medalla. Igual que
            # ORAS/X/Y, una carga de estado anterior puede reducir el contador.
            badge_changed = self._process_oras_badge_value(
                badge_value, source=badge_source,
            )
            if (
                badge_value is not None and 0 <= int(badge_value) <= 4
                and (
                    badge_changed
                    or int(badge_value) == int(self.project.counters.get("medallas", 0))
                )
            ):
                self._oras_badge_live_value = int(badge_value)
                self._oras_badge_live_source = str(badge_source or "desconocida")

            # Alpha.41: Sol/Luna tiene ya un carril INDEPENDIENTE de HP de batalla.
            # El flag 0x30000158 y los HP player 0x30002776/78 + 0x30009760
            # proceden de código público específico de SM; el reader solo publica
            # health_game si el Max HP coincide además con nuestra party PK7 live.
            #
            # Usamos DISPLAYED HP: la baja se registra cuando el propio juego ha
            # llevado visualmente la barra a 0. Por eso esta fuente NO necesita el
            # retraso artificial de 1 s que ORAS aplica a su ``source=battle``. La
            # ventana de sustitución, en cambio, sigue cerrada hasta ver fin de
            # combate en dos muestras, exactamente igual que antes.
            probe_state = getattr(battle_probe, "state", None) if battle_probe is not None else None
            probe_health = getattr(battle_probe, "health_game", None) if battle_probe is not None else None
            previous_probe_state = self._oras_battle_probe_last_state

            if probe_state == "battle":
                self._oras_battle_probe_last_state = "battle"
                if probe_health is not None:
                    if previous_probe_state == "unknown":
                        # Conectar RoleRun YA dentro de un combate solo establece
                        # una línea base: no se cobra una muerte que pudo ocurrir
                        # antes de abrir/conectar el programa. Si RoleRun vio antes
                        # ``none``, sí compara y detecta el primer KO normalmente.
                        self._oras_live_health_snapshot = probe_health
                    else:
                        self._process_oras_health_snapshot(probe_health, source="battle-visible")
                self._process_oras_battle_state("trainer")  # token común = dentro de combate
            elif probe_state == "none":
                self._oras_battle_probe_last_state = "none"
                self._process_oras_health_snapshot(snapshot.game, source="overworld")
                self._process_oras_battle_state("none")
            else:
                # Una lectura opcional fallida no puede convertir HP overworld
                # obsoletos en HP de batalla. Solo usamos el fallback normal si no
                # consta que sigamos dentro de un combate.
                if previous_probe_state != "battle":
                    self._process_oras_health_snapshot(snapshot.game, source="overworld")
                self._process_oras_battle_state(None)

            self._reconcile_pending_faints_against_party(snapshot.game)

            difference = diff_live_party(before_game, snapshot.game)

            # Alpha.28: la captura validada del juego es SIEMPRE la verdad visible.
            # Alpha.29 conserva esa propiedad, pero una sustitución no intenta
            # escribir su marcador mientras el PC todavía está cambiando de buffer.
            if difference.changed:
                self._publish_oras_live_snapshot(snapshot, difference=difference)

            current_transition_key = self._sm_role_transition_key(snapshot.game)
            pending_transition = getattr(self, "_sm_pending_role_transition", None)
            if pending_transition is not None and pending_transition[0] == current_transition_key:
                # No degradamos una sustitución directa a "primer rol libre" en
                # ticks posteriores. La decisión original (rol del saliente) queda
                # retenida hasta que PC↔party vuelva a estar demostrado.
                role_changes = list(pending_transition[1])
            else:
                if pending_transition is not None:
                    self._sm_pending_role_transition = None
                role_changes = self._incoming_oras_role_changes(before_game, snapshot.game)
                if role_changes:
                    self._queue_sm_role_transition(snapshot.game, role_changes)

            party_changed = bool(getattr(difference, "party_changed", False))
            if party_changed and self._active_azahar_realtime_key() in LIVE_PC_READ_GAME_KEYS:
                self._schedule_oras_external_pc_reconcile(before_game, snapshot.game)
            elif role_changes:
                # También para un SIN ROL ya presente al conectar: antes de tocar
                # el marcador exigimos una prueba PC fresca que desambigüe las
                # copias host de Azahar. Con caché validada esta lectura es corta.
                self._schedule_oras_external_pc_reconcile(
                    snapshot.game, snapshot.game, force=True,
                )

            if role_changes:
                self.sync_status = (
                    f"◷ {self._active_azahar_realtime_label()} · validando Equipo↔PC para heredar el rol…"
                    if party_changed else
                    f"◷ {self._active_azahar_realtime_label()} · validando Equipo↔PC para asignar el rol libre…"
                )
                self._update_top_status()
                self._schedule_oras_live_reconciliation(250 if probe_state == "battle" else 950)
                return

            if difference.changed:
                self.sync_status = f"✓ {self._active_azahar_realtime_label()} → RoleRun · {difference.label()}"
                self._update_top_status()
            self._schedule_oras_live_reconciliation(250 if probe_state == "battle" else 950)
            return

        # Alpha.33: la salud de batalla jamás condiciona la captura principal.
        # Si la sonda ve combate y trae HP válidos, usamos esos PS. Si ve combate
        # pero no pudo validar HP, NO sustituimos con la party overworld obsoleta.
        # Al volver a ``none`` procesamos la party normal, que constituye además
        # el fallback definitivo de muerte al terminar el combate.
        probe_state = getattr(battle_probe, "state", None) if battle_probe is not None else None
        probe_health = getattr(battle_probe, "health_game", None) if battle_probe is not None else None
        if probe_state in {"wild", "trainer"}:
            self._oras_battle_probe_last_state = probe_state
            if probe_health is not None:
                self._process_oras_health_snapshot(probe_health, source="battle")
        elif probe_state == "none":
            self._oras_battle_probe_last_state = "none"
            self._process_oras_health_snapshot(snapshot.game, source="overworld")
        elif self._oras_battle_probe_last_state not in {"wild", "trainer"}:
            # La sonda no respondió y no consta que sigamos en combate: el monitor
            # normal continúa haciendo de fallback, sin bloquearse por ello.
            self._process_oras_health_snapshot(snapshot.game, source="overworld")

        self._process_oras_battle_state(probe_state)
        self._reconcile_pending_faints_against_party(snapshot.game)
        badge_changed = self._process_oras_badge_value(
            badge_value, source=badge_source,
        )
        if (
            badge_value is not None and 0 <= int(badge_value) <= 8
            and (
                badge_changed
                or int(badge_value) == int(self.project.counters.get("medallas", 0))
            )
        ):
            self._oras_badge_live_value = int(badge_value)
            self._oras_badge_live_source = str(badge_source or "desconocida")
        if self.run.pending_changes:
            self._schedule_oras_live_reconciliation(500)
            return
        if expected != self._oras_live_expected_fingerprint:
            self._schedule_oras_live_reconciliation(600)
            return

        actual = live_party_fingerprint(snapshot.game)
        visible = live_party_fingerprint(self.current_game)
        difference = diff_live_party(self.current_game, snapshot.game)
        training_presentation_changed = bool(
            self._active_azahar_realtime_key() == "bdsp"
            and self._party_training_presentation_changed(
                self.current_game, snapshot.game,
            )
        )
        memory_changed = bool(
            self._oras_live_changes_unpersisted
            and not self._oras_live_memory_watches_match(snapshot)
        )

        if difference.changed:
            if (
                getattr(difference, "party_changed", False)
                and self._active_azahar_realtime_key() in LIVE_PC_READ_GAME_KEYS
            ):
                self._schedule_oras_external_pc_reconcile(self.current_game, snapshot.game)
            expected_now = self._oras_live_expected_fingerprint
            looks_like_reload = bool(
                self._oras_live_changes_unpersisted
                and expected_now is not None
                and actual != expected_now
                # ``is True`` explícito: si no se pudo leer ``main`` la respuesta
                # es ``None`` y no se declara un Reset con una comprobación que
                # nunca llegó a hacerse. Se reintenta en el siguiente ciclo.
                and self._oras_live_snapshot_matches_disk(snapshot) is True
            )

            if looks_like_reload or memory_changed:
                # Reset/state-load: volvemos a la RAM real y la revisión de
                # acciones anteriores deja de ser una base segura para DESHACER.
                self._reconcile_oras_live_memory_watches(snapshot)
                self._clear_oras_live_reconciliation()
                self._publish_oras_live_snapshot(snapshot)
                self.sync_status = (
                    f"↺ {self._active_azahar_realtime_label()} recargado · {len(snapshot.game.party)} Pokémon · "
                    "RoleRun recuperó el estado real"
                )
                self._update_top_status()
                self._show_live_sync_toast(
                    f"ESTADO DE {self._active_azahar_realtime_label()} RECUPERADO",
                    "Azahar volvió a un estado guardado/anterior. RoleRun ha actualizado el equipo real; no se escribió ningún byte.",
                    True,
                )
                # _clear... detiene el timer; la conexión sigue viva, así que
                # rearmamos inmediatamente el monitor permanente.
                self._oras_live_active = True
                self._schedule_oras_live_reconciliation(850)
                return

            # Si el cambio hecho en el propio juego mete un Pokémon nuevo al
            # equipo, normalizamos primero su rol EN AZAHAR y publicamos después.
            # De este modo nunca existe un frame intermedio con una séptima tarjeta
            # SIN ROL: sustitución directa = rol del saliente; alta nueva = primer
            # rol libre de izquierda a derecha.
            role_changes = self._incoming_oras_role_changes(self.current_game, snapshot.game)
            if role_changes:
                generated_ids = {id(change) for change in role_changes}
                self._oras_live_system_role_assignment_ids.update(generated_ids)
                if self._save_oras_live_changes(
                    role_changes, automatic=True, base_game=snapshot.game,
                ):
                    self.sync_status = "◷ Juego → RoleRun · asignando rol al Pokémon entrante…"
                    self._update_top_status()
                    return
                self._oras_live_system_role_assignment_ids.difference_update(generated_ids)

            # Cambio normal hecho dentro del propio juego: el nuevo snapshot pasa
            # a ser la fuente de verdad visual. Si había cambios de RoleRun aún
            # sin guardar, ampliamos la huella esperada en vez de confundir esta
            # acción con un Reset. Los escritores verifican de nuevo identidad,
            # movimiento anterior y rol antes de cualquier DESHACER posterior.
            if self._oras_live_changes_unpersisted:
                self._oras_live_expected_fingerprint = actual
            self._publish_oras_live_snapshot(snapshot, difference=difference)
            self.sync_status = f"✓ Juego → RoleRun · {difference.label()}"
            self._update_top_status()
            self._schedule_oras_live_reconciliation(850)
            return

        # La identidad, los roles y los movimientos pueden coincidir aunque la
        # Run se hubiera abierto inicialmente desde un save sin presentación
        # viva. Publicamos este snapshot solo en BDSP y solo cuando aporta una
        # naturaleza/stat/IV/EV/base stat distinta. No se interpreta como cambio
        # de equipo ni se ejecuta ninguna escritura.
        if training_presentation_changed:
            self._publish_oras_live_snapshot(snapshot)
            self.sync_status = (
                "✓ Perla Reluciente en vivo · datos de entrenamiento actualizados"
            )
            self._update_top_status()
            self._schedule_oras_live_reconciliation(850)
            return

        # Red de seguridad: incluso si RoleRun ya abrió la Run con ese mismo
        # Pokémon SIN ROL (por lo que la huella no cambió), lo normalizamos en
        # cuanto Azahar está estable. Así nunca dependemos de que el miembro sea
        # "nuevo" para ocupar una de las seis casillas de rol.
        role_changes = self._incoming_oras_role_changes(self.current_game, snapshot.game)
        if role_changes:
            generated_ids = {id(change) for change in role_changes}
            self._oras_live_system_role_assignment_ids.update(generated_ids)
            if self._save_oras_live_changes(
                role_changes, automatic=True, base_game=snapshot.game,
            ):
                self.sync_status = "◷ Juego → RoleRun · asignando rol libre…"
                self._update_top_status()
                return
            self._oras_live_system_role_assignment_ids.difference_update(generated_ids)

        if memory_changed:
            # Una casilla auxiliar escrita por RoleRun cambió aunque la party sea
            # idéntica. Conservamos el comportamiento defensivo de alpha.19.
            self._reconcile_oras_live_memory_watches(snapshot)
            self._clear_oras_live_reconciliation()
            self._publish_oras_live_snapshot(snapshot)
            self.sync_status = f"↺ {self._active_azahar_realtime_label()} recargado · memoria auxiliar reconciliada"
            self._update_top_status()
            self._oras_live_active = True
            self._schedule_oras_live_reconciliation(850)
            return

        # No hubo ningún campo gestionado por RoleRun distinto. EXP, PS, amistad
        # y demás datos volátiles no provocan ningún redibujado; el nivel sí se
        # publica directamente desde la RAM viva cuando cambia. Alpha.40 deja
        # visible además la fuente de medallas: si algo falla en un PC real ya no
        # tenemos que deducir a ciegas qué lector devolvió el valor.
        badge_fragment = self._oras_badge_status_fragment()
        if badge_fragment:
            diagnostic_status = (
                f"✓ {self._active_azahar_realtime_label()} en vivo · {len(snapshot.game.party)} Pokémon · "
                f"{snapshot.process.name} · lectura {snapshot.attempts}{badge_fragment}"
            )
            if self.sync_status != diagnostic_status:
                self.sync_status = diagnostic_status
                self._update_top_status()
        self._schedule_oras_live_reconciliation(450 if probe_state in {"wild", "trainer"} else 950)

    def _oras_badge_status_fragment(self) -> str:
        """Resumen compacto de la fuente de medallas para diagnóstico en vivo."""
        value = self._oras_badge_live_value
        source = str(self._oras_badge_live_source or "")
        if value is None:
            return ""
        if source.startswith("Premios líderes"):
            label = "Premios"
        elif source.startswith("SUBE vivo"):
            label = "SUBE"
        elif source.startswith("EventWork vivo"):
            label = "EventWork"
        elif source.startswith("Misc vivo X/Y"):
            label = "MiscXY"
        elif source.startswith("Misc vivo"):
            label = "Misc"
        elif source.startswith("main X/Y"):
            label = "mainXY"
        elif source.startswith("main"):
            label = "main"
        else:
            label = "?"
        return f" · medallas {label}:{int(value)}"

    def sync_oras_live(self) -> None:
        """Resincronización manual del adaptador Azahar activo, sin tocar el save."""
        if self._live_write_in_progress:
            self._show_live_sync_toast(
                "CAMBIOS EN CURSO",
                "Espera a que Azahar confirme la escritura actual.",
                False,
            )
            return
        if self._oras_live_monitor_in_progress:
            self._show_live_sync_toast(
                "COMPROBACIÓN EN CURSO",
                "RoleRun está verificando que el emulador no haya recargado un estado. Espera un instante.",
                False,
            )
            return
        if self._live_sync_in_progress:
            self._show_live_sync_toast("SINCRONIZACIÓN EN CURSO", "Espera a que termine la doble lectura.", False)
            return
        if self._oras_auto_sync_in_progress:
            self._show_live_sync_toast(
                "SINCRONIZACIÓN AUTOMÁTICA EN CURSO",
                f"RoleRun ya está detectando la partida de {self._active_azahar_realtime_label()} en el emulador compatible.",
                False,
            )
            return
        if not self.project or not self.current_game or not self.current_save:
            return
        if getattr(self.save_engine, "key", "") not in REALTIME_READ_GAME_KEYS:
            self._show_live_sync_toast(
                "F5 · SIN ENLACE EN VIVO",
                "El tiempo real está disponible para los juegos con un backend validado y activo.",
                False,
            )
            return
        if self.run.pending_changes:
            pending = list(self.run.pending_changes)
            unsupported = self._oras_live_unsupported_changes(pending)
            if self._oras_live_auto_apply_available() and not unsupported:
                # F5 es solo una relectura del juego: no tiene sentido pedir al
                # usuario que "guarde" una acción que ya pertenece al flujo de
                # escritura inmediata. Si todavía queda en la cola, solicitamos
                # su confirmación normal en RAM y dejamos F5 para después.
                self._request_oras_live_auto_apply(pending)
                self.sync_status = "◷ F5 esperando confirmación del cambio en RAM"
                self._update_top_status()
                self._show_live_sync_toast(
                    "CAMBIO EN RAM AÚN POR CONFIRMAR",
                    "F5 no guarda cambios. RoleRun está terminando de aplicar y verificar la acción inmediata; "
                    "cuando desaparezca este estado, F5 volverá a ser solo una resincronización.",
                    False,
                )
            else:
                detail = (
                    "La cola contiene una operación que X/Y todavía no puede escribir en tiempo real: "
                    + ", ".join(unsupported) + ". "
                    if unsupported else
                    "Hay una operación no confirmada en la cola. "
                )
                self.sync_status = "⚠ F5 pausado: operación no confirmada"
                self._update_top_status()
                self._show_live_sync_toast(
                    "F5 NO GUARDA CAMBIOS",
                    detail + "Revísala o descártala; F5 no la escribirá en el archivo ni en el juego.",
                    False,
                )
            return

        # F5 sigue disponible como resincronización manual. Si había un intento
        # automático programado, esta acción explícita toma el control.
        self._cancel_oras_initial_auto_sync()
        generation = self._session_generation
        project_slug = self.project.slug
        current = self.current_game
        # F5 invalida además las tablas de ROM específicas de ORAS. X/Y alpha.3
        # todavía no usa una tabla de MT runtime propia.
        if self._active_azahar_realtime_key() == "oras":
            self._clear_oras_rom_tm_runtime_profile()
            self._prepare_oras_live_metadata_profile()
        elif self._active_azahar_realtime_key() == "sm":
            self._clear_sm_rom_tm_runtime_profile()
        elif self._active_azahar_realtime_key() == "usum":
            self._clear_usum_rom_tm_runtime_profile()
        memory_requests = self._oras_live_memory_requests()
        self._live_sync_in_progress = True
        self.sync_status = f"◷ Leyendo {self._active_azahar_realtime_label()} en vivo…"
        self._update_top_status()

        def worker() -> None:
            try:
                snapshot = self.realtime_core.capture_full(
                    current, save_path=self.current_save.path, memory_requests=memory_requests,
                )
                error = None
            except Exception as exc:
                snapshot = None
                error = str(exc)
            self.after(0, lambda: self._finish_oras_live_sync(
                generation, project_slug, snapshot, error
            ))

        threading.Thread(target=worker, daemon=True, name="RoleRunAzaharRPC").start()

    def _finish_oras_live_sync(
        self, generation: int, project_slug: str, snapshot, error: str | None,
        automatic: bool = False,
    ) -> None:
        self._live_sync_in_progress = False
        if (
            generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self.current_game
        ):
            return
        if error or snapshot is None:
            self._oras_live_active = False
            self.sync_status = f"⚠ Tiempo real: {error or 'lectura fallida'}"
            self._update_top_status()
            self._show_live_sync_toast(f"NO SE PUDO LEER {self._active_azahar_realtime_label()}", error or "Lectura fallida.", False)
            # Tras un F5 fallido, el enlace automático vuelve a quedar armado.
            self._schedule_oras_initial_auto_sync(1200)
            return

        self._cancel_oras_initial_auto_sync()
        self._oras_live_monitor_failures = 0

        if self._active_azahar_realtime_key() in MELONDS_REALTIME_GAME_KEYS:
            discarded_ghosts = self._discard_b2w2_ghost_team_changes()
            initial_battle = getattr(snapshot, "battle", None)
            initial_state = str(getattr(initial_battle, "state", "unknown") or "unknown")
            initial_health = getattr(initial_battle, "health_game", None)
            self._oras_battle_probe_last_state = initial_state
            self._oras_live_health_snapshot = (
                initial_health if initial_state == "battle" and initial_health is not None
                else snapshot.game
            )
            self._publish_oras_live_snapshot(snapshot)
            pc_refresh = getattr(self, "_schedule_gen6_live_pc_refresh", None)
            if callable(pc_refresh):
                pc_refresh()
            self.sync_status = (
                f"✓ Negro 2/Blanco 2 en vivo · {len(snapshot.game.party)} "
                "Pokémon · melonDS · solo lectura"
            )
            self._update_top_status()
            self._schedule_oras_live_reconciliation(
                250 if initial_state == "battle" else 950
            )
            self._show_live_sync_toast(
                "NEGRO 2/BLANCO 2 CONECTADO",
                (
                    "Equipo y PS leídos desde melonDS en modo seguro de solo lectura."
                    + (
                        f" Se retiraron {discarded_ghosts} cambios Equipo↔PC que "
                        "la versión anterior había proyectado sin escribir."
                        if discarded_ghosts else ""
                    )
                ),
                True,
            )
            return

        if self._active_azahar_realtime_key() == "bdsp":
            # capture_full incluye BattleProc para que abrir RoleRun dentro de un
            # combate solo establezca baseline y nunca cobre un KO retrospectivo.
            initial_battle = getattr(snapshot, "battle", None)
            initial_battle_state = str(
                getattr(initial_battle, "state", "unknown") or "unknown"
            )
            initial_battle_health = getattr(initial_battle, "health_game", None)
            if initial_battle_state == "none":
                self._oras_battle_probe_last_state = "none"
                self._oras_live_health_snapshot = snapshot.game
            elif initial_battle_state == "battle":
                self._oras_battle_probe_last_state = "battle"
                self._oras_live_health_snapshot = initial_battle_health
            else:
                self._oras_battle_probe_last_state = "unknown"
                self._oras_live_health_snapshot = snapshot.game

            self._reconcile_pending_faints_against_party(snapshot.game)
            migration_ids = set(getattr(self, "_bdsp_marker_migration_change_ids", set()))
            marker_migration = [
                change for change in getattr(getattr(self, "run", None), "pending_changes", ())
                if id(change) in migration_ids
            ]
            if marker_migration:
                current_ids = {id(change) for change in marker_migration}
                self._oras_live_role_marker_migration_ids.update(current_ids)
                self._oras_live_system_role_assignment_ids.update(current_ids)
                # Declaramos primero la party leída. El writer vuelve a capturarla
                # y exige que siga igual antes de tocar RAM.
                self._publish_oras_live_snapshot(snapshot)
                if self._save_oras_live_changes(
                    marker_migration, automatic=True, base_game=snapshot.game,
                ):
                    self.sync_status = "◷ Perla Reluciente detectada · migrando marcadores en Ryujinx…"
                    self._update_top_status()
                    return
                self._oras_live_role_marker_migration_ids.difference_update(current_ids)
                self._oras_live_system_role_assignment_ids.difference_update(current_ids)

            # La conexión inicial puede ocurrir después de que el usuario haya
            # hecho ya el intercambio en el PC. Es la misma transición semántica
            # que observa el monitor: no publicamos el marcador antiguo del
            # entrante y, por tanto, tampoco un conflicto como séptima tarjeta.
            initial_role_changes = self._incoming_oras_role_changes(
                self.current_game, snapshot.game,
            )
            if initial_role_changes:
                current_ids = {id(change) for change in initial_role_changes}
                self._oras_live_system_role_assignment_ids.update(current_ids)
                initial_difference = diff_live_party(self.current_game, snapshot.game)
                started = self._save_oras_live_changes(
                    initial_role_changes, automatic=True, base_game=snapshot.game,
                )
                if getattr(initial_difference, "party_changed", False):
                    self._schedule_oras_external_pc_reconcile(
                        self.current_game, snapshot.game,
                    )
                if started:
                    self.sync_status = (
                        "◷ Perla Reluciente detectada · heredando el rol antes de publicar el equipo…"
                    )
                    self._update_top_status()
                    return
                self._oras_live_system_role_assignment_ids.difference_update(current_ids)
                self.sync_status = (
                    "◌ Perla Reluciente · esperando una captura estable para heredar el rol…"
                )
                self._update_top_status()
                self._schedule_oras_initial_auto_sync(250)
                return
            self._publish_oras_live_snapshot(snapshot)
            self._record_bdsp_ui_event(
                "ui-initial-sync",
                battle_state=initial_battle_state,
                party_count=len(snapshot.game.party),
            )
            # Publicamos el PC inmediatamente después de la captura inicial ya
            # validada. No se deja detrás de actualizaciones visuales o toasts:
            # un fallo opcional en esas capas no puede cancelar el carril de PC.
            pc_refresh = getattr(self, "_schedule_gen6_live_pc_refresh", None)
            if callable(pc_refresh):
                pc_refresh()
            self.sync_status = (
                f"✓ Perla Reluciente en vivo · {len(snapshot.game.party)} Pokémon · "
                "Ryujinx HostMappedUnsafe · party/MT transaccional"
            )
            self._update_top_status()
            self._schedule_oras_live_reconciliation(
                250 if initial_battle_state in {"battle", "unknown"} else 750
            )
            self._show_live_sync_toast(
                "PERLA RELUCIENTE · TIEMPO REAL",
                f"{len(snapshot.game.party)} Pokémon y el carril de HP están validados. "
                "Los cambios de rol y movimientos se aplican directamente en Ryujinx; "
                "RoleRun no modifica el archivo de guardado.",
                True,
            )
            return

        # 0.2.2-alpha.5: party, MarkingValue y movimientos PK7 ya son fuente de verdad.
        # Antes de publicar, aplicamos la misma normalización de casillas de rol
        # que ORAS/X/Y: cualquier miembro SIN ROL recibe el primer rol libre.
        # El escritor SM solo toca MarkingValue y verifica/rollbackea cada PK7.
        if self._active_azahar_realtime_key() in GEN7_REALTIME_GAME_KEYS:
            # Alpha.57: capture_full ya trae el flag de batalla de Gen7. Así la
            # primera batalla tras abrir RoleRun no depende de que haya ocurrido
            # antes un tick del monitor de 950 ms. Si arrancamos fuera de combate,
            # dejamos una baseline overworld y estado ``none`` desde este instante.
            # Si arrancamos YA dentro de combate, usamos los HP de batalla solo como
            # baseline (nunca cobramos retrospectivamente); si esos HP no pudieron
            # demostrarse, dejamos baseline=None para que la primera muestra válida
            # dentro de ese mismo combate solo arme el detector.
            initial_battle = getattr(snapshot, "battle", None)
            initial_battle_state = str(getattr(initial_battle, "state", "unknown") or "unknown")
            initial_battle_health = getattr(initial_battle, "health_game", None)
            if initial_battle_state == "none":
                self._oras_battle_probe_last_state = "none"
                self._oras_live_health_snapshot = snapshot.game
            elif initial_battle_state == "battle":
                self._oras_battle_probe_last_state = "battle"
                self._oras_live_health_snapshot = initial_battle_health
            else:
                self._oras_battle_probe_last_state = "unknown"
                self._oras_live_health_snapshot = snapshot.game

            # Esta rama Gen7 nunca llegaba a la migración de marcadores genérica
            # (más abajo, para ORAS/X-Y): su propio bloque siempre hacía
            # ``return`` antes. Una Run <=alpha.42 se quedaba en
            # role_marker_layout=1 para siempre en SM/USUM: el lector PK7 en vivo
            # decodifica con layout=2 fijo (``usum_live.py``/``sm_live.py``), así
            # que todo Pokémon se leía "SIN ROL" y el mod de aprendizajes por rol
            # nunca veía un rol real que sustituir (2026-09-04, bug real
            # encontrado validando USUM: Carnivine Mago aprendió un movimiento
            # físico sin que RoleRun lo tocara).
            marker_migration = self._oras_marker_layout_migration_changes(snapshot.game)
            if marker_migration:
                migration_ids = {id(change) for change in marker_migration}
                self._oras_live_role_marker_migration_ids.update(migration_ids)
                self._oras_live_system_role_assignment_ids.update(migration_ids)
                self._publish_oras_live_snapshot(snapshot)
                if self._save_oras_live_changes(
                    marker_migration, automatic=True, base_game=snapshot.game,
                ):
                    self.sync_status = f"◷ {self._active_azahar_realtime_label()} detectado · migrando marcadores de roles…"
                    self._update_top_status()
                    return
                self._oras_live_role_marker_migration_ids.difference_update(migration_ids)
                self._oras_live_system_role_assignment_ids.difference_update(migration_ids)
            elif int(getattr(self.project, "role_marker_layout", 1) or 1) < 2:
                # Si la party solo contiene SIN ROL/Líbero no hay bits que mover.
                self._complete_role_marker_layout_migration()

            initial_role_changes = self._incoming_oras_role_changes(self.current_game, snapshot.game)
            if initial_role_changes:
                generated_ids = {id(change) for change in initial_role_changes}
                self._oras_live_system_role_assignment_ids.update(generated_ids)
                # Publicamos primero la party real para declarar el enlace activo;
                # la escritura inmediata se lanza después con base_game=snapshot.
                self._publish_oras_live_snapshot(snapshot)
                if self._save_oras_live_changes(
                    initial_role_changes, automatic=True, base_game=snapshot.game,
                ):
                    self.sync_status = f"◷ {self._active_azahar_realtime_label()} detectado · asignando marcadores de rol…"
                    self._update_top_status()
                    return
                self._oras_live_system_role_assignment_ids.difference_update(generated_ids)

            self._publish_oras_live_snapshot(snapshot)
            emulator_name = str((getattr(snapshot, "metadata", {}) or {}).get("emulator") or "AzaharPlus")
            self.sync_status = (
                f"✓ {self._active_azahar_realtime_label()} en vivo · {len(snapshot.game.party)} Pokémon · {emulator_name} · "
                f"{snapshot.process.name} · roles/movimientos PK7 activos"
            )
            self._update_top_status()
            # Alpha.57: si la conexión inicial ocurrió dentro de combate o la
            # sonda inicial fue excepcionalmente desconocida, no esperamos el
            # tick normal de 950 ms. El reintento rápido elimina otra ventana de
            # carrera sin aumentar la carga habitual del overworld demostrado.
            initial_monitor_delay = 250 if initial_battle_state in {"battle", "unknown"} else 950
            self._schedule_oras_live_reconciliation(initial_monitor_delay)
            self._show_live_sync_toast(
                f"{self._active_azahar_realtime_label().upper()} · PK7 EN VIVO",
                f"{len(snapshot.game.party)} Pokémon, marcadores y movimientos se leen desde RAM. Los cambios de rol y movimientos compatibles ya se escriben y verifican directamente en AzaharPlus.",
                True,
            )
            return

        self._reconcile_pending_faints_against_party(snapshot.game)

        # Alpha.43: antes de inferir roles libres, migramos UNA VEZ las marcas
        # físicas de Runs antiguas. Así Support deja de ocupar la 5ª marca y pasa
        # a la 6ª sin que ningún Pokémon cambie de rol semántico.
        marker_migration = self._oras_marker_layout_migration_changes(snapshot.game)
        if marker_migration:
            migration_ids = {id(change) for change in marker_migration}
            self._oras_live_role_marker_migration_ids.update(migration_ids)
            self._oras_live_system_role_assignment_ids.update(migration_ids)
            if self._save_oras_live_changes(
                marker_migration, automatic=True, base_game=snapshot.game,
            ):
                self.sync_status = f"◷ {self._active_azahar_realtime_label()} detectado · migrando marcadores de roles…"
                self._update_top_status()
                return
            self._oras_live_role_marker_migration_ids.difference_update(migration_ids)
            self._oras_live_system_role_assignment_ids.difference_update(migration_ids)
        elif int(getattr(self.project, "role_marker_layout", 1) or 1) < 2:
            # Si la party solo contiene SIN ROL/Líbero no hay bits que mover.
            self._complete_role_marker_layout_migration()

        # La primera sincronización también debe respetar las seis casillas de rol.
        # Si la partida ya contenía un Pokémon SIN ROL antes de abrir RoleRun, no
        # esperamos a que ocurra otro cambio para corregirlo: se asigna ahora el
        # primer rol libre y solo después se publica la party.
        initial_role_changes = self._incoming_oras_role_changes(self.current_game, snapshot.game)
        if initial_role_changes:
            generated_ids = {id(change) for change in initial_role_changes}
            self._oras_live_system_role_assignment_ids.update(generated_ids)
            if self._save_oras_live_changes(
                initial_role_changes, automatic=True, base_game=snapshot.game,
            ):
                self.sync_status = f"◷ {self._active_azahar_realtime_label()} detectado · asignando rol libre…"
                self._update_top_status()
                return
            self._oras_live_system_role_assignment_ids.difference_update(generated_ids)

        fingerprint = live_party_fingerprint(snapshot.game)
        differs_from_expected = bool(
            self._oras_live_changes_unpersisted
            and self._oras_live_expected_fingerprint is not None
            and fingerprint != self._oras_live_expected_fingerprint
        )
        # En alpha.30 una diferencia puede ser una acción legítima hecha dentro
        # del juego. Solo la tratamos como Reset cuando coincide con el main; de
        # lo contrario F5 amplía la nueva huella viva sin borrar REVISAR CAMBIOS.
        matches_disk = (
            self._oras_live_snapshot_matches_disk(snapshot)
            if differs_from_expected else False
        )
        party_recovered = bool(differs_from_expected and matches_disk is True)
        memory_recovered = bool(
            self._oras_live_changes_unpersisted
            and not self._oras_live_memory_watches_match(snapshot)
        )
        recovered = party_recovered or memory_recovered
        if recovered:
            self._reconcile_oras_live_memory_watches(snapshot)
            self._clear_oras_live_reconciliation()
        elif self._oras_live_changes_unpersisted and matches_disk is not None:
            # Solo se adopta la huella viva como nueva expectativa cuando la
            # comparación con ``main`` se pudo hacer de verdad. Si el motor
            # falló, conservamos la expectativa anterior y se reintenta en el
            # siguiente ciclo; adoptarla a ciegas destruiría la capacidad de
            # detectar el Reset más tarde.
            self._oras_live_expected_fingerprint = fingerprint

        # La primera conexión también puede llegar después de que el usuario
        # haya movido un Pokémon al PC desde el juego. Antes de reemplazar
        # ``current_game`` conservamos ambos lados de esa transición para que
        # X/Y pueda usar al Pokémon saliente como testigo de la matriz viva.
        initial_pc_difference = diff_live_party(self.current_game, snapshot.game)
        if (
            getattr(initial_pc_difference, "party_changed", False)
            and self._active_azahar_realtime_key() in LIVE_PC_READ_GAME_KEYS
        ):
            self._schedule_oras_external_pc_reconcile(self.current_game, snapshot.game)

        self._publish_oras_live_snapshot(snapshot)

        if recovered:
            self.sync_status = (
                f"↺ {self._active_azahar_realtime_label()} recargado · {len(snapshot.game.party)} Pokémon · "
                "RoleRun descartó la vista sin guardar"
            )
            self._update_top_status()
            self._show_live_sync_toast(
                f"ESTADO DE {self._active_azahar_realtime_label()} RECUPERADO",
                "El emulador volvió a un estado distinto. RoleRun ha actualizado el equipo real; no se escribió ningún byte.",
                True,
            )
            self._oras_live_active = True
            self._schedule_oras_live_reconciliation(850)
            return

        emulator_name = str((getattr(snapshot, "metadata", {}) or {}).get("emulator") or snapshot.process.emulator or "Emulador")
        self.sync_status = (
            f"✓ {self._active_azahar_realtime_label()} en vivo · {len(snapshot.game.party)} Pokémon · "
            f"{emulator_name} · {snapshot.process.name} · lectura {snapshot.attempts}"
        )
        self._update_top_status()
        self._schedule_oras_live_reconciliation(850)
        self._show_live_sync_toast(
            f"{self._active_azahar_realtime_label()} SINCRONIZADO AUTOMÁTICAMENTE" if automatic else f"{self._active_azahar_realtime_label()} ACTUALIZADO EN TIEMPO REAL",
            (
                f"{len(snapshot.game.party)} Pokémon detectados al entrar en la partida. "
                "No se escribió ningún byte."
                if automatic else
                f"{len(snapshot.game.party)} Pokémon validados. No se escribió ningún byte."
            ),
            True,
        )

    def _oras_live_unsupported_changes(self, changes) -> list[str]:
        """Describe operaciones no cubiertas por el adaptador vivo activo."""
        live_key = self._active_azahar_realtime_key()
        # HeartGold entra en `MELONDS_REALTIME_GAME_KEYS` para poder LEER en
        # vivo, pero eso no significa que su escritura de equipo/PC (PK4) esté
        # habilitada -sigue detrás de `MELONDS_GEN4_ESCRIBE = False` por el
        # historial real de «Huevo malo»-. Antes de esta rama, el `if` de
        # abajo trataba a hgss como b2w2/bw y dejaba pasar rol/curación/PC sin
        # ninguna comprobación: un agujero real, no algo que se hubiera
        # decidido a propósito. Mochila/dinero no tocan ningún PK4 y siguen
        # permitidos siempre.
        if live_key in MELONDS_GEN4_REALTIME_GAME_KEYS and live_key not in MELONDS_WRITE_GAME_KEYS:
            labels = {
                "PendingChange": "cambios de movimientos",
                "PendingTMTeach": "enseñanza de MT",
                "PendingRoleChange": "cambios de rol",
                "PendingPCRoleChange": "roles del PC",
                "PendingPartyHeal": "curación",
                "PendingTeamChange": "cambios Equipo ↔ PC",
            }
            result: list[str] = []
            for change in changes:
                if isinstance(change, PendingInventoryChange):
                    continue
                label = labels.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        if live_key in MELONDS_REALTIME_GAME_KEYS:
            labels = {
                "PendingChange": "cambios de movimientos",
                "PendingTMTeach": "enseñanza de MT",
                "PendingRoleChange": "cambios de rol",
                "PendingPCRoleChange": "roles del PC",
                "PendingPartyHeal": "curación",
                "PendingInventoryChange": "inventario",
                "PendingTeamChange": "cambios Equipo ↔ PC",
            }
            result: list[str] = []
            for change in changes:
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingInventoryChange,
                    PendingTMTeach, PendingChange,
                )):
                    continue
                if (
                    isinstance(change, PendingTeamChange)
                    and change.operation in {
                        "move-box-slot", "swap-box-slots", "swap-party-box",
                        "party-to-box", "box-to-party", "replace-fainted",
                    }
                ):
                    continue
                label = labels.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        if self._active_azahar_realtime_key() == "bdsp":
            result: list[str] = []
            for change in changes:
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingChange, PendingTMTeach,
                    PendingInventoryChange,
                )):
                    continue
                if isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party", "replace-fainted",
                    "move-box-slot", "swap-box-slots",
                }:
                    continue
                label = {
                    "PendingPCRoleChange": "roles de Pokémon que permanecen en el PC",
                    "PendingTeamChange": "cambios Equipo ↔ PC",
                }.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        if self._active_azahar_realtime_key() in GEN7_REALTIME_GAME_KEYS:
            result: list[str] = []
            for change in changes:
                if isinstance(change, (
                    PendingRoleChange, PendingPartyHeal, PendingChange,
                    PendingInventoryChange, PendingTMTeach,
                )):
                    continue
                if isinstance(change, PendingTeamChange) and (
                    change.operation in {"swap-party-box", "party-to-box", "box-to-party", "replace-fainted"}
                    or (
                        self._active_azahar_realtime_key() in {"sm", "usum"}
                        and change.operation in {"move-box-slot", "swap-box-slots"}
                    )
                ):
                    continue
                label = {
                    "PendingTMTeach": "enseñanza de MT",
                    "PendingPCRoleChange": "roles del PC",
                    "PendingInventoryChange": "utilidades de inventario",
                    "PendingTeamChange": "cambios Equipo ↔ PC",
                }.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        if self._active_azahar_realtime_key() == "xy":
            result: list[str] = []
            for change in changes:
                if isinstance(change, (
                    PendingChange, PendingRoleChange, PendingPCRoleChange,
                    PendingPartyHeal, PendingTMTeach, PendingInventoryChange,
                )):
                    continue
                if isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party",
                    "replace-fainted", "move-box-slot", "swap-box-slots",
                }:
                    continue
                label = {
                    "PendingInventoryChange": "escritura de utilidades de inventario",
                    "PendingTeamChange": "entradas/salidas que cambian el tamaño del equipo",
                }.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        if self._active_azahar_realtime_key() == "oras":
            result: list[str] = []
            for change in changes:
                if isinstance(change, (
                    PendingChange, PendingRoleChange, PendingPCRoleChange,
                    PendingPartyHeal, PendingTMTeach, PendingInventoryChange,
                )):
                    continue
                if isinstance(change, PendingTeamChange) and change.operation in {
                    "swap-party-box", "party-to-box", "box-to-party", "replace-fainted",
                    "move-box-slot", "swap-box-slots",
                }:
                    continue
                label = {
                    "PendingInventoryChange": "escritura de utilidades de inventario",
                    "PendingTeamChange": "entradas/salidas que cambian el tamaño del equipo",
                }.get(type(change).__name__, type(change).__name__)
                if label not in result:
                    result.append(label)
            return result
        result: list[str] = []
        for change in changes:
            label = None
            if isinstance(change, PendingTeamChange) and change.operation not in {"swap-party-box", "replace-fainted"}:
                label = "entradas/salidas que cambian el tamaño del equipo"
            if label and label not in result:
                result.append(label)
        return result

    def _dialog_parent(self):
        """Mantiene los diálogos sobre la barra si la ventana principal está retirada."""
        parent = self
        try:
            if self.floating_bar and self.floating_bar.winfo_exists() and str(self.floating_bar.state()) != "withdrawn":
                parent = self.floating_bar
        except Exception:
            pass
        return parent

    # ---------- COLA DE CAMBIOS ----------

    def _cola_debe_esperar(self) -> bool:
        """¿Hay ahora mismo algo que impida escribir en la RAM del juego?

        Una escritura en vuelo, una lectura o el monitor. Todas son razones para
        ESPERAR TURNO, no para rechazar la acción del usuario.
        """
        return bool(
            self._live_write_in_progress
            or self._live_sync_in_progress
            or self._oras_live_monitor_in_progress
            or self.cola_de_cambios.en_vuelo is not None
        )

    @staticmethod
    def _solo_son_movimientos_de_caja(changes) -> bool:
        """¿El lote entero son traslados PC→PC y nada más?

        Es la única operación que se encola. El motivo no es técnico sino de
        honestidad visual: origen y destino son ambos huecos del PC, así que
        RoleRun puede adelantar el movimiento en pantalla y devolver al Pokémon
        a su sitio si la escritura falla, sin haber afirmado nunca nada del
        equipo, de la mochila ni de los PS. Cualquier otro cambio sigue
        esperando a que el juego confirme.
        """
        lote = list(changes)
        return bool(lote) and all(
            isinstance(change, PendingTeamChange) and change.operation == "move-box-slot"
            for change in lote
        )

    def _encolar_cambios_en_vivo(self, changes, *, automatic: bool = False) -> bool:
        """Registra el lote y devuelve el control a la interfaz de inmediato."""
        lote = [
            change for change in changes
            if not self.cola_de_cambios.contiene_cambio(change)
        ]
        if not lote:
            # El flujo automático y el botón manual pueden pedir lo mismo. Ya
            # está encolado; volver a encolarlo lo escribiría dos veces.
            return True
        trabajo_id = self.cola_de_cambios.encolar(
            lote,
            etiqueta=self._etiqueta_de_trabajo(lote),
            automatico=bool(automatic),
        )
        perf.mark("ui.cola.encolado", trabajo=trabajo_id, cambios=len(lote))
        self._publicar_estado_de_cola()
        self._programar_bombeo_de_cola(180)
        return True

    @staticmethod
    def _etiqueta_de_trabajo(changes) -> str:
        """Nombre corto y honesto del lote, para la barra y para 'Revisar'."""
        nombres = {
            "PendingChange": "movimiento",
            "PendingTMTeach": "MT",
            "PendingRoleChange": "rol",
            "PendingPartyHeal": "curación",
            "PendingInventoryChange": "utilidades",
            "PendingPCRoleChange": "rol en el PC",
            "PendingTeamChange": "equipo",
        }
        tipos: list[str] = []
        for change in changes:
            nombre = nombres.get(type(change).__name__, "cambio")
            if nombre not in tipos:
                tipos.append(nombre)
        return " + ".join(tipos) if tipos else "cambio"

    def _programar_bombeo_de_cola(self, delay_ms: int = 180) -> None:
        if getattr(self, "_bombeo_de_cola_after_id", None):
            return
        self._bombeo_de_cola_after_id = None
        try:
            self._bombeo_de_cola_after_id = self.after(
                max(30, int(delay_ms)), self._bombear_cola_de_cambios,
            )
        except Exception:
            self._bombeo_de_cola_after_id = None

    def _bombear_cola_de_cambios(self) -> None:
        """Despacha el siguiente trabajo si el juego ya admite una escritura.

        Es el único punto que saca trabajos de la cola. Se le llama al encolar y
        al terminar cada escritura; si todavía no se puede, se reprograma.
        """
        self._bombeo_de_cola_after_id = None
        cola = self.cola_de_cambios
        if cola.en_vuelo is not None or cola.pausada or not cola.pendientes:
            return
        if self._live_write_in_progress or self._live_sync_in_progress or self._oras_live_monitor_in_progress:
            self._programar_bombeo_de_cola(220)
            return
        trabajo = cola.siguiente()
        if trabajo is None:
            return
        self._trabajo_en_vuelo_id = trabajo.id
        self._publicar_estado_de_cola()
        try:
            lanzado = self._save_oras_live_changes(
                trabajo.cambios, automatic=trabajo.automatico, desde_cola=True,
            )
        except Exception as exc:  # el preflight no debe dejar la cola colgada
            lanzado = False
            self._trabajo_lanzo_hilo = False
            cola.terminar(trabajo.id, error=str(exc))
            self._trabajo_en_vuelo_id = None
            self._publicar_estado_de_cola()
            return
        if not self._trabajo_lanzo_hilo:
            # El preflight cortó la operación (ROM ausente, cambio no
            # compatible, confirmación denegada). Ya avisó por su cuenta: aquí
            # solo cerramos el trabajo para que la cola vuelva a avanzar.
            cola.terminar(
                trabajo.id,
                error=None if lanzado else "el cambio no llegó a enviarse al juego",
            )
            self._trabajo_en_vuelo_id = None
            self._publicar_estado_de_cola()
            self._programar_bombeo_de_cola(120)

    def _resolver_pausa_de_cola(self, cola) -> None:
        """Decide si un fallo detiene la cola o si basta la política de siempre."""
        if not cola.pausada:
            self._programar_bombeo_de_cola(120)
            return
        if cola.pendientes:
            # Hay trabajos detrás esperando. Sus testigos se capturaron dando
            # por supuesto un estado que esta escritura fallida ya no garantiza:
            # no seguimos escribiendo a ciegas sobre una partida viva.
            self._publicar_estado_de_cola()
            return
        # Nada detrás que proteger. La política de recuperación que sigue a esta
        # llamada (sustitución, normalización de roles, ruta automática) se basta
        # sola; una pausa aquí solo sería una alarma vacía.
        cola.reanudar()

    def _olvidar_cola_de_cambios(self) -> None:
        """Vacía la cola al cambiar de partida, proyecto o sesión."""
        after_id = getattr(self, "_bombeo_de_cola_after_id", None)
        self._bombeo_de_cola_after_id = None
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._trabajo_en_vuelo_id = None
        self._trabajo_lanzo_hilo = False
        cola = getattr(self, "cola_de_cambios", None)
        if cola is not None:
            cola.olvidar_todo()

    def _al_cambiar_la_cola(self, estado) -> None:
        """Enganche del modelo. La barra se refresca desde el hilo de Tk."""
        self._ultimo_estado_de_cola = estado

    def _publicar_estado_de_cola(self) -> None:
        """Refleja la cola en la barra inferior, sin afirmar nunca un éxito."""
        estado = self.cola_de_cambios.estado()
        set_status = getattr(self, "_set_operation_status", None)
        if not callable(set_status):
            return
        if estado.pausada:
            set_status(
                "failed",
                "COLA EN PAUSA",
                (
                    f"{estado.motivo_pausa} · Quedan {estado.en_cola} cambio(s) sin enviar. "
                    "RoleRun no seguirá escribiendo hasta que decidas."
                ),
                actions=("Reanudar cola", "Descartar cola"),
            )
            return
        if estado.aplicando is not None:
            # 2026-09-05: este detalle incluía la etiqueta y el resumen de cada
            # trabajo de la cola («enviando «X» · 2/5»...). Cuando varios
            # cambios se aplican en ráfaga -algo tan normal como un solo cambio
            # de rol que dispara internamente varias escrituras pequeñas-, cada
            # trabajo republicaba un texto DISTINTO, y publicar dos veces algo
            # distinto reinicia la barra letra a letra (ver el comentario de
            # OperationStatusStore.publish). El resultado: 4 o 5 avisos
            # ilegibles que se pisan entre sí antes de que el usuario llegue a
            # leer ninguno. Un texto fijo aquí hace que las repúblicas sean
            # IDÉNTICAS -publish() ya las descarta sin tocar la barra- y el
            # usuario ve un único «Cargando…» estable hasta el resultado final.
            set_status("applying", LOADING_STATUS_TITLE, LOADING_STATUS_DETAIL)
            return
        if estado.en_cola:
            set_status(
                "pending",
                "CAMBIOS EN COLA",
                f"{estado.resumen()}. Se aplicarán en orden en cuanto el juego lo permita.",
            )

    def _accion_de_cola(self, action: str) -> bool:
        """Atiende los botones que publica la barra cuando la cola se pausa."""
        normal = str(action).strip().lower()
        if normal == "reanudar cola":
            self.cola_de_cambios.reanudar()
            self._publicar_estado_de_cola()
            self._programar_bombeo_de_cola(80)
            return True
        if normal == "descartar cola":
            descartados = self.cola_de_cambios.descartar_pendientes()
            olvidados = {id(c) for t in descartados for c in t.cambios}
            if olvidados:
                self.run.pending_changes = [
                    change for change in self.run.pending_changes
                    if id(change) not in olvidados
                ]
                self._oras_live_auto_apply_ids.difference_update(olvidados)
            self._set_operation_status(
                "warning",
                "COLA DESCARTADA",
                (
                    f"Se retiraron {len(descartados)} cambio(s) sin enviarlos. "
                    "No se escribió ningún byte por ellos."
                ),
            )
            self._refresh_main_after_oras_live_write()
            return True
        return False

    @perf.timed("ui.save_live_changes")
    def _save_oras_live_changes(
        self, changes, *, automatic: bool = False, base_game: SaveGameData | None = None,
        desde_cola: bool = False,
    ) -> bool:
        """Envía el subconjunto seguro de cambios al emulador activo en RAM.

        La ruta automática reutiliza exactamente la misma doble captura,
        preflight, verificación y rollback que el botón manual; solo omite el
        diálogo porque la acción ya fue confirmada en la interfaz que la creó.

        Si el emulador está ocupado, el lote NO se rechaza: entra en
        ``cola_de_cambios`` y saldrá en su turno. ``desde_cola`` distingue la
        reentrada del bombeo, que ya pasó por ese filtro y no debe volver a
        encolarse a sí misma.
        """
        if automatic and self._defer_automatic_libero_role_until_ev_choice(
            changes, base_game=base_game,
        ):
            return True

        live_key = self._active_azahar_realtime_key()
        emulator_label = "Ryujinx" if live_key == "bdsp" else "Azahar"
        if not desde_cola and self._cola_debe_esperar():
            # Solo los movimientos dentro del PC se encolan. Son la única
            # operación que se puede adelantar visualmente sin mentir: el hueco
            # de origen y el de destino son ambos del PC, y si la escritura falla
            # el Pokémon vuelve solo a su sitio al retirarse el cambio pendiente.
            # El resto (equipo, MT, roles, mochila) sigue esperando turno.
            if self._solo_son_movimientos_de_caja(changes):
                return self._encolar_cambios_en_vivo(changes, automatic=automatic)
            if self._live_write_in_progress:
                if automatic:
                    self._schedule_oras_live_auto_apply(220)
                else:
                    self._show_live_sync_toast(
                        "CAMBIOS EN CURSO",
                        f"Espera a que termine la comprobación de {emulator_label}.",
                        False,
                    )
                return False
            if automatic:
                self._schedule_oras_live_auto_apply(220)
            else:
                self._show_live_sync_toast(
                    "LECTURA EN CURSO",
                    "Espera a que termine la comprobación de Azahar antes de aplicar cambios.",
                    False,
                )
            return False
        self._trabajo_lanzo_hilo = False
        _anotar_intento_vivo(
            self, "enviando",
            tipos=[type(c).__name__ for c in changes],
            automatico=bool(automatic),
        )
        unsupported = self._oras_live_unsupported_changes(changes)
        if unsupported:
            if automatic:
                self._stop_oras_live_auto_apply_for(changes)
                # Rechazar aquí (antes de llegar al writer) es tan definitivo
                # como un fallo dentro de él: dejar el cambio en la cola sin
                # limpiarlo mostraba una proyección fantasma (el Pokémon
                # "incorporado" pero sin PS, sin que ORAS lo tuviera de
                # verdad) que ningún ciclo posterior retiraba solo.
                rejected_ids = {id(change) for change in changes}
                self.run.pending_changes = [
                    change for change in self.run.pending_changes
                    if id(change) not in rejected_ids
                ]
                self._pc_cache = None
                self._pc_cache_signature = None
                self._refresh_main_after_oras_live_write()
                self.sync_status = "⚠ Aplicación inmediata pausada: cambio no compatible"
                self._update_top_status()
                self._show_live_sync_toast(
                    "CAMBIO PENDIENTE PROTEGIDO",
                    f"Esta operación no tiene writer validado. No se escribió ningún byte en {emulator_label}.",
                    False,
                )
                return False
            continue_on_disk = messagebox.askyesno(
                "Cambios que requieren el archivo",
                f"No se aplicó ningún cambio. El adaptador vivo de {self._active_azahar_realtime_label()} no cubre todavía: "
                + ", ".join(unsupported)
                + ".\n\nCierra el emulador antes de usar cualquier flujo clásico de archivo; así no se sobrescribe progreso del juego.\n\n"
                "¿El emulador ya está cerrado y quieres continuar por el flujo normal?",
                parent=self._dialog_parent(),
            )
            if continue_on_disk:
                # Esta confirmación explícita evita caer a disco de forma
                # automática mientras el emulador pueda seguir abierto.
                self._oras_live_active = False
                self.save_pending_changes()
            return False
        if any(isinstance(change, (PendingChange, PendingTMTeach)) for change in changes):
            move_pp_table = (
                None if live_key == "bdsp" else
                self.sm_live_move_pp if live_key in GEN7_REALTIME_GAME_KEYS else
                self.oras_live_move_pp
            )
            if live_key != "bdsp" and not move_pp_table:
                self._stop_oras_live_auto_apply_for(changes)
                self._show_live_sync_toast(
                    "TABLA DE MOVIMIENTOS NO DISPONIBLE",
                    (
                        "Falta la tabla de PP de Gen 7. No se escribió ningún byte."
                        if live_key in GEN7_REALTIME_GAME_KEYS else
                        "Falta la tabla de PP de Gen 6. No se escribió ningún byte."
                    ),
                    False,
                )
                return False
        team_swaps = [
            change for change in changes
            if isinstance(change, PendingTeamChange) and change.operation in {"swap-party-box", "replace-fainted"}
        ]
        sm_team_transfers = [
            change for change in changes
            if isinstance(change, PendingTeamChange)
            and change.operation in {"swap-party-box", "party-to-box", "box-to-party", "replace-fainted", "move-box-slot"}
        ]
        if self._oras_changes_require_personal(changes) and self._active_azahar_realtime_key() == "oras":
            with perf.span("ui.save_live.get_oras_rom_tm_profile"):
                profile = self._get_oras_rom_tm_profile(prompt=False)
            if profile is None or not profile.personal_stats:
                self._stop_oras_live_auto_apply_for(changes)
                self._show_live_sync_toast(
                    "ROM ORAS NO DISPONIBLE",
                    "No se pudieron leer las estadísticas de la ROM configurada. No se escribió ningún byte; revisa ARCHIVOS para ese juego.",
                    False,
                )
                return False
            # El writer se ejecuta en otro hilo. Conservamos aquí una referencia
            # fuerte al perfil exacto que superó la precondición, en vez de dejar
            # que su callback vuelva a consultar la caché mutable de la UI. Esta
            # caché se invalida legítimamente al reconectar/cambiar de proceso y
            # no debe transformar una ROM válida en un falso "falta especie" a
            # mitad del recálculo de estadísticas.
            self._pin_oras_personal_profile(self.oras_live_writer, profile)

        if team_swaps and self._active_azahar_realtime_key() == "xy":
            profile = self._get_xy_rom_tm_profile(prompt=False)
            if profile is None or not profile.personal_stats:
                self._stop_oras_live_auto_apply_for(changes)
                self._show_live_sync_toast(
                    "ROM X/Y NO DISPONIBLE",
                    "No se pudieron leer las estadísticas personales de la ROM X/Y configurada. No se escribió ningún byte; revisa ARCHIVOS para ese juego.",
                    False,
                )
                return False

        # 2026-09-04: un simple cambio de rol (sin ningún traslado Equipo↔PC)
        # también recalcula EV/stats -``new_evs`` no nulo- y por lo tanto
        # también necesita Personal cargado antes de escribir. Antes esto solo
        # se comprobaba para ``sm_team_transfers``: si el PRIMER cambio
        # auto-aplicado de la sesión era un cambio de rol puro (p. ej. al
        # reconciliar justo al conectar), el perfil todavía no se había
        # precargado nunca y el writer fallaba con "la ROM efectiva no aportó
        # Personal" -un error real, no cosmético, pero que se autocorregía en
        # el siguiente reintento porque para entonces el perfil ya estaba en
        # caché-. Se demuestra aquí de la misma forma, así nunca llega a
        # fallar la primera vez.
        gen7_needs_personal = sm_team_transfers or any(
            isinstance(change, PendingRoleChange) and change.new_evs is not None
            for change in changes
        )
        if gen7_needs_personal and self._active_azahar_realtime_key() in GEN7_REALTIME_GAME_KEYS:
            # El writer trabaja en segundo plano: cargamos Personal aquí, en el
            # hilo UI, y el callback live solo consulta el perfil ya validado.
            gen7_key = self._active_azahar_realtime_key()
            profile = (
                self._get_usum_rom_tm_profile(prompt=False)
                if gen7_key == "usum" else self._get_sm_rom_tm_profile(prompt=False)
            )
            if profile is None or not profile.personal_stats:
                self._stop_oras_live_auto_apply_for(changes)
                label = "ULTRASOL/ULTRALUNA" if gen7_key == "usum" else "SOL/LUNA"
                self._show_live_sync_toast(
                    f"ROM {label} NO DISPONIBLE",
                    f"No se pudieron leer las estadísticas personales de la ROM {label} configurada. No se escribió ningún byte; revisa ARCHIVOS para ese juego.",
                    False,
                )
                return False

        if not automatic and not desde_cola:
            # `desde_cola` es la reentrada del bombeo: este lote ya se confirmó
            # cuando el usuario lo pidió. Volver a preguntarlo al despacharlo
            # sería pedir permiso dos veces por la misma acción, y además con la
            # ventana ya en otra pantalla.
            parent = self._dialog_parent()
            if not messagebox.askyesno(
                "Aplicar cambios en tiempo real",
                f"Se aplicarán {len(changes)} cambio(s) directamente al equipo que está abierto en Azahar.\n\n"
                f"RoleRun capturará el equipo dos veces, comprobará identidad/estado/checksum y escribirá solo los campos {'PK7' if self._active_azahar_realtime_key() in GEN7_REALTIME_GAME_KEYS else 'PK6'} necesarios antes de volver a leerlos. "
                "Si la comprobación falla, restaurará el bloque original en RAM.\n\n"
                "No se tocará el archivo main, tu historia ni tu ubicación. Para que estos cambios sobrevivan al cierre del emulador, guarda normalmente desde el menú del juego cuando quieras.\n\n"
                "Ponte fuera de combate, de menús de cambio de equipo y de animaciones. ¿Aplicar ahora?",
                parent=parent,
            ):
                return False

        generation = self._session_generation
        project_slug = self.project.slug if self.project else ""
        current = base_game if base_game is not None else self.current_game
        # Si había una comprobación futura de una escritura anterior, el nuevo
        # guardado en vivo la sustituirá cuando se confirme. Evitamos una lectura
        # RPC simultánea justo al empezar la operación.
        self._cancel_oras_live_reconciliation_timer()
        self._live_write_in_progress = True
        # Aquí había una superficie opaca sobre `content`. Era literalmente lo
        # que impedía navegar durante los segundos que tarda una escritura +
        # verificación. La actividad se comunica ahora por la barra inferior,
        # que informa sin secuestrar la ventana.
        self.sync_status = (
            f"◷ Aplicando cambio automáticamente en {emulator_label}…"
            if automatic else f"◷ Aplicando cambios verificados en {emulator_label}…"
        )
        set_operation_status = getattr(self, "_set_operation_status", None)
        if callable(set_operation_status):
            set_operation_status("applying", LOADING_STATUS_TITLE, LOADING_STATUS_DETAIL)
        self._update_top_status()

        def show_verifying() -> None:
            if (
                self._live_write_in_progress
                and generation == self._session_generation
                and self.project
                and self.project.slug == project_slug
            ):
                set_verifying = getattr(self, "_set_operation_status", None)
                if callable(set_verifying):
                    # kind "verifying" pasa igualmente por el texto fijo de
                    # _set_operation_status; ver el comentario de ahí sobre
                    # por qué toda la fase "en curso" muestra el mismo aviso.
                    set_verifying("verifying", "VERIFICANDO EN EL JUEGO", "")

        self.after(260, show_verifying)

        def worker() -> None:
            try:
                realtime_core = getattr(self, "realtime_core", None)
                result = (
                    realtime_core.apply_changes(current, changes)
                    if realtime_core is not None
                    else self.oras_live_writer.apply(current, changes)
                )
                error = None
            except Exception as exc:
                result = None
                error = str(exc)
            self.after(0, lambda: self._finish_oras_live_write(
                generation, project_slug, changes, result, error, automatic,
            ))

        self._trabajo_lanzo_hilo = True
        threading.Thread(target=worker, daemon=True, name="RoleRunRealtimeWrite").start()
        return True

    @staticmethod
    def _oras_changes_require_personal(changes) -> bool:
        """Indica si ORAS tendrá que recalcular estadísticas desde Personal."""
        return any(
            (
                isinstance(change, PendingTeamChange)
                and change.operation in {"swap-party-box", "replace-fainted", "box-to-party"}
            )
            or (
                isinstance(change, PendingRoleChange)
                and change.new_evs is not None
            )
            for change in changes
        )

    @staticmethod
    def _pin_oras_personal_profile(writer, profile) -> None:
        """Fija en el writer el perfil validado durante toda la transacción."""
        writer.personal_for = profile.personal_for

    @perf.timed("ui.live.finalizar_escritura")
    def _finish_oras_live_write(
        self, generation: int, project_slug: str, changes, result, error: str | None, automatic: bool = False,
    ) -> None:
        _anotar_intento_vivo(
            self, "terminado",
            tipos=[type(c).__name__ for c in changes],
            error=error,
            aplicados=int(getattr(result, "applied_count", 0) or 0),
        )
        self._live_write_in_progress = False
        hide_busy = getattr(self, "_hide_busy_indicator", None)
        if callable(hide_busy):
            # Compatibilidad: esta escritura ya no levanta la superficie opaca,
            # pero un flujo antiguo pudo dejarla puesta y no debe quedarse.
            hide_busy("live-write")
        # Cierra el trabajo en la cola ANTES de la política de errores de abajo:
        # cualquier `return` temprano de esa política dejaría la cola colgada.
        # Barrera defensiva: un fixture o una sesión anterior a la cola llega
        # aquí sin ella montada, y la política de errores de abajo se basta sola.
        cola = getattr(self, "cola_de_cambios", None)
        trabajo_id = getattr(self, "_trabajo_en_vuelo_id", None)
        self._trabajo_en_vuelo_id = None
        if cola is not None:
            if trabajo_id is not None:
                cola.terminar(
                    trabajo_id,
                    resultado=result,
                    error=(error or None) if result is not None else (error or "escritura no confirmada"),
                )
            self._resolver_pausa_de_cola(cola)
        # Barrera defensiva para sesiones/fixtures creados antes de alpha.43.
        # En la aplicación normal el set existe desde __init__, pero no debe
        # romper la recuperación de una escritura por faltar metadato migratorio.
        if not hasattr(self, "_oras_live_role_marker_migration_ids"):
            self._oras_live_role_marker_migration_ids = set()
        change_ids = {id(change) for change in changes}
        system_generated = bool(change_ids) and change_ids.issubset(
            self._oras_live_system_role_assignment_ids
        )
        death_generated = bool(change_ids.intersection(self._oras_live_death_replacement_ids))
        marker_migration = bool(change_ids) and change_ids.issubset(
            self._oras_live_role_marker_migration_ids
        )
        if (
            generation != self._session_generation
            or not self.project
            or self.project.slug != project_slug
            or not self.current_game
        ):
            self._oras_live_system_role_assignment_ids.difference_update(change_ids)
            self._oras_live_death_replacement_ids.difference_update(change_ids)
            return
        if error or result is None:
            self._stop_oras_live_auto_apply_for(changes)
            if self._oras_live_undo_inverse_ids.intersection(change_ids):
                self._oras_live_undo_batch = None
                self._oras_live_undo_inverse_ids.clear()
            detail = error or "escritura no confirmada"
            if death_generated:
                # La muerte ya está registrada y la vida descontada. Si la
                # sustitución no pudo confirmarse, retiramos solo esa operación
                # técnica para que el usuario pueda volver a elegir sin dejar la
                # cola viva bloqueada. La baja pendiente permanece persistida.
                self.run.pending_changes = [
                    change for change in self.run.pending_changes
                    if id(change) not in change_ids
                ]
                self._oras_live_auto_apply_ids.difference_update(change_ids)
                self._oras_live_death_replacement_ids.difference_update(change_ids)
                self.sync_status = f"⚠ Sustitución pendiente: {detail}"
                self._update_top_status()
                self._show_live_sync_toast(
                    "NO SE PUDO APLICAR LA SUSTITUCIÓN",
                    detail + (
                        "\n\nLa baja y la vida perdida siguen registradas. "
                        "RoleRun no cambiará visualmente el equipo hasta que Azahar "
                        "confirme el estado. Puedes hacer la sustitución desde el PC "
                        "del juego; el monitor la recogerá automáticamente."
                    ),
                    False,
                )
                # La operación proyectada puede haber mostrado el sustituto mientras
                # la escritura estaba en curso. Al fallar, retiramos la proyección y
                # redibujamos desde la última party confirmada: nunca afirmamos que
                # Golem (u otro) entró si Azahar sigue conservando al debilitado.
                self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
                self._floating_bar_last_signature = None
                try:
                    if self.floating_bar and self.floating_bar.winfo_exists():
                        self._render_floating_bar(force=True)
                except Exception:
                    pass
                self._schedule_oras_live_reconciliation(450)
                # Alpha.37: el aviso de sustitución es de una sola aparición. Un
                # fallo de escritura NO vuelve a abrir el modal automáticamente.
                return
            if system_generated:
                # La normalización automática puede coincidir con una transición
                # del PC. Nunca hacemos write-loop contra una party host ambigua.
                self._oras_live_system_role_assignment_ids.difference_update(change_ids)
                self._oras_live_role_marker_migration_ids.difference_update(change_ids)
                if (
                    not marker_migration
                    and self._active_azahar_realtime_key() in GEN7_REALTIME_GAME_KEYS
                    and self.current_game is not None
                ):
                    # Alpha.29: preserva la decisión original de la transición
                    # (sustitución directa = rol del saliente) y exige otra prueba
                    # completa PC↔party antes de volver a tocar el marcador.
                    self._sm_pending_role_transition = (
                        self._sm_role_transition_key(self.current_game), list(changes),
                    )
                    self.sync_status = f"◌ {self._active_azahar_realtime_label()} · revalidando Equipo↔PC antes de reintentar el rol…"
                    self._update_top_status()
                    try:
                        self.after(250, lambda: self._schedule_oras_external_pc_reconcile(
                            self.current_game, self.current_game, force=True,
                        ))
                    except Exception:
                        pass
                    self._schedule_oras_live_reconciliation(900)
                    return

                self.sync_status = (
                    f"◌ {self._active_azahar_realtime_label()} · reintentando migración de marcadores…"
                    if marker_migration else
                    "◌ Juego → RoleRun · reintentando asignación de rol…"
                )
                self._update_top_status()
                if self._oras_live_active:
                    self._schedule_oras_live_reconciliation(900)
                else:
                    # Puede ocurrir durante la primera conexión automática, antes
                    # de publicar la party. Si la transición de ORAS hizo fallar la
                    # escritura, volvemos a enlazar en vez de quedarnos sin monitor.
                    self._schedule_oras_initial_auto_sync(900)
                return

            if automatic:
                # Una acción inmediata que NO llegó a Azahar no puede quedarse
                # proyectada como "pendiente manual". Ese estado fantasma era el
                # que, tras un error de MT/mochila, bloqueaba cambios posteriores y
                # podía impedir que un reinicio/state-load volviese a reflejar el
                # equipo real. Retiramos únicamente este lote fallido y volvemos a
                # leer el juego; otras acciones pendientes no relacionadas se
                # conservan.
                self.run.pending_changes = [
                    change for change in self.run.pending_changes
                    if id(change) not in change_ids
                ]
                self._oras_live_auto_apply_ids.difference_update(change_ids)
                self._oras_live_system_role_assignment_ids.difference_update(change_ids)
                self._oras_live_role_marker_migration_ids.difference_update(change_ids)
                self._oras_live_death_replacement_ids.difference_update(change_ids)
                if self._oras_live_undo_inverse_ids.intersection(change_ids):
                    self._oras_live_undo_batch = None
                    self._oras_live_undo_inverse_ids.clear()
                self.current_results = []
                self.selected_pokemon = None
                self._pc_cache = None
                self._pc_cache_signature = None
                self._floating_bar_last_signature = None
                self._refresh_main_after_oras_live_write()
                try:
                    if self.floating_bar and self.floating_bar.winfo_exists():
                        self._render_floating_bar(force=True)
                except Exception:
                    pass

            live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
            live_key = live_key_getter() if callable(live_key_getter) else "oras"
            emulator_label = "Ryujinx" if live_key == "bdsp" else "Azahar"
            unavailable = live_key != "bdsp" and "Azahar no responde por RPC" in detail
            if unavailable:
                self._oras_live_active = False
                detail += "\n\nSi has cerrado Azahar, pulsa GUARDAR CAMBIOS otra vez para usar el flujo normal de archivo."
            self.sync_status = f"⚠ {emulator_label}: {detail}"
            self._update_top_status()
            active_label_getter = getattr(self, "_active_azahar_realtime_label", None)
            active_label = active_label_getter() if callable(active_label_getter) else "ORAS"
            self._show_live_sync_toast(
                f"NO SE APLICARON CAMBIOS EN {active_label}",
                detail,
                False,
            )
            self._schedule_oras_live_reconciliation(220 if automatic else 450)
            return
        self._finalize_oras_live_changes(changes, result, automatic=automatic)

    def _refresh_main_after_oras_live_write(self) -> bool:
        """Refresca la vista normal solo si no está detrás de la barra.

        Devuelve ``True`` cuando hubo render. Mantener esta decisión en un único
        punto evita que nuevas escrituras vivas reintroduzcan el bug de cerrar la
        barra al provocar un ``<Map>`` de la raíz retirada en Windows.
        """
        if self._floating_bar_is_visible():
            self._main_ui_dirty_while_floating = True
            return False
        self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
        return True

    @perf.timed("ui.finalize_live_changes")
    def _finalize_oras_live_changes(self, changes, result, *, automatic: bool = False) -> None:
        """Publica una escritura ya verificada sin modificar el archivo ``main``."""
        if not self.project or not self.current_save:
            return

        current_ids = {id(change) for change in changes}
        system_generated = bool(current_ids) and current_ids.issubset(
            self._oras_live_system_role_assignment_ids
        )
        death_generated = bool(current_ids.intersection(self._oras_live_death_replacement_ids))
        marker_migration = bool(current_ids) and current_ids.issubset(
            self._oras_live_role_marker_migration_ids
        )
        already_applied = bool(getattr(result, "already_applied", False))

        # El lector vivo conoce IDs y números, pero el Pokémon que acaba de
        # entrar no estaba en la party anterior de la que preservar nombres
        # localizados. Restauramos sus etiquetas desde la ficha de PC elegida.
        for change in changes:
            if not isinstance(change, PendingTeamChange) or not change.incoming_snapshot:
                continue
            incoming = self._pokemon_from_snapshot(change.incoming_snapshot)
            identity = change.incoming_identity or self._pokemon_identity(incoming)
            live = next((
                pokemon for pokemon in result.game.party
                if self._pokemon_identity(pokemon) == identity
            ), None)
            if live is not None:
                live.species = incoming.species
                live.nickname = incoming.nickname
                live.held_item = incoming.held_item
                live.ability = incoming.ability

        for change in changes:
            if isinstance(change, PendingRoleChange):
                event = {
                    "type": "role_changed",
                    "pokemon": change.pokemon,
                    "species": change.species,
                    "old_role": change.old_role,
                    "new_role": change.new_role,
                    "source": "Azahar en vivo",
                    "output": "RAM",
                }
                pokemon = next((
                    item for item in result.game.party
                    if (change.pokemon_identity and self._pokemon_identity(item) == change.pokemon_identity)
                    or (not change.pokemon_identity and item.slot == change.pokemon_slot)
                ), None)
                if pokemon is not None:
                    key = self.project_service.pokemon_key(pokemon.slot, pokemon.species_id, pokemon.nickname)
                    self.project.role_overrides.pop(key, None)
                    identity = self._pokemon_identity(pokemon)
                    if change.new_role in ROLE_TO_KEY:
                        self.project.managed_pokemon_roles[identity] = change.new_role
                    else:
                        self.project.managed_pokemon_roles.pop(identity, None)
            elif isinstance(change, PendingChange):
                event = {
                    "type": "draft_applied",
                    "role": change.role,
                    "move": change.new_move,
                    "move_id": change.new_move_id,
                    "pokemon": change.pokemon,
                    "species": change.species,
                    "old_move": change.old_move,
                    "source": "Azahar en vivo",
                    "output": "RAM",
                }
            elif isinstance(change, PendingTMTeach):
                event = {
                    "type": "tm_taught",
                    "role": change.role,
                    "move": change.new_move,
                    "move_id": change.new_move_id,
                    "pokemon": change.pokemon,
                    "species": change.species,
                    "tm": change.item_name,
                    "old_move": change.old_move,
                    "source": "Azahar en vivo",
                    "output": "RAM",
                    "reusable": not bool(change.consumes_item),
                }
            elif isinstance(change, PendingPCRoleChange):
                event = {
                    "type": "pc_role_changed",
                    "pokemon": change.pokemon,
                    "species": change.species,
                    "old_role": change.old_role,
                    "new_role": change.new_role,
                    "box": change.box,
                    "box_slot": change.box_slot,
                    "source": "Azahar en vivo",
                    "output": "RAM",
                }
                if change.new_role in ROLE_TO_KEY:
                    self.project.managed_pokemon_roles[change.pokemon_identity] = change.new_role
                else:
                    self.project.managed_pokemon_roles.pop(change.pokemon_identity, None)
            elif isinstance(change, PendingInventoryChange):
                event = {
                    "type": "inventory_changed",
                    "item": change.item_name,
                    "quantity": change.quantity,
                    "source": "Azahar en vivo",
                    "output": "RAM",
                }
            elif isinstance(change, PendingTeamChange):
                if change.operation == "swap-box-slots":
                    # Las dos casillas siguen ocupadas: cada Pokémon pasa a la
                    # del otro. Nada se vacía, así que aquí no interviene
                    # `_oras_live_pc_empty_overrides` más que para retirar un
                    # vacío antiguo que ya no es cierto.
                    source_pos = (int(change.box or 0), int(change.box_slot or 0))
                    destination_pos = (
                        int(change.destination_box or 0), int(change.destination_box_slot or 0),
                    )
                    dragged = self._pokemon_from_snapshot(
                        change.incoming_snapshot, slot=destination_pos[1], projected=False,
                    )
                    dragged.box, dragged.box_slot, dragged.slot = (
                        destination_pos[0], destination_pos[1], destination_pos[1],
                    )
                    displaced = self._pokemon_from_snapshot(
                        change.outgoing_snapshot, slot=source_pos[1], projected=False,
                    )
                    displaced.box, displaced.box_slot, displaced.slot = (
                        source_pos[0], source_pos[1], source_pos[1],
                    )
                    self._oras_live_pc_empty_overrides.discard(source_pos)
                    self._oras_live_pc_empty_overrides.discard(destination_pos)
                    self._oras_live_pc_overrides[destination_pos] = dragged
                    self._oras_live_pc_overrides[source_pos] = displaced
                    event = {
                        "type": "pc_swapped",
                        "pokemon": change.incoming_pokemon,
                        "species": change.incoming_species,
                        "old_pokemon": change.outgoing_pokemon,
                        "source_box": source_pos[0], "source_box_slot": source_pos[1],
                        "box": destination_pos[0], "box_slot": destination_pos[1],
                        "source": "Azahar en vivo", "output": "RAM",
                    }
                    if not system_generated:
                        self.run.history.append(event)
                        self.project_service.append_history(self.project, event)
                    continue
                if change.operation == "move-box-slot":
                    source_pos = (int(change.box or 0), int(change.box_slot or 0))
                    destination_pos = (
                        int(change.destination_box or 0), int(change.destination_box_slot or 0),
                    )
                    moved = self._pokemon_from_snapshot(
                        change.incoming_snapshot,
                        slot=destination_pos[1], projected=False,
                    )
                    moved.box = destination_pos[0]
                    moved.box_slot = destination_pos[1]
                    moved.slot = destination_pos[1]
                    self._oras_live_pc_overrides.pop(source_pos, None)
                    self._oras_live_pc_empty_overrides.add(source_pos)
                    self._oras_live_pc_empty_overrides.discard(destination_pos)
                    self._oras_live_pc_overrides[destination_pos] = moved
                    event = {
                        "type": "pc_moved",
                        "pokemon": change.incoming_pokemon,
                        "species": change.incoming_species,
                        "source_box": source_pos[0], "source_box_slot": source_pos[1],
                        "box": destination_pos[0], "box_slot": destination_pos[1],
                        "source": "Azahar en vivo", "output": "RAM",
                    }
                    if not system_generated:
                        self.run.history.append(event)
                        self.project_service.append_history(self.project, event)
                    continue
                confirmed_incoming_role = str(change.incoming_role or "SIN ROL")
                if change.incoming_identity:
                    confirmed_incoming = next((
                        pokemon for pokemon in result.game.party
                        if self._pokemon_identity(pokemon) == change.incoming_identity
                    ), None)
                    if confirmed_incoming is not None:
                        live_role = canonical_role(confirmed_incoming.role)
                        if live_role in ROLE_ORDER:
                            confirmed_incoming_role = live_role
                if change.operation == "party-to-box":
                    event = {
                        "type": "team_to_pc",
                        "pokemon": change.outgoing_pokemon,
                        "species": change.outgoing_species,
                        "box": change.box,
                        "box_slot": change.box_slot,
                        "source": "Azahar en vivo",
                        "output": "RAM",
                    }
                elif change.operation == "box-to-party":
                    event = {
                        "type": "pc_to_team",
                        "pokemon": change.incoming_pokemon,
                        "species": change.incoming_species,
                        "role": confirmed_incoming_role,
                        "box": change.box,
                        "box_slot": change.box_slot,
                        "source": "Azahar en vivo",
                        "output": "RAM",
                    }
                else:
                    event = {
                        "type": "team_pc_swap",
                        "pokemon": change.incoming_pokemon,
                        "species": change.incoming_species,
                        "old_pokemon": change.outgoing_pokemon,
                        "role": confirmed_incoming_role,
                        "box": change.box,
                        "box_slot": change.box_slot,
                        "source": "Azahar en vivo",
                        "output": "RAM",
                    }
                outgoing_identity = str(change.outgoing_identity or "")
                outgoing_role = str(change.outgoing_snapshot.get("role", "SIN ROL")) if change.outgoing_snapshot else "SIN ROL"

                if change.operation == "replace-fainted":
                    # La casilla del sustituto queda vacía en la RAM viva. El
                    # debilitado no vuelve a esa posición: se conserva en la
                    # caja de Cementerio con su último rol utilizado.
                    source_pos = (int(change.box), int(change.box_slot))
                    self._oras_live_pc_overrides.pop(source_pos, None)
                    self._oras_live_pc_empty_overrides.add(source_pos)

                    if (
                        change.outgoing_snapshot
                        and change.graveyard_box is not None
                        and change.graveyard_box_slot is not None
                    ):
                        grave_pos = (int(change.graveyard_box), int(change.graveyard_box_slot))
                        outgoing = self._pokemon_from_snapshot(
                            change.outgoing_snapshot, slot=grave_pos[1], projected=False,
                        )
                        outgoing.box = grave_pos[0]
                        outgoing.box_slot = grave_pos[1]
                        outgoing.slot = grave_pos[1]
                        self._oras_live_pc_empty_overrides.discard(grave_pos)
                        self._oras_live_pc_overrides[grave_pos] = outgoing
                        outgoing_identity = outgoing_identity or self._pokemon_identity(outgoing)
                        if outgoing_role in ROLE_TO_KEY:
                            self.project.managed_pokemon_roles[outgoing_identity] = outgoing_role
                        else:
                            self.project.managed_pokemon_roles.pop(outgoing_identity, None)

                    if change.incoming_snapshot:
                        incoming = self._pokemon_from_snapshot(change.incoming_snapshot)
                        incoming_identity = change.incoming_identity or self._pokemon_identity(incoming)
                        if confirmed_incoming_role in ROLE_TO_KEY:
                            self.project.managed_pokemon_roles[incoming_identity] = confirmed_incoming_role
                        else:
                            self.project.managed_pokemon_roles.pop(incoming_identity, None)

                    if (
                        outgoing_identity
                        and change.graveyard_box is not None
                        and change.graveyard_box_slot is not None
                    ):
                        self.project_service.resolve_detected_faint(
                            self.project, outgoing_identity,
                            box=int(change.graveyard_box),
                            box_slot=int(change.graveyard_box_slot),
                            substitute=change.incoming_pokemon,
                        )
                    # resolve_detected_faint registra el historial específico.
                    # Evitamos añadir también el genérico team_pc_swap.
                    event = None
                else:
                    # PC→Equipo deja vacío el slot origen; Equipo→PC y swap dejan
                    # allí al Pokémon saliente. Estas overrides son solo una capa
                    # visual inmediata hasta la siguiente reconciliación PC live.
                    if (
                        change.operation == "box-to-party"
                        and change.box is not None and change.box_slot is not None
                    ):
                        source_pos = (int(change.box), int(change.box_slot))
                        self._oras_live_pc_overrides.pop(source_pos, None)
                        self._oras_live_pc_empty_overrides.add(source_pos)
                    if change.outgoing_snapshot and change.box is not None and change.box_slot is not None:
                        outgoing = self._pokemon_from_snapshot(
                            change.outgoing_snapshot, slot=int(change.box_slot), projected=False,
                        )
                        outgoing.box = int(change.box)
                        outgoing.box_slot = int(change.box_slot)
                        outgoing.slot = int(change.box_slot)
                        self._oras_live_pc_empty_overrides.discard((int(change.box), int(change.box_slot)))
                        self._oras_live_pc_overrides[(int(change.box), int(change.box_slot))] = outgoing
                        outgoing_identity = outgoing_identity or self._pokemon_identity(outgoing)
                        if outgoing_role in ROLE_TO_KEY:
                            self.project.managed_pokemon_roles[outgoing_identity] = outgoing_role
                        else:
                            self.project.managed_pokemon_roles.pop(outgoing_identity, None)
                    if change.incoming_snapshot:
                        incoming = self._pokemon_from_snapshot(change.incoming_snapshot)
                        incoming_identity = change.incoming_identity or self._pokemon_identity(incoming)
                        if confirmed_incoming_role in ROLE_TO_KEY:
                            self.project.managed_pokemon_roles[incoming_identity] = confirmed_incoming_role
                        else:
                            self.project.managed_pokemon_roles.pop(incoming_identity, None)
            else:
                # Este método solo se alcanza después del filtro anterior, pero
                # mantenemos una barrera defensiva para no registrar una acción
                # que no haya sido escrita por el escritor seguro.
                continue
            if event is not None and not system_generated:
                self.run.history.append(event)
                self.project_service.append_history(self.project, event)

        if self.run.role_rules_activation_pending:
            self._set_role_rules_active()
        self.project.save_path = str(self.current_save.path)
        if marker_migration:
            self.project.role_marker_layout = 2
            self.native_save_engine.set_role_marker_layout(2)
            if self._active_azahar_realtime_key() == "bdsp":
                self._bdsp_marker_migration_change_ids.difference_update(current_ids)
                self._bdsp_marker_migration_expected.clear()
        self.project_service.save(self.project)

        # REVISAR CAMBIOS en ORAS trabaja sobre acciones ya confirmadas en RAM.
        # Una acción compuesta se conserva como un lote para deshacerla completa.
        is_live_undo = bool(
            self._oras_live_undo_batch is not None
            and current_ids == self._oras_live_undo_inverse_ids
        )
        if is_live_undo:
            target_batch = self._oras_live_undo_batch
            self._oras_live_review_batches = [
                batch for batch in self._oras_live_review_batches
                if batch is not target_batch
            ]
            self._oras_live_undo_batch = None
            self._oras_live_undo_inverse_ids.clear()
        elif (
            changes and not system_generated and not death_generated
            and self._oras_live_batch_is_reversible(changes)
        ):
            # Las utilidades de inventario no se guardan en esta pila: una compra,
            # venta o uso posterior dentro del juego podría hacer peligroso volver
            # a una cantidad antigua. La revisión reversible se centra en las
            # ediciones de Pokémon que RoleRun puede invertir semánticamente.
            self._oras_live_review_batches.append(copy.deepcopy(list(changes)))
            if len(self._oras_live_review_batches) > 60:
                del self._oras_live_review_batches[:-60]

        applied_ids = current_ids
        self._oras_live_auto_apply_ids.difference_update(applied_ids)
        self._oras_live_system_role_assignment_ids.difference_update(applied_ids)
        self._oras_live_role_marker_migration_ids.difference_update(applied_ids)
        self._oras_live_death_replacement_ids.difference_update(applied_ids)
        self.run.pending_changes = [
            change for change in self.run.pending_changes
            if id(change) not in applied_ids
        ]
        self.current_game = result.game
        self._oras_live_health_snapshot = result.game
        followup_ev_changes: list[PendingRoleChange] = []
        if self._active_azahar_realtime_key() in ROLE_EV_WRITER_GAME_KEYS:
            for team_change in changes:
                if not isinstance(team_change, PendingTeamChange) or not team_change.incoming_snapshot:
                    continue
                desired_map = dict(team_change.incoming_snapshot.get("evs", {}) or {})
                if set(desired_map) != set(STAT_KEYS):
                    continue
                incoming = next((
                    member for member in result.game.party
                    if self._pokemon_identity(member) == str(team_change.incoming_identity or "")
                ), None)
                if incoming is None:
                    continue
                old_evs = tuple(int(incoming.evs.get(key, 0)) for key in STAT_KEYS)
                new_evs = tuple(int(desired_map[key]) for key in STAT_KEYS)
                if old_evs == new_evs:
                    continue
                role = canonical_role(incoming.role)
                followup_ev_changes.append(PendingRoleChange(
                    pokemon_slot=int(incoming.slot),
                    pokemon=incoming.nickname or incoming.species,
                    species=incoming.species,
                    old_role=role,
                    new_role=role,
                    pokemon_identity=self._pokemon_identity(incoming),
                    old_evs=old_evs,
                    new_evs=new_evs,
                ))
            if followup_ev_changes:
                self.run.pending_changes.extend(followup_ev_changes)
        self._oras_live_active = True
        previous_watches = (
            self._oras_live_expected_memory_watches
            if self._oras_live_changes_unpersisted else ()
        )
        memory_watches = self._merge_oras_live_memory_watches(
            previous_watches,
            getattr(result, "memory_watches", ()),
        )
        self._begin_oras_live_reconciliation(result.game, memory_watches)
        self._register_party_roles(result.game)
        self._pc_cache = None
        self._pc_cache_signature = None
        self._sync_live_layout(refresh_floating=True)
        self.current_results = []
        self.selected_pokemon = None
        if not self.run.pending_changes:
            self.run.reset_after_save_change()
            # La escritura ya quedó confirmada en RAM; deshacer no debe intentar
            # reconstruir una cola anterior contra un juego que sigue avanzando.
            self._reset_edit_history()
        if death_generated:
            resolved = next((change for change in changes if isinstance(change, PendingTeamChange) and change.operation == "replace-fainted"), None)
            if resolved is not None:
                self.sync_status = (
                    f"☠ {resolved.outgoing_pokemon} → Caja {resolved.graveyard_box} · "
                    f"{resolved.incoming_pokemon} entra como {resolved.incoming_role}"
                )
            else:
                self.sync_status = "☠ Sustitución por debilitado aplicada"
        elif marker_migration:
            self.sync_status = "✓ Marcadores migrados · Líbero 1 · Asesino 2 · Mago 3 · Tanque 4 · Prisma 5 · Support 6"
        elif system_generated:
            self.sync_status = "✓ Juego → RoleRun · rol libre asignado"
        elif changes and all(isinstance(change, PendingPartyHeal) for change in changes):
            emulator_label = "Ryujinx" if self._active_azahar_realtime_key() == "bdsp" else "Azahar"
            self.sync_status = (
                f"✓ Equipo curado en {emulator_label} · {result.applied_count} Pokémon · "
                "PS, estado y PP verificados"
            )
        elif already_applied:
            emulator_label = "Ryujinx" if self._active_azahar_realtime_key() == "bdsp" else "Azahar"
            self.sync_status = (
                f"✓ Ya estaba aplicado en {emulator_label} · {result.applied_count} cambio(s) · "
                "guarda dentro del juego para persistir"
            )
        else:
            emulator_label = "Ryujinx" if self._active_azahar_realtime_key() == "bdsp" else "Azahar"
            self.sync_status = (
                f"✓ Aplicado automáticamente en {emulator_label} · {result.applied_count} cambio(s) · "
                "guarda dentro del juego para persistir"
                if automatic else
                f"✓ Aplicado en {emulator_label} · {result.applied_count} cambio(s) · "
                "guarda dentro del juego para persistir"
            )
        self._update_top_status()
        if followup_ev_changes:
            self.after(140, lambda pending=tuple(followup_ev_changes): self._request_oras_live_auto_apply(pending))
        # Igual que en el monitor juego → RoleRun, una escritura confirmada desde
        # la propia barra NO debe reconstruir la ventana principal retirada. Ese
        # <Map> espurio era la causa de que arrastrar un Pokémon entre roles cerrase
        # la barra. El estado ya está confirmado; dejamos la vista normal pendiente
        # hasta que el usuario vuelva a RoleRun.
        refreshed_global_tm = False
        if self.active_page == "tms" and self._global_tm_context is not None:
            profile, cached_inventory, source_detail = self._global_tm_context
            inventory = dict(cached_inventory)
            for change in changes:
                if not isinstance(change, PendingTMTeach):
                    continue
                # Este punto solo se alcanza tras el readback completo del
                # writer. Actualizar antes produciría una cantidad ficticia.
                if bool(change.consumes_item):
                    inventory[int(change.item_id)] = max(0, int(change.quantity_before) - 1)
            self._global_tm_context = (profile, inventory, source_detail)
            view = self._global_tm_view
            if view is not None and callable(getattr(view, "update_entries", None)):
                view.update_entries(
                    self._global_tm_entries(profile, inventory),
                    tuple(self._projected_party()[:6]),
                    self._entradas_de_drafteos_guardados(),
                )
                refreshed_global_tm = True
        if not refreshed_global_tm:
            self._refresh_main_after_oras_live_write()
        self._schedule_team_integrity_check()
        # Las acciones automáticas ya se ven inmediatamente en juego, Manager y
        # barra. No mostramos el antiguo toast verde "CAMBIO APLICADO": era ruido
        # visual y además obligaba a crear una superposición sobre la barra.
        if not automatic:
            emulator_label = "Ryujinx" if self._active_azahar_realtime_key() == "bdsp" else "Azahar"
            self._show_live_sync_toast(
                f"CAMBIOS YA PRESENTES EN {emulator_label.upper()}" if already_applied else f"CAMBIOS APLICADOS EN {emulator_label.upper()}",
                (
                    f"{result.applied_count} cambio(s) ya coincidían con la RAM de {emulator_label}. "
                    "No se escribió ningún byte; el archivo main no se tocó."
                    if already_applied else
                    f"{result.applied_count} cambio(s) verificados en RAM. El archivo main no se tocó; guarda dentro del juego cuando quieras conservarlos."
                ),
                True,
            )
        self._schedule_oras_live_auto_apply()
        if death_generated:
            self.run.history = self.project_service.history(self.project)

    @staticmethod
    def _pokemon_visibility_identity(pokemon: SavePokemon) -> str:
        nickname = (pokemon.nickname or pokemon.species).strip().casefold()
        return f"{pokemon.species_id}:{nickname}"

    def toggle_role_visibility(self, role: str) -> None:
        if not self.project or not self.current_game:
            return
        role_key = ROLE_TO_KEY.get(role)
        if role_key is None:
            return
        assigned = [pokemon for pokemon in self._projected_party() if self._effective_role(pokemon)[0] == role]
        if len(assigned) != 1:
            self._show_quick_action_toast("NO HAY UN ÚNICO POKÉMON EN ESE ROL")
            return
        pokemon = assigned[0]
        identity = self._pokemon_visibility_identity(pokemon)
        currently_hidden = self.project.hidden_roles.get(role_key) == identity
        if currently_hidden:
            self.project.hidden_roles.pop(role_key, None)
            visible = True
        else:
            self.project.hidden_roles[role_key] = identity
            visible = False
        self.project_service.append_history(self.project, {
            "type": "role_visibility_changed",
            "role": role,
            "pokemon": pokemon.nickname or pokemon.species,
            "visible": visible,
        })
        self._sync_live_layout()
        self._show_quick_action_toast("POKÉMON MOSTRADO" if visible else "POKÉMON OCULTADO")
        if self.active_page == "dashboard":
            self._refresh_dashboard_role_visibility(role)
            self._update_top_status()
        elif self.active_page == "drafts":
            # En Drafteos no hace falta reconstruir toda la aplicación por un cambio de OBS.
            self._update_top_status()
        else:
            self._smooth_render_page()
        self._record_edit_transition()

    def _register_global_hotkeys(self, show_error: bool = False) -> None:
        self.hotkey_registration_errors = []
        if not self.project:
            self.hotkey_manager.stop()
            return
        self.hotkey_registration_errors = self.hotkey_manager.start(self.project.hotkeys)
        if show_error and self.hotkey_registration_errors:
            messagebox.showwarning(
                "Algunos atajos no pudieron activarse",
                "\n".join(self.hotkey_registration_errors),
            )

    def _start_save_watcher(self, path: Path) -> None:
        self.sync_status = "● Vigilando guardado"
        self.save_watcher.start(path)
        # Al abrir una segunda Run todavía estamos en la pantalla de
        # bienvenida. El estado se pintará tras construir la nueva shell.
        if self._shell_built:
            self._update_top_status()

    def _on_watched_save_changed(self, path: Path) -> None:
        generation = self._session_generation
        self.after(0, lambda p=path, g=generation: self._reload_from_watched_save(p, g))

    @perf.timed("ui.reload_from_watched_save")
    def _reload_from_watched_save(self, path: Path, generation: int | None = None) -> None:
        if generation is not None and generation != self._session_generation:
            return
        if not self._shell_built or not self.current_save or Path(path).resolve() != self.current_save.path.resolve():
            return
        if self.run.pending_changes:
            self.sync_status = "⚠ Cambio externo pendiente"
            self._update_top_status()
            return
        try:
            data = self.save_engine.read(path)
            info = self.save_service.inspect(path)
            allowed_move_ids = self.save_engine.valid_moves(path)
        except Exception:
            self.sync_status = "⚠ Esperando a que termine el guardado"
            self._update_top_status()
            return
        self.current_save = info
        live_key = self._active_azahar_realtime_key()
        # Hallazgo del usuario 01-09-2026: en BDSP, el autoguardado de una
        # transición de zona (entrar/salir de un edificio) también dispara este
        # watcher, pero no es el guardado completo del jugador — el archivo en
        # disco puede seguir sin reflejar cambios que ya viven solo en la RAM
        # vigilada en vivo (p. ej. una sustitución de equipo hecha desde
        # RoleRun). Publicar ese `data` de disco pisaba la vista en vivo, ya
        # correcta, con un Pokémon que en la party actual ya no está, hasta que
        # la siguiente reconciliación en vivo (más abajo) lo corregía sola. Con
        # el monitor en vivo activo, el disco deja de ser la fuente de verdad de
        # la party/PC: se sigue reprogramando la reconciliación, pero sin
        # publicar antes esta instantánea.
        live_tracking_active = bool(self._oras_live_active) and live_key in REALTIME_READ_GAME_KEYS
        if not live_tracking_active:
            self.current_game = data
        self._record_bdsp_ui_event(
            "save-watcher-reload",
            live_active=bool(self._oras_live_active),
            monitor_scheduled=bool(self._oras_live_monitor_after_id),
            monitor_in_progress=bool(self._oras_live_monitor_in_progress),
            live_tracking_active=live_tracking_active,
        )
        # El propio juego ya ha consolidado (o sustituido) main. Desde este
        # momento no debemos conservar como actual la instantánea de RAM previa.
        self._clear_oras_live_auto_apply()
        self._clear_oras_live_reconciliation()
        self.engine.set_allowed_moves(allowed_move_ids)
        self.run.save_path = info.path
        if not live_tracking_active:
            # Recargar la partida es el momento prometido en el aviso: si antes
            # faltó Internet, se vuelve a intentar la descarga de esas imágenes.
            self._retry_placeholder_sprites()
            result = self._sync_obs_state(data)
            self.sync_status = "⚠ Conflicto de roles" if result.get("status") == "conflict" else "✓ Sincronizado con el guardado"
            for pokemon in data.party:
                if pokemon.species_id not in self.sprite_pil_cache:
                    self._load_sprite_async(pokemon)
            self._pc_cache = None
            self._pc_cache_signature = None
            self._smooth_render_page(preserve_scroll=(self.active_page == "team"))
            self._schedule_team_integrity_check()
        # El watcher sustituye la vista viva por la copia consolidada y
        # _clear_oras_live_reconciliation cancela el timer/baseline. Todos los
        # backends realtime registrados deben rearmar su reader; limitarlo a
        # ORAS dejó BDSP en live_active=True pero sin Core snapshot ni monitor.
        if self._oras_live_active and live_key in REALTIME_READ_GAME_KEYS:
            self._schedule_oras_live_reconciliation(650)

    def _sync_obs_state(self, data: SaveGameData | None = None) -> dict[str, str]:
        if not self.project or not (data or self.current_game):
            return {"status": "inactive"}
        result = self.obs_sync.sync(self.project, data or self.current_game)
        if result.get("status") == "conflict":
            self.sync_status = f"⚠ Conflicto: {result.get('conflicts', 'roles duplicados')}"
        return result

    def _manual_obs_sync(self) -> None:
        result = self._sync_obs_state(self.current_game)
        self.sync_status = "⚠ Conflicto de roles" if result.get("status") == "conflict" else "✓ OBS sincronizado"
        self._smooth_render_page()

    def _on_close(self) -> None:
        if self.run.pending_changes:
            if self._uses_instant_realtime_ui():
                # En el Real-Time Core 3DS no existe ya un segundo flujo de
                # guardado desde RoleRun. Las acciones confirmadas viven en el emulador; solo
                # avisamos por aquellas que todavía quedaron pendientes.
                emulator_label = (
                    "Ryujinx" if getattr(self.save_engine, "key", "") == "bdsp" else
                    "Azahar"
                )
                if not messagebox.askokcancel(
                    "Cambios no aplicados",
                    f"Hay cambios que todavía no han sido confirmados en {emulator_label}. Si cierras RoleRun Manager, esas acciones pendientes se descartarán.\n\n"
                    "Los cambios que ya aparecen dentro del juego no se perderán por cerrar RoleRun; quedan definitivos cuando guardes desde el propio juego.\n\n"
                    "¿Cerrar RoleRun Manager?",
                    parent=self,
                ):
                    return
            else:
                answer = messagebox.askyesnocancel(
                    "Cambios sin guardar",
                    "Hay cambios pendientes. ¿Quieres guardarlos antes de cerrar RoleRun Manager?",
                    parent=self,
                )
                if answer is None:
                    return
                if answer:
                    self.save_pending_changes()
                    if self.run.pending_changes or self._pending_ds_install is not None:
                        return
        self._shutdown_application()

    # ---------- RENDER FLOW ----------

    def _restore_body_scroll_px_immediate(self, offset_px: float) -> None:
        """Restaura el scroll de forma síncrona, antes de volver a permitir pintura."""
        target_px = max(0.0, float(offset_px))
        try:
            self.update_idletasks()
        except Exception:
            pass
        metrics = self._body_scroll_metrics()
        if metrics is None:
            return
        canvas, total_height, max_scroll, _current = metrics
        target = min(target_px, max_scroll)
        fraction = 0.0 if total_height <= 0 else max(0.0, min(target / total_height, 1.0))
        try:
            canvas.yview_moveto(fraction)
            self._smooth_scroll_target_px = target
        except Exception:
            return

    def _scroll_team_to_identity_immediate(self, identity: str) -> bool:
        """Coloca la tarjeta indicada a la vista antes de permitir el repintado."""
        if not identity or self.active_page != "team":
            return False
        card = self.team_card_by_identity.get(identity)
        metrics = self._body_scroll_metrics()
        if card is None or metrics is None:
            return False
        canvas, total_height, max_scroll, current = metrics
        try:
            self.update_idletasks()
            viewport_top = float(canvas.winfo_rooty())
            card_top = float(card.winfo_rooty())
            target = max(0.0, min(current + card_top - viewport_top - 18.0, max_scroll))
            fraction = 0.0 if total_height <= 0 else max(0.0, min(target / total_height, 1.0))
            canvas.yview_moveto(fraction)
            self._smooth_scroll_target_px = target
            return True
        except Exception:
            return False

    @perf.timed("ui.smooth_render_page")
    def _resume_deferred_render_after_modal(self) -> None:
        """Retoma un repintado aplazado mientras un `IntegratedWindowSurface`
        seguía abierto. Lo llama ese componente al cerrarse, cuando ya no
        queda ningún otro diálogo igual abierto (ver `_smooth_render_page`).
        """
        requested = self._body_rerender_requested
        self._body_rerender_requested = None
        if requested:
            self.after(0, lambda values=requested: self._smooth_render_page(
                preserve_scroll=values[0], reset_scroll=values[1],
            ))

    def _smooth_render_page(
        self,
        preserve_scroll: bool = False,
        reset_scroll: bool = False,
        _prepared_navigation_overlay=None,
        _navigation_token: int | None = None,
    ) -> None:
        """Reconstruye una vista mediante doble buffer y una barrera compuesta.

        El body visible permanece intacto y por encima mientras un segundo
        CTkScrollableFrame se construye en la misma celda. Solo cuando el árbol nuevo,
        su geometría y su scroll están resueltos se intercambia el orden de apilado.
        Las navegaciones conservan además el último frame completo en un Toplevel
        DWM independiente hasta que el destino ya está compuesto; los refrescos
        internos mantienen su barrera local histórica.
        """
        if self._body_swap_in_progress or getattr(self, "_integrated_modal_count", 0) > 0:
            # Reportado por el usuario 03-09-2026: un diálogo como el de EVs de
            # Líbero es un `IntegratedWindowSurface` -un velo superpuesto sobre
            # este mismo root, no una ventana de sistema aparte-. El sondeo en
            # vivo puede pedir un repintado de Equipo/PC en cualquier momento,
            # también con ese diálogo todavía abierto; los widgets nuevos que
            # cree ese repintado se apilan por encima del velo (son hermanos
            # suyos dentro del mismo root), viéndose la página de fondo encima
            # del diálogo. Igual que ya se hace mientras hay un intercambio de
            # body en marcha, este repintado se aplaza y se retoma solo cuando
            # el diálogo se cierra -ver `_resume_deferred_render_after_modal`-,
            # nunca mientras compite visualmente con él.
            requested = self._body_rerender_requested
            self._body_rerender_requested = (
                bool(preserve_scroll or (requested and requested[0])),
                bool(reset_scroll or (requested and requested[1])),
            )
            # La barrera que traía esta llamada no la va a retirar nadie: el
            # repintado se aplaza y su token se pierde aquí. Sin esto quedaba una
            # ventana opaca encima de una aplicación que ya había terminado.
            if _prepared_navigation_overlay is not None:
                self._finish_navigation_transition(
                    _prepared_navigation_overlay, _navigation_token or 0,
                )
            return

        # Si el estado editable cambió, este render marca el límite de una acción
        # para Ctrl+Z/Ctrl+Shift+Z. Navegar sin editar no genera pasos fantasma.
        self._record_edit_transition()

        if self._aplazar_repintado_de_arranque(
            preserve_scroll, reset_scroll, _prepared_navigation_overlay,
        ):
            return

        # Un refresco interno de Equipo y PC que no cambia la forma de la página
        # no necesita un body nuevo: cambiar los datos cuesta decenas de
        # milisegundos y reconstruirlo, cientos. Las navegaciones y los
        # refrescos que piden volver arriba o enfocar a alguien siguen por el
        # camino de siempre, que es el que mueve el scroll.
        #
        # La decisión NO se escribe aquí en línea: Python cortocircuita el `and`,
        # así que una condición temprana dejaba la reconstrucción sin motivo
        # anotado. Con 30 reconstrucciones medidas y 8 motivos, 22 quedaron sin
        # explicar. Un solo sitio decide y un solo sitio anota.
        if self._refrescar_team_pc_en_sitio(
            _prepared_navigation_overlay, bool(reset_scroll),
        ):
            perf.mark("ui.render.en_sitio", pagina=str(self.active_page))
            # Lo que `render_page()` hace fuera del body: no está en el doble
            # buffer, así que aquí se hace igual que allí.
            self._render_sidebar()
            self._update_top_status()
            self._render_context_navigation()
            return
        scroll_px = self._capture_body_scroll_px() if preserve_scroll else 0.0
        scroll_fraction = self._capture_body_scroll_fraction() if preserve_scroll else 0.0

        old_body = self.body
        old_draft_view = self._draft_view
        old_team_pc_view = self._team_pc_view
        old_body_visible = bool(
            self._shell_built
            and self._widget_alive(old_body)
            and self._widget_alive(getattr(self, "content", None))
            and str(self.state()) not in {"withdrawn", "iconic"}
        )
        new_body = None
        transition_overlay = _prepared_navigation_overlay
        external_transition = transition_overlay is not None
        self._body_swap_in_progress = True
        try:
            if old_body_visible:
                # Una operación (PC, MT, writer) ya mantiene una superficie DWM
                # independiente encima. Crear además la captura local dejaba dos
                # barreras con ciclos de retirada distintos; al cerrar MT podía
                # sobrevivir la copia oscura del selector aunque el loader real
                # ya hubiera terminado.
                if transition_overlay is None and not self._widget_alive(self._busy_indicator):
                    transition_overlay = self._create_page_transition_overlay()
                # Las vistas antiguas dejan de escuchar teclado/resize, pero sus
                # widgets permanecen intactos como buffer visual. Destruir aquí
                # Drafteos era la primera divergencia del glitch entre pestañas:
                # el body viejo quedaba vacío antes de terminar el nuevo.
                for view in (old_draft_view, old_team_pc_view):
                    suspend = getattr(view, "suspend_interaction", None)
                    if callable(suspend):
                        suspend()
                if old_draft_view is not None:
                    self._draft_view = None
                if old_team_pc_view is not None:
                    self._team_pc_view = None
                new_body = self._create_body_widget(below=old_body)
                self.body = new_body
            self.render_page()
            # Resuelve por completo grid/pack y el scrollregion mientras la página
            # anterior continúa siendo la superficie superior.
            self.update_idletasks()
            focus_identity = self._team_focus_identity if self.active_page == "team" else None
            if focus_identity:
                self._scroll_team_to_identity_immediate(focus_identity)
                self.update_idletasks()
                self._team_focus_identity = None
            if reset_scroll and not focus_identity:
                # Las navegaciones también fijan el inicio ANTES de reactivar el
                # repintado. Así nunca se ve un frame de la nueva página heredando
                # la posición vertical de la pestaña anterior.
                self._reset_body_scroll()
                self.update_idletasks()
            elif preserve_scroll:
                # Fracción como fallback y píxeles como valor autoritativo. Repetimos
                # tras un segundo cálculo de geometría para absorber cambios de altura
                # sin recurrir a after_idle (que era el salto visible de 1.12.15).
                self._restore_body_scroll_fraction_immediate(scroll_fraction)
                self._restore_body_scroll_px_immediate(scroll_px)
                self.update_idletasks()
                self._restore_body_scroll_px_immediate(scroll_px)
                self.update_idletasks()
            if new_body is not None and self._widget_alive(old_body):
                # El buffer nuevo se coloca encima, pero mantenemos el anterior
                # unas decenas de milisegundos por debajo. En Windows destruir el
                # viejo en el mismo callback puede dejar un frame del fondo antes
                # de que DWM haya pintado el nuevo, visible como un pestañeo.
                self._stack_body_surface(new_body, old_body, above=True)

                presented_team_pc_view = self._team_pc_view

                def retire_old_body(
                    widget=old_body,
                    committed_body=new_body,
                    committed_view=presented_team_pc_view,
                ) -> None:
                    try:
                        if widget.winfo_exists():
                            widget.grid_forget()
                            widget.destroy()
                    except Exception:
                        pass
                    # Una vista construida no es todavía una vista presentada.
                    # El callback que retira el body anterior puede quedar detrás
                    # de la lectura inicial del PC; hasta esta frontera Windows
                    # continúa enseñando realmente la superficie provisional.
                    if (
                        self.body is committed_body
                        and self._team_pc_view is committed_view
                    ):
                        try:
                            self.update_idletasks()
                        except Exception:
                            pass
                        self._presented_team_pc_view = committed_view
                        if self._initial_shell_waiting:
                            self._retire_initial_shell_when_ready()

                self.after(70, retire_old_body)
            if transition_overlay is not None:
                if external_transition:
                    self._finish_navigation_transition(
                        transition_overlay, int(_navigation_token or 0),
                    )
                else:
                    # Los refrescos internos conservan su barrera local. Las
                    # navegaciones usan la superficie DWM externa preparada.
                    #
                    # 140 ms eran fijos y no dependían de nada: con la página ya
                    # compuesta debajo, la barrera seguía tapándola. Dos
                    # fotogramas bastan para que el destino haya llegado al
                    # compositor, y son ~60 de los ~60 refrescos internos.
                    self.after(
                        32,
                        lambda overlay=transition_overlay: self._retire_page_transition_overlay(overlay),
                    )
            if new_body is None:
                # Durante el primer acceso la raíz permanece retirada para que
                # Windows no llegue a mostrar el árbol provisional. En ese estado
                # no existe un body visible que intercambiar, pero render_page() y
                # update_idletasks() ya han compuesto por completo la superficie
                # que se publicará al retirar la barrera. No marcarla aquí hacía
                # imposible satisfacer la propia barrera: los seis PS renderizados
                # coincidían con RAM, pero `presented` permanecía falso para siempre.
                self._presented_team_pc_view = self._team_pc_view
                if self._initial_shell_waiting:
                    self._retire_initial_shell_when_ready()
        except Exception:
            # Un fallo de render nunca debe dejar una página vacía: conservamos el
            # buffer anterior y retiramos únicamente la construcción incompleta.
            if new_body is not None:
                try:
                    if new_body.winfo_exists():
                        new_body.destroy()
                except Exception:
                    pass
                self.body = old_body
                self._draft_view = old_draft_view
                self._team_pc_view = old_team_pc_view
            if external_transition:
                self._destroy_navigation_transition(transition_overlay)
            else:
                self._retire_page_transition_overlay(transition_overlay)
            raise
        finally:
            self._body_swap_in_progress = False
            requested = self._body_rerender_requested
            self._body_rerender_requested = None
            if requested:
                self.after(0, lambda values=requested: self._smooth_render_page(
                    preserve_scroll=values[0], reset_scroll=values[1],
                ))

    def navigate(self, page: str) -> None:
        self._cancel_help_animations()
        page = normalize_navigation_target(page)
        sidebar_expanded = bool(getattr(self, "sidebar_expanded", False))
        sidebar_closing = bool(
            getattr(self, "sidebar_animation_id", None) and not sidebar_expanded
        )
        if sidebar_expanded or sidebar_closing:
            # Cerrar y renderizar a la vez bloqueaba el hilo de Tk: los callbacks
            # del drawer no podían ejecutarse y el usuario veía varios árboles a
            # medio construir. Primero termina el deslizamiento; después cambia
            # la página con todo el ancho de trabajo ya recuperado.
            self._pending_sidebar_navigation = page
            if sidebar_expanded:
                self._set_sidebar_expanded(False)
            return
        # El menú lateral es una capa temporal. Cualquier destino elegido desde
        # él devuelve inmediatamente el espacio completo a la vista de trabajo.
        close_sidebar = getattr(self, "_set_sidebar_expanded", None)
        if callable(close_sidebar):
            close_sidebar(False)
        # Enlaces históricos y callbacks antiguos continúan siendo válidos,
        # pero Dashboard ya no es un destino visual.
        if page != "moves":
            self._moves_return_page = None
        previous_page = self.active_page
        if page == previous_page:
            # Seleccionar la pestaña ya visible solo cierra el drawer. El vídeo
            # físico alpha.93 demostró que reconstruirla fabricaba un ciclo de
            # carga completo sin que hubiera cambiado ningún estado.
            # Si el destino procedía del drawer, la captura limpia ya no tiene
            # consumidor. Descartarla evita que una navegación posterior use un
            # frame antiguo como autoridad visual.
            self._navigation_source_capture = None
            return
        self._begin_page_navigation(page, previous_page)

    @perf.timed("ui.render_page")
    def render_page(self) -> None:
        # Nunca reconstruir widgets mientras el canvas todavía está animándose.
        # Era otra fuente de pequeños flashes/temblores al cambiar de vista.
        self._cancel_smooth_scroll(sync_target=False)
        if self._draft_view is not None:
            self._draft_view.destroy()
            self._draft_view = None
        if self._global_tm_view is not None:
            self._global_tm_view.destroy()
            self._global_tm_view = None
        self._format_help_view = None
        self._clear(self.body)
        self.step_widgets = {}
        self.sprite_buttons = {}
        self._main_role_drop_targets = []
        if self.active_page == "dashboard":
            self.active_page = DEFAULT_PAGE
        with perf.span("ui.render.sidebar"):
            self._render_sidebar()
        with perf.span("ui.render.estado_superior"):
            self._update_top_status()
        titles = {
            "drafts": ("Drafteos", "Genera movimientos compatibles con el rol del Pokémon."),
            "team": ("Equipo y PC", "Gestiona el equipo y las cajas."),
            "tms": ("Movimientos", "MT de la mochila y drafteos que te guardaste."),
            "moves": ("Movimientos · Consulta de movimientos", "Comprueba qué movimientos admite cada rol en el juego actual."),
            "pc":("Equipo y PC", "Consulta las cajas y reorganiza el equipo desde el mismo espacio."),
            "history": ("Configuración · Registro y recuperación", "Consulta la línea temporal y las opciones de recuperación de la Run."),
            "settings": ("Configuración", "Preferencias y archivos de la Run."),
            "help": ("Ayuda", ""),
        }
        title, subtitle = titles.get(self.active_page, titles["team"])
        self.page_title.configure(text=title)
        responsive_wrap = max(300, min(720, int(self.winfo_width() or 1100) - 700))
        self.page_subtitle.configure(wraplength=responsive_wrap)
        if self.active_page == "help":
            self.page_subtitle.grid_remove()
        else:
            self.page_subtitle.configure(text=subtitle)
            self.page_subtitle.grid()
        with perf.span("ui.render.navegacion_contextual"):
            self._render_context_navigation()
        self._set_body_scrollbar_visible(self.active_page not in {"team", "tms", "pc", "moves", "drafts"})
        with perf.span("ui.render.cuerpo", pagina=str(self.active_page)):
            self._render_page_body()
        # Para qué página es el árbol que hay ahora. Quien quiera reutilizarlo en
        # vez de reconstruirlo tiene que poder comprobarlo, no deducirlo.
        self._pagina_del_body = str(self.active_page)

    def _render_page_body(self) -> None:
        """Pinta solo el cuerpo de la página activa.

        Sale de `render_page` para poder medirlo aparte: en el arranque de BDSP,
        `render_page` cuesta 2585 ms medidos y construir la vista con Tk son 660,
        así que casi dos segundos estaban sin explicar.
        """
        if self.active_page == "drafts":
            self.render_workflow()
        elif self.active_page == "team":
            self._render_team_pc_unified_page()
        elif self.active_page == "tms":
            self._render_global_tm_page()
        elif self.active_page == "moves":
            self._render_moves_page()
        elif self.active_page == "pc":
            self._render_team_pc_unified_page()
        elif self.active_page == "history":
            self._render_history_page()
        elif self.active_page == "settings":
            self._render_settings_page()
        else:
            self._render_help_page()

    def render_workflow(self) -> None:
        self._clear(self.body)
        self.step_widgets = {}
        self.sprite_buttons = {}
        self.draft_card_images = []
        self.draft_role_buttons = {}
        self.draft_pokemon_buttons = {}
        self.draft_move_cards = {}
        self.draft_move_name_labels = {}
        self.draft_move_select_buttons = {}
        self._update_top_status()
        if not self.current_game:
            self._empty_page("No hay partida cargada", "Abre una Run para utilizar los drafteos.", self._return_to_welcome)
            return
        if self.selected_pokemon is not None:
            identity = self._pokemon_identity(self.selected_pokemon)
            fresh = next((
                pokemon for pokemon in self._projected_party()
                if self._pokemon_identity(pokemon) == identity
            ), None)
            if fresh is None:
                self._reset_visual_draft_flow()
            else:
                self.selected_pokemon = fresh
        slots = build_fixed_team_slots(
            self._projected_party(),
            lambda pokemon: self._effective_role(pokemon)[0],
            self._pokemon_identity,
        )
        self._draft_view = IntegratedDraftFlow(
            self.body,
            team_slots=slots,
            selected_pokemon=self.selected_pokemon,
            selected_pool=self.run.role,
            results=self.current_results,
            selected_draft=self.run.draft,
            draft_count=int(self.project.counters.get("drafteos", 0)) if self.project else 0,
            role_names=tuple(self.engine.role_names()),
            role_for=self._effective_role,
            sprite_for=self._team_pc_sprite,
            role_icon_for=self.role_icons.image,
            move_metadata_for=self._draft_move_metadata,
            moves_for=self._effective_moves_for_review,
            on_choose_pokemon=self._draft_choose_visual_pokemon,
            on_choose_move=self.select_drafted_move,
            on_reroll=self.reroll_move,
            on_choose_slot=self.select_move_slot,
            on_save_move=self.guardar_drafteo,
            on_back=self._draft_back,
            on_cancel=self._draft_cancel,
            on_open_moves=self._open_moves_from_draft,
            navigation_keys=self.project.menu_keys if self.project else None,
            on_left_edge=self._select_sidebar_from_content,
            on_edge_accept=self._accept_sidebar_from_content,
            category_icons=self.category_icons,
        )
        self._set_navigation_owner(self._draft_view)
        if self._draft_fade_in_pending:
            self._draft_fade_in_pending = False
            draft_view = self._draft_view
            self.after(0, draft_view.fade_in)

    def _open_moves_from_draft(self) -> None:
        self._moves_return_page = "drafts"
        self.navigate("moves")

    def _return_to_draft_from_moves(self) -> None:
        self._moves_return_page = None
        self.navigate("drafts")

    def _draft_move_metadata(self, move_id: int) -> dict[str, object]:
        move_id = int(move_id or 0)
        if move_id <= 0:
            return {
                "category": "unknown", "pp": "—", "power": "—", "accuracy": "—",
                "type_id": None,
            }
        key = str(getattr(self.save_engine, "key", "") or "")
        pp: int | str = "—"
        power: int | str = "—"
        accuracy: int | str = "—"
        type_id: int | None = None
        description = "Descripción no disponible en la fuente activa."
        if key == "bdsp":
            profile = self._get_bdsp_tm_profile(prompt=False)
            if profile is not None:
                try:
                    pp = int(profile.base_pp(move_id)) or "—"
                    power = int(profile.power(move_id)) or "—"
                    accuracy = int(profile.accuracy(move_id)) or "—"
                    type_id = profile.type_id(move_id)
                    raw_description = str(profile.description(move_id) or "").strip()
                    language = str(getattr(profile, "description_language", "") or "")
                    if raw_description and language.casefold() != "english":
                        description = raw_description
                    else:
                        # El dump del usuario solo trae inglés (confirmado
                        # 2026-09-04: su carpeta Message solo tiene
                        # "english", no hay "spanish"/"es" que ofrecer). En
                        # vez de mostrar el inglés crudo, se reutiliza el
                        # mismo catálogo de descripciones en español ya
                        # cargado para Sol/Luna (``self.gen7_move_metadata``,
                        # PokeAPI) — mismo movimiento, misma descripción,
                        # independientemente del juego. Solo si tampoco está
                        # ahí (movimientos de Gen 8 que BDSP incluye pero
                        # Sol/Luna no conocía) se cae al inglés con aviso.
                        localized = str(
                            self.gen7_move_metadata.get(move_id, {}).get("description_es") or ""
                        ).strip()
                        if localized:
                            description = localized
                        elif raw_description:
                            description = "EN · " + raw_description
                except (TypeError, ValueError):
                    pp = power = accuracy = "—"
        elif key in GEN7_REALTIME_GAME_KEYS:
            metadata = self.gen7_move_metadata.get(move_id, {})
            pp = int(metadata.get("pp") or self.sm_live_move_pp.get(move_id, 0)) or "—"
            power = int(metadata.get("power") or 0) or "—"
            accuracy = int(metadata.get("accuracy") or 0) or "—"
            type_id = metadata.get("type_id")
            localized_description = str(metadata.get("description_es") or "").strip()
            if localized_description:
                description = localized_description
        elif key == "xy":
            metadata = self.xy_move_metadata.get(move_id, {})
            pp = int(metadata.get("pp") or self.oras_live_move_pp.get(move_id, 0)) or "—"
            power = int(metadata.get("power") or 0) or "—"
            accuracy = int(metadata.get("accuracy") or 0) or "—"
            type_id = metadata.get("type_id")
            localized_description = str(metadata.get("description_es") or "").strip()
            if localized_description:
                description = localized_description
        elif key in GEN6_REALTIME_GAME_KEYS:
            metadata = self.oras_move_metadata.get(move_id, {})
            pp = int(metadata.get("pp") or self.oras_live_move_pp.get(move_id, 0)) or "—"
            power = int(metadata.get("power") or 0) or "—"
            accuracy = int(metadata.get("accuracy") or 0) or "—"
            type_id = metadata.get("type_id")
            localized_description = str(metadata.get("description_es") or "").strip()
            if localized_description:
                description = localized_description
        elif key in MELONDS_REALTIME_GAME_KEYS:
            # Potencia, precisión, PP y tipo salen de la ROM cargada: son los
            # valores de esta partida —incluida una randomizada— y no de una
            # tabla fijada de antemano. Cuarta (HGSS/DP/Pt) y quinta (B2W2/BW)
            # traen lectores de ROM distintos; usar el de quinta para cuarta
            # dejaba estos cuatro campos siempre en «—» para HGSS.
            rom = (
                self._get_gen4_rom_profile(key)
                if key in MELONDS_GEN4_REALTIME_GAME_KEYS
                else self._get_b2w2_rom_profile()
            )
            if rom is not None:
                pp = int(rom.base_pp(move_id)) or "—"
                power = int(rom.power(move_id)) or "—"
                accuracy = int(rom.accuracy(move_id)) or "—"
                type_id = rom.type_id(move_id)
            else:
                adaptador = getattr(
                    self, f"{key}_realtime_adapter", None,
                )
                pp = int(
                    adaptador.base_pp_for(move_id) if adaptador is not None else 0
                ) or "—"
            # El texto no depende de la randomización —un randomizer cambia qué
            # MT enseña cada movimiento, no lo que hace el movimiento—, así que
            # se reutiliza el catálogo español que RoleRun ya trae.
            localized_description = str(
                self.oras_move_metadata.get(move_id, {}).get("description_es") or ""
            ).strip()
            if localized_description:
                description = localized_description
        return {
            "category": self._damage_class_for_move(move_id),
            "pp": pp,
            "power": power,
            "accuracy": accuracy,
            "type_id": int(type_id) if isinstance(type_id, int) else None,
            "description": description,
        }

    def _draft_choose_visual_pokemon(self, pokemon: SavePokemon, pool_role: str) -> None:
        if self._team_change_is_locked(show_warning=True):
            return
        draft_count = max(0, int(self.project.counters.get("drafteos", 0))) if self.project else 0
        if draft_count <= 0:
            self._set_operation_status(
                "warning", "SIN DRAFTEOS DISPONIBLES",
                "Aumenta el contador antes de generar opciones.", persistent=True,
            )
            return
        effective_role, _symbol = self._effective_role(pokemon)
        if effective_role == "SIN ROL" or effective_role not in {*self.engine.role_names(), "Líbero"}:
            self._set_operation_status(
                "warning", "POKÉMON EN PREPARACIÓN",
                "Asigna un rol antes de iniciar un drafteo con este Pokémon.", persistent=True,
            )
            return
        generated = self.engine.generate_role(effective_role)
        if not generated:
            self._set_operation_status(
                "failed", "NO SE GENERARON OPCIONES",
                "El pool validado no devolvió movimientos. No se consumió ningún drafteo.", persistent=True,
            )
            return
        self.run.role = effective_role
        self.run.pokemon_slot = int(pokemon.slot)
        self.run.draft = None
        self.run.move_slot = None
        self.selected_pokemon = pokemon
        self.current_results = generated
        self._set_operation_status(
            "neutral", "OPCIONES GENERADAS",
            "Todavía no se ha consumido ningún drafteo.",
        )
        self._draft_transition()

    def _reset_visual_draft_flow(self) -> None:
        self.run.role = None
        self.run.draft = None
        self.run.pokemon_slot = None
        self.run.move_slot = None
        self.selected_pokemon = None
        self.current_results = []

    def _draft_back(self) -> None:
        if self.run.draft is not None:
            self.run.draft = None
            self.run.move_slot = None
        elif self.selected_pokemon is not None:
            self._reset_visual_draft_flow()
        else:
            self._draft_cancel()
            return
        self._draft_transition()

    def _draft_cancel(self) -> None:
        self._reset_visual_draft_flow()
        self._set_operation_status(
            "neutral", "DRAFTEO CANCELADO",
            "No se ha consumido ningún drafteo ni preparado ningún movimiento.",
        )
        if self.active_page == "drafts":
            self._smooth_render_page()

    def _draft_transition(self) -> None:
        self._draft_transition_token += 1
        token = self._draft_transition_token

        def render_next() -> None:
            if token != self._draft_transition_token or self.active_page != "drafts":
                return
            self._draft_fade_in_pending = True
            self._smooth_render_page()

        # El flujo anima únicamente sus tarjetas, textos e imágenes. Cabecera,
        # navegación lateral, barra inferior y ventana conservan siempre opacidad 1.
        draft_view = self._draft_view
        if draft_view is not None and self._widget_alive(draft_view.frame):
            draft_view.fade_out(render_next)
        else:
            self.after(0, render_next)

    def _destroy_draft_steps_from(self, first_step: int) -> None:
        """Destruye solo la parte del flujo que cambia, evitando un flash completo."""
        for step in sorted([n for n in self.step_widgets if n >= first_step], reverse=True):
            widget = self.step_widgets.pop(step, None)
            try:
                if widget is not None and widget.winfo_exists():
                    widget.destroy()
            except Exception:
                pass
        if first_step <= 2:
            self.draft_pokemon_buttons = {}
        if first_step <= 3:
            self.draft_move_cards = {}
            self.draft_move_name_labels = {}
            self.draft_move_select_buttons = {}
        self._schedule_body_scroll_redraw()

    def _refresh_draft_role_buttons(self) -> None:
        draft_count = max(0, int(self.project.counters.get("drafteos", 0))) if self.project else 0
        for role, button in list(self.draft_role_buttons.items()):
            try:
                if not button.winfo_exists():
                    continue
                selected = self.run.role == role
                configurar_si_cambia(
                    button,
                    fg_color="#2A2419" if selected else "#1B1B1B",
                    border_width=2 if selected else 1,
                    border_color=GOLD if selected else "#3A3A3A",
                    text_color=GOLD if selected else TEXT,
                    state="normal" if draft_count > 0 else "disabled",
                )
            except Exception:
                pass

    def _refresh_draft_pokemon_buttons(self) -> None:
        for slot, button in list(self.draft_pokemon_buttons.items()):
            try:
                if not button.winfo_exists():
                    continue
                selected = self.run.pokemon_slot == slot
                configurar_si_cambia(
                    button,
                    fg_color="#2A2419" if selected else PANEL_ALT,
                    hover_color="#332B1D" if selected else "#303030",
                    border_width=2 if selected else 1,
                    border_color=GOLD if selected else "#3A3A3A",
                    text_color=GOLD if selected else TEXT,
                    state="normal",
                )
            except Exception:
                pass

    def _refresh_draft_move_selection(self) -> None:
        for index, result in enumerate(self.current_results):
            selected = bool(
                self.run.draft is not None
                and self.run.draft.pool_key == result["pool_key"]
                and self.run.draft.move_id == int(result["move_id"])
            )
            card = self.draft_move_cards.get(index)
            label = self.draft_move_name_labels.get(index)
            button = self.draft_move_select_buttons.get(index)
            try:
                if card is not None and card.winfo_exists():
                    configurar_si_cambia(
                        card,
                        border_width=2 if selected else 0,
                        border_color=GOLD,
                    )
                if label is not None and label.winfo_exists():
                    configurar_si_cambia(
                        label,
                        text=result["move"],
                        text_color=GOLD if selected else TEXT,
                    )
                if button is not None and button.winfo_exists():
                    configurar_si_cambia(
                        button,
                        text="ELEGIDO" if selected else "ELEGIR",
                        fg_color="#D7B467" if selected else GOLD,
                        hover_color="#E0C17E",
                        border_color=GOLD,
                        text_color="#111111",
                    )
            except Exception:
                pass

    def _role_rules_are_active(self) -> bool:
        # ``role_rules_active`` se conserva en JSON por compatibilidad, pero el
        # producto ya no ofrece un estado de reglas desactivadas.
        return self.project is not None

    def _set_role_rules_active(self) -> None:
        if not self.project:
            self.run.role_rules_activation_pending = False
            return
        if self.project.role_rules_active:
            self.run.role_rules_activation_pending = False
            return
        self.project.role_rules_active = True
        self.run.role_rules_activation_pending = False
        self.project_service.save(self.project)

    def _toggle_role_rules(self) -> None:
        """Compatibilidad con callbacks antiguos: las reglas ya no se apagan."""
        if not self.project:
            return
        self.project.role_rules_active = True
        self.run.role_rules_activation_pending = False
        self.project_service.save(self.project)
        self._set_operation_status(
            "neutral",
            "REGLAS ROLERUN ACTIVAS",
            "Los Pokémon SIN ROL siguen disponibles para preparar el equipo, pero no deben combatir todavía.",
        )

    def _show_rules_mode_toast(self, active: bool) -> None:
        toast = ctk.CTkFrame(
            self, fg_color="#151515", corner_radius=16, border_width=2,
            border_color=SUCCESS if active else GOLD,
        )
        toast.place(relx=0.57, rely=0.5, anchor="center")
        ctk.CTkLabel(
            toast, text="✓  REGLAS DE ROL · ON" if active else "REGLAS DE ROL · OFF",
            text_color=SUCCESS if active else GOLD,
            font=ctk.CTkFont("Segoe UI", 17, "bold"),
        ).pack(padx=30, pady=(18, 2))
        ctk.CTkLabel(
            toast,
            text="Las restricciones RoleRun están activas" if active else "Modo libre: las restricciones RoleRun están desactivadas",
            text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12, "bold"),
        ).pack(padx=30, pady=(0, 18))
        toast.lift()
        self.after(1250, toast.destroy)

    def _show_rules_activation_toast(self, pending: bool = False) -> None:
        toast = ctk.CTkFrame(self, fg_color="#151515", corner_radius=16, border_width=2, border_color=GOLD)
        toast.place(relx=0.57, rely=0.5, anchor="center")
        ctk.CTkLabel(
            toast, text="◷  ACTIVACIÓN PREPARADA" if pending else "✓  REGLAS DE ROL ACTIVAS",
            text_color=GOLD if pending else SUCCESS,
            font=ctk.CTkFont("Segoe UI", 17, "bold"),
        ).pack(padx=30, pady=(18, 2))
        ctk.CTkLabel(
            toast,
            text="Guarda los cambios para completar la activación" if pending else "Las restricciones ya se aplican a esta Run",
            text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12, "bold"),
        ).pack(padx=30, pady=(0, 18))
        toast.lift()
        self.after(1500, toast.destroy)

    def _activate_role_rules(self) -> None:
        if not self.project or not self.current_game:
            return
        if self.project.role_rules_active:
            return
        if self.run.role_rules_activation_pending:
            messagebox.showinfo(
                "Activación pendiente",
                "La activación ya está preparada. Guarda los cambios pendientes para completarla.",
            )
            return

        relevant_pending = any(
            isinstance(change, (PendingRoleChange, PendingChange, PendingTMTeach))
            for change in self.run.pending_changes
        )
        if relevant_pending:
            messagebox.showinfo(
                "Guarda primero los cambios",
                "Antes de activar las reglas de rol, guarda o descarta los cambios de rol y movimientos que ya tengas pendientes.\n\n"
                "Así la fase de preparación se cierra siempre sobre un estado real y verificable del guardado.",
            )
            return

        issues, unassigned = self._collect_team_move_issues()
        # SIN ROL es un estado de preparación permitido. Incluso tras activar las
        # reglas, esos Pokémon pueden permanecer en la party para entrenarse o
        # aprender movimientos; simplemente no son aptos para combatir todavía.

        conflicts = self._team_role_conflicts()
        if conflicts:
            roles = ", ".join(conflicts)
            messagebox.showwarning(
                "Hay roles repetidos",
                "Antes de activar las reglas no puede haber dos Pokémon activos con el mismo rol.\n\n"
                f"Roles repetidos: {roles}",
            )
            return

        if not issues:
            preparation_note = ""
            if unassigned:
                preparation_note = (
                    f"\n\nHay {len(unassigned)} Pokémon SIN ROL. Podrán seguir en el equipo para prepararlos, "
                    "pero no deberán usarse en combate RoleRun hasta recibir uno."
                )
            if not messagebox.askyesno(
                "Activar reglas de rol",
                "Las reglas de rol se activarán para esta Run. Puedes volver a desactivarlas cuando quieras desde el Dashboard.\n\n"
                "¿Quieres continuar?" + preparation_note,
            ):
                return
            self._set_role_rules_active()
            self._smooth_render_page()
            self._show_rules_activation_toast(pending=False)
            return

        self._open_rules_activation_review(issues)

    def _open_rules_activation_review(self, issues: list[dict]) -> None:
        window = IntegratedWindowSurface(self)
        self._apply_window_icon(window)
        window.title("Activar reglas de rol")
        window.geometry("780x620")
        window.minsize(720, 560)
        window.configure(fg_color=BG)
        window.transient(self)
        window.grab_set()

        header = ctk.CTkFrame(window, fg_color="#111111", corner_radius=0)
        header.pack(fill="x")
        ctk.CTkLabel(
            header, text="ACTIVAR REGLAS DE ROL", text_color=TEXT,
            font=ctk.CTkFont("Segoe UI", 25, "bold"),
        ).pack(anchor="w", padx=28, pady=(24, 4))
        ctk.CTkLabel(
            header,
            text="La fase de preparación termina justo antes del primer líder de gimnasio.",
            text_color=MUTED, font=ctk.CTkFont("Segoe UI", 12),
        ).pack(anchor="w", padx=28, pady=(0, 20))

        notice = ctk.CTkFrame(window, fg_color="#2A2011", corner_radius=14, border_width=1, border_color=GOLD)
        notice.pack(fill="x", padx=24, pady=(18, 10))
        ctk.CTkLabel(
            notice, text=f"⚠  {len(issues)} MOVIMIENTO(S) INCOMPATIBLE(S)",
            text_color=GOLD, font=ctk.CTkFont("Segoe UI", 15, "bold"),
        ).pack(anchor="w", padx=18, pady=(14, 3))
        ctk.CTkLabel(
            notice,
            text=("Para activar las reglas, estos movimientos deben desaparecer. En ORAS conectado, los borrados "
                  "se aplican automáticamente en Azahar; en los motores clásicos se mantienen como cambios pendientes."),
            text_color=TEXT, wraplength=700, justify="left",
            font=ctk.CTkFont("Segoe UI", 11),
        ).pack(anchor="w", padx=18, pady=(0, 14))

        scroll = ctk.CTkScrollableFrame(window, fg_color=PANEL, corner_radius=12)
        scroll.pack(fill="both", expand=True, padx=24, pady=(0, 12))
        for issue in issues:
            line = ctk.CTkFrame(scroll, fg_color=PANEL_ALT, corner_radius=10)
            line.pack(fill="x", padx=6, pady=5)
            ctk.CTkLabel(
                line, text=f"{issue['pokemon'].nickname or issue['pokemon'].species} · {issue['move_name']}",
                text_color=TEXT, font=ctk.CTkFont("Segoe UI", 13, "bold"),
            ).pack(anchor="w", padx=14, pady=(10, 1))
            ctk.CTkLabel(
                line, text=issue["reason"], text_color=DANGER,
                font=ctk.CTkFont("Segoe UI", 10),
            ).pack(anchor="w", padx=14, pady=(0, 10))

        actions = ctk.CTkFrame(window, fg_color="#111111", corner_radius=0)
        actions.pack(fill="x")
        ctk.CTkButton(
            actions, text="CANCELAR", command=window.destroy,
            width=120, height=40, fg_color="transparent", border_width=1,
            border_color="#4A4A4A", hover_color=PANEL_ALT, text_color=MUTED,
        ).pack(side="right", padx=(8, 24), pady=16)
        ctk.CTkButton(
            actions, text="ACTIVAR Y ELIMINAR INCOMPATIBLES",
            command=lambda w=window, found=issues: self._prepare_role_rules_activation(found, w),
            width=300, height=42, fg_color=GOLD, hover_color="#D8B875",
            text_color="#111111", font=ctk.CTkFont("Segoe UI", 11, "bold"),
        ).pack(side="right", padx=8, pady=16)

    def _prepare_role_rules_activation(self, issues: list[dict], window=None) -> None:
        pending_ids_before = {id(change) for change in self.run.pending_changes}
        queued = self._append_invalid_move_removals(issues)
        self.run.role_rules_activation_pending = True
        if window is not None and window.winfo_exists():
            window.destroy()
        self._smooth_render_page()
        self._show_rules_activation_toast(pending=True)
        self._request_oras_live_auto_apply_since(pending_ids_before)

    def _render_dashboard(self) -> None:
        if not self.current_game or not self.project:
            hero = ctk.CTkFrame(self.body, fg_color=PANEL, corner_radius=18, border_width=1, border_color=PANEL_ALT)
            hero.grid(row=0, column=0, sticky="ew", pady=(5, 18))
            ctk.CTkLabel(hero, text="TU ROLERUN EMPIEZA AQUÍ", text_color=GOLD,
                         font=ctk.CTkFont("Segoe UI", 12, "bold")).pack(anchor="w", padx=25, pady=(24, 5))
            ctk.CTkLabel(hero, text="Abre una partida para crear o continuar su Run.", text_color=TEXT,
                         font=ctk.CTkFont("Segoe UI", 23, "bold")).pack(anchor="w", padx=25)
            ctk.CTkButton(hero, text="ABRIR PARTIDA Y CREAR RUN", command=self.select_save,
                          height=46, fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
                          font=ctk.CTkFont("Segoe UI", 11, "bold")).pack(anchor="w", padx=25, pady=24)
            return

        projected_party = self._projected_party()
        conflicts = self._team_role_conflicts(projected_party) if self.project.role_rules_active else {}
        unassigned = self._unassigned_active_pokemon(projected_party) if self.project.role_rules_active else []

        summary = ctk.CTkFrame(self.body, fg_color="#181818", corner_radius=20, border_width=1, border_color="#343434")
        dashboard_right_gutter = 18
        summary.grid(row=0, column=0, sticky="ew", padx=(0, dashboard_right_gutter), pady=(4, 16))
        summary.grid_columnconfigure(0, weight=1)
        ctk.CTkLabel(summary, text=self._game_label(), text_color=TEXT,
                     font=ctk.CTkFont("Segoe UI", 28, "bold")).grid(row=0, column=0, sticky="w", padx=22, pady=(18, 2))
        ctk.CTkLabel(summary, text=self._trainer_label(), text_color=MUTED,
                     font=ctk.CTkFont("Segoe UI", 19, "bold")).grid(row=1, column=0, sticky="w", padx=22, pady=(0, 18))
        rules_panel = ctk.CTkFrame(
            self.body,
            fg_color="#132017" if self.project.role_rules_active else "#211D13",
            corner_radius=16, border_width=1,
            border_color=SUCCESS if self.project.role_rules_active else GOLD,
        )
        rules_panel.grid(row=1, column=0, sticky="ew", padx=(0, dashboard_right_gutter), pady=(0, 12))
        # El panel no empuja el toggle hasta el borde derecho. Dejamos una zona de
        # aire también a su derecha para que texto + acciones formen un bloque más
        # equilibrado dentro de la tarjeta.
        rules_panel.grid_columnconfigure(0, weight=3)
        rules_panel.grid_columnconfigure(1, weight=0)
        rules_panel.grid_columnconfigure(2, weight=0)
        rules_panel.grid_columnconfigure(3, weight=1)
        rules_active = bool(self.project.role_rules_active)
        has_context_action = bool(rules_active and (conflicts or unassigned))
        rules_toggle_column = 2 if has_context_action else 1
        ctk.CTkButton(
            rules_panel,
            text="REGLAS · ON" if rules_active else "REGLAS · OFF",
            command=self._toggle_role_rules, width=140, height=40,
            fg_color=SUCCESS if rules_active else "transparent",
            hover_color="#3D8A59" if rules_active else "#332B1D",
            border_width=1, border_color=SUCCESS if rules_active else GOLD,
            text_color="#111111" if rules_active else GOLD,
            font=ctk.CTkFont("Segoe UI", 10, "bold"),
        ).grid(row=0, column=rules_toggle_column, rowspan=2, padx=(16, 10), pady=12)
        if self.project.role_rules_active:
            if conflicts:
                rules_panel.configure(fg_color="#251818", border_color=DANGER, border_width=2)
                issue_parts = [", ".join(f"{role} ×{len(members)}" for role, members in conflicts.items())]
                ctk.CTkLabel(
                    rules_panel, text="⚠  CONFLICTO DE ROLES", text_color=DANGER,
                    font=ctk.CTkFont("Segoe UI", 16, "bold"),
                ).grid(row=0, column=0, sticky="w", padx=18, pady=(13, 2))
                ctk.CTkLabel(
                    rules_panel, text=" · ".join(issue_parts) + ". Resuélvelo antes de considerar el equipo listo para combate.",
                    text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12, "bold"),
                ).grid(row=1, column=0, sticky="w", padx=18, pady=(0, 13))
                ctk.CTkButton(
                    rules_panel, text="RESOLVER", command=self._prompt_current_team_conflicts,
                    width=150, height=40, fg_color=DANGER, hover_color="#B84B4B",
                    text_color="#FFFFFF", font=ctk.CTkFont("Segoe UI", 10, "bold"),
                ).grid(row=0, column=1, rowspan=2, padx=(12, 4), pady=12)
            elif unassigned:
                rules_panel.configure(fg_color="#211D13", border_color=GOLD, border_width=2)
                ctk.CTkLabel(
                    rules_panel, text="◷  EQUIPO EN PREPARACIÓN", text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 16, "bold"),
                ).grid(row=0, column=0, sticky="w", padx=18, pady=(13, 2))
                ctk.CTkLabel(
                    rules_panel,
                    text=f"{len(unassigned)} Pokémon sin rol. Puedes guardar y prepararlos con normalidad, pero no deben usarse en combate RoleRun hasta asignarles uno.",
                    text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12, "bold"), wraplength=850, justify="left",
                ).grid(row=1, column=0, sticky="w", padx=18, pady=(0, 13))
                ctk.CTkButton(
                    rules_panel, text="ASIGNAR ROL", command=self._prompt_current_team_conflicts,
                    width=150, height=40, fg_color=GOLD, hover_color="#D3AF70",
                    text_color="#111111", font=ctk.CTkFont("Segoe UI", 10, "bold"),
                ).grid(row=0, column=1, rowspan=2, padx=(12, 4), pady=12)
            else:
                ctk.CTkLabel(
                    rules_panel, text="✓  REGLAS DE ROL ACTIVAS", text_color=SUCCESS,
                    font=ctk.CTkFont("Segoe UI", 16, "bold"),
                ).grid(row=0, column=0, sticky="w", padx=18, pady=(13, 2))
                ctk.CTkLabel(
                    rules_panel, text="Cada Pokémon listo para combatir tiene un rol único y su moveset debe respetarlo.",
                    text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12),
                ).grid(row=1, column=0, sticky="w", padx=18, pady=(0, 13))
        else:
            self.run.role_rules_activation_pending = False
            ctk.CTkLabel(
                rules_panel, text="MODO LIBRE · REGLAS DE ROL OFF", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 16, "bold"),
            ).grid(row=0, column=0, sticky="w", padx=18, pady=(13, 2))
            ctk.CTkLabel(
                rules_panel,
                text="Puedes preparar el equipo sin restricciones. Activa o desactiva las reglas cuando quieras con el botón ON/OFF.",
                text_color=TEXT, font=ctk.CTkFont("Segoe UI", 12),
            ).grid(row=1, column=0, sticky="w", padx=18, pady=(0, 13))

        ctk.CTkLabel(self.body, text="ESTADO DE LA RUN", text_color=TEXT,
                     font=ctk.CTkFont("Segoe UI", 19, "bold")).grid(row=2, column=0, sticky="w", pady=(8, 10))
        counters = ctk.CTkFrame(self.body, fg_color="transparent")
        counters.grid(row=3, column=0, sticky="ew", padx=(0, dashboard_right_gutter))
        counters.grid_columnconfigure((0, 1, 2, 3), weight=1)
        definitions = [
            ("vidas", "VIDAS", "♥"),
            ("pociones", "CURACIONES", "⚕"),
            ("medallas", "MEDALLAS", "◆"),
            ("drafteos", "DRAFTEOS", None),
        ]
        self.dashboard_counter_labels = {}
        for col, (key, label, icon) in enumerate(definitions):
            value = int(self.project.counters.get(key, 0))
            card = ctk.CTkFrame(counters, fg_color="#191919", corner_radius=17, border_width=1, border_color="#353535")
            card.grid(row=0, column=col, sticky="nsew", padx=5)
            if key == "drafteos" and self.draft_icon_image is not None:
                ctk.CTkLabel(card, text="", image=self.draft_icon_image).pack(pady=(12, 1))
            else:
                ctk.CTkLabel(card, text=icon or "", text_color=GOLD,
                             font=ctk.CTkFont("Segoe UI Symbol", 24, "bold")).pack(pady=(14, 0))
            value_label = ctk.CTkLabel(card, text=str(value), text_color=TEXT, font=ctk.CTkFont("Segoe UI", 50, "bold"))
            value_label.pack()
            self.dashboard_counter_labels[key] = value_label
            ctk.CTkLabel(card, text=label, text_color=MUTED, font=ctk.CTkFont("Segoe UI", 15, "bold")).pack(pady=(0, 2))
            controls = ctk.CTkFrame(card, fg_color="transparent")
            controls.pack(pady=(10, 14))
            if self._counter_is_automatic(key):
                ctk.CTkLabel(
                    controls, text="AUTOMÁTICO", text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 10, "bold"), height=34,
                ).grid(row=0, column=0, padx=3)
            else:
                ctk.CTkButton(controls, text="−", width=42, height=34, fg_color=PANEL_ALT, hover_color="#333333",
                              command=lambda k=key: self.adjust_run_counter(k, -1)).grid(row=0, column=0, padx=3)
                ctk.CTkButton(controls, text="+", width=42, height=34, fg_color=GOLD, hover_color="#D3AF70",
                              text_color="#111111", command=lambda k=key: self.adjust_run_counter(k, 1)).grid(row=0, column=1, padx=3)

        ctk.CTkLabel(self.body, text="EQUIPO ACTUAL", text_color=TEXT,
                     font=ctk.CTkFont("Segoe UI", 19, "bold")).grid(row=4, column=0, sticky="w", pady=(16, 8))
        strip = ctk.CTkFrame(self.body, fg_color=PANEL, corner_radius=16)
        strip.grid(row=5, column=0, sticky="ew", padx=(0, dashboard_right_gutter))
        strip.grid_columnconfigure(tuple(range(6)), weight=1, uniform="roleslots")
        self.dashboard_sprite_images = {}
        self.dashboard_role_widgets = {}
        pending_slots = {c.pokemon_slot for c in self.run.pending_changes if hasattr(c, "pokemon_slot")}
        role_occupants, role_extras = self._role_slot_occupants(projected_party)

        # Las seis posiciones son CASILLAS DE ROL fijas. El Pokémon se desplaza
        # entre ellas; Líbero siempre sigue siendo la primera, Tanque la segunda…
        for i, role in enumerate(ROLE_ORDER):
            role_key = ROLE_TO_KEY[role]
            symbol = self._role_symbol(role)
            pokemon = role_occupants.get(role)
            identity = self._pokemon_visibility_identity(pokemon) if pokemon else None
            hidden = bool(pokemon and self.project.hidden_roles.get(role_key) == identity)
            pending = bool(pokemon and pokemon.slot in pending_slots)
            card = ctk.CTkFrame(
                strip, fg_color="#141414" if hidden else "#1D1D1D", corner_radius=12,
                border_width=2 if pending else 1,
                border_color=GOLD if pending else ("#474747" if pokemon is None else "#303030"),
            )
            card.grid(row=0, column=i, sticky="nsew", padx=5, pady=8)
            card.grid_columnconfigure(0, weight=1)
            self._main_role_drop_targets.append((card, role))

            eye = ctk.CTkButton(
                card, text="⊘" if hidden else "👁", width=30, height=26, corner_radius=8,
                fg_color="#333333" if hidden else "transparent", hover_color="#3A3A3A",
                border_width=1, border_color=GOLD if pokemon else "#444444",
                text_color=GOLD if pokemon else MUTED,
                state="normal" if pokemon else "disabled",
                command=lambda selected_role=role: self.toggle_role_visibility(selected_role),
            )
            eye.grid(row=0, column=0, sticky="ne", padx=6, pady=6)
            self.dashboard_role_widgets[role_key] = (card, eye)

            if pokemon:
                image = self._sprite_image(pokemon, (138, 108))
                if image is not None:
                    self.dashboard_sprite_images[pokemon.slot] = image
                    ctk.CTkLabel(card, text="", image=image, height=118, fg_color="transparent").grid(row=0, column=0, pady=(10, 0))
                else:
                    ctk.CTkLabel(card, text="", height=118).grid(row=0, column=0)
                ctk.CTkLabel(
                    card, text=pokemon.nickname or pokemon.species, text_color=TEXT,
                    font=ctk.CTkFont("Segoe UI", 20, "bold"), wraplength=165,
                ).grid(row=1, column=0, pady=(6, 0))
                self._register_role_drag_tree(card, pokemon, "main", card, role)
            else:
                ctk.CTkLabel(
                    card, text="—", height=118, text_color="#555555",
                    font=ctk.CTkFont("Segoe UI", 42, "bold"),
                ).grid(row=0, column=0, pady=(10, 0))
                ctk.CTkLabel(
                    card, text="ROL LIBRE", text_color=MUTED,
                    font=ctk.CTkFont("Segoe UI", 14, "bold"),
                ).grid(row=1, column=0, pady=(6, 0))

            # El rótulo pertenece a la casilla y por ello nunca viaja con el Pokémon.
            ctk.CTkLabel(
                card, text=f"{symbol} {role}", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 16, "bold"),
            ).grid(row=2, column=0, pady=(4, 12))
            eye.lift()

        if role_extras:
            prep = ctk.CTkFrame(self.body, fg_color="#171717", corner_radius=14, border_width=1, border_color="#383838")
            prep.grid(row=6, column=0, sticky="ew", padx=(0, dashboard_right_gutter), pady=(10, 0))
            ctk.CTkLabel(
                prep, text="EN PREPARACIÓN · SIN ROL / CONFLICTOS", text_color=MUTED,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).pack(anchor="w", padx=14, pady=(10, 4))
            extras_row = ctk.CTkFrame(prep, fg_color="transparent")
            extras_row.pack(fill="x", padx=10, pady=(0, 10))
            for pokemon in role_extras:
                extra = ctk.CTkFrame(extras_row, fg_color="#202020", corner_radius=10, border_width=1, border_color="#3A3A3A")
                extra.pack(side="left", padx=4, pady=3)
                img = self._sprite_image(pokemon, (52, 52))
                if img is not None:
                    self.dashboard_sprite_images[-1000 - len(self.dashboard_sprite_images)] = img
                    ctk.CTkLabel(extra, text="", image=img).pack(side="left", padx=(7, 3), pady=5)
                ctk.CTkLabel(
                    extra, text=pokemon.nickname or pokemon.species, text_color=TEXT,
                    font=ctk.CTkFont("Segoe UI", 12, "bold"),
                ).pack(side="left", padx=(3, 9), pady=7)
                self._register_role_drag_tree(extra, pokemon, "main", extra, "SIN ROL")


    @staticmethod
    def _inventory_money_max_for_engine(engine_key: str) -> int:
        # B2/W2 escribe RAM en una dirección demostrada, y el único tope
        # demostrado para ella es el que usa la propia utilidad de RoleRun.
        return (
            999_999
            if str(engine_key) in ({"bdsp"} | MELONDS_REALTIME_GAME_KEYS)
            else 9_999_999
        )

    def _get_gen5_rom_profile(self, game_key: str):
        """Datos de juego de la ROM que melonDS tiene cargada, o ``None``.

        Un randomizer cambia estadísticas base y datos de movimientos. Sin esto,
        aplicar un rol recalcularía las estadísticas con la tabla original y las
        **escribiría** en la partida. Es el mismo papel que cumple la ROM en
        ORAS y X/Y, aquí resuelto sin preguntar: melonDS guarda la partida junto
        a la ROM y con el mismo nombre.

        Se intenta una sola vez por guardado y por juego. Un fallo no bloquea
        nada: RoleRun sigue con las tablas de quinta original, que es lo correcto
        en una partida sin randomizar.
        """
        game_key = str(game_key)
        if game_key in MELONDS_GEN4_REALTIME_GAME_KEYS:
            # 06-09-2026, bug real: un llamador que pidiera "la ROM de quinta"
            # con el motor de HGSS activo no solo fallaba, sino que dejaba
            # marcado en la caché COMPARTIDA (`_gen5_rom_checked_for`) que ese
            # guardado ya se había intentado -con la clave de discovery
            # equivocada (`discover_gen5_rom` en vez de `discover_gen4_rom`)-,
            # bloqueando para siempre el intento correcto de
            # `_get_gen4_rom_profile`. Cuarta tiene su propia función; esta no
            # la sustituye ni comparte su caché con ella.
            return None
        if str(getattr(self.save_engine, "key", "") or "") != game_key:
            return None
        save_path = str(getattr(self.current_save, "path", "") or "")
        if not save_path:
            return None
        if self._gen5_rom_checked_for.get(game_key) == save_path:
            return self._gen5_rom_profiles.get(game_key)
        self._gen5_rom_checked_for[game_key] = save_path
        self._gen5_rom_profiles[game_key] = None
        self._gen5_rom_last_error[game_key] = None
        try:
            ruta = discover_gen5_rom(save_path, game_key)
            if ruta is None:
                self._gen5_rom_last_error[game_key] = (
                    "No se encontró la ROM junto al guardado."
                )
                return None
            perfil = load_gen5_rom_profile_cached(ruta, game_key)
        except Exception as exc:
            self._gen5_rom_last_error[game_key] = str(exc)
            return None
        try:
            set_personal_override(
                perfil.game.key, perfil.personal, perfil.game.personal_record_size,
            )
        except Exception as exc:
            # Una tabla que no encaja no se instala a medias.
            clear_personal_override(game_key)
            self._gen5_rom_last_error[game_key] = str(exc)
            return None
        self._gen5_rom_profiles[game_key] = perfil
        self._ensure_gen5_levelup_registered(ruta)
        return perfil

    def _ensure_gen5_levelup_registered(self, rom_path) -> None:
        """Decodifica la tabla de aprendizajes de quinta desde la ROM.

        La ROM es la fuente de la verdad vainilla y **se abre siempre en solo
        lectura**: lo que se parchea es la copia que melonDS tiene en memoria,
        nunca el archivo. Localizar la imagen se deja para el primer sondeo
        que la necesite, para no cargar el arranque.
        """
        if str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN5_REALTIME_GAME_KEYS:
            return
        try:
            entradas = gen5_levelup_moves.parse_levelup_narc(rom_path)
        except Exception as exc:
            self._registrar_intento_vivo("gen5_levelup_registro_error", error=str(exc))
            return
        self._gen5_levelup_entries = entradas
        self._gen5_levelup_rom_path = Path(rom_path)
        self._gen5_levelup_image = None
        self._gen5_levelup_last_roles_key = None
        self._registrar_intento_vivo(
            "gen5_levelup_registro_ok",
            especies=len(entradas), rom=str(rom_path),
        )
        if self.current_game is not None:
            self._sync_gen5_levelup_moves(self.current_game)

    def _gen5_levelup_usable_move_ids(self) -> set[int] | None:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else None
        )

    @perf.timed("ui.sync_gen5_levelup_moves")
    def _sync_gen5_levelup_moves(self, game: SaveGameData | None) -> None:
        """Ajusta al rol la tabla de aprendizajes dentro de la RAM de melonDS.

        Equivalente al Enfoque A de los juegos de 3DS, pero sin archivo: se
        escriben los dos bytes del ID de movimiento de cada entrada que no
        encaja con el rol, dejando el nivel intacto. Quinta relee la tabla en
        cada aprendizaje, así que esto basta para que el juego enseñe **y
        anuncie** el movimiento correcto.
        """
        if (
            str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN5_REALTIME_GAME_KEYS
            or game is None
            or self._gen5_levelup_entries is None
            or self._gen5_levelup_rom_path is None
        ):
            return
        self._record_gen5_levelup_move_history(game)
        try:
            roles_by_species: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                roles_by_species[int(pokemon.species_id)] = role
            # Mismo adelanto a las evoluciones futuras que ya hace X/Y: cuando
            # evolucione, su fila lleva un rato correcta y no hay carrera que
            # perder. `setdefault` nunca pisa el rol de un miembro real.
            for species_id, role in list(roles_by_species.items()):
                for descendant in evolution_descendants(species_id):
                    roles_by_species.setdefault(descendant, role)
            roles_key = (
                frozenset(roles_by_species.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key == self._gen5_levelup_last_roles_key:
                return

            patch = gen5_levelup_moves.compute_role_patch(
                self._gen5_levelup_entries, roles_by_species,
                pools=self.engine.pools,
                damage_classes=self.engine.damage_classes,
                speed_status_moves=self.engine.speed_status_moves,
                self_healing_damage_moves=self.engine.self_healing_damage_moves,
                usable_move_ids=self._gen5_levelup_usable_move_ids(),
            )
            # Todo lo que se escribió antes y ya no toca, vuelve a su valor de
            # la ROM. Si no, un rol retirado dejaría su sustituto puesto.
            restaurar = {
                offset: vanilla
                for offset, vanilla in self._gen5_levelup_written.items()
                if offset not in patch
            }
            deseado = {**restaurar, **patch}
            if not deseado:
                self._gen5_levelup_last_roles_key = roles_key
                return

            imagen = self._gen5_levelup_locate_image()
            if imagen is None:
                return
            escritas = imagen.apply(deseado, expected_levels=self._gen5_levelup_levels())
            for offset in restaurar:
                self._gen5_levelup_written.pop(offset, None)
            vanilla_por_offset = self._gen5_levelup_vanilla_moves()
            for offset in patch:
                if offset in vanilla_por_offset:
                    self._gen5_levelup_written[offset] = vanilla_por_offset[offset]
            self._gen5_levelup_last_roles_key = roles_key
            self._registrar_intento_vivo(
                "gen5_levelup_parcheado",
                roles_by_species=roles_by_species,
                entradas=len(deseado), escritas=int(escritas),
            )
        except Exception as exc:
            self._registrar_intento_vivo("gen5_levelup_sync_error", error=str(exc))

    def _gen5_levelup_locate_image(self):
        """La imagen de la ROM en melonDS, revalidando la base ya encontrada."""
        if self._gen5_levelup_entries is None or self._gen5_levelup_rom_path is None:
            return None
        # Mismo criterio que el resto de la interfaz para melonDS: el
        # adaptador del juego ACTIVO, no uno fijo. Blanco/Negro y B2/W2 tienen
        # cada uno el suyo, y pedirle la party al equivocado leería la
        # dirección de otro juego (el fallo real de alpha.62).
        live_key = str(getattr(self.save_engine, "key", "") or "")
        adaptador = getattr(self, f"{live_key}_realtime_adapter", None)
        lector = getattr(adaptador, "reader", None)
        if lector is None:
            return None
        try:
            process_id = int(lector.read_party().process_id)
        except Exception:
            return None
        conocida = getattr(self._gen5_levelup_image, "base_address", None)
        if self._gen5_levelup_image is not None and int(
            getattr(self._gen5_levelup_image, "process_id", -1)
        ) != process_id:
            conocida = None
        try:
            imagen = gen5_levelup_memory.locate_rom_image(
                process_id, self._gen5_levelup_rom_path, self._gen5_levelup_entries,
                known_base=conocida,
            )
        except Exception as exc:
            self._registrar_intento_vivo("gen5_levelup_localizar_error", error=str(exc))
            return None
        if imagen is None:
            self._registrar_intento_vivo("gen5_levelup_imagen_no_encontrada")
            return None
        if self._gen5_levelup_image is None or getattr(
            self._gen5_levelup_image, "base_address", None,
        ) != imagen.base_address:
            self._registrar_intento_vivo(
                "gen5_levelup_imagen_localizada", base=f"0x{imagen.base_address:X}",
            )
        self._gen5_levelup_image = imagen
        return imagen

    def _gen5_levelup_levels(self) -> dict[int, int]:
        """``{desplazamiento: nivel}`` de toda la tabla, tal y como está en la ROM."""
        return {
            offset: level
            for entradas in (self._gen5_levelup_entries or {}).values()
            for _move, level, offset in entradas
        }

    def _gen5_levelup_vanilla_moves(self) -> dict[int, int]:
        """``{desplazamiento: movimiento}`` vainilla, para poder restaurar."""
        return {
            offset: move
            for entradas in (self._gen5_levelup_entries or {}).values()
            for move, _level, offset in entradas
        }

    def _revert_gen5_levelup_moves(self) -> None:
        """Devuelve a la ROM en memoria todo lo que RoleRun escribió."""
        if not self._gen5_levelup_written or self._gen5_levelup_entries is None:
            return
        try:
            imagen = self._gen5_levelup_locate_image()
            if imagen is None:
                return
            imagen.apply(
                dict(self._gen5_levelup_written),
                expected_levels=self._gen5_levelup_levels(),
            )
            self._gen5_levelup_written.clear()
            self._gen5_levelup_last_roles_key = None
        except Exception as exc:
            self._registrar_intento_vivo("gen5_levelup_revertir_error", error=str(exc))

    def _record_gen5_levelup_move_history(self, game: SaveGameData) -> None:
        """Historial para RECUERDA MOVIMIENTOS, igual que en los demás juegos.

        Anota, en el instante del cruce de nivel, qué movimiento le tocaba a
        ese Pokémon por su rol — que es justo el que la tabla parcheada le va
        a enseñar—, para que la pantalla de recordar movimientos pueda
        ofrecérselo después.
        """
        if (
            str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN5_REALTIME_GAME_KEYS
            or self.project is None
            or self._gen5_levelup_entries is None
        ):
            return
        try:
            cambiado = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._gen5_levelup_history_last_levels.get(identity)
                self._gen5_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                entries = self._gen5_levelup_entries.get(species_id)
                if level > 0 and self._purge_gen5_levelup_history_above_level(identity, level):
                    cambiado = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_gen5_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True,
                        ):
                            cambiado = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                role, _symbol = self._effective_role(pokemon)
                if self._append_gen5_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                ):
                    cambiado = True
            if cambiado:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("gen5_levelup_history_error", error=str(exc))

    def _append_gen5_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool,
    ) -> bool:
        """Anota en el historial lo que la tabla parcheada le va a enseñar.

        06-09-2026, bug real reportado por el usuario: Patrat aprendió **Llama
        Fusión** y el historial registró **Onda Certera** —los dos compatibles
        con su rol, pero distintos—. La causa: ``compute_species_patch`` excluye
        los movimientos que la especie YA tiene en su tabla, así que calcular
        sobre el subconjunto recién cruzado da un conjunto de exclusiones
        distinto al de la tabla completa, y elige otro sustituto. Medido en la
        ROM real: 13 de las 14 entradas de Patrat discrepaban.

        La corrección de 2026-09-04 (semilla estable por ``clave``) era
        necesaria pero no suficiente: la semilla ya coincidía; lo que no
        coincidía era la exclusión. Se calcula sobre la tabla COMPLETA de la
        especie —lo mismo que hace el parche— y de ahí se leen solo las
        entradas que interesan.
        """
        if not entries:
            return False
        completa = (self._gen5_levelup_entries or {}).get(int(species_id)) or entries
        patch = gen5_levelup_moves.compute_species_patch(
            completa, role, species_id=species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._gen5_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_gen5_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Mirror de ``_purge_xy_levelup_history_above_level``."""
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    def _ensure_hgss_levelup_registered(self, rom_path) -> None:
        """Decodifica la tabla de aprendizajes de HeartGold desde la ROM.

        Mirror de ``_ensure_gen5_levelup_registered``. La ROM es la fuente de
        la verdad vainilla y se abre siempre en solo lectura: lo que se
        parchea es la copia que melonDS tiene en memoria, nunca el archivo.
        """
        if str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN4_REALTIME_GAME_KEYS:
            return
        try:
            entradas = gen4_levelup_moves.parse_levelup_narc(rom_path)
        except Exception as exc:
            self._registrar_intento_vivo("hgss_levelup_registro_error", error=str(exc))
            return
        self._hgss_levelup_entries = entradas
        self._hgss_levelup_rom_path = Path(rom_path)
        self._hgss_levelup_image = None
        self._hgss_levelup_last_roles_key = None
        self._registrar_intento_vivo(
            "hgss_levelup_registro_ok",
            especies=len(entradas), rom=str(rom_path),
        )
        if self.current_game is not None:
            self._sync_hgss_levelup_moves(self.current_game)

    def _hgss_levelup_usable_move_ids(self) -> set[int] | None:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else None
        )

    @perf.timed("ui.sync_hgss_levelup_moves")
    def _sync_hgss_levelup_moves(self, game: SaveGameData | None) -> None:
        """Ajusta al rol la tabla de aprendizajes dentro de la RAM de melonDS.

        Mirror de ``_sync_gen5_levelup_moves``, con la diferencia real de
        formato: cada entrada de HeartGold es un solo u16 empaquetado
        (``gen4_levelup_moves.pack_entry``), así que escribir exige volver a
        empaquetar con el nivel esperado -lo hace ``Gen4RomImage.apply``, no
        aquí-. Si HeartGold cachea la tabla como X/Y o la relee como ORAS
        todavía no se ha probado contra la partida real.
        """
        if (
            str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN4_REALTIME_GAME_KEYS
            or game is None
        ):
            return
        if self._hgss_levelup_entries is None or self._hgss_levelup_rom_path is None:
            # 06-09-2026: a diferencia de quinta, nada más en la interfaz de
            # HeartGold pide la ROM de forma rutinaria -Consulta de Movimientos
            # y Recuerda-Movimientos no la tocan-, así que el registro nunca
            # llegaba a dispararse por sí solo y esta sincronización se
            # quedaba sin tabla para siempre. El propio sondeo periódico la
            # pide aquí: `_get_gen4_rom_profile` ya se controla a sí mismo
            # -un intento por guardado- y llama a
            # `_ensure_hgss_levelup_registered` en cuanto tiene éxito.
            self._get_gen4_rom_profile("hgss")
            if self._hgss_levelup_entries is None or self._hgss_levelup_rom_path is None:
                return
        self._record_hgss_levelup_move_history(game)
        try:
            roles_by_species: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                roles_by_species[int(pokemon.species_id)] = role
            for species_id, role in list(roles_by_species.items()):
                for descendant in evolution_descendants(species_id):
                    roles_by_species.setdefault(descendant, role)
            roles_key = (
                frozenset(roles_by_species.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key == self._hgss_levelup_last_roles_key:
                return

            patch = gen4_levelup_moves.compute_role_patch(
                self._hgss_levelup_entries, roles_by_species,
                pools=self.engine.pools,
                damage_classes=self.engine.damage_classes,
                speed_status_moves=self.engine.speed_status_moves,
                self_healing_damage_moves=self.engine.self_healing_damage_moves,
                usable_move_ids=self._hgss_levelup_usable_move_ids(),
            )
            restaurar = {
                offset: vanilla
                for offset, vanilla in self._hgss_levelup_written.items()
                if offset not in patch
            }
            deseado = {**restaurar, **patch}
            if not deseado:
                self._hgss_levelup_last_roles_key = roles_key
                return

            imagen = self._hgss_levelup_locate_image()
            if imagen is None:
                return
            escritas = imagen.apply(deseado, expected_levels=self._hgss_levelup_levels())
            for offset in restaurar:
                self._hgss_levelup_written.pop(offset, None)
            vanilla_por_offset = self._hgss_levelup_vanilla_moves()
            for offset in patch:
                if offset in vanilla_por_offset:
                    self._hgss_levelup_written[offset] = vanilla_por_offset[offset]
            self._hgss_levelup_last_roles_key = roles_key
            self._registrar_intento_vivo(
                "hgss_levelup_parcheado",
                roles_by_species=roles_by_species,
                entradas=len(deseado), escritas=int(escritas),
            )
        except Exception as exc:
            self._registrar_intento_vivo("hgss_levelup_sync_error", error=str(exc))

    def _hgss_levelup_locate_image(self):
        """La imagen de la ROM en melonDS, revalidando la base ya encontrada."""
        if self._hgss_levelup_entries is None or self._hgss_levelup_rom_path is None:
            return None
        adaptador = getattr(self, "hgss_realtime_adapter", None)
        lector = getattr(adaptador, "reader", None)
        if lector is None:
            return None
        try:
            process_id = int(lector.read_party().process_id)
        except Exception:
            return None
        conocida = getattr(self._hgss_levelup_image, "base_address", None)
        if self._hgss_levelup_image is not None and int(
            getattr(self._hgss_levelup_image, "process_id", -1)
        ) != process_id:
            conocida = None
        try:
            imagen = gen4_levelup_memory.locate_rom_image(
                process_id, self._hgss_levelup_rom_path, self._hgss_levelup_entries,
                known_base=conocida,
            )
        except Exception as exc:
            self._registrar_intento_vivo("hgss_levelup_localizar_error", error=str(exc))
            return None
        if imagen is None:
            self._registrar_intento_vivo("hgss_levelup_imagen_no_encontrada")
            return None
        if self._hgss_levelup_image is None or getattr(
            self._hgss_levelup_image, "base_address", None,
        ) != imagen.base_address:
            self._registrar_intento_vivo(
                "hgss_levelup_imagen_localizada", base=f"0x{imagen.base_address:X}",
            )
        self._hgss_levelup_image = imagen
        return imagen

    def _hgss_levelup_levels(self) -> dict[int, int]:
        """``{desplazamiento: nivel}`` de toda la tabla, tal y como está en la ROM."""
        return {
            offset: level
            for entradas in (self._hgss_levelup_entries or {}).values()
            for _move, level, offset in entradas
        }

    def _hgss_levelup_vanilla_moves(self) -> dict[int, int]:
        """``{desplazamiento: movimiento}`` vainilla, para poder restaurar."""
        return {
            offset: move
            for entradas in (self._hgss_levelup_entries or {}).values()
            for move, _level, offset in entradas
        }

    def _revert_hgss_levelup_moves(self) -> None:
        """Devuelve a la ROM en memoria todo lo que RoleRun escribió."""
        if not self._hgss_levelup_written or self._hgss_levelup_entries is None:
            return
        try:
            imagen = self._hgss_levelup_locate_image()
            if imagen is None:
                return
            imagen.apply(
                dict(self._hgss_levelup_written),
                expected_levels=self._hgss_levelup_levels(),
            )
            self._hgss_levelup_written.clear()
            self._hgss_levelup_last_roles_key = None
        except Exception as exc:
            self._registrar_intento_vivo("hgss_levelup_revertir_error", error=str(exc))

    def _record_hgss_levelup_move_history(self, game: SaveGameData) -> None:
        """Historial para RECUERDA MOVIMIENTOS. Mirror de la versión de quinta."""
        if (
            str(getattr(self.save_engine, "key", "") or "") not in MELONDS_GEN4_REALTIME_GAME_KEYS
            or self.project is None
            or self._hgss_levelup_entries is None
        ):
            return
        try:
            cambiado = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._hgss_levelup_history_last_levels.get(identity)
                self._hgss_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                entries = self._hgss_levelup_entries.get(species_id)
                if level > 0 and self._purge_hgss_levelup_history_above_level(identity, level):
                    cambiado = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_hgss_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True,
                        ):
                            cambiado = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                role, _symbol = self._effective_role(pokemon)
                if self._append_hgss_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                ):
                    cambiado = True
            if cambiado:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("hgss_levelup_history_error", error=str(exc))

    def _append_hgss_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool,
    ) -> bool:
        """Anota en el historial lo que la tabla parcheada le va a enseñar.

        Mismo criterio que ``_append_gen5_levelup_history_entries``: calculado
        sobre la tabla COMPLETA de la especie, no sobre el subconjunto recién
        cruzado -son conjuntos de exclusión distintos y eligen sustitutos
        distintos, el bug real que ya se corrigió en los otros cinco juegos-.
        """
        if not entries:
            return False
        completa = (self._hgss_levelup_entries or {}).get(int(species_id)) or entries
        patch = gen4_levelup_moves.compute_species_patch(
            completa, role, species_id=species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._hgss_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_hgss_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Mirror de ``_purge_gen5_levelup_history_above_level``."""
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    def _get_gen4_rom_profile(self, game_key: str):
        """Datos de juego de la ROM de cuarta que melonDS tiene cargada.

        Mismo papel y misma política que en quinta: un randomizer cambia las
        estadísticas base, y sin esto RoleRun las enseñaría mal. Se intenta una
        sola vez por guardado; un fallo no bloquea nada, solo deja las tablas de
        PKHeX, que es lo correcto en una partida sin randomizar.
        """
        game_key = str(game_key)
        motor_key = str(getattr(self.save_engine, "key", "") or "")
        if motor_key != game_key:
            return None
        save_path = str(getattr(self.current_save, "path", "") or "")
        if not save_path:
            return None
        if self._gen5_rom_checked_for.get(game_key) == save_path:
            return self._gen5_rom_profiles.get(game_key)
        self._gen5_rom_checked_for[game_key] = save_path
        self._gen5_rom_profiles[game_key] = None
        self._gen5_rom_last_error[game_key] = None
        try:
            ruta = discover_gen4_rom(save_path, game_key)
            if ruta is None:
                self._gen5_rom_last_error[game_key] = (
                    "No se encontró la ROM junto al guardado."
                )
                _anotar_intento_vivo(
                    self, "rom-cuarta-no-encontrada", guardado=save_path,
                )
                return None
            perfil = load_gen4_rom_profile_cached(ruta, game_key)
        except Exception as exc:
            self._gen5_rom_last_error[game_key] = str(exc)
            _anotar_intento_vivo(self, "rom-cuarta-fallida", motivo=str(exc))
            return None
        try:
            set_personal_override(perfil.game.key, perfil.personal, len(perfil.personal) // perfil.game.personal_count)
        except Exception as exc:
            # Una tabla que no encaja no se instala a medias.
            clear_personal_override(game_key)
            self._gen5_rom_last_error[game_key] = str(exc)
            _anotar_intento_vivo(self, "rom-cuarta-sin-instalar", motivo=str(exc))
            return None
        self._gen5_rom_profiles[game_key] = perfil
        _anotar_intento_vivo(self, "rom-cuarta-cargada", archivo=str(ruta.name))
        if game_key == "hgss":
            self._ensure_hgss_levelup_registered(ruta)
        return perfil

    def _get_b2w2_rom_profile(self):
        """Compatibilidad: el resto de la interfaz sigue preguntando por juego.

        06-09-2026, bug real: desviaba también las llamadas hechas con el
        motor de HGSS conectado hacia ``_get_gen5_rom_profile``, que no solo
        no encontraba nada, sino que marcaba en la caché COMPARTIDA
        (``_gen5_rom_checked_for``) que esa partida ya se había "intentado"
        -con el buscador de ROM equivocado-, dejando a
        ``_get_gen4_rom_profile`` sin poder intentarlo nunca. Causa real de
        que los aprendizajes por rol de HeartGold no se activaran jamás.
        """
        engine_key = str(getattr(self.save_engine, "key", "") or "")
        if engine_key in MELONDS_GEN4_REALTIME_GAME_KEYS:
            return self._get_gen4_rom_profile(engine_key)
        return self._get_gen5_rom_profile(engine_key)

    def _forget_b2w2_rom_profile(self) -> None:
        """Olvida la ROM al cambiar de Run: la de otra partida sería peor que nada."""
        self._gen5_rom_profiles.clear()
        self._gen5_rom_checked_for.clear()
        self._gen5_rom_last_error.clear()
        for familia in ("b2w2", "bw", *GEN4_GAMES):
            clear_personal_override(familia)

    def _get_b2w2_tm_profile(self):
        """Perfil de MT del juego de quinta que hay delante.

        No hay ROM que pedir ni tabla que cargar de disco: la lista vive en la
        RAM del juego. Es la única fuente correcta jugando en randomizers, donde
        cada MT puede enseñar otra cosa.

        Se pide al adaptador **del juego activo**. Preguntárselo siempre al de
        Negro 2 leía su dirección aunque la partida abierta fuera Blanco: ese
        era el motivo de que Blanco no tuviera MT.
        """
        clave = self._active_azahar_realtime_key()
        if clave not in MELONDS_REALTIME_GAME_KEYS:
            return None
        adapter = getattr(self, f"{clave}_realtime_adapter", None)
        if adapter is None:
            return None
        try:
            return adapter.read_tm_profile()
        except Exception as exc:
            messagebox.showerror(
                "No se pudo leer la tabla de MT de "
                + self._active_azahar_realtime_label(),
                "RoleRun no va a mostrar una tabla supuesta: en una partida "
                "randomizada cada MT puede enseñar otra cosa.\n\n" + str(exc),
                parent=self._dialog_parent(),
            )
            return None

    def _resolve_global_tm_profile(self):
        """Resuelve únicamente fuentes ya usadas por el selector individual."""
        key = str(getattr(self.save_engine, "key", "") or "")
        if key not in LIVE_TM_GAME_KEYS or not self.current_save:
            return None
        if not self._oras_live_active:
            messagebox.showinfo(
                "Tiempo real no disponible",
                "Abre el juego y espera a que RoleRun confirme la conexión antes de consultar la mochila de MT.",
                parent=self._dialog_parent(),
            )
            return None
        if key in MELONDS_REALTIME_GAME_KEYS:
            # Ni cuarta ni quinta piden ROM para esto: la tabla se lee de la RAM
            # del juego, que es lo único correcto jugando en randomizers.
            return self._get_b2w2_tm_profile()
        if key == "bdsp":
            return self._get_bdsp_tm_profile(prompt=True)
        if key == "xy":
            return self._get_xy_rom_tm_profile(prompt=False) or self._get_xy_rom_tm_profile(prompt=True)
        if key == "sm":
            return self._get_sm_rom_tm_profile(prompt=False) or self._get_sm_rom_tm_profile(prompt=True)
        if key == "usum":
            return self._get_usum_rom_tm_profile(prompt=False) or self._get_usum_rom_tm_profile(prompt=True)
        profile = self._get_oras_rom_tm_profile(prompt=False)
        if profile is None and bool(str(getattr(self.project, "oras_fvx_tm_log", "") or "").strip()):
            profile = self._get_oras_fvx_tm_profile(prompt=False)
        if profile is None:
            profile = self._get_oras_rom_tm_profile(prompt=True)
        return profile

    def _load_global_tm_context(self) -> None:
        if self._global_tm_load_requested or self.active_page != "tms":
            return
        profile = self._resolve_global_tm_profile()
        if profile is None:
            # Sin mochila no se puede pintar la columna de MT, pero los drafteos
            # guardados NO dependen de ella y esta página es su única superficie
            # en todo el programa: un drafteo ya pagado se quedaba inalcanzable,
            # detrás de un rótulo de carga que no terminaba nunca.
            self._global_tm_sin_mochila = self._motivo_sin_mochila_de_mt()
            self._smooth_render_page(reset_scroll=True)
            return
        self._global_tm_sin_mochila = ""
        self._global_tm_load_requested = True

        def loaded(profile, inventory, source) -> None:
            self._global_tm_load_requested = False
            if self.active_page != "tms":
                return
            detail = f"{getattr(getattr(profile, 'source', None), 'name', 'fuente validada')} · {source}"
            self._global_tm_context = (profile, dict(inventory), detail)
            self._smooth_render_page(reset_scroll=True)

        self._start_live_tm_inventory_load(
            None, 1, replace_existing=True, profile=profile, on_loaded=loaded,
            on_failed=lambda: setattr(self, "_global_tm_load_requested", False),
        )

    def _motivo_sin_mochila_de_mt(self) -> str:
        """Por qué no se puede listar la mochila de MT del juego abierto."""
        clave = str(getattr(self.save_engine, "key", "") or "")
        if clave not in LIVE_TM_GAME_KEYS:
            return (
                f"{self._game_label(clave) or 'Este juego'} todavía no tiene una "
                "lectura demostrada de su mochila de MT. Los drafteos que hayas "
                "guardado sí puedes enseñarlos desde aquí."
            )
        if not self._oras_live_active:
            return (
                "Abre el juego y espera a que RoleRun confirme la conexión para "
                "ver tus MT. Los drafteos guardados no necesitan la conexión."
            )
        return (
            "No se pudo preparar la tabla de MT de este juego. Los drafteos "
            "guardados siguen disponibles."
        )

    def _global_tm_entries(self, profile, inventory: dict[int, int]) -> tuple[dict[str, object], ...]:
        party = tuple(self._projected_party()[:6])
        compatible_by_move: dict[int, set[str]] = {}
        known_by_move: dict[int, set[str]] = {}
        for pokemon in party:
            _names, move_ids = self._effective_moves_for_review(pokemon)
            identity = self._pokemon_identity(pokemon)
            for move_id in move_ids:
                if int(move_id or 0) > 0:
                    known_by_move.setdefault(int(move_id), set()).add(identity)
            for candidate in self._tm_flow_candidates(pokemon, profile, inventory, move_ids):
                move_id = int(candidate["move_id"])
                compatible_by_move.setdefault(move_id, set()).add(identity)

        entries: list[dict[str, object]] = []
        for number in sorted(getattr(profile, "tms", {})):
            tm = profile.tm(number)
            if tm is None:
                continue
            quantity = int(inventory.get(int(tm.item_id), 0))
            if quantity <= 0:
                continue
            metadata = self._draft_move_metadata(int(tm.move_id))
            move = self.engine.move(int(tm.move_id))
            entries.append({
                "kind": "tm",
                "number": int(number), "item_id": int(tm.item_id), "move_id": int(tm.move_id),
                "move_name": str(move.get("name_es", f"Movimiento #{int(tm.move_id)}")),
                "quantity": quantity, "owned": quantity > 0,
                "category": {
                    "physical": "FÍSICO", "special": "ESPECIAL", "status": "ESTADO",
                }.get(str(self._damage_class_for_move(int(tm.move_id))), "NO DISPONIBLE"),
                "category_key": str(self._damage_class_for_move(int(tm.move_id))),
                "power": metadata.get("power", "—"), "accuracy": metadata.get("accuracy", "—"),
                "pp": self._tm_pp_for_profile(profile, int(tm.move_id)) or "—",
                "type_id": metadata.get("type_id"),
                "description": metadata.get("description", "No disponible"),
                "compatible": tuple(sorted(compatible_by_move.get(int(tm.move_id), set()))),
                "known": tuple(sorted(known_by_move.get(int(tm.move_id), set()))),
            })
        return tuple(entries)

    def _entradas_de_drafteos_guardados(self) -> tuple[dict[str, object], ...]:
        """Los drafteos guardados, con la misma forma que una MT.

        Que compartan forma no es casualidad: la columna de la izquierda y la de
        la derecha son dos maneras de llegar a lo mismo —enseñar un movimiento—
        y el selector de Pokémon es idéntico para las dos. Con formas distintas
        habría que escribir dos veces la misma pantalla.

        La diferencia real está en quién puede aprenderlo: una MT la limita la
        compatibilidad que demuestra el juego; un drafteo, **el rol**, porque
        salió del conjunto de ese rol.
        """
        if not self.project:
            return ()
        entradas: list[dict[str, object]] = []
        for guardado in drafteos_guardados.ordenados(self.project.saved_drafts):
            move_id = int(guardado.get("move_id", 0) or 0)
            metadata = self._draft_move_metadata(move_id)
            compatibles: list[str] = []
            conocidos: list[str] = []
            for pokemon in tuple(self._projected_party()[:6]):
                identidad = self._pokemon_identity(pokemon)
                rol, _simbolo = self._effective_role(pokemon)
                _nombres, ids = self._effective_moves_for_review(pokemon)
                if move_id in {int(valor or 0) for valor in ids}:
                    conocidos.append(identidad)
                elif drafteos_guardados.puede_aprenderlo(guardado, rol):
                    compatibles.append(identidad)
            entradas.append({
                "kind": "draft",
                "move_id": move_id,
                "move_name": str(guardado.get("move", "")),
                "role": str(guardado.get("role", "")),
                "origen": str(guardado.get("origen_nombre", "")),
                "category": {
                    "physical": "FÍSICO", "special": "ESPECIAL", "status": "ESTADO",
                }.get(str(self._damage_class_for_move(move_id)), "NO DISPONIBLE"),
                "category_key": str(self._damage_class_for_move(move_id)),
                "power": metadata.get("power", "—"),
                "accuracy": metadata.get("accuracy", "—"),
                "pp": metadata.get("pp", "—"),
                "type_id": metadata.get("type_id"),
                "description": metadata.get("description", "No disponible"),
                "compatible": tuple(compatibles),
                "known": tuple(conocidos),
                "guardado": dict(guardado),
            })
        return tuple(entradas)

    def _render_global_tm_page(self) -> None:
        self._clear(self.body)
        if not self.current_game:
            self._empty_page("No hay partida cargada", "Abre una Run para ver qué puedes enseñar.", self._return_to_welcome)
            return
        context = self._global_tm_context
        if context is None and not self._global_tm_sin_mochila:
            panel = ctk.CTkFrame(self.body, height=520, fg_color="#151515", corner_radius=16,
                                 border_width=1, border_color="#3A3A3A")
            panel.grid(row=0, column=0, sticky="nsew")
            panel.grid_propagate(False)
            ctk.CTkLabel(panel, text="COMPROBANDO LA MOCHILA DE MT…", text_color=GOLD,
                         font=ctk.CTkFont("Segoe UI", 18, "bold")).place(relx=.5, rely=.46, anchor="center")
            ctk.CTkLabel(panel, text="RoleRun mostrará únicamente datos demostrados por el juego activo.",
                         text_color=MUTED, font=ctk.CTkFont("Segoe UI", 12)).place(relx=.5, rely=.52, anchor="center")
            self.after(20, self._load_global_tm_context)
            return
        # Sin mochila la página se pinta igual: la columna de MT explica por qué
        # está vacía y la de DRAFTEOS funciona entera.
        profile, inventory, source_detail = context or (None, {}, "")
        entradas = (
            self._global_tm_entries(profile, inventory) if profile is not None else ()
        )
        party = tuple(self._projected_party()[:6])
        self._global_tm_view = GlobalTMView(
            self.body, entries=entradas, party=party,
            identity_for=self._pokemon_identity, role_for=self._effective_role,
            sprite_for=self._team_pc_sprite, role_icon_for=self.role_icons.image,
            on_choose=lambda entry, pokemon: self._open_global_tm_choice(profile, inventory, source_detail, entry, pokemon),
            source_detail=source_detail,
            drafts=self._entradas_de_drafteos_guardados(),
            on_choose_draft=self.ensenar_drafteo_guardado,
            on_delete_draft=self.descartar_drafteo_guardado,
            sin_mt=self._global_tm_sin_mochila,
            navigation_keys=self.project.menu_keys if self.project else None,
            on_left_edge=self._select_sidebar_from_content,
            on_edge_accept=self._accept_sidebar_from_content,
            category_icons=self.category_icons,
            on_open_levelup_history=self._open_oras_levelup_history,
            on_view_compatible_moves=lambda pokemon: self._open_global_tm_compatible_moves(
                profile, inventory, source_detail, pokemon,
            ),
        )
        self._set_navigation_owner(self._global_tm_view)
        self._pin_body_scrollregion_soon()

    def _open_global_tm_compatible_moves(self, profile, inventory, source_detail, pokemon) -> None:
        """VER MT COMPATIBLES: abre el paso 1 (lista de MT) para un Pokémon.

        Pedido por el usuario el 2026-09-03: antes solo se llegaba a esta
        pantalla retrocediendo desde «qué hueco olvidará» después de pulsar
        ELEGIR en una MT concreta —una pantalla que aparecía sin haberla
        pedido nunca. Sin ``initial_move_id`` el flujo aterriza directo en el
        paso 1, con la lista completa de MT compatibles con este Pokémon.
        """
        if profile is None:
            return
        self._open_integrated_tm_flow(pokemon, profile, inventory, source_detail, return_page="tms")

    def _open_global_tm_choice(self, profile, inventory, source_detail, entry, pokemon) -> None:
        if entry is None or profile is None:
            return
        self._open_integrated_tm_flow(
            pokemon, profile, inventory, source_detail,
            initial_move_id=int(entry["move_id"]), return_page="tms",
        )

    #: Estados que merecen un sonido, y cuál.
    SONIDO_DEL_ESTADO = {
        "done": "confirmacion",
        "confirmed": "confirmacion",
        "prepared": "confirmacion",
        "failed": "error",
        "warning": "error",
    }

    #: Segundos que un mismo aviso no vuelve a sonar. Un solo movimiento pasa
    #: por «confirmado» tres veces —al preparar, al escribir y al releer el PC—
    #: y sonar tres campanitas por arrastre sería insufrible.
    SILENCIO_ENTRE_AVISOS = 2.0

    def _sonar_por_el_estado(self, kind: str, title: str) -> None:
        efecto = self.SONIDO_DEL_ESTADO.get(kind)
        if efecto is None:
            self._ultimo_aviso_sonado = None
            return
        ahora = time.monotonic()
        anterior = getattr(self, "_ultimo_aviso_sonado", None)
        if anterior and anterior[0] == efecto and ahora - anterior[1] < self.SILENCIO_ENTRE_AVISOS:
            return
        self._ultimo_aviso_sonado = (efecto, ahora)
        self.sonar(efecto)

    def sonar(self, nombre: str) -> None:
        """Un efecto de interfaz. Nunca puede estorbar a lo que se estaba haciendo."""
        try:
            self.sonidos.reproducir(str(nombre))
        except Exception:
            pass

    def _anotar_de_la_vista(self, evento: str, **campos: object) -> None:
        """Recoge lo que la vista quiera dejar anotado.

        Va a los dos sitios a propósito. La medición de tiempos solo existe si se
        abrió con `medir_lentitud.bat`, y un fallo intermitente —«a veces no me
        deja arrastrar»— nunca aparece cuando uno se acuerda de medir. El
        trazado del juego en vivo está siempre encendido.
        """
        perf.mark(f"ui.{evento}", **campos)
        self._record_bdsp_ui_event(evento, **campos)

    def _refrescar_team_pc_en_sitio(
        self, overlay=None, reset_scroll: bool = False,
    ) -> bool:
        """Cambia los datos de Equipo y PC sin reconstruir la página.

        Devuelve si pudo. Un ``False`` significa que hay que repintar de verdad,
        y se decide **antes** de tocar nada: la vista se construyó con unos
        botones, unos límites de caja y un modo concretos que aquí no se
        rehacen, así que si alguno de ellos cambiaría, este camino no vale.

        Cada negativa deja anotado su motivo. Reconstruir cuesta entre 626 y 937
        ms medidos —30.255 llamadas a Tcl—, así que saber cuál de las nueve
        condiciones lo impidió es la diferencia entre arreglarlo y adivinar.
        """
        motivo = self._motivo_para_reconstruir_team_pc(overlay, reset_scroll)
        if motivo is not None:
            perf.mark("ui.render.reconstruye", motivo=motivo)
            return False
        return self._aplicar_refresco_team_pc_en_sitio()

    def _motivo_para_reconstruir_team_pc(
        self, overlay=None, reset_scroll: bool = False,
    ) -> str | None:
        """Qué impide actualizar en sitio, o ``None`` si no lo impide nada.

        Aquí están **todas** las condiciones, incluidas las que antes vivían en
        el `if` del que llama: si alguna se queda fuera, su reconstrucción no
        aparece en la medición y no hay forma de saber qué arreglar.
        """
        if overlay is not None:
            # Esa barrera la retira el camino largo; nadie más sabe hacerlo.
            return "navegacion con barrera"
        if reset_scroll:
            return "pide volver arriba"
        if self._team_focus_identity:
            return "pide enfocar a un miembro"
        if self.active_page not in TEAM_PC_PAGES:
            return f"pagina {self.active_page}"
        if not self._shell_built:
            return "shell sin construir"
        if self._initial_shell_waiting:
            # La barrera de arranque no publica por timeout: compara la
            # evidencia de lo que la vista materializó y espera indefinidamente
            # si no cuadra. Ahí hay que reconstruir, que es lo que esa
            # comprobación sabe verificar.
            return "arrancando"
        if self._body_swap_in_progress:
            return "cambiando de superficie"
        vista = getattr(self, "_team_pc_view", None)
        if vista is None:
            return "sin vista"
        if not self.current_game:
            return "sin partida"
        if self._faint_replacement_mode is not None:
            return "sustitucion por baja"
        if getattr(vista, "mode_banner", None):
            return "modo banner"
        if not self._widget_alive(getattr(vista, "frame", None)):
            return "vista destruida"
        # Esta es la comprobación de «está en pantalla»: exige que el marco y
        # los tres paneles existan, estén mapeados y tengan tamaño.
        #
        # Antes se exigía además `_presented_team_pc_view`, la marca que pone
        # `retire_old_body` con `after(70, …)` porque destruir el body anterior
        # en el mismo callback deja un parpadeo. Eso convertía cada
        # reconstrucción en una ventana de 70 ms durante la cual el siguiente
        # refresco tenía que reconstruir también, abriendo otra ventana: en la
        # medición los refrescos llegaban a los 8 ms y se encadenaban dos
        # reconstrucciones de 836 y 826 ms por cada arrastre. Esa marca es la
        # frontera que necesita la barrera de arranque —excluida aquí por el
        # motivo «arrancando»—, no esta.
        if not vista.puede_actualizarse_en_sitio():
            return "vista a medio componer"

        # La forma se calcula igual que la calcularía el repintado completo,
        # con la misma función, para que no puedan discrepar.
        cajas, huecos = self._forma_del_pc(self._team_pc_cached_data())
        if cajas != vista.pc_box_count:
            return "otro numero de cajas"
        if huecos != vista.pc_slot_count:
            return "otro tamano de caja"
        if bool(vista.compact) != (self.winfo_width() <= 1160):
            return "cambio el modo compacto"
        # Los dos botones de cabecera existen o no según estas dos condiciones,
        # y no se crean ni se destruyen por este camino.
        if (vista.on_heal_party is not None) != bool(self._live_party_heal_available()):
            return "cambio el boton de curar"
        if (vista.on_fix_roles is not None) != bool(self._roles_pendientes_de_fijar()):
            return "cambio el boton de fijar roles"
        return None

    def _aplicar_refresco_team_pc_en_sitio(self) -> bool:
        """Pone los datos de ahora en la vista ya construida."""
        vista = self._team_pc_view
        with perf.span("ui.team_pc_en_sitio.pc_cached_data"):
            pc_data = self._team_pc_cached_data()
        # `_asegurar_lectura_del_pc` sigue recibiendo el estado REAL de la
        # caché más abajo: si no, una relectura pendiente no se pediría nunca.
        with perf.span("ui.team_pc_en_sitio.matriz_para_pintar"):
            pintable = self._pc_matriz_para_pintar(pc_data)
        cajas, _huecos = self._forma_del_pc(pintable)
        with perf.span("ui.team_pc_en_sitio.projected_party"):
            projected_party = list(self._projected_party())
        with perf.span("ui.team_pc_en_sitio.fixed_team_slots"):
            team_slots = build_fixed_team_slots(
                projected_party,
                lambda pokemon: self._effective_role(pokemon)[0],
                self._pokemon_identity,
            )
        box_number = max(1, min(int(self._pc_page_box or 1), cajas))
        with perf.span("ui.team_pc_en_sitio.box_members"):
            members = self._team_pc_box_members(pintable, box_number)
        with perf.span("ui.team_pc_en_sitio.vista_refrescar_en_sitio"):
            fallo = vista.refrescar_en_sitio(team_slots, members, box_number)
        if fallo is not None:
            perf.mark("ui.render.reconstruye", motivo=str(fallo))
            return False
        # Lo mismo que hace el repintado completo al terminar: si no, atajar
        # dejaría el PC sin pedirse.
        with perf.span("ui.team_pc_en_sitio.asegurar_lectura_del_pc"):
            self._asegurar_lectura_del_pc(pc_data)

        self._pc_page_box = box_number
        # La barrera inicial compara contra lo que la vista compuso de verdad.
        # Sin actualizarlo aquí, la firma quedaría hablando del equipo anterior.
        with perf.span("ui.team_pc_en_sitio.health_signature"):
            vista._source_health_signature = self._party_health_signature(projected_party)
        return True

    def _render_team_pc_unified_page(self) -> None:
        """Compone Equipo, Caja PC e inspector sin duplicar lógica funcional."""
        if not self.current_game:
            self._empty_page(
                "No hay equipo cargado",
                "Abre una Run para consultar el equipo y sus cajas.",
                self.select_save,
            )
            return

        with perf.span("ui.team_pc.party_proyectada"):
            projected_party = list(self._projected_party())
        with perf.span("ui.team_pc.casillas_fijas"):
            team_slots = build_fixed_team_slots(
                projected_party,
                lambda pokemon: self._effective_role(pokemon)[0],
                self._pokemon_identity,
            )
        with perf.span("ui.team_pc.datos_del_pc") as medida:
            pc_data = self._team_pc_cached_data()
            medida.add(hay_datos=pc_data is not None)
        # Igual que el refresco en sitio: mientras una relectura está en vuelo
        # se conservan las cajas ya confirmadas en vez de vaciarlas.
        pintable = self._pc_matriz_para_pintar(pc_data)
        box_count, slot_count = self._forma_del_pc(pintable)
        requested_box = int(self._pc_page_box or (pintable.current_box if pintable is not None else 1) or 1)
        faint_mode = self._faint_replacement_mode
        if faint_mode is not None and requested_box == ORAS_GRAVEYARD_BOX:
            requested_box = 1 if box_count >= 1 else requested_box
        box_number = max(1, min(requested_box, box_count))
        self._pc_page_box = box_number
        with perf.span("ui.team_pc.miembros_de_la_caja") as medida:
            members = self._team_pc_box_members(pintable, box_number)
            medida.add(cuantos=len(members or ()))

        # El estado inferior ya comunica la sustitución. El segundo aviso rojo
        # duplicaba la información y, además, activaba el layout compacto que
        # recortaba el botón de reemplazo de la ficha.
        mode_banner = None
        # Se cronometra por fuera y no con un `with`: envolver la llamada
        # obligaria a re-sangrar cuarenta lineas de argumentos para medirla.
        _inicio_de_la_vista = time.perf_counter()
        self._team_pc_view = UnifiedTeamPCView(
            self.body,
            team_slots=team_slots,
            pc_members=members,
            pc_box=box_number,
            pc_box_count=box_count,
            pc_slot_count=slot_count,
            selection=self._team_pc_selection,
            identity_for=self._pokemon_identity,
            role_for=self._team_pc_role_for,
            sprite_for=self._team_pc_sprite,
            role_icon_for=self.role_icons.image,
            base_stats_for=self._team_pc_base_stats,
            pending_for=self._team_pc_pokemon_has_pending_change,
            move_issues_for=self._collect_pokemon_move_issues,
            effective_moves_for=self._effective_moves_for_review,
            support_damage_for=self._support_damage_excess,
            on_support_damage=self._open_support_damage_removal_selector,
            on_box_change=self._team_pc_change_box,
            on_search=self._team_pc_global_search,
            on_action=self._team_pc_action,
            on_role_info=self._show_role_information,
            move_metadata_for=self._draft_move_metadata,
            on_move_info=self._show_move_information,
            on_heal_party=(
                self._heal_bdsp_party
                if faint_mode is None and self._live_party_heal_available()
                else None
            ),
            on_fix_roles=(
                self.fijar_roles_del_equipo
                if faint_mode is None and self._roles_pendientes_de_fijar()
                else None
            ),
            on_drop=None if faint_mode is not None else self._team_pc_drop,
            can_drop=None if faint_mode is not None else self._team_pc_can_drop,
            on_select=self._team_pc_select,
            on_composed=self._team_pc_view_composed,
            on_cancel=(
                self._dismiss_integrated_faint_picker
                if faint_mode is not None else self._cancel_team_pc_pending_selection
            ),
            interaction_mode="faint-replacement" if faint_mode is not None else "normal",
            mode_banner=mode_banner,
            excluded_boxes={ORAS_GRAVEYARD_BOX} if faint_mode is not None else set(),
            compact=self.winfo_width() <= 1160,
            navigation_keys=self.project.menu_keys if self.project else None,
            on_left_edge=self._select_sidebar_from_content,
            on_edge_accept=self._accept_sidebar_from_content,
        )
        self._team_pc_view.anotar = self._anotar_de_la_vista
        # Un sprite volando vive en la ventana principal, no en los paneles:
        # tienen scroll y recortarian el vuelo al salir de ellos.
        self._team_pc_view._raiz_para_animar = self
        self._team_pc_view.sonar = self.sonar
        perf.record(
            "ui.team_pc.construir_vista",
            (time.perf_counter() - _inicio_de_la_vista) * 1000.0,
            miembros=len(projected_party),
        )
        # La vista conserva la firma de los PS que realmente compuso. Durante
        # el arranque BDSP ``current_game`` puede recibir la party live mientras
        # esta instancia todavía representa el save provisional. Sin esta
        # frontera, comprobar solo ``is_fully_composed`` autorizaba a retirar el
        # loader sobre el árbol antiguo y el repintado correcto aparecía varios
        # segundos después.
        self._team_pc_view._source_health_signature = self._party_health_signature(
            projected_party
        )
        self._set_navigation_owner(self._team_pc_view)

        self._asegurar_lectura_del_pc(pc_data)

    def _team_pc_base_stats(self, pokemon) -> dict[str, int]:
        """Lee la tabla Personal efectiva; nunca reconstruye stats raciales."""
        embedded = dict(getattr(pokemon, "base_stats", {}) or {})
        if embedded:
            return embedded
        engine_key = str(getattr(self.save_engine, "key", "") or "")
        if engine_key == "bdsp":
            profile = self._get_bdsp_tm_profile(prompt=False)
        elif engine_key == "oras":
            profile = self._get_oras_rom_tm_profile(prompt=False)
        elif engine_key == "sm":
            profile = self._get_sm_rom_tm_profile(prompt=False)
        elif engine_key == "usum":
            profile = self._get_usum_rom_tm_profile(prompt=False)
        elif engine_key == "xy":
            # 2026-09-05: faltaba. X/Y usa el mismo ORASTMProfile con
            # personal_stats (``xy_rom_service.load_xy_rom_tm_profile``), así
            # que la fila BASE salía vacía solo por no estar en esta cadena.
            profile = self._get_xy_rom_tm_profile(prompt=False)
        else:
            return {}
        if profile is None:
            return {}
        if engine_key in {"oras", "sm", "usum", "xy"}:
            personal = profile.personal_for(
                int(getattr(pokemon, "species_id", 0) or 0),
                int(getattr(pokemon, "form", 0) or 0),
            )
            values = personal.base_stats if personal is not None else None
        else:
            values = profile.base_stats(
                int(getattr(pokemon, "species_id", 0) or 0),
                int(getattr(pokemon, "form", 0) or 0),
            )
        if engine_key in {"oras", "sm", "usum", "xy"} and values is not None:
            # Personal Gen 6/7 conserva el orden binario
            # PS, Atq., Def., Vel., At. Esp., Def. Esp.; la UI usa Velocidad
            # al final, igual que SavePokemon.stats/ivs/evs.
            values = tuple(values[index] for index in (0, 1, 2, 4, 5, 3))
        return stat_dict(values) if values is not None else {}

    def _team_pc_view_composed(self, view) -> None:
        """Recibe la frontera final desde la vista que realmente se presentará."""
        if view is not getattr(self, "_team_pc_view", None):
            return
        if self._initial_shell_waiting:
            self._retire_initial_shell_when_ready()

    def _team_pc_cached_data(self) -> SavePCData | None:
        if self._pc_cache is None:
            return None
        if self.current_save is None:
            return self._pc_cache
        signature = self._save_file_signature(Path(self.current_save.path))
        if self._pc_cache_signature is None or signature == self._pc_cache_signature:
            return self._pc_cache
        return None

    #: Cuantas anclas de PC se recuerdan entre sesiones. El localizador exige
    #: dos coincidencias, asi que un puñado sobra; guardar las 930 casillas solo
    #: engordaria el config.json de la Run sin localizar nada mejor.
    LIMITE_ANCLAS_PC_RECORDADAS = 12

    def _recordar_anclas_del_pc_vivo(self, data: SavePCData | None) -> None:
        """Guarda en la Run las coordenadas que la RAM acaba de demostrar.

        Un traslado hecho desde RoleRun vive en la RAM hasta que el jugador
        guarda dentro del juego. Sin esta memoria, al reabrir solo quedaban las
        anclas del ``main`` —ya caducadas— y la matriz viva no se podía
        localizar: el PC quedaba ilegible hasta guardar la partida.
        """
        if data is None or not self.project:
            return
        recordadas: list[dict[str, int]] = []
        for box in data.boxes:
            for pokemon in box.pokemon:
                if pokemon.box is None or pokemon.box_slot is None:
                    continue
                if int(pokemon.species_id or 0) <= 0:
                    continue
                recordadas.append({
                    "box": int(pokemon.box),
                    "box_slot": int(pokemon.box_slot),
                    "species_id": int(pokemon.species_id),
                    "pid": int(pokemon.pid or 0),
                    "tid": int(pokemon.tid or 0),
                    "sid": int(pokemon.sid or 0),
                })
                if len(recordadas) >= self.LIMITE_ANCLAS_PC_RECORDADAS:
                    break
            if len(recordadas) >= self.LIMITE_ANCLAS_PC_RECORDADAS:
                break
        if not recordadas or recordadas == list(self.project.pc_anchor_memory):
            return
        self.project.pc_anchor_memory = recordadas
        try:
            self.run_service.save(self.project)
        except Exception:
            # Recordar anclas es una ayuda, no un requisito: si no se puede
            # persistir, la sesion actual sigue funcionando igual.
            pass

    def _anclas_del_pc_recordadas(self) -> list[SavePokemon]:
        """Reconstruye las anclas persistidas como Pokémon mínimos.

        Solo se usan para localizar la matriz: el comparador mira especie, PID,
        TID y SID, nada más. Una ancla caducada no cuenta y ya está; el
        localizador exige coincidencias, no ausencia de fallos.
        """
        if not self.project:
            return []
        anclas: list[SavePokemon] = []
        for raw in list(getattr(self.project, "pc_anchor_memory", ()) or ()):
            try:
                box = int(raw["box"])
                box_slot = int(raw["box_slot"])
                species_id = int(raw["species_id"])
            except (KeyError, TypeError, ValueError):
                continue
            if species_id <= 0 or box <= 0 or box_slot <= 0:
                continue
            anclas.append(SavePokemon(
                slot=box_slot, species_id=species_id, species="", nickname="",
                level=0, held_item="", ability="", moves=[], move_ids=[],
                is_egg=False, markings=[], role="SIN ROL", role_symbol="",
                box=box, box_slot=box_slot,
                pid=int(raw.get("pid", 0) or 0),
                tid=int(raw.get("tid", 0) or 0),
                sid=int(raw.get("sid", 0) or 0),
            ))
        return anclas

    def _pc_matriz_para_pintar(self, pc_data: SavePCData | None) -> SavePCData | None:
        """La matriz que se enseña mientras una relectura está en vuelo.

        Una escritura viva invalida ``_pc_cache`` a propósito para releer el PC
        del juego. Durante esos milisegundos ``_team_pc_cached_data`` devuelve
        ``None``, y pintar con ``None`` no dibuja una caja «pendiente»: dibuja
        una caja VACÍA. Ese era el parpadeo tras mover un Pokémon —todas las
        casillas desaparecían unos frames y volvían—, y además afirmaba algo
        falso: que ahí no había nada.

        Mientras llega la lectura nueva se conserva la última matriz confirmada.
        Las proyecciones pendientes se aplican encima igual que siempre, así que
        el movimiento recién hecho se sigue viendo en su destino.
        """
        if pc_data is not None:
            self._pc_ultima_matriz_pintada = pc_data
            return pc_data
        return getattr(self, "_pc_ultima_matriz_pintada", None)

    def _ensure_live_pc_matrix_loaded(self) -> bool:
        """Agenda la matriz PC viva cuando la vista aún conserva datos del save.

        La conexión puede quedar marcada como activa antes de publicar el primer
        snapshot. Por ello esta garantía se evalúa tras cada publicación validada
        y no depende de detectar una transición ``False -> True``.
        """
        live_key_getter = getattr(self, "_active_azahar_realtime_key", None)
        live_key = live_key_getter() if callable(live_key_getter) else ""
        if live_key not in FULL_MATRIX_LIVE_PC_GAME_KEYS:
            return False
        pc_data = self._team_pc_cached_data()
        needs_live_matrix = bool(
            self._oras_live_active
            and self.active_page in {"team", "pc"}
            and not bool((getattr(pc_data, "raw", None) or {}).get("live_matrix"))
        )
        if (
            needs_live_matrix
            and not self._team_pc_pc_loading
            and not getattr(self, "_pc_selector_live_refresh_in_progress", False)
        ):
            self.after(20, self._start_team_pc_load)
            return True
        return False

    def _hay_cajas_ya_en_pantalla(self) -> bool:
        """¿La vista Equipo/PC está montada y mostrando cajas ahora mismo?

        Distingue la primera carga —donde no hay nada que enseñar y el cargador
        sí ayuda— de una relectura posterior, donde tapar la pantalla es la
        única razón por la que un cambio ya aplicado se siente como una espera.
        """
        if not getattr(self, "_pc_mostrado_con_datos", False):
            return False
        if self.active_page not in {"team", "pc"}:
            return False
        view = getattr(self, "_team_pc_view", None)
        return view is not None and self._widget_alive(getattr(view, "frame", None))

    @perf.timed("ui.start_team_pc_load")
    def _start_team_pc_load(self) -> None:
        if self._team_pc_pc_loading or not self.current_save or not self.current_game or not self.project:
            return
        if getattr(self, "_pc_selector_live_refresh_in_progress", False):
            self.after(180, self._start_team_pc_load)
            return
        self._team_pc_pc_loading = True
        hay_cajas = getattr(self, "_hay_cajas_ya_en_pantalla", None)
        if not (callable(hay_cajas) and hay_cajas()):
            # La superficie opaca solo tiene sentido cuando NO hay nada que
            # mirar todavía. Al releer el PC después de un movimiento ya
            # aplicado, las cajas están en pantalla y son correctas: taparlas
            # con «Cargando las cajas del PC…» es justo lo contrario de lo que
            # hace falta, porque convierte un cambio instantáneo en una espera.
            self._show_busy_indicator("pc-load", "Cargando las cajas del PC…")
        self._set_operation_status(
            "applying",
            "CARGANDO CAJAS PC",
            "RoleRun está obteniendo la matriz de cajas sin bloquear la ventana.",
        )
        live_key = self._active_azahar_realtime_key()
        if live_key in FULL_MATRIX_LIVE_PC_GAME_KEYS and self._oras_live_active:
            if live_key == "usum":
                # El cambio de proceso invalida correctamente Personal antes del
                # primer snapshot. Hay que volver a demostrar/cargar el perfil
                # ANTES de leer el PK7 de caja: sin él, el reader conserva IV/EV
                # pero no puede calcular las stats que PK7 almacenado no contiene.
                self._get_usum_rom_tm_profile(prompt=False)
            self._open_pc_selector_from_live_matrix(
                replace_pokemon=None,
                forced_role=None,
                browse_only=True,
                on_loaded=self._finish_team_pc_load,
                on_error=self._fail_team_pc_load,
            )
            return

        generation = self._session_generation
        project_slug = self.project.slug
        save_path = Path(self.current_save.path)
        signature = self._save_file_signature(save_path)

        def worker() -> None:
            try:
                data = self.save_engine.read_boxes(save_path)
                error = None
            except Exception as exc:
                data = None
                error = str(exc)
            self.after(0, lambda: finish(data, error))

        def finish(data: SavePCData | None, error: str | None) -> None:
            if (
                generation != self._session_generation
                or not self.project
                or self.project.slug != project_slug
            ):
                self._team_pc_pc_loading = False
                self._hide_busy_indicator("pc-load")
                return
            if error or data is None:
                self._fail_team_pc_load(error or "No se obtuvo una matriz de cajas válida.")
                return
            self._pc_cache = data
            self._pc_cache_signature = signature
            self._finish_team_pc_load(data)
            if live_key in LIVE_PC_READ_GAME_KEYS:
                self._schedule_gen6_live_pc_refresh()

        threading.Thread(
            target=worker, daemon=True, name="RoleRunUnifiedPCLoad",
        ).start()

    @perf.timed("ui.finish_team_pc_load")
    def _finish_team_pc_load(self, data: SavePCData) -> None:
        self._team_pc_pc_loading = False
        self._pc_cache = data
        # A partir de aquí el usuario ya tiene cajas delante. Las relecturas
        # posteriores no vuelven a taparlas (ver `_hay_cajas_ya_en_pantalla`).
        self._pc_mostrado_con_datos = True
        if getattr(self, "_initial_shell_waiting", False):
            # La barrera inicial debe componer y publicar exactamente la matriz
            # live que acaba de ser demostrada, nunca la lectura antigua del save.
            self._initial_shell_pc_data = data
        self._set_operation_status(
            "confirmed",
            "CAJAS PC DISPONIBLES",
            f"RoleRun cargó {int(data.box_count)} caja(s) y mantiene la ventana lista para usar.",
        )
        requested_identity = self._faint_reopen_requested_identity
        self._faint_reopen_requested_identity = None
        if requested_identity and self.project:
            event = next((
                item for item in self.project.pending_faints
                if str(item.get("identity", "") or "") == requested_identity
                and bool(item.get("battle_ended", False))
            ), None)
            dead = self._pending_faint_party_member(event) if event is not None else None
            if event is not None and dead is not None:
                self._open_faint_replacement_picker(event, dead, pc_data=data)
                self._hide_busy_indicator("pc-load")
                return
        if self.active_page in {"team", "pc"}:
            self._smooth_render_page()
        # _smooth_render_page puede encolar el trabajo si otro intercambio está
        # activo. La barrera solo se retira tras observar la vista final real.
        self._retire_team_pc_loader_when_ready(data)

    def _retire_team_pc_loader_when_ready(
        self, data: SavePCData, attempt: int = 0, stable_frames: int = 0,
    ) -> None:
        view = getattr(self, "_team_pc_view", None)
        frame = getattr(view, "frame", None)
        ready = bool(
            not self._body_swap_in_progress
            and view is not None
            and self._widget_alive(frame)
            and int(getattr(view, "pc_box_count", 0) or 0) == int(data.box_count)
            and int(frame.winfo_width() or 0) > 400
            and int(frame.winfo_height() or 0) > 400
        )
        stable_frames = stable_frames + 1 if ready else 0
        if stable_frames >= 3:
            self._hide_busy_indicator("pc-load")
            return
        if attempt >= 120:
            self._hide_busy_indicator("pc-load")
            self._set_operation_status(
                "failed", "LA VISTA NO TERMINÓ DE COMPONERSE",
                "Las cajas se leyeron, pero Equipo/PC no alcanzó un estado visual estable.",
                persistent=True,
            )
            return
        self.after(35, lambda: self._retire_team_pc_loader_when_ready(
            data, attempt + 1, stable_frames,
        ))

    def _fail_team_pc_load(self, error: str) -> None:
        self._team_pc_pc_loading = False
        self._hide_busy_indicator("pc-load")
        self._set_operation_status(
            "failed",
            "NO SE PUDIERON ABRIR LAS CAJAS",
            str(error) + PISTA_GUARDAR_PARA_LOCALIZAR_EL_PC,
            actions=("Reintentar",),
            persistent=True,
        )

    def _forma_del_pc(self, pc_data: SavePCData | None) -> tuple[int, int]:
        """Cuántas cajas y de qué tamaño, aunque el contenido no esté ahora.

        Lo usan por igual el repintado completo y la comprobación del refresco
        en sitio: si cada uno calculara lo suyo, la comprobación podría decir
        «misma forma» sobre una página que se va a construir con otra.
        """
        if pc_data is not None:
            forma = (int(pc_data.box_count), int(pc_data.box_slot_count))
            self._pc_forma_conocida = forma
            return forma
        return self._pc_forma_conocida or (1, ORAS_PC_BOX_SLOT_COUNT)

    def _asegurar_lectura_del_pc(self, pc_data: SavePCData | None) -> None:
        """Pide las cajas si no las tiene nadie pedidas ya.

        Vive aparte porque la programa el repintado completo, y el refresco en
        sitio tiene que hacer exactamente lo mismo: si no, atajar dejaría el PC
        sin cargarse nunca.
        """
        if pc_data is None and not self._team_pc_pc_loading:
            self.after(20, self._start_team_pc_load)
        else:
            self._ensure_live_pc_matrix_loaded()

    def _team_pc_box_members(
        self, pc_data: SavePCData | None, box_number: int,
    ) -> dict[int, SavePokemon]:
        if pc_data is None or not (1 <= int(box_number) <= int(pc_data.box_count)):
            return {}
        return {
            int(pokemon.box_slot or pokemon.slot): pokemon
            for pokemon in self._project_pc_box_pokemon(pc_data, int(box_number))
            if int(pokemon.box_slot or pokemon.slot or 0) > 0
        }

    def _team_pc_change_box(self, box_number: int) -> tuple[int, dict[int, SavePokemon]]:
        pc_data = self._team_pc_cached_data()
        if pc_data is None:
            return 1, {}
        target = max(1, min(int(box_number), int(pc_data.box_count)))
        if self._faint_replacement_mode is not None and target == ORAS_GRAVEYARD_BOX:
            choices = [
                value for value in range(1, int(pc_data.box_count) + 1)
                if value != ORAS_GRAVEYARD_BOX
            ]
            if choices:
                target = min(choices, key=lambda value: (abs(value - target), value))
        self._pc_page_box = target
        return target, self._team_pc_box_members(pc_data, target)

    def _team_pc_global_search(self, query: str) -> list[tuple[int, int, SavePokemon]]:
        pc_data = self._team_pc_cached_data()
        if pc_data is None or not str(query).strip():
            return []
        results: list[tuple[int, int, SavePokemon]] = []
        for box_number in range(1, int(pc_data.box_count) + 1):
            members = self._project_pc_box_pokemon(pc_data, box_number)
            for pokemon in filter_pc_pokemon(members, query):
                results.append((
                    box_number,
                    int(pokemon.box_slot or pokemon.slot or 0),
                    pokemon,
                ))
        return results

    def _team_pc_role_for(self, pokemon: SavePokemon, context: str) -> tuple[str, str]:
        if context == "pc":
            return self._pc_effective_role(pokemon)
        return self._effective_role(pokemon)

    def _team_pc_sprite(
        self, pokemon: SavePokemon | None, size: tuple[int, int],
    ) -> ctk.CTkImage | None:
        if pokemon is None:
            return None
        return self._sprite_image(pokemon, size)

    def _team_pc_pokemon_has_pending_change(self, pokemon: SavePokemon, context: str) -> bool:
        identity = self._pokemon_identity(pokemon)
        box = int(pokemon.box or 0)
        box_slot = int(pokemon.box_slot or 0)
        for change in self.run.pending_changes:
            identities = {
                str(getattr(change, name, "") or "")
                for name in ("pokemon_identity", "incoming_identity", "outgoing_identity")
            }
            if identity and identity in identities:
                return True
            if context == "pc" and (
                int(getattr(change, "box", 0) or 0) == box
                and int(getattr(change, "box_slot", 0) or 0) == box_slot
            ):
                return True
        return False

    def _team_pc_action(self, action: str, pokemon: SavePokemon) -> None:
        if action.startswith("replace_move:"):
            self._open_tm_selector(pokemon, int(action.partition(":")[2]), replace_existing=True)
            return
        if action.startswith("delete_move:"):
            slot = int(action.partition(":")[2])
            role, _symbol = self._effective_role(pokemon)
            issue = next((
                item for item in self._collect_pokemon_move_issues(pokemon, role)
                if int(item["move_slot"]) == slot
            ), None)
            if issue is None:
                # Un ataque que sobra en un Support no es «incompatible»: el
                # límite de dos es de conjunto, así que ninguno lo incumple por
                # sí solo. Aun así el usuario tiene que poder quitarlo, y por la
                # misma vía que cualquier otro borrado.
                _excess, candidates = self._support_damage_excess(pokemon, role)
                issue = next((
                    item for item in candidates if int(item["move_slot"]) == slot
                ), None)
            if issue is not None:
                self._queue_invalid_move_removals([issue])
            return
        if action == "replace_fainted":
            self._prepare_faint_replacement(pokemon)
        elif action == "move_help":
            self.navigate("moves")
        elif action == "change_role":
            self.open_role_editor(pokemon)
        elif action == "swap_with_pc":
            self._team_pc_pending_outgoing = self._pokemon_identity(pokemon)
            self._set_operation_status(
                "prepared",
                "ELIGE UN POKÉMON DEL PC",
                f"Selecciona en la caja quién sustituirá a {pokemon.nickname or pokemon.species}. Pulsa Escape para cancelar.",
                actions=("Cancelar",),
                persistent=True,
            )
        elif action == "send_to_pc":
            self.send_pokemon_to_pc(pokemon, ask=False)
        elif action == "pc_to_team":
            if len(self._projected_party()) < 6:
                self._team_pc_execute_change(pokemon, None)
            else:
                self._team_pc_pending_incoming = (
                    int(pokemon.box or self._pc_page_box or 1),
                    int(pokemon.box_slot or pokemon.slot or 0),
                    self._pokemon_identity(pokemon),
                )
                self._set_operation_status(
                    "prepared",
                    "ELIGE LA CASILLA DEL EQUIPO",
                    f"Selecciona el Pokémon al que sustituirá {pokemon.nickname or pokemon.species}. Pulsa Escape para cancelar.",
                    actions=("Cancelar",),
                    persistent=True,
                )
        elif action == "teach_tm":
            _moves, move_ids = self._effective_moves_for_review(pokemon)
            try:
                slot_index = next(index for index, move_id in enumerate(move_ids[:4], start=1) if int(move_id or 0) == 0)
            except StopIteration:
                slot_index = 1
            self._open_tm_selector(
                pokemon,
                slot_index,
                replace_existing=bool(int(move_ids[slot_index - 1] or 0)),
            )

    def _registrar_intento_vivo(self, etapa: str, **datos) -> None:
        """Deja constancia de cada intento de escritura viva, en un archivo.

        El usuario no usa la línea de comandos, así que cuando una acción «no
        hace nada» no hay forma de saber dónde se quedó. Esto la deja escrita:
        una línea por etapa, con lo justo para reconstruir el camino.

        No puede tumbar la interfaz por nada del mundo: cualquier fallo al
        escribirlo se traga en silencio.
        """
        try:
            registro = {
                "cuando": datetime.now().isoformat(timespec="milliseconds"),
                "etapa": etapa,
                "juego": str(getattr(self.save_engine, "key", "") or ""),
                "vivo": str(self._active_azahar_realtime_key()),
                "enlace_activo": bool(getattr(self, "_oras_live_active", False)),
                **datos,
            }
            LOG_DIR.mkdir(parents=True, exist_ok=True)
            with (LOG_DIR / "escrituras_vivas.jsonl").open("a", encoding="utf-8") as salida:
                salida.write(json.dumps(registro, ensure_ascii=False) + chr(10))
        except Exception:
            pass

    def _heal_bdsp_party(self) -> None:
        """Cura toda la party como una sola transacción verificada."""
        if not RoleRunManager._live_party_heal_available(self) or not self.current_game:
            self._registrar_intento_vivo(
                "curar-descartado",
                disponible=bool(RoleRunManager._live_party_heal_available(self)),
                hay_partida=bool(self.current_game),
            )
            return
        pending_ids_before = {id(change) for change in self.run.pending_changes}
        self.run.pending_changes.extend(
            PendingPartyHeal(
                pokemon_slot=int(pokemon.slot),
                pokemon=pokemon.nickname or pokemon.species,
                species=pokemon.species,
                pokemon_identity=self._pokemon_identity(pokemon),
            )
            for pokemon in self.current_game.party
        )
        self._set_operation_status(
            "applying", "CURANDO EL EQUIPO",
            "Restaurando PS, problemas de estado y PP; después se hará readback completo.",
        )
        disponible = getattr(self, "_oras_live_auto_apply_available", None)
        _anotar_intento_vivo(
            self, "curar-encolado",
            cuantos=len(self.current_game.party),
            auto_disponible=bool(disponible()) if callable(disponible) else None,
        )
        self._request_oras_live_auto_apply_since(pending_ids_before)

    def _team_pc_select(self, context: str, pokemon: SavePokemon) -> None:
        if self._faint_replacement_mode is not None:
            return
        if context == "pc" and self._team_pc_pending_outgoing is not None:
            outgoing = self._find_projected_pokemon_by_identity(self._team_pc_pending_outgoing)
            if outgoing is None:
                self._team_pc_pending_outgoing = None
                self._set_operation_status(
                    "failed", "EL EQUIPO HA CAMBIADO",
                    "El Pokémon saliente ya no pertenece al equipo confirmado. No se preparó nada.",
                    persistent=True,
                )
                return
            self._team_pc_execute_change(pokemon, outgoing)
            return
        if context != "team" or self._team_pc_pending_incoming is None:
            return
        incoming = self._team_pc_pending_pokemon()
        if incoming is None:
            self._team_pc_pending_incoming = None
            self._set_operation_status(
                "failed",
                "EL PC HA CAMBIADO",
                "El Pokémon elegido ya no ocupa la posición validada. No se preparó ningún cambio.",
                persistent=True,
            )
            return
        self._team_pc_execute_change(incoming, pokemon)

    def _cancel_team_pc_pending_selection(self) -> None:
        if self._team_pc_pending_incoming is None and self._team_pc_pending_outgoing is None:
            return
        self._team_pc_pending_incoming = None
        self._team_pc_pending_outgoing = None
        self._set_operation_status(
            "neutral", "SELECCIÓN CANCELADA", "No se ha preparado ningún cambio Equipo↔PC.",
        )

    def _team_pc_pending_pokemon(self) -> SavePokemon | None:
        pending = self._team_pc_pending_incoming
        data = self._team_pc_cached_data()
        if pending is None or data is None:
            return None
        box, slot, identity = pending
        candidate = next((
            pokemon for pokemon in self._project_pc_box_pokemon(data, int(box))
            if int(pokemon.box_slot or pokemon.slot or 0) == int(slot)
        ), None)
        if candidate is None or self._pokemon_identity(candidate) != identity:
            return None
        return candidate

    @perf.timed("ui.drop.ejecutar_cambio")
    def _team_pc_execute_change(
        self,
        incoming: SavePokemon,
        outgoing: SavePokemon | None,
        *,
        target_role: str | None = None,
        libero_stats: tuple[str, ...] = (),
    ) -> bool:
        """Invoca el modelo Equipo↔PC existente desde botones o drag."""
        if (
            self._active_azahar_realtime_key() in MELONDS_REALTIME_GAME_KEYS
            and outgoing is None
            and len(self._projected_party()) >= 6
        ):
            self._team_pc_pending_incoming = None
            self._team_pc_pending_outgoing = None
            self._set_operation_status(
                "warning",
                "ESCRITURA B2/W2 AÚN CERRADA",
                "No se proyectó ningún intercambio: RoleRun seguirá mostrando "
                "exactamente el equipo y el PC reales hasta validar el writer PK5.",
                persistent=True,
            )
            return False
        projected = self._projected_party()
        effective_target_role = target_role
        if outgoing is not None:
            effective_target_role = self._effective_role(outgoing)[0]
        elif effective_target_role not in ROLE_ORDER:
            occupied = {self._effective_role(member)[0] for member in projected}
            effective_target_role = next((role for role in ROLE_ORDER if role not in occupied), None)
        if effective_target_role == "Líbero" and len(libero_stats) != 2:
            self._prompt_libero_ev_stats(
                incoming,
                lambda stats, inc=incoming, out=outgoing, role=target_role: self._team_pc_execute_change(
                    inc, out, target_role=role, libero_stats=stats,
                ),
            )
            return True
        pending_before = {id(change) for change in self.run.pending_changes}
        try:
            verb = self._prepare_pc_team_change(
                incoming,
                outgoing,
                incoming_role_override=target_role,
                incoming_libero_stats=libero_stats,
            )
        except RuntimeError as exc:
            self._set_operation_status(
                "failed", "NO SE PUDO PREPARAR EL CAMBIO", str(exc), persistent=True,
            )
            return False
        created = [change for change in self.run.pending_changes if id(change) not in pending_before]
        self._team_pc_pending_incoming = None
        self._team_pc_pending_outgoing = None
        self._pc_cache = None
        self._update_top_status()
        self._sync_live_layout()
        self.active_page = DEFAULT_PAGE
        self._smooth_render_page(preserve_scroll=True)
        if created:
            self._set_operation_status(
                "applying" if self._oras_live_auto_apply_available() else "prepared",
                "APLICANDO CAMBIO" if self._oras_live_auto_apply_available() else verb,
                (
                    "RoleRun ha enviado la misma operación transaccional del botón y espera readback del juego."
                    if self._oras_live_auto_apply_available()
                    else f"{incoming.nickname or incoming.species} está preparado para el flujo de guardado."
                ),
            )
            # Faltaba esto: el cambio se preparaba, la pantalla decía «APLICANDO
            # CAMBIO» y nadie lo enviaba nunca al emulador. Se quedaba en la
            # cola, el Pokémon aparecía en el equipo proyectado con «PS no
            # disponible» y en el juego no estaba. Todas las demás acciones que
            # crean cambios terminan con esta misma llamada.
            self._request_oras_live_auto_apply_since(pending_before)
        return True

    @perf.timed("ui.drop.sincrono")
    def _team_pc_drop(
        self,
        source_context: str,
        source: SavePokemon,
        target_context: str,
        target: dict[str, object],
    ) -> None:
        # El usuario cuenta desde que suelta el ratón. La parte síncrona de este
        # método suele ser corta; lo que hay que poder medir es el hueco hasta
        # que el estado llega a su forma final.
        perf.mark("ui.drop.soltado", origen=source_context, destino=target_context)
        target_pokemon = target.get("pokemon")
        if source_context == target_context == "team":
            target_role = str(target.get("slot_role") or "")
            if target_role in ROLE_ORDER:
                self._move_pokemon_to_role_by_drag(source, target_role, context="main")
            return
        intent = resolve_team_pc_drop(
            source_context,
            target_context,
            target_occupied=target_pokemon is not None,
            team_count=len(self._projected_party()),
        )
        perf.mark(
            "ui.drop.operacion",
            operacion=str(intent.operation or "ninguna"),
            motivo=str(intent.reason or "")[:70] or None,
        )
        if intent.operation is None:
            # Sin caducidad, este aviso seguia abajo mucho despues del gesto que
            # lo provoco, y el usuario lo leia como el resultado del movimiento
            # que SI acababa de hacer bien. Se explica lo que hay que hacer y se
            # recoge solo.
            self._set_operation_status(
                "warning",
                "AHI NO SE PUEDE SOLTAR",
                intent.reason or "No existe una escritura demostrada para ese movimiento.",
                persistent=False,
            )
            return
        if intent.operation == "party-to-box":
            exact_destination = None
            if self._active_azahar_realtime_key() in (
                # BDSP faltaba aquí: soltar sobre una casilla concreta del PC
                # se ignoraba y el Pokémon acababa siempre en el primer hueco
                # libre, aunque el escritor de BDSP sí acepta un destino exacto
                # (`_apply_party_box_resize`, hallazgo del usuario 31-08-2026).
                *GEN7_REALTIME_GAME_KEYS, "xy", "oras", "bdsp", *MELONDS_REALTIME_GAME_KEYS,
            ):
                box = int(target.get("box") or 0)
                slot = int(target.get("slot") or 0)
                if box > 0 and slot > 0:
                    exact_destination = (box, slot)
            self.send_pokemon_to_pc(source, ask=False, destination=exact_destination)
            return
        if intent.operation == "box-to-party":
            self._team_pc_execute_change(
                source,
                None,
                target_role=str(target.get("slot_role") or "") or None,
            )
            return
        if intent.operation == "swap-box-slots":
            if self._active_azahar_realtime_key() not in PC_SWAP_GAME_KEYS:
                game_label = self._active_azahar_realtime_label()
                self._set_operation_status(
                    "warning", "INTERCAMBIO NO HABILITADO",
                    f"{game_label} todavía no tiene una escritura validada para "
                    "intercambiar dos casillas ocupadas del PC. No se proyectó ningún cambio.",
                    persistent=True,
                )
                return
            source_box = int(getattr(source, "box", 0) or 0)
            source_slot = int(getattr(source, "box_slot", 0) or getattr(source, "slot", 0) or 0)
            destination_box = int(target.get("box") or 0)
            destination_slot = int(target.get("slot") or 0)
            if (
                target_pokemon is None
                or min(source_box, source_slot, destination_box, destination_slot) <= 0
            ):
                self._set_operation_status(
                    "failed", "DESTINO INVÁLIDO",
                    "La ocupación cambió antes de soltar. No se preparó nada.", persistent=True,
                )
                return
            if (source_box, source_slot) == (destination_box, destination_slot):
                return
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            self.run.pending_changes.append(PendingTeamChange(
                operation="swap-box-slots", party_slot=0,
                box=source_box, box_slot=source_slot,
                destination_box=destination_box, destination_box_slot=destination_slot,
                # `incoming` es el que se arrastra y acaba en el destino;
                # `outgoing`, el que estaba allí y pasa al hueco de origen.
                incoming_pokemon=source.nickname or source.species,
                incoming_species=source.species,
                incoming_snapshot=self._pokemon_snapshot(source),
                incoming_identity=self._pokemon_identity(source),
                outgoing_pokemon=target_pokemon.nickname or target_pokemon.species,
                outgoing_species=target_pokemon.species,
                outgoing_snapshot=self._pokemon_snapshot(target_pokemon),
                outgoing_identity=self._pokemon_identity(target_pokemon),
                # Las dos identidades del intercambio ya son testigos por sí
                # mismas; estos vecinos solo refuerzan la calibración.
                box_witnesses=self._pc_box_witnesses(source_box, source_slot),
            ))
            self._request_oras_live_auto_apply_since(pending_ids_before)
            self._set_operation_status(
                "applying", "INTERCAMBIANDO EN EL PC",
                f"Verificando Caja {source_box}, posición {source_slot} ↔ "
                f"Caja {destination_box}, posición {destination_slot}.",
            )
            return
        if intent.operation == "move-box-slot":
            if self._active_azahar_realtime_key() not in PC_A_PC_GAME_KEYS:
                game_label = self._active_azahar_realtime_label()
                self._set_operation_status(
                    "warning", "DESTINO NO HABILITADO",
                    f"{game_label} ya lee y sigue el PC, pero todavía no tiene "
                    "una escritura PC→PC validada. No se proyectó ningún cambio.",
                    persistent=True,
                )
                return
            source_box = int(getattr(source, "box", 0) or 0)
            source_slot = int(getattr(source, "box_slot", 0) or getattr(source, "slot", 0) or 0)
            destination_box = int(target.get("box") or 0)
            destination_slot = int(target.get("slot") or 0)
            if min(source_box, source_slot, destination_box, destination_slot) <= 0:
                self._set_operation_status(
                    "failed", "DESTINO INVÁLIDO",
                    "No se pudo demostrar el origen y el destino exactos del PC.", persistent=True,
                )
                return
            if (source_box, source_slot) == (destination_box, destination_slot):
                return
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            self.run.pending_changes.append(PendingTeamChange(
                operation="move-box-slot", party_slot=0,
                box=source_box, box_slot=source_slot,
                destination_box=destination_box, destination_box_slot=destination_slot,
                incoming_pokemon=source.nickname or source.species,
                incoming_species=source.species,
                incoming_snapshot=self._pokemon_snapshot(source),
                incoming_identity=self._pokemon_identity(source),
                box_witnesses=(
                    # `_pc_box_witnesses` sale de la proyección viva; los
                    # vecinos que se acaban de depositar en RAM y todavía no
                    # están en el `main` también cuentan. `_pc_role_witnesses`
                    # solo mira el guardado, y en una caja recién estrenada no
                    # aportaba ningún acompañante con el que calibrar.
                    self._pc_box_witnesses(source_box, source_slot)
                    if self._active_azahar_realtime_key() in {"xy", "oras"}
                    else self._pc_role_witnesses(source)
                ),
            ))
            self._request_oras_live_auto_apply_since(pending_ids_before)
            # Adelanto visual: el Pokémon aparece YA en su destino, sin esperar
            # a que el juego confirme. Es lo que permite volver a moverlo de
            # inmediato en vez de quedarse mirando el hueco viejo. Si la
            # escritura falla, `_finish_oras_live_write` retira este cambio
            # pendiente y la proyección lo devuelve sola a su hueco original.
            refrescar = getattr(self, "_refrescar_team_pc_en_sitio", None)
            if not (callable(refrescar) and refrescar()):
                repintar = getattr(self, "_refresh_main_after_oras_live_write", None)
                if callable(repintar):
                    repintar()
            self._set_operation_status(
                "applying", "MOVIENDO EN EL PC",
                f"Caja {source_box}, posición {source_slot} → Caja {destination_box}, posición {destination_slot}. "
                "Mostrado por adelantado; falta la confirmación del juego.",
            )
            return
        if source_context == "team":
            incoming = target_pokemon
            outgoing = source
        else:
            incoming = source
            outgoing = target_pokemon
        if incoming is None or outgoing is None:
            self._set_operation_status(
                "failed", "DESTINO INVÁLIDO", "La ocupación cambió antes de soltar. No se preparó nada.",
                persistent=True,
            )
            return
        self._team_pc_execute_change(incoming, outgoing)

    def _team_pc_can_drop(
        self,
        source_context: str,
        _source: SavePokemon,
        target_context: str,
        target: dict[str, object],
    ) -> bool:
        if source_context == target_context == "team":
            return str(target.get("slot_role") or "") in ROLE_ORDER
        intent = resolve_team_pc_drop(
            source_context,
            target_context,
            target_occupied=target.get("pokemon") is not None,
            team_count=len(self._projected_party()),
        )
        if intent.operation is None:
            return False
        if intent.operation == "move-box-slot":
            return (
                self._active_azahar_realtime_key() in PC_A_PC_GAME_KEYS
                and self._oras_live_auto_apply_available()
            )
        if intent.operation == "swap-box-slots":
            return (
                self._active_azahar_realtime_key() in PC_SWAP_GAME_KEYS
                and self._oras_live_auto_apply_available()
            )
        if (
            intent.operation in {"party-to-box", "box-to-party"}
            and self._active_azahar_realtime_key() in GEN6_REALTIME_GAME_KEYS
            and self._oras_live_auto_apply_available()
        ):
            # X/Y (bloque PK6, compactación, contador 0x08CE1C74) y ahora ORAS
            # (ORAS_PARTY_COUNT_ADDRESS, sin compactación — ver
            # ORASLiveWriter._apply_party_resize) tienen transacción de cambio
            # de tamaño validada por tests sintéticos. Sin validar aún contra
            # una partida real (ver docs/CURRENT_STATE.md, 30-08-2026).
            return self._active_azahar_realtime_key() in {"xy", "oras"}
        return True

    def _show_role_information(self, role: str) -> None:
        if role not in ROLE_GUIDE or not self._widget_alive(getattr(self, "content", None)):
            return
        previous = self._role_info_popover
        if previous is not None:
            previous.close()

        def closed() -> None:
            self._role_info_popover = None

        self._role_info_popover = IntegratedRoleInfoPopover(
            self.content, role, on_close=closed,
            on_open_moves=lambda: self.navigate("moves"),
        )

    def _show_move_information(self, move_id: int, move_name: str) -> None:
        move_id = int(move_id or 0)
        if move_id <= 0 or not self._widget_alive(getattr(self, "content", None)):
            return
        previous = self._move_info_popover
        if previous is not None:
            previous.close()

        def closed() -> None:
            self._move_info_popover = None

        metadata = self._draft_move_metadata(move_id)
        self._move_info_popover = MoveInfoPopover(
            self.content, move_name, metadata, on_close=closed,
            category_icons=self.category_icons,
        )

    def _render_team_page(self) -> None:
        if not self.current_game:
            self._empty_page("No hay equipo cargado", "Abre una Run desde el Dashboard.", self.select_save)
            return

        projected_party = self._projected_party()
        self.team_card_by_identity = {}
        conflicts = self._team_role_conflicts(projected_party) if self.project and self.project.role_rules_active else {}
        unassigned = self._unassigned_active_pokemon(projected_party) if self.project and self.project.role_rules_active else []
        row_offset = 0
        if conflicts:
            warning = ctk.CTkFrame(
                self.body, fg_color="#251818", corner_radius=16, border_width=2, border_color=DANGER,
            )
            warning.grid(row=0, column=0, sticky="ew", pady=(2, 14))
            warning.grid_columnconfigure(0, weight=1)
            pieces = ["Roles repetidos: " + ", ".join(conflicts)]
            ctk.CTkLabel(
                warning, text="⚠  CONFLICTO DE ROLES", text_color=DANGER,
                font=ctk.CTkFont("Segoe UI", 18, "bold"),
            ).grid(row=0, column=0, sticky="w", padx=20, pady=(14, 2))
            ctk.CTkLabel(
                warning, text=" · ".join(pieces) + ". Elige qué Pokémon conserva cada rol.",
                text_color=TEXT, font=ctk.CTkFont("Segoe UI", 13), wraplength=900, justify="left",
            ).grid(row=1, column=0, sticky="w", padx=20, pady=(0, 14))
            ctk.CTkButton(
                warning, text="RESOLVER", command=self._prompt_current_team_conflicts,
                width=140, height=38, fg_color=DANGER, hover_color="#E27A7A", text_color="#111111",
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).grid(row=0, column=1, rowspan=2, padx=20, pady=12)
            row_offset = 1
        elif unassigned:
            warning = ctk.CTkFrame(
                self.body, fg_color="#211D13", corner_radius=16, border_width=2, border_color=GOLD,
            )
            warning.grid(row=0, column=0, sticky="ew", pady=(2, 14))
            warning.grid_columnconfigure(0, weight=1)
            names = ", ".join(p.nickname or p.species for p in unassigned)
            ctk.CTkLabel(
                warning, text="◷  POKÉMON EN PREPARACIÓN · SIN ROL", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 18, "bold"),
            ).grid(row=0, column=0, sticky="w", padx=20, pady=(14, 2))
            ctk.CTkLabel(
                warning, text=f"{names}. Puedes guardar el equipo así para entrenar o preparar movimientos; estos Pokémon no son aptos para combate RoleRun hasta recibir un rol.",
                text_color=TEXT, font=ctk.CTkFont("Segoe UI", 13), wraplength=900, justify="left",
            ).grid(row=1, column=0, sticky="w", padx=20, pady=(0, 14))
            ctk.CTkButton(
                warning, text="ASIGNAR ROL", command=self._prompt_current_team_conflicts,
                width=140, height=38, fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).grid(row=0, column=1, rowspan=2, padx=20, pady=12)
            row_offset = 1

        review_panel = ctk.CTkFrame(
            self.body, fg_color="#1B1811", corner_radius=18,
            border_width=2, border_color=GOLD,
        )
        review_panel.grid(row=row_offset, column=0, sticky="ew", pady=(2, 14))
        review_panel.grid_columnconfigure(0, weight=1)
        ctk.CTkLabel(
            review_panel, text="GESTIÓN DE EQUIPO", text_color=GOLD,
            font=ctk.CTkFont("Segoe UI", 20, "bold"),
        ).grid(row=0, column=0, sticky="w", padx=22, pady=(18, 6))
        review_text = (
            "La compatibilidad se revisa automáticamente: cualquier movimiento que no encaje con el rol actual aparece en rojo en su propia tarjeta. "
            "Cada ataque rojo puede SUSTITUIRSE por una MT compatible de la mochila o ELIMINARSE. Si no existe ninguna MT válida, SUSTITUIR aparece apagado."
        )
        if self.project and not self.project.role_rules_active:
            review_text += " Durante la fase de preparación los avisos siguen siendo únicamente informativos."
        ctk.CTkLabel(
            review_panel, text=review_text,
            text_color=TEXT, wraplength=900, justify="left", anchor="w",
            font=ctk.CTkFont("Segoe UI", 15),
        ).grid(row=1, column=0, sticky="ew", padx=22, pady=(0, 18))

        utilities = ctk.CTkFrame(
            self.body, fg_color=PANEL, corner_radius=16,
            border_width=1, border_color=PANEL_ALT,
        )
        utilities.grid(row=1 + row_offset, column=0, sticky="ew", pady=(0, 14))
        ctk.CTkLabel(
            utilities, text="UTILIDADES DE LA RUN", text_color=GOLD,
            font=ctk.CTkFont("Segoe UI", 18, "bold"),
        ).pack(anchor="w", padx=18, pady=(14, 3))
        ctk.CTkLabel(
            utilities,
            text=("Añade recursos de comodidad. En ORAS, X/Y, Sol/Luna y BDSP conectados se aplican al instante en el emulador y quedan definitivos "
                  "cuando guardes dentro del juego; en los motores clásicos se mantienen como cambios pendientes."),
            text_color=MUTED, wraplength=820, justify="left",
            font=ctk.CTkFont("Segoe UI", 13),
        ).pack(anchor="w", padx=18, pady=(0, 10))
        utility_actions = ctk.CTkFrame(utilities, fg_color="transparent")
        utility_actions.pack(fill="x", padx=18, pady=(0, 16))
        utility_actions.grid_columnconfigure((0, 1, 2), weight=1, uniform="runutilities")
        self.team_utility_images = []

        def utility_icon(filename: str) -> ctk.CTkImage | None:
            path = RESOURCES_DIR / "item_icons" / filename
            if not path.exists():
                return None
            try:
                source = Image.open(path).convert("RGBA")
                image = ctk.CTkImage(
                    light_image=source,
                    dark_image=source,
                    size=(42, 42),
                )
                self.team_utility_images.append(image)
                return image
            except Exception:
                return None

        rare_candy_image = utility_icon("rare-candy.png")
        max_repel_image = utility_icon("max-repel.png")
        bdsp_money_max = self._inventory_money_max_for_engine(
            getattr(self.save_engine, "key", ""),
        )
        ctk.CTkButton(
            utility_actions, text="x999", image=rare_candy_image, compound="left",
            command=lambda: self.queue_inventory_change("rare-candy", "Caramelo Raro", 999),
            fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
            height=58, corner_radius=12,
            font=ctk.CTkFont("Segoe UI", 20, "bold"),
        ).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ctk.CTkButton(
            utility_actions, text="x999", image=max_repel_image, compound="left",
            command=lambda: self.queue_inventory_change("max-repel", "Repelente Máximo", 999),
            fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
            height=58, corner_radius=12,
            font=ctk.CTkFont("Segoe UI", 20, "bold"),
        ).grid(row=0, column=1, sticky="ew", padx=6)
        ctk.CTkButton(
            utility_actions, text="₽  +∞",
            command=lambda amount=bdsp_money_max: self.queue_inventory_change(
                "money-max", "Dinero", amount,
            ),
            fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
            height=58, corner_radius=12,
            font=ctk.CTkFont("Segoe UI Symbol", 21, "bold"),
        ).grid(row=0, column=2, sticky="ew", padx=(6, 0))

        grid = ctk.CTkFrame(self.body, fg_color="transparent")
        grid.grid(row=2 + row_offset, column=0, sticky="ew")
        grid.grid_columnconfigure((0, 1, 2), weight=1, uniform="team")
        pending_slots = {c.pokemon_slot for c in self.run.pending_changes if hasattr(c, "pokemon_slot")}
        # Debe calcularse dentro de Equipo. En 1.12.0 solo existía como variable
        # local del Dashboard y la primera tarjeta lanzaba NameError justo después
        # de dibujar el rol, dejando el resto del equipo sin renderizar.
        pending_team_changes = self._pending_team_changes()
        composition_locked = bool(pending_team_changes)
        # Los movimientos Equipo ↔ PC ya no bloquean nuevas operaciones. Si hay un
        # hueco proyectado, el botón sigue ofreciendo elegir un sustituto.
        can_complete_pending_pc = bool(pending_team_changes and len(projected_party) < 6)
        self.team_sprite_images = {}
        role_occupants, role_extras, display_index_by_identity, extra_role_indices = (
            self._team_role_grid_layout(projected_party)
        )
        display_party = [role_occupants[role] for role in ROLE_ORDER if role in role_occupants] + role_extras
        for role_index, role_name in enumerate(ROLE_ORDER):
            member = role_occupants.get(role_name)
            if member is None and role_index not in extra_role_indices:
                # La casilla sigue existiendo aunque el rol esté libre.
                empty_role = ctk.CTkFrame(
                    grid, fg_color="#151515", corner_radius=18, border_width=1, border_color="#3A3A3A",
                )
                empty_role.grid(row=role_index // 3, column=role_index % 3, sticky="nsew", padx=6, pady=6)
                self._main_role_drop_targets.append((empty_role, role_name))
                ctk.CTkButton(
                    empty_role, text="＋", width=88, height=70, corner_radius=14,
                    command=lambda r=role_name: self._open_team_to_pc_swap_picker(None, target_role=r),
                    fg_color="#202020", hover_color="#30291E", border_width=1,
                    border_color=GOLD, text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 38, "bold"),
                ).pack(pady=(36, 8))
                ctk.CTkLabel(
                    empty_role, text=f"{self._role_symbol(role_name)} {role_name}", text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 20, "bold"),
                ).pack()
                ctk.CTkLabel(
                    empty_role, text="AÑADIR DESDE PC · O ARRASTRA AQUÍ UN POKÉMON", text_color=MUTED,
                    font=ctk.CTkFont("Segoe UI", 11, "bold"), wraplength=250, justify="center",
                ).pack(padx=18, pady=(7, 36))
        # La disponibilidad de MTs se calcula como máximo una vez por render.
        # Así seis tarjetas no releen seis veces la mochila ni la ROM.
        tm_context_loaded = False
        tm_context = None
        tm_replacement_cache: dict[tuple[str, int], bool] = {}

        def has_tm_replacement(member: SavePokemon, move_slot: int) -> bool:
            nonlocal tm_context_loaded, tm_context
            key = (self._pokemon_identity(member), int(move_slot))
            if key in tm_replacement_cache:
                return tm_replacement_cache[key]

            # Alpha.18: Sol/Luna NO puede escanear FCRAM durante un render de
            # Equipo. El botón SUSTITUIR solo abre el selector; la existencia
            # real de una MT compatible se valida al pulsarlo, fuera del render.
            # Dejar el botón disponible no autoriza ninguna escritura.
            if getattr(self.save_engine, "key", "") in DEFERRED_LIVE_TM_INVENTORY_GAME_KEYS:
                available = self._tm_replacement_can_load_on_click()
                tm_replacement_cache[key] = available
                return available

            if not tm_context_loaded:
                tm_context = self._tm_replacement_context()
                tm_context_loaded = True
            available = False
            if tm_context is not None:
                profile, inventory = tm_context
                try:
                    available = bool(self._build_tm_candidates(member, move_slot, profile, inventory))
                except Exception:
                    available = False
            tm_replacement_cache[key] = available
            return available

        for pokemon in display_party:
            role, symbol = self._effective_role(pokemon)
            i = display_index_by_identity.get(self._pokemon_identity(pokemon), 99)
            card = ctk.CTkFrame(
                grid, fg_color="#191919", corner_radius=18,
                border_width=2 if pokemon.slot in pending_slots else 1,
                border_color=GOLD if pokemon.slot in pending_slots else "#343434",
            )
            card.grid(row=i // 3, column=i % 3, sticky="nsew", padx=6, pady=6)
            self.team_card_by_identity[self._pokemon_identity(pokemon)] = card
            image = self._get_team_sprite(pokemon)
            if image is not None:
                self.team_sprite_images[pokemon.slot] = image
                ctk.CTkLabel(card, text="", image=image).pack(pady=(14, 2))
            else:
                ctk.CTkLabel(card, text="", height=116).pack(pady=(8, 0))

            title = pokemon.nickname or pokemon.species
            ctk.CTkLabel(
                card, text=title, text_color=TEXT,
                font=ctk.CTkFont("Segoe UI", 27, "bold"),
            ).pack(pady=(2, 0))
            ctk.CTkLabel(
                card, text=f"{pokemon.species} · Nv. {pokemon.level}", text_color=MUTED,
                font=ctk.CTkFont("Segoe UI", 15),
            ).pack()

            role_color = GOLD if role != "SIN ROL" else (GOLD if self._role_rules_are_active() else MUTED)
            role_text = f"{symbol} {role}".strip()
            if role == "SIN ROL" and self._role_rules_are_active():
                role_text = "—  SIN ROL · NO APTO PARA COMBATE"
            ctk.CTkLabel(
                card, text=role_text, text_color=role_color,
                font=ctk.CTkFont("Segoe UI", 18, "bold"),
            ).pack(pady=(8, 8))

            # El rol permanece SIEMPRE editable. Los drafteos y las reorganizaciones
            # ya siguen la identidad estable del Pokémon, por lo que no hay motivo
            # para bloquear decisiones de teambuilding hasta el guardado final.
            actions = ctk.CTkFrame(card, fg_color="transparent")
            actions.pack(fill="x", padx=18, pady=(0, 12))
            actions.grid_columnconfigure((0, 1, 2), weight=1, uniform="teamactions")
            ctk.CTkButton(
                actions, text="CAMBIAR ROL", command=lambda p=pokemon: self.open_role_editor(p),
                height=37, fg_color="transparent", border_width=1, border_color=GOLD,
                hover_color=PANEL_ALT, text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 10, "bold"),
            ).grid(row=0, column=0, sticky="ew", padx=(0, 3))
            ctk.CTkButton(
                actions, text="CAMBIAR CON PC", height=37,
                command=lambda p=pokemon: self._open_team_to_pc_swap_picker(p),
                fg_color="transparent", border_width=1, border_color=GOLD,
                hover_color="#332B1D", text_color=GOLD, state="normal",
                font=ctk.CTkFont("Segoe UI", 9, "bold"),
            ).grid(row=0, column=1, sticky="ew", padx=3)
            ctk.CTkButton(
                actions, text="ENVIAR AL PC", height=37,
                command=lambda p=pokemon: self.send_pokemon_to_pc(p, ask=False),
                fg_color="transparent", border_width=1, border_color="#696969",
                hover_color=PANEL_ALT, text_color=TEXT, state="normal",
                font=ctk.CTkFont("Segoe UI", 9, "bold"),
            ).grid(row=0, column=2, sticky="ew", padx=(3, 0))

            details = ctk.CTkFrame(card, fg_color="transparent")
            details.pack(fill="x", padx=14, pady=(0, 10))
            details.grid_columnconfigure((0, 1), weight=1, uniform="details")
            ability_box = ctk.CTkFrame(details, fg_color="#151515", corner_radius=10, border_width=1, border_color="#333333")
            ability_box.grid(row=0, column=0, sticky="nsew", padx=(0, 3))
            ctk.CTkLabel(
                ability_box, text="HABILIDAD", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).pack(pady=(8, 2))
            ctk.CTkLabel(
                ability_box, text=pokemon.ability or "Desconocida", text_color=TEXT,
                wraplength=160, justify="center",
                font=ctk.CTkFont("Segoe UI", 16, "bold"),
            ).pack(padx=6, pady=(0, 9))

            item_box = ctk.CTkFrame(details, fg_color="#151515", corner_radius=10, border_width=1, border_color="#333333")
            item_box.grid(row=0, column=1, sticky="nsew", padx=(3, 0))
            ctk.CTkLabel(
                item_box, text="OBJETO", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 11, "bold"),
            ).pack(pady=(8, 2))
            ctk.CTkLabel(
                item_box, text=pokemon.held_item or "Sin objeto", text_color=TEXT,
                wraplength=160, justify="center",
                font=ctk.CTkFont("Segoe UI", 16, "bold"),
            ).pack(padx=6, pady=(0, 9))

            move_issues = self._collect_pokemon_move_issues(pokemon, role) if role != "SIN ROL" else []
            issue_by_slot = {int(issue["move_slot"]): issue for issue in move_issues}
            incompatible_slots = set(issue_by_slot)
            support_excess, support_candidates = self._support_damage_excess(pokemon, role)
            support_damage_slots = {int(item["move_slot"]) for item in support_candidates} if support_excess else set()
            # La tarjeta debe reflejar el moveset proyectado (incluidos borrados o
            # cambios todavía pendientes) y no el snapshot antiguo del guardado.
            # Así el rojo siempre corresponde al movimiento que realmente quedará.
            display_moves, display_move_ids = self._effective_moves_for_review(pokemon)
            moves_grid = ctk.CTkFrame(card, fg_color="transparent")
            moves_grid.pack(fill="x", padx=14, pady=(0, 8 if (move_issues or support_excess) else 14))
            moves_grid.grid_columnconfigure((0, 1), weight=1, uniform="moves")
            for move_index, move_name in enumerate(display_moves[:4], start=1):
                move_id = int(display_move_ids[move_index - 1] or 0)
                incompatible = move_index in incompatible_slots
                support_choice = move_index in support_damage_slots and not incompatible
                if move_id == 0:
                    # Un hueco vacío se convierte en una acción. En BDSP abre las
                    # MTs reales de la mochila cruzadas con personal_masterdatas.
                    ctk.CTkButton(
                        moves_grid, text="＋", height=56, corner_radius=10,
                        command=lambda p=pokemon, slot=move_index: self._open_tm_selector(p, slot),
                        fg_color=PANEL_ALT, hover_color="#30291E",
                        border_width=1, border_color=GOLD, text_color=GOLD,
                        font=ctk.CTkFont("Segoe UI", 28, "bold"),
                    ).grid(
                        row=(move_index - 1) // 2, column=(move_index - 1) % 2,
                        sticky="nsew", padx=3, pady=3,
                    )
                    continue
                move_box = ctk.CTkFrame(
                    moves_grid,
                    # Incompatibilidad individual: rojo inequívoco en fondo, borde
                    # y texto. El dorado de Support solo significa "elige cuáles
                    # sobran", no que esos movimientos sean ilegales por sí solos.
                    fg_color="#341A1A" if incompatible else ("#292315" if support_choice else PANEL_ALT),
                    corner_radius=10, border_width=2 if incompatible else 1,
                    border_color=DANGER if incompatible else (GOLD if support_choice else "#3A3A3A"), height=56,
                )
                move_box.grid(
                    row=(move_index - 1) // 2, column=(move_index - 1) % 2,
                    sticky="nsew", padx=3, pady=3,
                )
                move_box.grid_propagate(False)
                ctk.CTkLabel(
                    move_box, text=move_name or "—",
                    text_color=DANGER if incompatible else (GOLD if support_choice else TEXT),
                    font=ctk.CTkFont("Segoe UI", 17, "bold"),
                    wraplength=175, justify="center",
                ).place(relx=0.5, rely=0.5, anchor="center")
            if support_excess:
                ctk.CTkLabel(
                    card,
                    text=f"◆ Support tiene {len(support_candidates)} movimientos de daño · elige {support_excess} para eliminar",
                    text_color=GOLD, font=ctk.CTkFont("Segoe UI", 9, "bold"),
                ).pack(padx=14, pady=(0, 6))
                ctk.CTkButton(
                    card,
                    text=f"ELEGIR {support_excess} MOVIMIENTO(S) DE DAÑO A ELIMINAR",
                    command=lambda p=pokemon: self._open_support_damage_removal_selector(p),
                    height=34, fg_color="transparent", border_width=1, border_color=GOLD,
                    hover_color="#332B1D", text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 9, "bold"),
                ).pack(fill="x", padx=14, pady=(0, 8))
            if move_issues:
                issue_actions = ctk.CTkFrame(card, fg_color="#221515", corner_radius=10, border_width=1, border_color="#5A2A2A")
                issue_actions.pack(fill="x", padx=14, pady=(0, 10))
                for issue_index, issue in enumerate(move_issues):
                    move_slot = int(issue["move_slot"])
                    replacement_available = has_tm_replacement(pokemon, move_slot)
                    row = ctk.CTkFrame(issue_actions, fg_color="transparent")
                    row.pack(fill="x", padx=8, pady=(7 if issue_index == 0 else 3, 7 if issue_index == len(move_issues) - 1 else 3))
                    row.grid_columnconfigure(0, weight=1)
                    ctk.CTkLabel(
                        row, text=str(issue["move_name"]), text_color=DANGER, anchor="w",
                        font=ctk.CTkFont("Segoe UI", 10, "bold"), wraplength=135,
                    ).grid(row=0, column=0, sticky="ew", padx=(2, 6))
                    ctk.CTkButton(
                        row, text="SUSTITUIR", width=82, height=29,
                        command=lambda p=pokemon, slot=move_slot: self._open_tm_selector(p, slot, replace_existing=True),
                        state="normal" if replacement_available else "disabled",
                        fg_color=GOLD if replacement_available else "#292929",
                        hover_color="#D3AF70", text_color="#111111" if replacement_available else MUTED,
                        text_color_disabled="#6A6A6A", border_width=1,
                        border_color=GOLD if replacement_available else "#414141",
                        font=ctk.CTkFont("Segoe UI", 8, "bold"),
                    ).grid(row=0, column=1, padx=3)
                    ctk.CTkButton(
                        row, text="ELIMINAR ATAQUE", width=112, height=29,
                        command=lambda current_issue=dict(issue): self._queue_invalid_move_removals([current_issue]),
                        fg_color="transparent", border_width=1, border_color=DANGER,
                        hover_color="#3A2222", text_color=DANGER,
                        font=ctk.CTkFont("Segoe UI", 8, "bold"),
                    ).grid(row=0, column=2, padx=(3, 0))
            if pokemon.slot in pending_slots:
                ctk.CTkLabel(
                    card, text="● CAMBIOS PENDIENTES", text_color=GOLD,
                    font=ctk.CTkFont("Segoe UI", 9, "bold"),
                ).pack(pady=(0, 12))

            if role in ROLE_ORDER and role_occupants.get(role) is pokemon:
                # Esta tarjeta ocupa físicamente la casilla de SU rol fijo.
                self._main_role_drop_targets.append((card, role))
            self._register_role_drag_tree(card, pokemon, "main", card, role if role in ROLE_ORDER else "SIN ROL")

        # El espacio físico del equipo y las casillas de rol son conceptos
        # distintos. Si aún caben Pokémon, ofrecemos añadirlos sin inventar una
        # séptima "casilla de rol": entrarán SIN ROL, como hasta ahora.
        if len(projected_party) < 6:
            add_row = 2
            add_panel = ctk.CTkFrame(grid, fg_color="#171717", corner_radius=14, border_width=1, border_color="#3A3A3A")
            add_panel.grid(row=add_row, column=0, columnspan=3, sticky="ew", padx=6, pady=(8, 4))
            add_panel.grid_columnconfigure(0, weight=1)
            ctk.CTkLabel(
                add_panel, text=f"＋  {6 - len(projected_party)} HUECO(S) FÍSICO(S) EN EL EQUIPO", text_color=GOLD,
                font=ctk.CTkFont("Segoe UI", 15, "bold"),
            ).grid(row=0, column=0, sticky="w", padx=16, pady=13)
            ctk.CTkButton(
                add_panel, text="ABRIR PC" if not can_complete_pending_pc else "ELEGIR POKÉMON DEL PC", height=38,
                command=self.open_pc_selector, fg_color=GOLD, hover_color="#D3AF70", text_color="#111111",
                font=ctk.CTkFont("Segoe UI", 10, "bold"),
            ).grid(row=0, column=1, padx=14, pady=9)

    def _get_bdsp_tm_profile(self, prompt: bool = False) -> BDSPTMProfile | None:
        """Carga la tabla real MT→movimiento de la randomización de BDSP.

        Primero intenta localizarla automáticamente en Ryujinx (incluida la ruta
        Atmosphère/Output usada por Imposter's Ordeal). Solo abre un selector si
        el usuario pulsa un '+' y la detección automática no fue suficiente.
        """
        if getattr(self.save_engine, "key", "") != "bdsp":
            return None
        source = discover_personal_masterdatas()
        if source is not None:
            try:
                # load_bdsp_tm_profile ya cachea por ruta + mtime + tamaño. Así
                # una nueva randomización que sobrescriba el mismo archivo se
                # recarga automáticamente sin penalizar las aperturas normales.
                profile = load_bdsp_tm_profile(source)
                self._bdsp_tm_profile = profile
                self._bdsp_tm_profile_source = source
                self._bdsp_tm_auto_checked = True
                return profile
            except Exception as exc:
                self._bdsp_tm_profile = None
                self._bdsp_tm_profile_source = None
                self._bdsp_tm_auto_checked = True
                if prompt:
                    messagebox.showwarning(
                        "No se pudo leer la tabla de MTs",
                        f"Se encontró personal_masterdatas, pero no se pudo interpretar:\n\n{exc}\n\nSelecciona manualmente el archivo correcto.",
                    )
        elif not self._bdsp_tm_auto_checked:
            self._bdsp_tm_auto_checked = True

        if not prompt:
            return None

        messagebox.showinfo(
            "Tabla de MTs randomizadas",
            "RoleRun Manager necesita personal_masterdatas para saber qué movimiento enseña realmente cada MT y qué Pokémon puede aprenderla.\n\n"
            "Selecciona el archivo de tu mod de Imposter's Ordeal. Normalmente está dentro de:\n"
            "Ryujinx\\sdcard\\atmosphere\\contents\\...\\Output\\romfs\\Data\\StreamingAssets\\AssetAssistant\\Pml",
        )
        selected = filedialog.askopenfilename(
            title="Selecciona personal_masterdatas",
            filetypes=[("personal_masterdatas", "personal_masterdatas"), ("Todos los archivos", "*")],
        )
        if not selected:
            return None
        try:
            profile = load_bdsp_tm_profile(selected)
            remember_source(selected)
            self._bdsp_tm_profile = profile
            self._bdsp_tm_profile_source = Path(selected).resolve()
            return profile
        except Exception as exc:
            messagebox.showerror(
                "Archivo no válido",
                f"No se pudo leer el archivo seleccionado como personal_masterdatas de BDSP:\n\n{exc}",
            )
            return None

    def _ensure_bdsp_levelup_table_loaded(self) -> None:
        """Decodifica WazaOboeTable una vez por sesión (no una vez por sondeo).

        BDSP no puede parchear la tabla que lee el propio juego (no hay mod
        de LayeredFS confirmado para Ryujinx, ver
        ``app/bdsp_levelup_moves.py``): esta tabla solo sirve para saber, al
        cruzar un nivel, qué movimiento vainilla le tocaría a cada especie —
        la sustitución real ocurre reescribiendo el hueco ya aprendido, en
        ``_sync_bdsp_levelup_moves``. Un fallo aquí nunca debe impedir que
        RoleRun siga funcionando sin esta capacidad.

        Se llama en CADA sondeo en vivo (cada 250-950 ms), así que una vez
        cargada la tabla con éxito no se vuelve a buscar el archivo de
        origen: ``discover_personal_masterdatas`` recorre directorios del
        disco (Atmosphere/mods de Ryujinx), y repetirlo en cada sondeo fue
        la causa demostrada el 2026-09-04 de una ralentización general de
        toda la aplicación -el archivo no se mueve mientras el juego sigue
        abierto, así que no hace falta volver a buscarlo hasta reiniciar
        RoleRun-.
        """
        if getattr(self.save_engine, "key", "") != "bdsp":
            return
        if self._bdsp_levelup_table is not None:
            return
        source = discover_personal_masterdatas()
        if source is None:
            return
        source_key = str(source)
        try:
            objects = load_personal_masterdatas_objects(source)
            self._bdsp_levelup_table = parse_wazaoboe_table(objects)
            self._bdsp_levelup_table_source = source_key
            self._registrar_intento_vivo(
                "bdsp_levelup_tabla_ok", entradas=len(self._bdsp_levelup_table),
            )
        except Exception as exc:
            self._registrar_intento_vivo("bdsp_levelup_tabla_error", error=str(exc))

    def _bdsp_levelup_usable_move_ids(self) -> set[int] | None:
        allowed = self.engine.allowed_move_ids
        return set(int(move_id) for move_id in allowed) if allowed is not None else None

    def _sync_bdsp_levelup_table_patch(self, game: SaveGameData | None) -> None:
        """Parcheo proactivo de WazaOboeTable en vivo (Enfoque A para BDSP).

        Antes de que el juego llegue a enseñar nada, se mantiene la fila de
        la tabla de cada especie/forma del equipo ya parcheada con el
        movimiento de rol — para que el propio diálogo "X quiere aprender
        <movimiento>" del juego muestre ya el nombre correcto, en vez de la
        sustitución a ciegas de ``_sync_bdsp_levelup_moves`` (Enfoque B, que
        se mantiene intacto como red de seguridad si este parche no llega a
        tiempo). Demostrado en vivo el 2026-09-03 contra la partida real del
        usuario: tras parchear la tabla, el propio diálogo del juego mostró
        el movimiento sustituto.

        Como la tabla es compartida por especie/forma (no por individuo),
        si dos miembros ACTIVOS del equipo son de la misma especie con
        roles distintos, se elige un único ganador determinista por sondeo
        —el de menor slot— para no alternar el contenido cada vez.
        """
        if getattr(self.save_engine, "key", "") != "bdsp" or game is None:
            return
        self._ensure_bdsp_levelup_table_loaded()
        if not self._bdsp_levelup_table:
            return
        adapter = getattr(self, "bdsp_realtime_adapter", None)
        sync = getattr(adapter, "sync_levelup_table", None)
        if sync is None:
            return
        try:
            usable_move_ids = self._bdsp_levelup_usable_move_ids()
            winners: dict[tuple[int, int], SavePokemon] = {}
            for pokemon in game.party:
                species_form = (int(pokemon.species_id), int(getattr(pokemon, "form", 0) or 0))
                current = winners.get(species_form)
                if current is None or int(pokemon.slot) < int(current.slot):
                    winners[species_form] = pokemon

            patches: dict[tuple[int, int], dict[int, int]] = {}
            anchors: dict[tuple[int, int], object] = {}
            for species_form, pokemon in winners.items():
                species_id, form = species_form
                entries = (
                    self._bdsp_levelup_table.get((species_id, form))
                    or self._bdsp_levelup_table.get((species_id, 0))
                )
                if not entries:
                    continue
                role, _symbol = self._effective_role(pokemon)
                patch = compute_species_patch(
                    entries, role, species_id=species_id,
                    pools=self.engine.pools, damage_classes=self.engine.damage_classes,
                    speed_status_moves=self.engine.speed_status_moves,
                    self_healing_damage_moves=self.engine.self_healing_damage_moves,
                    usable_move_ids=usable_move_ids,
                )
                if not patch:
                    continue
                # Comodín SOLO en las entradas que de verdad hace falta
                # parchear (no en las 15-20 de toda la tabla): un patrón
                # demasiado genérico puede coincidir por azar en otro punto
                # de la memoria y perder la especie como ambigua —
                # demostrado el 2026-09-04 con Absol.
                anchors[species_form] = build_species_anchor(
                    species_form, entries, wildcard_keys=frozenset(patch.keys()),
                )
                patches[species_form] = {int(index): int(move_id) for index, move_id in patch.items()}

            if not patches:
                return
            outcomes = sync(patches, anchors)
            for outcome in outcomes:
                if outcome.changed:
                    self._registrar_intento_vivo(
                        "bdsp_levelup_tabla_parcheada",
                        especie_forma=list(outcome.species_form),
                        indices=list(outcome.patched_indices),
                    )
        except Exception as exc:
            self._registrar_intento_vivo("bdsp_levelup_tabla_parche_error", error=str(exc))

    def _sync_bdsp_levelup_moves(self, game: SaveGameData | None) -> None:
        """Aprendizajes por rol en BDSP: red de seguridad tras el parche proactivo.

        Se llama en cada sondeo en vivo, después de
        ``_sync_bdsp_levelup_table_patch`` (Enfoque A: parchea la tabla en
        vivo para que el propio diálogo del juego ya muestre el movimiento
        de rol — demostrado el 2026-09-03 contra la partida real del
        usuario). Este método es el Enfoque B (sustitución posterior) que
        se queda como respaldo: si el parche proactivo no llegó a tiempo
        (primer arranque, especie recién detectada, tabla no localizada
        todavía) el juego enseña el vainilla, y aquí se reescribe el mismo
        hueco reutilizando el camino que ya usa cualquier cambio de
        movimiento confirmado por el usuario (``PendingChange`` +
        ``_request_oras_live_auto_apply_since``) — nunca un escritor nuevo.

        El diálogo de aprendizaje del juego puede tardar más de un sondeo en
        resolverse (o el jugador puede rechazar el movimiento): las entradas
        cruzadas se guardan en ``_bdsp_levelup_pending`` y se reintentan en
        cada sondeo hasta ver aparecer el movimiento vainilla O el sustituto
        en la party de verdad (el sustituto aparece directamente cuando el
        parche proactivo sí llegó a tiempo — en ese caso no hace falta
        ningún ``PendingChange``, pero el historial de "recuerda-
        movimientos" se registra igual), comparado contra un
        ``known_before`` fijado en el momento del cruce -para no confundir
        un movimiento que ya tenía de antes con uno recién aprendido-.
        """
        if (
            getattr(self.save_engine, "key", "") != "bdsp"
            or game is None
            or self.project is None
        ):
            return
        self._ensure_bdsp_levelup_table_loaded()
        if not self._bdsp_levelup_table:
            return
        try:
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            usable_move_ids = self._bdsp_levelup_usable_move_ids()
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                species_id = int(pokemon.species_id)
                form = int(getattr(pokemon, "form", 0) or 0)
                previous = self._bdsp_levelup_last_levels.get(identity)
                self._bdsp_levelup_last_levels[identity] = level
                current_ids = [int(move_id or 0) for move_id in pokemon.move_ids[:4]]
                entries = (
                    self._bdsp_levelup_table.get((species_id, form))
                    or self._bdsp_levelup_table.get((species_id, 0))
                )

                if previous is None:
                    # Recuerda-movimientos: la primera vez que RoleRun ve a
                    # este Pokémon en toda la Run, se retro-rellena con lo
                    # que habría aprendido sin ajustar a ningún rol hasta su
                    # nivel actual —igual que ya hace ORAS—, sin tocar nada
                    # en RAM: es solo historial de lo que pasó antes de que
                    # RoleRun lo gestionara.
                    if entries and identity not in self.project.oras_levelup_move_history:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        self._append_bdsp_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True,
                        )
                    self._registrar_intento_vivo(
                        "bdsp_levelup_primera_vez",
                        identidad=identity, especie=species_id,
                        nivel=level, movimientos=current_ids,
                    )

                if previous is not None and level > previous and level > 0:
                    crossed = tuple(entry for entry in (entries or ()) if previous < entry[1] <= level)
                    self._registrar_intento_vivo(
                        "bdsp_levelup_cruce_detectado",
                        identidad=identity, especie=species_id, forma=form,
                        nivel_anterior=previous, nivel_actual=level,
                        hay_tabla_para_especie=bool(entries),
                        entradas_totales=len(entries or ()),
                        cruzadas=[(int(m), int(l)) for m, l, _k in crossed],
                    )
                    if crossed:
                        role, _symbol = self._effective_role(pokemon)
                        # Se calcula sobre TODAS las entradas de la especie
                        # (no solo las cruzadas), exactamente igual que
                        # ``_sync_bdsp_levelup_table_patch`` (Enfoque A) —
                        # ``compute_species_patch`` excluye del pool de
                        # candidatos los movimientos ya usados en el resto de
                        # la tabla que se le pase, así que pasarle un
                        # subconjunto distinto podía elegir un sustituto
                        # DISTINTO para la misma entrada y que esta detección
                        # nunca reconociera lo que el parche proactivo ya
                        # había enseñado -demostrado el 2026-09-03-.
                        patch = compute_species_patch(
                            entries, role, species_id=species_id,
                            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
                            speed_status_moves=self.engine.speed_status_moves,
                            self_healing_damage_moves=self.engine.self_healing_damage_moves,
                            usable_move_ids=usable_move_ids,
                        )
                        self._registrar_intento_vivo(
                            "bdsp_levelup_parche_calculado",
                            identidad=identity, rol=str(role),
                            parche=[(int(v), int(s)) for v, s in patch.items()] if patch else [],
                        )
                        # Recuerda-movimientos: se registra AQUÍ, en el
                        # instante del cruce, igual que ya hace ORAS
                        # (``_record_oras_levelup_move_history``) — no se
                        # espera a ver el movimiento confirmado en la party.
                        # Pedido por el usuario el 2026-09-04: si el jugador
                        # rechaza o deja sin resolver el diálogo del juego,
                        # el movimiento que le habría tocado por su rol debe
                        # seguir apareciendo en el historial de todos modos
                        # -es lo que el rol dice que le corresponde, no una
                        # promesa de que el juego ya lo aplicó-.
                        for vanilla_move_id, entry_level, key in crossed:
                            self._append_bdsp_levelup_history_record(
                                identity, pokemon, species_id, entry_level,
                                int(patch.get(key, vanilla_move_id)), role,
                                pre_capture=False,
                            )
                        if patch:
                            known_before = frozenset(mid for mid in current_ids if mid > 0)
                            expires_at = time.monotonic() + BDSP_LEVELUP_PENDING_GRACE_SECONDS
                            pending = self._bdsp_levelup_pending.setdefault(identity, set())
                            for vanilla_move_id, entry_level, key in crossed:
                                substitute = patch.get(key)
                                if substitute is None:
                                    continue
                                pending.add((
                                    int(vanilla_move_id), int(substitute), known_before,
                                    str(role), int(entry_level), expires_at,
                                ))

                pending = self._bdsp_levelup_pending.get(identity)
                if not pending:
                    continue
                still_pending: set[tuple[int, int, frozenset, str, int, float]] = set()
                pokemon_identity = self._pokemon_identity(pokemon)
                now = time.monotonic()
                for vanilla_move_id, substitute, known_before, role, entry_level, expires_at in pending:
                    if vanilla_move_id in known_before:
                        # Ya lo tenía antes de este cruce: no fue este
                        # aprendizaje el que lo puso ahí. Se descarta sin
                        # tocar un hueco que no viene de aquí.
                        self._registrar_intento_vivo(
                            "bdsp_levelup_descartado_ya_conocido",
                            identidad=identity, movimiento_vainilla=vanilla_move_id,
                        )
                        continue
                    if substitute in current_ids and vanilla_move_id not in current_ids:
                        # El parche proactivo (_sync_bdsp_levelup_table_patch)
                        # llegó a tiempo: el juego ya enseñó directamente el
                        # movimiento de rol, así que el vainilla nunca
                        # aparece y no hace falta ningún PendingChange. Solo
                        # falta el historial de "recuerda-movimientos", que
                        # de otro modo nunca se registraría.
                        self._append_bdsp_levelup_history_record(
                            identity, pokemon, species_id, entry_level, substitute, role,
                            pre_capture=False,
                        )
                        self._registrar_intento_vivo(
                            "bdsp_levelup_confirmado_por_parche_proactivo",
                            identidad=identity, sustituto=substitute,
                        )
                        continue
                    if vanilla_move_id not in current_ids:
                        # El diálogo del juego puede no haberse resuelto
                        # todavía (o el jugador rechazó aprender nada — en ese
                        # caso el moveset nunca cambia y esto queda esperando
                        # sin más, hasta el margen de abajo). Reintentar
                        # mientras quede margen POR NIVEL (subidas normales,
                        # de una en una) O por TIEMPO real transcurrido desde
                        # el cruce (un salto de nivel enorme de una vez, como
                        # varios Caramelo Raro seguidos, agota el margen por
                        # nivel en el mismo sondeo del cruce, pero el juego
                        # todavía puede tardar varios sondeos en encolar y
                        # resolver los diálogos en cadena).
                        if level - entry_level <= 20 or now < expires_at:
                            still_pending.add((
                                vanilla_move_id, substitute, known_before, role, entry_level,
                                expires_at,
                            ))
                            self._registrar_intento_vivo(
                                "bdsp_levelup_esperando_al_juego",
                                identidad=identity, movimiento_vainilla=vanilla_move_id,
                                movimientos_actuales=current_ids,
                            )
                        else:
                            self._registrar_intento_vivo(
                                "bdsp_levelup_abandonado",
                                identidad=identity, movimiento_vainilla=vanilla_move_id,
                                nivel_de_la_entrada=entry_level, nivel_actual=level,
                            )
                        continue
                    move_slot = current_ids.index(vanilla_move_id) + 1
                    move_name = str(self.engine.move(vanilla_move_id).get("name_es") or f"Movimiento #{vanilla_move_id}")
                    substitute_name = str(self.engine.move(substitute).get("name_es") or f"Movimiento #{substitute}")
                    change = PendingChange(
                        role=role,
                        pokemon_slot=pokemon.slot,
                        pokemon=pokemon.nickname or pokemon.species,
                        species=pokemon.species,
                        move_slot=move_slot,
                        old_move=move_name,
                        old_move_id=vanilla_move_id,
                        new_move=substitute_name,
                        new_move_id=substitute,
                        pokemon_identity=pokemon_identity,
                    )
                    self.run.pending_changes = [
                        existing for existing in self.run.pending_changes
                        if not (
                            isinstance(existing, (PendingChange, PendingTMTeach))
                            and getattr(existing, "move_slot", 0) == change.move_slot
                            and getattr(existing, "pokemon_identity", "") == pokemon_identity
                        )
                    ]
                    self.run.pending_changes.append(change)
                    # Recuerda-movimientos: se registra AQUÍ, no al detectar el
                    # cruce -a diferencia de ORAS, la sustitución de BDSP no
                    # está garantizada hasta este momento (el jugador podría
                    # haber rechazado aprender nada)-.
                    self._append_bdsp_levelup_history_record(
                        identity, pokemon, species_id, entry_level, substitute, role,
                        pre_capture=False,
                    )
                    self._registrar_intento_vivo(
                        "bdsp_levelup_sustitucion_encolada",
                        identidad=identity, hueco=move_slot,
                        vainilla=vanilla_move_id, sustituto=substitute,
                    )
                if still_pending:
                    self._bdsp_levelup_pending[identity] = still_pending
                elif identity in self._bdsp_levelup_pending:
                    del self._bdsp_levelup_pending[identity]
            self._request_oras_live_auto_apply_since(pending_ids_before)
        except Exception as exc:
            self._registrar_intento_vivo("bdsp_levelup_sync_error", error=str(exc))

    def _append_bdsp_levelup_history_record(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        level: int, move_id: int, role: str, *, pre_capture: bool,
    ) -> bool:
        """Recuerda-movimientos de BDSP: una entrada YA resuelta.

        A diferencia de ORAS, aquí nunca se calcula un parche: quien llama
        ya sabe el movimiento exacto que corresponde -el que de verdad se
        escribió en la sustitución confirmada, o el vainilla en el
        retro-relleno de la primera vez-. Calcularlo de nuevo aquí, sobre
        una sola entrada suelta, podría dar un sustituto distinto al que
        realmente quedó en el hueco si esa entrada cruzó junto a otras en el
        mismo sondeo (``compute_species_patch`` excluye entre sí los
        movimientos del mismo lote).
        """
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        record_key = (int(level), int(move_id))
        if record_key in seen:
            return False
        history.append({
            "level": int(level),
            "move_id": int(move_id),
            "role": str(role),
            "species_id": species_id,
            "nickname": str(pokemon.nickname or pokemon.species),
            "recorded_at": datetime.now().isoformat(timespec="seconds"),
            "pre_capture": bool(pre_capture),
        })
        self.project_service.save(self.project)
        return True

    def _append_bdsp_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool,
    ) -> bool:
        """Retro-relleno de la primera vez: calcula qué le habría tocado a
        cada entrada vainilla con el rol de ahora, igual que ORAS, para que
        la pantalla decida si ENSEÑAR tiene sentido. Solo para eso — una
        sustitución ya confirmada en RAM se registra con
        ``_append_bdsp_levelup_history_record`` directamente, sin recalcular
        nada.
        """
        if not entries:
            return False
        patch = compute_species_patch(
            entries, role, species_id=species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._bdsp_levelup_usable_move_ids(),
        )
        changed = False
        for vanilla_move_id, entry_level, key in entries:
            actual_move_id = int(patch.get(key, vanilla_move_id))
            if self._append_bdsp_levelup_history_record(
                identity, pokemon, species_id, entry_level, actual_move_id, role,
                pre_capture=pre_capture,
            ):
                changed = True
        return changed

    def _clear_oras_rom_tm_runtime_profile(self) -> None:
        self._oras_rom_tm_profile = None
        self._oras_rom_tm_profile_source = None
        self._oras_rom_tm_profile_process = None
        self._oras_rom_tm_last_error = None
        self._oras_discovered_rom_source = None
        self._oras_discovered_rom_source_process = None

    def _prepare_oras_live_metadata_profile(self) -> ORASTMProfile | None:
        """Carga el Personal ORAS antes de publicar equipo o PC vivos.

        El callback del adaptador es deliberadamente de solo consulta para no
        descubrir ni persistir rutas desde un worker. Por eso esta preparación
        ocurre en el hilo de UI, antes de iniciar cualquier captura.
        """
        if getattr(self.save_engine, "key", "") != "oras":
            return None
        return self._get_oras_rom_tm_profile(prompt=False)

    def _remember_oras_rom_tm_profile(
        self, profile: ORASTMProfile, process_name: str | None, azahar_root: Path | None = None,
    ) -> ORASTMProfile:
        """Asocia una ROM ORAS validada a la Run sin guardar datos del juego."""
        self._oras_rom_tm_profile = profile
        self._oras_rom_tm_profile_source = profile.source
        self._oras_rom_tm_profile_process = process_name
        if self.project is not None:
            source_text = str(profile.source)
            if getattr(self.project, "oras_tm_rom_path", "") != source_text:
                self.project.oras_tm_rom_path = source_text
                self.project_service.save(self.project)
        self._ensure_oras_levelup_moves_registered(profile.source, azahar_root, process_name)
        return profile

    def _ensure_oras_levelup_moves_registered(
        self, rom_path: Path, azahar_root: Path | None, process_name: str | None,
    ) -> None:
        """Prepara el mod de aprendizajes por nivel para la ROM ORAS activa.

        Solo lee la tabla vainilla y garantiza que el archivo de mod exista
        con ese tamaño (ver ``app/oras_levelup_moves.ensure_registered``).
        Nunca escribe el contenido ajustado a roles aquí: eso lo hace
        ``_sync_oras_levelup_moves_mod`` en cada sondeo en vivo. Un fallo
        aquí nunca debe impedir que RoleRun siga funcionando sin esta
        capacidad — la tabla de MT ya validada no depende de esto.
        """
        if getattr(self.save_engine, "key", "") != "oras" or azahar_root is None:
            return
        try:
            with perf.span("ui.ensure_oras_levelup_moves.load_blob"):
                blob, title_id = load_oras_levelup_moves_blob(
                    rom_path, process_name=process_name, azahar_root=azahar_root,
                )
            with perf.span("ui.ensure_oras_levelup_moves.ensure_registered"):
                estado = oras_levelup_moves_mod.ensure_registered(azahar_root, title_id, blob)
        except Exception as exc:
            self._registrar_intento_vivo(
                "oras_levelup_registro_error", error=str(exc), rom_path=str(rom_path),
                azahar_root=str(azahar_root),
            )
            return
        self._oras_levelup_moves_vanilla = blob
        self._oras_levelup_moves_title_id = title_id
        self._oras_levelup_moves_azahar_root = Path(azahar_root)
        self._oras_levelup_moves_last_written = None
        self._oras_levelup_moves_last_roles_key = None
        self._oras_levelup_moves_vanilla_entries = oras_levelup_moves_mod.parse_levelup_garc(blob)
        self._registrar_intento_vivo(
            "oras_levelup_registro_ok", estado=estado, title_id=f"{title_id:016X}",
            azahar_root=str(azahar_root), blob_size=len(blob),
        )

    @perf.timed("ui.sync_oras_levelup_moves_mod")
    def _sync_oras_levelup_moves_mod(self, game: SaveGameData | None) -> None:
        """Ajusta al rol el mod de aprendizajes por nivel de ORAS, si aplica.

        Se llama en cada sondeo en vivo con la party ya leída de Azahar. Solo
        toca las especies con un miembro activo en el equipo con un rol que
        de verdad restringe algo (Líbero y SIN ROL se dejan tal cual: ver
        ``app/oras_levelup_moves.py``). Nunca escribe si el contenido
        calculado es igual al último escrito, ni si el archivo de mod no
        quedó registrado con el tamaño correcto.

        Pedido por el usuario el 2026-09-03 tras notar el programa lento: si
        el mapa especie→rol de este sondeo es igual al del anterior, se sale
        antes de recalcular nada — ni la copia del blob ni la evaluación de
        cada entrada de nivel. Antes se repetía ese trabajo en cada sondeo
        (hasta cada 250ms) aunque los roles no hubieran cambiado.
        """
        if (
            getattr(self.save_engine, "key", "") != "oras"
            or game is None
            or self._oras_levelup_moves_vanilla is None
            or self._oras_levelup_moves_title_id is None
            or self._oras_levelup_moves_azahar_root is None
        ):
            return
        self._record_oras_levelup_move_history(game)
        try:
            roles_by_species: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                roles_by_species[int(pokemon.species_id)] = role
            # El resto de esta función —copiar el blob vainilla y evaluar
            # cada entrada de nivel de cada especie en juego— es trabajo
            # real de CPU que antes se repetía en cada sondeo aunque nada
            # hubiera cambiado desde el anterior. Si el mapa especie→rol es
            # idéntico al del último sondeo (el caso normal: los roles solo
            # cambian cuando el usuario los cambia), el parche ya calculado
            # sigue siendo válido tal cual, así que no hace falta
            # reconstruirlo ni volver a compararlo byte a byte.
            roles_key = (
                frozenset(roles_by_species.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key == self._oras_levelup_moves_last_roles_key:
                return
            # Nunca ofrecer un sustituto fuera del rango real de ORAS. Los
            # pools de data/moves.json son comunes a todos los juegos y
            # llegan a movimientos de generaciones muy posteriores (más allá
            # de 621) que ORAS no reconoce y mostraría en blanco. Se usa
            # `engine.allowed_move_ids` cuando ya está poblado (más preciso:
            # respeta lo que el guardado activo declara jugable) y si todavía
            # no lo está, el rango completo de IDs de ORAS como red de
            # seguridad — nunca sin ningún filtro.
            usable_move_ids = (
                set(int(move_id) for move_id in self.engine.allowed_move_ids)
                if self.engine.allowed_move_ids is not None
                else set(range(1, _ORAS_MAX_MOVE_ID + 1))
            )
            patched = oras_levelup_moves_mod.build_party_patched_blob(
                self._oras_levelup_moves_vanilla, roles_by_species,
                pools=self.engine.pools,
                damage_classes=self.engine.damage_classes,
                speed_status_moves=self.engine.speed_status_moves,
                self_healing_damage_moves=self.engine.self_healing_damage_moves,
                usable_move_ids=usable_move_ids,
                entries_by_species=self._oras_levelup_moves_vanilla_entries,
            )
            if patched == self._oras_levelup_moves_last_written:
                self._oras_levelup_moves_last_roles_key = roles_key
                return
            oras_levelup_moves_mod.write_blob(
                self._oras_levelup_moves_azahar_root,
                self._oras_levelup_moves_title_id,
                patched,
                expected_size=len(self._oras_levelup_moves_vanilla),
            )
            self._oras_levelup_moves_last_written = patched
            self._oras_levelup_moves_last_roles_key = roles_key
            self._registrar_intento_vivo(
                "oras_levelup_sync_escrito", roles_by_species=roles_by_species,
            )
        except Exception as exc:
            self._registrar_intento_vivo("oras_levelup_sync_error", error=str(exc))
            return

    def _oras_levelup_usable_move_ids(self) -> set[int]:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else set(range(1, _ORAS_MAX_MOVE_ID + 1))
        )

    def _append_oras_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool,
    ) -> bool:
        """Calcula la sustitución de ``entries`` para ``role`` y las añade.

        Devuelve ``True`` si añadió alguna entrada nueva. No duplica una
        (nivel, movimiento) ya registrada para esa identidad.
        """
        if not entries:
            return False
        # 06-09-2026: se calcula sobre la tabla COMPLETA de la especie, no
        # sobre el subconjunto recién cruzado. `compute_species_patch` excluye
        # los movimientos que la especie ya tiene, así que un subconjunto da
        # otro conjunto de exclusiones y elige OTRO sustituto: el historial
        # acababa registrando un movimiento distinto del que el juego enseña
        # de verdad (bug reportado en quinta; medido: 13 de 14 entradas de
        # Patrat discrepaban). Mismo cálculo que el parche, por construcción.
        completa = (self._oras_levelup_moves_vanilla_entries or {}).get(int(species_id)) or entries
        patch = oras_levelup_moves_mod.compute_species_patch(
            completa, role, species_id=species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._oras_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_oras_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Descarta del recuerda-movimientos lo aprendido por encima de ``level``.

        Pedido por el usuario el 2026-09-03: si el nivel real baja —partida
        reiniciada sin guardar, en esta sesión o entre sesiones—, lo que se
        había registrado por encima de ese nivel nunca llegó a persistir en
        el juego, así que no puede seguir ofreciéndose como ENSEÑAR.
        """
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    @perf.timed("ui.record_oras_levelup_move_history")
    def _record_oras_levelup_move_history(self, game: SaveGameData) -> None:
        """Recuerda-movimientos: registra cada aprendizaje por nivel real.

        Compara el nivel actual de cada miembro del equipo con el último
        visto esta sesión. Si subió, mira en la tabla vainilla qué entradas
        cruzó y calcula, para el rol de AHORA, qué movimiento correspondía a
        cada una — el mismo cálculo que ya hace ``build_party_patched_blob``,
        pero solo para la especie que realmente subió de nivel, no para las
        826. Se persiste en la Run, sin duplicar una (nivel, movimiento) que
        ya estuviera registrada para esa identidad.

        La primera vez que se ve a un Pokémon —en toda la Run, no solo esta
        sesión— se retro-rellena con lo que habría aprendido sin ajustar a
        ningún rol hasta su nivel actual, como pidió el usuario: son los
        movimientos de antes de que RoleRun lo gestionara, así que no llevan
        rol y no se pueden enseñar si no encajan con el rol de ahora (eso lo
        decide la propia pantalla, comparando contra el rol actual).

        Si el nivel real baja —partida reiniciada sin guardar, dentro de esta
        sesión o entre sesiones— se descarta primero lo registrado por
        encima del nivel actual: nunca llegó a persistir en el juego, así
        que no puede seguir apareciendo como algo que se le pueda enseñar.
        """
        if (
            getattr(self.save_engine, "key", "") != "oras"
            or self.project is None
            or self._oras_levelup_moves_vanilla_entries is None
        ):
            return
        try:
            changed = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._oras_levelup_history_last_levels.get(identity)
                self._oras_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                entries = self._oras_levelup_moves_vanilla_entries.get(species_id)
                if level > 0 and self._purge_oras_levelup_history_above_level(identity, level):
                    changed = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_oras_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True,
                        ):
                            changed = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                role, _symbol = self._effective_role(pokemon)
                if self._append_oras_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                ):
                    changed = True
            if changed:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("oras_levelup_history_error", error=str(exc))

    def _revert_oras_levelup_moves_mod(self) -> None:
        """Devuelve el mod de aprendizajes por nivel a la tabla vainilla de la ROM.

        Se llama al cerrar RoleRun: con RoleRun cerrado, ORAS debe volver a
        enseñar exactamente lo que su ROM/randomizer diría por sí sola.
        """
        if (
            self._oras_levelup_moves_vanilla is None
            or self._oras_levelup_moves_title_id is None
            or self._oras_levelup_moves_azahar_root is None
        ):
            return
        try:
            oras_levelup_moves_mod.write_blob(
                self._oras_levelup_moves_azahar_root,
                self._oras_levelup_moves_title_id,
                self._oras_levelup_moves_vanilla,
                expected_size=len(self._oras_levelup_moves_vanilla),
            )
        except Exception:
            return

    def _ensure_xy_levelup_moves_registered(
        self, rom_path: Path, azahar_root: Path | None, process_name: str | None,
        emulator_key: str | None = None,
    ) -> None:
        """Prepara el mod de aprendizajes por nivel para la ROM X/Y activa.

        Mirror de ``_ensure_oras_levelup_moves_registered``: X/Y comparte el
        mismo motor/generación que ORAS (GARC indexado 1:1 por species_id,
        confirmado el 2026-09-05 en ``a/2/1/4``). A diferencia de ORAS, X/Y
        puede correr en Azahar o en AzaharPlus, así que sin una raíz explícita
        se autodescubre la de ``qt-config.ini`` más reciente entre las
        instalaciones detectadas -mismo criterio que ya usa
        ``_load_xy_rom_tm_source``-.
        """
        if getattr(self.save_engine, "key", "") != "xy":
            return
        if azahar_root is None:
            discovered = azahar_user_roots()
            azahar_root = max(
                discovered,
                key=lambda root: (root / "config" / "qt-config.ini").stat().st_mtime
                if (root / "config" / "qt-config.ini").is_file() else -1.0,
                default=None,
            )
        if azahar_root is None:
            return
        try:
            with perf.span("ui.ensure_xy_levelup_moves.load_blob"):
                blob, title_id = load_xy_levelup_moves_blob(
                    rom_path, process_name=process_name, azahar_root=azahar_root,
                    emulator_key=emulator_key,
                )
            with perf.span("ui.ensure_xy_levelup_moves.ensure_registered"):
                estado = xy_levelup_moves_mod.ensure_registered(azahar_root, title_id, blob)
        except Exception as exc:
            self._registrar_intento_vivo(
                "xy_levelup_registro_error", error=str(exc), rom_path=str(rom_path),
                azahar_root=str(azahar_root),
            )
            return
        self._xy_levelup_moves_vanilla = blob
        self._xy_levelup_moves_title_id = title_id
        self._xy_levelup_moves_azahar_root = Path(azahar_root)
        self._xy_levelup_moves_last_written = None
        self._xy_levelup_moves_last_roles_key = None
        self._xy_levelup_moves_vanilla_entries = xy_levelup_moves_mod.parse_levelup_garc(blob)
        self._registrar_intento_vivo(
            "xy_levelup_registro_ok", estado=estado, title_id=f"{title_id:016X}",
            azahar_root=str(azahar_root), blob_size=len(blob),
        )
        # 2026-09-05, bug real: este registro se repite en cada reenganche
        # de la conexión (no solo la primera vez), y siempre deja el
        # archivo en su contenido VAINILLA -createlo o no-, con la caché de
        # roles ya reiniciada arriba. Sin esta llamada, la fila del rol
        # actual se quedaba vainilla hasta el siguiente sondeo pasivo (o
        # hasta el siguiente cambio de rol): demostrado en vivo con
        # Pidgey, que cruzó un nivel entero con el archivo recién
        # reenganchado sin que nadie volviera a parchearlo a tiempo.
        # Resincronizar aquí mismo, en el mismo instante del reenganche,
        # cierra esa ventana en vez de esperarla.
        if self.current_game is not None:
            self._sync_xy_levelup_moves_mod(self.current_game)
            self._sync_xy_levelup_moves_backup(self.current_game)

    @perf.timed("ui.sync_xy_levelup_moves_mod")
    def _sync_xy_levelup_moves_mod(self, game: SaveGameData | None) -> None:
        """Ajusta al rol el mod de aprendizajes por nivel de X/Y, si aplica.

        Mirror exacto de ``_sync_oras_levelup_moves_mod``.
        """
        if (
            getattr(self.save_engine, "key", "") != "xy"
            or game is None
            or self._xy_levelup_moves_vanilla is None
            or self._xy_levelup_moves_title_id is None
            or self._xy_levelup_moves_azahar_root is None
        ):
            return
        self._record_xy_levelup_move_history(game)
        leveled_species = set(getattr(self, "_xy_levelup_species_leveled_this_tick", None) or ())
        try:
            roles_by_species: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                roles_by_species[int(pokemon.species_id)] = role
            # Copia previa a adelantar evoluciones futuras: el búfer de
            # anuncio en RAM (ver más abajo) solo puede tocar especies que
            # de verdad tienen un Pokémon vivo en la party -una evolución
            # adelantada no tiene ningún búfer real asignado todavía, y
            # buscar uno ahí arriesga una coincidencia de bytes falsa en
            # otra estructura de memoria-. El archivo del mod sí puede
            # incluir especies especulativas sin riesgo: se queda ahí sin
            # usarse hasta que ese Pokémon exista de verdad.
            roles_by_species_in_party = dict(roles_by_species)
            # 2026-09-05: adelanta el mismo parche a las evoluciones futuras
            # conocidas de cada especie con rol asignado. Evolucionar cambia
            # species_id de golpe en el juego; RoleRun solo se entera en su
            # siguiente sondeo, y parchear (releer la party, recorrer las
            # ~826 especies del GARC, reescribir el archivo) tarda lo
            # suficiente como para perder la carrera si se sube de nivel
            # enseguida después -demostrado en vivo con el usuario: Flabébé
            # evolucionó a Floette y aprendió Deseo sin sustituir, con el
            # rol ya puesto desde antes de evolucionar-. Adelantando el
            # parche, cuando evolucione de verdad su fila ya lleva un rato
            # correcta. `setdefault` nunca pisa el rol de un miembro real
            # de la party con esta suposición.
            for species_id, role in list(roles_by_species.items()):
                for descendant in evolution_descendants(species_id):
                    roles_by_species.setdefault(descendant, role)
            roles_key = (
                frozenset(roles_by_species.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key != self._xy_levelup_moves_last_roles_key:
                usable_move_ids = self._xy_levelup_usable_move_ids()
                patched = xy_levelup_moves_mod.build_party_patched_blob(
                    self._xy_levelup_moves_vanilla, roles_by_species,
                    pools=self.engine.pools,
                    damage_classes=self.engine.damage_classes,
                    speed_status_moves=self.engine.speed_status_moves,
                    self_healing_damage_moves=self.engine.self_healing_damage_moves,
                    usable_move_ids=usable_move_ids,
                    entries_by_species=self._xy_levelup_moves_vanilla_entries,
                )
                if patched != self._xy_levelup_moves_last_written:
                    xy_levelup_moves_mod.write_blob(
                        self._xy_levelup_moves_azahar_root,
                        self._xy_levelup_moves_title_id,
                        patched,
                        expected_size=len(self._xy_levelup_moves_vanilla),
                    )
                    self._xy_levelup_moves_last_written = patched
                    self._registrar_intento_vivo(
                        "xy_levelup_sync_escrito", roles_by_species=roles_by_species,
                    )
                self._xy_levelup_moves_last_roles_key = roles_key
            # 2026-09-05, causa real de un crash del emulador confirmada
            # leyendo ``escrituras_vivas.jsonl``: la primera versión de esto
            # pasaba ``roles_by_species`` -ya expandido con evoluciones
            # futuras- a la búsqueda en RAM. Ese día se buscaron/escribieron
            # 8 especies y el RPC de Azahar dejó de responder segundos
            # después: varias de esas especies eran evoluciones adelantadas
            # sin ningún búfer real asignado, y localizar uno ahí arriesga
            # escribir sobre una coincidencia de bytes de otra estructura.
            # Se pasa ``roles_by_species_in_party`` -solo especies con un
            # Pokémon vivo ahora mismo- en su lugar.
            #
            # 2026-09-05, segundo bug real confirmado en el log: el cartel
            # del juego decodifica el búfer de anuncio de una especie en el
            # instante en que decide qué anunciar -normalmente justo al
            # cruzar un nivel de aprendizaje-, no cuando RoleRun reescribe
            # el archivo. Se dispara por cruce de nivel, no por cambio de
            # rol.
            #
            # 2026-09-05, TERCER y QUINTO bug real, los dos confirmados en
            # el log: hubo una versión que TAMBIÉN disparaba esto en cada
            # cambio de rol -barrido preventivo de 5-6 especies, 10+
            # segundos-. Se probó a arreglarlo con una cola en vez de
            # descartar la petición urgente que llegara ocupado (CUARTO,
            # motivado por ver el mismo patrón de 14-15s ya validado en el
            # log de USUM) — pero encolar no basta: el aviso urgente de
            # Zigzagoon se encoló DETRÁS del barrido preventivo y tardó 10
            # segundos en procesarse igual, solo que sin perderse. El
            # barrido por cambio de rol no aporta nada que el cartel vaya
            # a mostrar antes de que alguien suba de nivel, y si sigue
            # activo, cualquier aviso urgente que llegue mientras tanto
            # espera su turno detrás de él. Se dispara SOLO por cruce de
            # nivel -y por la propia red de seguridad, ver
            # ``_sync_xy_levelup_moves_backup``-, nunca por cambio de rol,
            # para que el aviso urgente nunca tenga nada delante en la
            # cola.
            if leveled_species and self._xy_levelup_moves_last_written is not None:
                cache_targets = {
                    species_id: role
                    for species_id, role in roles_by_species_in_party.items()
                    if species_id in leveled_species
                }
                if cache_targets:
                    self._sync_xy_levelup_announcement_cache(
                        game, cache_targets, self._xy_levelup_moves_last_written,
                    )
        except Exception as exc:
            self._registrar_intento_vivo("xy_levelup_sync_error", error=str(exc))
            return

    def _sync_xy_levelup_moves_backup(self, game: SaveGameData | None) -> None:
        """Aprendizajes por rol en X/Y: red de seguridad tras el parche proactivo.

        Mirror de ``_sync_usum_levelup_moves_backup``. 2026-09-05, validado
        físicamente en la partida real del usuario: a diferencia de lo que
        se creía (Azahar relee ``a/2/1/4`` sin caché en cada petición del
        juego, como ya se demostró para ORAS), X/Y puede seguir enseñando
        el sustituto de un rol YA ABANDONADO -ni el vainilla ni el
        sustituto del rol actual- incluso con el archivo del mod ya
        corregido varios segundos antes del aprendizaje, y hasta después
        de reabrir el menú de equipo del propio juego. Solo un reinicio
        completo del título lo refresca -demostrado con Zigzagoon: Mago
        tras un cambio reciente desde Asesino, aprendió Danza Dragón, el
        sustituto de ASESINO, con el archivo ya en el de Mago desde hacía
        rato-.

        En vez de perseguir esa caché (no expuesta por ningún archivo ni
        dirección conocida), esta red de seguridad hace lo mismo que ya
        resolvió el mismo problema en USUM: observa qué movimiento NUEVO
        aparece de verdad en los 4 huecos del Pokémon (comparado contra el
        sondeo anterior) y comprueba si encaja con el rol ACTUAL en ese
        instante -sin importar de dónde salió-. Si no encaja, lo sustituye
        ahí mismo en la propia partida, reutilizando el mismo camino
        transaccional que cualquier cambio de movimiento confirmado por el
        usuario.
        """
        if (
            getattr(self.save_engine, "key", "") != "xy"
            or game is None
            or self.project is None
        ):
            return
        try:
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            usable_move_ids = self._xy_levelup_usable_move_ids()
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                species_id = int(pokemon.species_id)
                current_ids = [int(move_id or 0) for move_id in pokemon.move_ids[:4]]
                previous_ids = self._xy_levelup_backup_known_moves.get(identity)
                self._xy_levelup_backup_known_moves[identity] = list(current_ids)
                if previous_ids is None:
                    continue
                new_ids = [mid for mid in current_ids if mid > 0 and mid not in previous_ids]
                if not new_ids:
                    continue
                role, _symbol = self._effective_role(pokemon)
                pokemon_identity = self._pokemon_identity(pokemon)
                substituted_here = False
                for new_move_id in new_ids:
                    substitute = compute_move_substitute(
                        new_move_id, role,
                        species_id=species_id,
                        level=level,
                        pools=self.engine.pools, damage_classes=self.engine.damage_classes,
                        speed_status_moves=self.engine.speed_status_moves,
                        self_healing_damage_moves=self.engine.self_healing_damage_moves,
                        exclude=set(current_ids) - {new_move_id},
                        usable_move_ids=usable_move_ids,
                    )
                    if substitute is None:
                        continue
                    move_slot = current_ids.index(new_move_id) + 1
                    move_name = str(self.engine.move(new_move_id).get("name_es") or f"Movimiento #{new_move_id}")
                    substitute_name = str(self.engine.move(substitute).get("name_es") or f"Movimiento #{substitute}")
                    change = PendingChange(
                        role=role,
                        pokemon_slot=pokemon.slot,
                        pokemon=pokemon.nickname or pokemon.species,
                        species=pokemon.species,
                        move_slot=move_slot,
                        old_move=move_name,
                        old_move_id=new_move_id,
                        new_move=substitute_name,
                        new_move_id=substitute,
                        pokemon_identity=pokemon_identity,
                    )
                    self.run.pending_changes = [
                        existing for existing in self.run.pending_changes
                        if not (
                            isinstance(existing, (PendingChange, PendingTMTeach))
                            and getattr(existing, "move_slot", 0) == change.move_slot
                            and getattr(existing, "pokemon_identity", "") == pokemon_identity
                        )
                    ]
                    self.run.pending_changes.append(change)
                    self._registrar_intento_vivo(
                        "xy_levelup_backup_sustitucion_encolada",
                        identidad=identity, hueco=move_slot,
                        aprendido=new_move_id, sustituto=substitute, rol=str(role),
                    )
                    substituted_here = True
                # 2026-09-05, CUARTO bug real confirmado en la partida: el
                # disparador por cruce de nivel (``_sync_xy_levelup_moves_mod``)
                # solo se arma comparando contra el ÚLTIMO nivel que RoleRun
                # vio de este Pokémon -y ese historial no se resetea si el
                # usuario reinicia el JUEGO sin reiniciar RoleRun (su propio
                # flujo de pruebas: reiniciar para bajar de nivel sin
                # relanzar la app). Si RoleRun se reconecta ya con el nivel
                # de vuelta en el mismo valor que tenía antes del reinicio,
                # nunca ve el cruce y nunca dispara el parcheo del cartel
                # -demostrado con Zigzagoon: Mago→Asesino, mismo nivel 9 tras
                # un reinicio del juego, cartel anunciando "Vozarrón" -el
                # sustituto de MAGO- con el archivo ya en Asesino-. Esta red
                # de seguridad, en cambio, compara el CONTENIDO real de los
                # 4 huecos en cada sondeo -nunca se "gasta"-, así que
                # engancha aquí también el parcheo del cartel: si acaba de
                # sustituir un movimiento, el cartel para esta especie
                # probablemente también quedó desactualizado.
                if substituted_here and self._xy_levelup_moves_last_written is not None:
                    self._sync_xy_levelup_announcement_cache(
                        game, {species_id: role}, self._xy_levelup_moves_last_written,
                    )
            self._request_oras_live_auto_apply_since(pending_ids_before)
        except Exception as exc:
            self._registrar_intento_vivo("xy_levelup_backup_sync_error", error=str(exc))

    def _sync_xy_levelup_announcement_cache(
        self, game: SaveGameData | None, roles_by_species: dict, patched_blob: bytes,
    ) -> None:
        """Parchea en vivo el búfer de RAM que decide qué anuncia el diálogo.

        Mirror de ``_sync_usum_levelup_announcement_cache``/
        ``_sync_sm_levelup_announcement_cache`` (mismo módulo
        ``usum_levelup_announcement_cache.py``, sin nada específico de
        Gen 7). Una diferencia real: en Gen 7 la base de la party hay que
        calibrarla en cada proceso (``reader._scan_reference_window``, la
        dirección se mueve). En X/Y la base es una constante ya demostrada
        físicamente (``XY_PARTY_ADDRESS``, ver ``xy_live.py``), así que no
        hace falta ningún paso de calibración: se usa directamente como
        centro de la ventana de búsqueda del búfer de anuncio.

        2026-09-05, validado físicamente contra la partida real del
        usuario (Zigzagoon, Asesino→Mago): el archivo del mod ya quedaba
        correcto (Enfoque A) y la red de seguridad ya garantizaba el
        movimiento final (Enfoque B, ``_sync_xy_levelup_moves_backup`` —
        confirmado en el log, sustituyó Golpe Cabeza por Onda Certera en
        235ms), pero el cartel "¡X ha aprendido Y!" seguía anunciando el
        nombre viejo durante ese instante porque el juego ya lo había
        decodificado en un búfer aparte antes de que la sustitución
        llegara. Esto cierra ese hueco parcheando también ese búfer.

        2026-09-05, QUINTO bug real: el log de USUM del día anterior (su
        propia validación física, ya dada por buena) muestra el MISMO
        patrón que aquí se creyó "imposible de ganar" -un barrido de 5
        especies tardando 14-15 segundos-, solo que allí nunca chocó con
        un aprendizaje real porque el usuario no encadenó cambio de rol +
        caramelo tan rápido como en X/Y. La carrera contra el cartel del
        juego SIEMPRE fue así de ajustada; lo que faltaba no era ganarla
        más rápido, sino no TIRAR una petición al suelo cuando llega
        mientras otra ya está en curso -exactamente lo que le pasó al
        aviso urgente de Zigzagoon, cancelado en silencio por el barrido
        preventivo de un cambio de rol segundos antes-. Por eso el candado
        ya no descarta: la petición que llega ocupado se guarda en
        ``_xy_levelup_announcement_cache_pending`` y el propio hilo la
        recoge en cuanto termina su vuelta actual, en vez de perderla.
        """
        if (
            getattr(self.save_engine, "key", "") != "xy"
            or game is None
            or not roles_by_species
        ):
            return
        if getattr(self, "_xy_levelup_announcement_cache_running", False):
            pending = dict(getattr(self, "_xy_levelup_announcement_cache_pending", None) or {})
            pending.update(roles_by_species)
            self._xy_levelup_announcement_cache_pending = pending
            self._xy_levelup_announcement_cache_pending_blob = patched_blob
            return
        self._xy_levelup_announcement_cache_pending = None
        self._xy_levelup_announcement_cache_pending_blob = None

        def _targets_for(roles: dict, blob: bytes) -> list[tuple[tuple, dict[object, int]]]:
            entries_by_species_patched = xy_levelup_moves_mod.parse_levelup_garc(blob)
            targets: list[tuple[tuple, dict[object, int]]] = []
            for species_id in roles:
                vanilla_entries = (self._xy_levelup_moves_vanilla_entries or {}).get(species_id)
                patched_entries = entries_by_species_patched.get(species_id)
                if not vanilla_entries or not patched_entries:
                    continue
                move_ids_by_key = {key: int(move_id) for move_id, _level, key in patched_entries}
                targets.append((vanilla_entries, move_ids_by_key))
            return targets

        def worker() -> None:
            from .azahar_rpc import AzaharRPCClient
            from .xy_live import (
                XY_ANNOUNCEMENT_CACHE_SCAN_SPAN, XY_PARTY_ADDRESS, XY_TITLE_IDS,
            )
            from .win_process_memory import WindowsProcessMemory
            from .usum_levelup_announcement_cache import patch_species_announcement_cache

            current_roles, current_blob = roles_by_species, patched_blob
            try:
                while True:
                    try:
                        targets = _targets_for(current_roles, current_blob)
                    except Exception as exc:
                        self._registrar_intento_vivo(
                            "xy_levelup_announcement_cache_error", error=str(exc),
                        )
                        targets = []
                    if targets:
                        with AzaharRPCClient() as client:
                            xy_processes = [
                                process for process in client.process_list()
                                if int(process.title_id) in XY_TITLE_IDS
                            ]
                            if len(xy_processes) == 1:
                                client.set_process(xy_processes[0].process_id)
                                wpm = WindowsProcessMemory()
                                windows_processes = wpm.list_azahar_processes()
                                total_patched = 0
                                for windows_process in windows_processes:
                                    handle = wpm.open_process(windows_process.pid)
                                    try:
                                        for vanilla_entries, move_ids_by_key in targets:
                                            total_patched += patch_species_announcement_cache(
                                                client, wpm, handle,
                                                party_base=XY_PARTY_ADDRESS,
                                                entries=vanilla_entries,
                                                move_ids_by_key=move_ids_by_key,
                                                scan_span=XY_ANNOUNCEMENT_CACHE_SCAN_SPAN,
                                            )
                                    finally:
                                        wpm.close_process(handle)
                                if total_patched:
                                    self._registrar_intento_vivo(
                                        "xy_levelup_announcement_cache_parcheado",
                                        especies=len(targets), copias=total_patched,
                                    )
                    pending = self._xy_levelup_announcement_cache_pending
                    pending_blob = self._xy_levelup_announcement_cache_pending_blob
                    self._xy_levelup_announcement_cache_pending = None
                    self._xy_levelup_announcement_cache_pending_blob = None
                    if not pending:
                        break
                    current_roles = pending
                    current_blob = pending_blob if pending_blob is not None else current_blob
            except Exception as exc:
                self._registrar_intento_vivo("xy_levelup_announcement_cache_error", error=str(exc))
            finally:
                self._xy_levelup_announcement_cache_running = False

        self._xy_levelup_announcement_cache_running = True
        threading.Thread(target=worker, daemon=True, name="RoleRunXyAnnouncementCache").start()

    def _xy_levelup_usable_move_ids(self) -> set[int]:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else set(range(1, XY_MAX_MOVE_ID + 1))
        )

    def _append_xy_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool,
    ) -> bool:
        """Mirror de ``_append_oras_levelup_history_entries``."""
        if not entries:
            return False
        # 06-09-2026: se calcula sobre la tabla COMPLETA de la especie, no
        # sobre el subconjunto recién cruzado. `compute_species_patch` excluye
        # los movimientos que la especie ya tiene, así que un subconjunto da
        # otro conjunto de exclusiones y elige OTRO sustituto: el historial
        # acababa registrando un movimiento distinto del que el juego enseña
        # de verdad (bug reportado en quinta; medido: 13 de 14 entradas de
        # Patrat discrepaban). Mismo cálculo que el parche, por construcción.
        completa = (self._xy_levelup_moves_vanilla_entries or {}).get(int(species_id)) or entries
        patch = xy_levelup_moves_mod.compute_species_patch(
            completa, role, species_id=species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._xy_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_xy_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Mirror de ``_purge_oras_levelup_history_above_level``."""
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    @perf.timed("ui.record_xy_levelup_move_history")
    def _record_xy_levelup_move_history(self, game: SaveGameData) -> None:
        """Mirror de ``_record_oras_levelup_move_history``."""
        if (
            getattr(self.save_engine, "key", "") != "xy"
            or self.project is None
            or self._xy_levelup_moves_vanilla_entries is None
        ):
            return
        self._xy_levelup_species_leveled_this_tick = set()
        try:
            changed = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._xy_levelup_history_last_levels.get(identity)
                self._xy_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                entries = self._xy_levelup_moves_vanilla_entries.get(species_id)
                if level > 0 and self._purge_xy_levelup_history_above_level(identity, level):
                    changed = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_xy_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True,
                        ):
                            changed = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                # 2026-09-05: marca esta especie como "acaba de cruzar un
                # nivel de aprendizaje" -ver ``_sync_xy_levelup_moves_mod``,
                # que usa esto para disparar el parcheo de RAM del cartel
                # incluso cuando el archivo del mod no cambió esta vuelta.
                self._xy_levelup_species_leveled_this_tick.add(species_id)
                role, _symbol = self._effective_role(pokemon)
                if self._append_xy_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                ):
                    changed = True
            if changed:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("xy_levelup_history_error", error=str(exc))

    def _revert_xy_levelup_moves_mod(self) -> None:
        """Mirror de ``_revert_oras_levelup_moves_mod``."""
        if (
            self._xy_levelup_moves_vanilla is None
            or self._xy_levelup_moves_title_id is None
            or self._xy_levelup_moves_azahar_root is None
        ):
            return
        try:
            xy_levelup_moves_mod.write_blob(
                self._xy_levelup_moves_azahar_root,
                self._xy_levelup_moves_title_id,
                self._xy_levelup_moves_vanilla,
                expected_size=len(self._xy_levelup_moves_vanilla),
            )
        except Exception:
            return

    def _ensure_usum_levelup_moves_registered(
        self, rom_path: Path, azahar_root: Path | None, process_name: str | None,
    ) -> None:
        """Prepara el mod de aprendizajes por nivel para la ROM USUM activa.

        Análogo a ``_ensure_oras_levelup_moves_registered``, con una pieza
        extra: el GARC de aprendizajes de USUM indexa por ``personal_id``
        (formas incluidas), no por species_id directo — se calcula también
        aquí, una sola vez, el mapa ``(species_id, form) -> personal_id``
        desde la tabla Personal efectiva (confirmado el 2026-09-04 contra la
        ROM real del usuario: Venusaur/Mega Venusaur decodifican listas de
        aprendizajes completas usando este mismo mapa).

        A diferencia de ORAS (que ya recibe ``azahar_root`` de un
        ``ORASRomSource`` descubierto de antemano), el camino de USUM
        (``_load_usum_rom_tm_source``) no encadena esa raíz — si no se pasa
        una explícita, se autodescubre aquí con ``azahar_user_roots()``
        (misma función que ya usan ``load_usum_levelup_moves_blob``/
        ``usum_personal_id_map_for_rom`` para localizar actualizaciones).

        2026-09-04, bug real: con Azahar Y AzaharPlus instalados a la vez
        (confirmado en la máquina del usuario), ``azahar_user_roots()``
        antepone "Azahar" porque está hardcodeado antes que el descubrimiento
        genérico — exactamente el fallo que ``discover_azahar_oras_source``
        ya documenta y evita para ORAS ("se prefiere la carpeta que modificó
        su qt-config.ini más recientemente: es la que de verdad se está
        usando ahora"). Tomar ``discovered[0]`` a ciegas escribía el mod en
        el fork equivocado, sin ningún error — el mod nunca lo veía la
        instancia realmente en marcha. Mismo criterio aquí.
        """
        if getattr(self.save_engine, "key", "") != "usum":
            return
        if azahar_root is None:
            discovered = azahar_user_roots()
            azahar_root = max(
                discovered,
                key=lambda root: (root / "config" / "qt-config.ini").stat().st_mtime
                if (root / "config" / "qt-config.ini").is_file() else -1.0,
                default=None,
            )
        if azahar_root is None:
            return
        try:
            with perf.span("ui.ensure_usum_levelup_moves.load_blob"):
                blob, title_id = load_usum_levelup_moves_blob(
                    rom_path, process_name=process_name, azahar_root=azahar_root,
                )
            with perf.span("ui.ensure_usum_levelup_moves.personal_id_map"):
                personal_id_map = usum_personal_id_map_for_rom(rom_path, azahar_root=azahar_root)
            with perf.span("ui.ensure_usum_levelup_moves.ensure_registered"):
                estado = usum_levelup_moves_mod.ensure_registered(azahar_root, title_id, blob)
        except Exception as exc:
            self._registrar_intento_vivo(
                "usum_levelup_registro_error", error=str(exc), rom_path=str(rom_path),
                azahar_root=str(azahar_root),
            )
            return
        self._usum_levelup_moves_vanilla = blob
        self._usum_levelup_moves_title_id = title_id
        self._usum_levelup_moves_azahar_root = Path(azahar_root)
        self._usum_levelup_moves_last_written = None
        self._usum_levelup_moves_last_roles_key = None
        self._usum_levelup_personal_id_map = personal_id_map
        self._usum_levelup_moves_vanilla_entries = usum_levelup_moves_mod.parse_levelup_garc(blob)
        self._registrar_intento_vivo(
            "usum_levelup_registro_ok", estado=estado, title_id=f"{title_id:016X}",
            azahar_root=str(azahar_root), blob_size=len(blob),
            especies_con_forma=sum(1 for k in personal_id_map if k[1] != 0),
        )

    @perf.timed("ui.sync_usum_levelup_moves_mod")
    def _sync_usum_levelup_moves_mod(self, game: SaveGameData | None) -> None:
        """Ajusta al rol el mod de aprendizajes por nivel de USUM, si aplica.

        Análogo a ``_sync_oras_levelup_moves_mod`` — misma caché por
        roles_key para no reescribir en cada sondeo, mismo criterio de "solo
        se escribe lo que cambia". La única diferencia real: la clave hacia
        ``entries_by_species``/``roles_by_species`` es el ``personal_id``
        traducido de ``(pokemon.species_id, pokemon.form)``, no el
        species_id directo — un Pokémon cuya forma no está en el mapa
        (nunca debería pasar con una tabla Personal válida) se ignora sin
        romper el resto del sondeo.
        """
        if (
            getattr(self.save_engine, "key", "") != "usum"
            or game is None
            or self._usum_levelup_moves_vanilla is None
            or self._usum_levelup_moves_title_id is None
            or self._usum_levelup_moves_azahar_root is None
            or self._usum_levelup_personal_id_map is None
        ):
            return
        self._record_usum_levelup_move_history(game)
        try:
            roles_by_personal_id: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                personal_id = self._usum_levelup_personal_id_for(
                    int(pokemon.species_id), int(getattr(pokemon, "form", 0) or 0)
                )
                if personal_id is None:
                    continue
                roles_by_personal_id[personal_id] = role
            roles_key = (
                frozenset(roles_by_personal_id.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key == self._usum_levelup_moves_last_roles_key:
                return
            # A diferencia de ORAS, deliberadamente sin red de seguridad de
            # rango fijo aquí: no hay un "USUM_MAX_MOVE_ID" ya demostrado en
            # este proyecto (ORAS/XY sí lo tienen, verificados contra sus
            # propias ROMs), y USUM tiene movimientos exclusivos (p. ej. los
            # de las formas Ultra de Necrozma) cerca del límite superior de
            # Gen 7 — inventar un número sin confirmarlo contra la ROM real
            # arriesga excluirlos por error. Mientras `allowed_move_ids` no
            # esté poblado (ventana breve, normalmente ya lo está), no se
            # restringe por rango, solo por los pools de rol ya curados.
            usable_move_ids = (
                set(int(move_id) for move_id in self.engine.allowed_move_ids)
                if self.engine.allowed_move_ids is not None
                else None
            )
            patched = usum_levelup_moves_mod.build_party_patched_blob(
                self._usum_levelup_moves_vanilla, roles_by_personal_id,
                pools=self.engine.pools,
                damage_classes=self.engine.damage_classes,
                speed_status_moves=self.engine.speed_status_moves,
                self_healing_damage_moves=self.engine.self_healing_damage_moves,
                usable_move_ids=usable_move_ids,
                entries_by_species=self._usum_levelup_moves_vanilla_entries,
            )
            if patched == self._usum_levelup_moves_last_written:
                self._usum_levelup_moves_last_roles_key = roles_key
                return
            usum_levelup_moves_mod.write_blob(
                self._usum_levelup_moves_azahar_root,
                self._usum_levelup_moves_title_id,
                patched,
                expected_size=len(self._usum_levelup_moves_vanilla),
            )
            self._usum_levelup_moves_last_written = patched
            self._usum_levelup_moves_last_roles_key = roles_key
            self._registrar_intento_vivo(
                "usum_levelup_sync_escrito", roles_by_personal_id=roles_by_personal_id,
            )
            self._sync_usum_levelup_announcement_cache(game, roles_by_personal_id, patched)
        except Exception as exc:
            self._registrar_intento_vivo("usum_levelup_sync_error", error=str(exc))
            return

    def _sync_usum_levelup_moves_backup(self, game: SaveGameData | None) -> None:
        """Aprendizajes por rol en USUM: red de seguridad tras el parche proactivo.

        2026-09-04, validado en la partida real del usuario: a diferencia
        de ORAS (relee ``a/1/9/1`` sin caché en cada petición del juego),
        USUM puede enseñar un movimiento que ya no es ni el vainilla ni el
        sustituto recién calculado — el que tenía cacheado de ANTES de un
        cambio de rol reciente (demostrado con Registeel: venía de Prisma,
        cambiado a Mago, y aprendió Somnífero — el sustituto de PRISMA, ni
        vainilla ni el de Mago). Un primer diseño (calcado de
        ``_sync_bdsp_levelup_moves``, que predice de antemano el
        movimiento vainilla exacto y espera a verlo aparecer) no cubre este
        caso: ni el vainilla ni el sustituto esperado llegan a aparecer
        nunca, así que la sustitución se queda esperando para siempre.

        Este diseño es más simple y robusto: en vez de predecir qué
        aprenderá el Pokémon, observa qué movimiento NUEVO aparece de
        verdad en sus 4 huecos (comparado contra el sondeo anterior) y
        comprueba si es compatible con el rol ACTUAL en ese mismo
        instante — sin importar si es el vainilla, un sustituto de un rol
        viejo, o cualquier otra cosa. Si no lo es, lo sustituye ahí mismo
        (``compute_move_substitute``) reutilizando el mismo camino
        transaccional que cualquier cambio de movimiento confirmado por el
        usuario (``PendingChange`` + ``_request_oras_live_auto_apply_since``
        — ``USUMLiveWriter._replace_move`` ya sabe aplicar un
        ``PendingChange``, la misma pieza que ya usa la enseñanza de MT).

        No registra historial aquí: ``_record_usum_levelup_move_history``
        (llamado antes, en ``_sync_usum_levelup_moves_mod``) ya lo hace en
        el instante del cruce de nivel, con el mismo criterio "aunque el
        juego no lo haya enseñado, el movimiento de rol debe seguir
        apareciendo" que ya usa ORAS/BDSP.
        """
        if (
            getattr(self.save_engine, "key", "") != "usum"
            or game is None
            or self.project is None
        ):
            return
        try:
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            usable_move_ids = self._usum_levelup_usable_move_ids()
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                species_id = int(pokemon.species_id)
                form = int(getattr(pokemon, "form", 0) or 0)
                current_ids = [int(move_id or 0) for move_id in pokemon.move_ids[:4]]
                previous_ids = self._usum_levelup_backup_known_moves.get(identity)
                self._usum_levelup_backup_known_moves[identity] = list(current_ids)
                if previous_ids is None:
                    continue
                new_ids = [mid for mid in current_ids if mid > 0 and mid not in previous_ids]
                if not new_ids:
                    continue
                role, _symbol = self._effective_role(pokemon)
                personal_id = self._usum_levelup_personal_id_for(species_id, form)
                pokemon_identity = self._pokemon_identity(pokemon)
                for new_move_id in new_ids:
                    substitute = compute_move_substitute(
                        new_move_id, role,
                        species_id=personal_id if personal_id is not None else species_id,
                        level=level,
                        pools=self.engine.pools, damage_classes=self.engine.damage_classes,
                        speed_status_moves=self.engine.speed_status_moves,
                        self_healing_damage_moves=self.engine.self_healing_damage_moves,
                        exclude=set(current_ids) - {new_move_id},
                        usable_move_ids=usable_move_ids,
                    )
                    if substitute is None:
                        continue
                    move_slot = current_ids.index(new_move_id) + 1
                    move_name = str(self.engine.move(new_move_id).get("name_es") or f"Movimiento #{new_move_id}")
                    substitute_name = str(self.engine.move(substitute).get("name_es") or f"Movimiento #{substitute}")
                    change = PendingChange(
                        role=role,
                        pokemon_slot=pokemon.slot,
                        pokemon=pokemon.nickname or pokemon.species,
                        species=pokemon.species,
                        move_slot=move_slot,
                        old_move=move_name,
                        old_move_id=new_move_id,
                        new_move=substitute_name,
                        new_move_id=substitute,
                        pokemon_identity=pokemon_identity,
                    )
                    self.run.pending_changes = [
                        existing for existing in self.run.pending_changes
                        if not (
                            isinstance(existing, (PendingChange, PendingTMTeach))
                            and getattr(existing, "move_slot", 0) == change.move_slot
                            and getattr(existing, "pokemon_identity", "") == pokemon_identity
                        )
                    ]
                    self.run.pending_changes.append(change)
                    self._registrar_intento_vivo(
                        "usum_levelup_backup_sustitucion_encolada",
                        identidad=identity, hueco=move_slot,
                        aprendido=new_move_id, sustituto=substitute, rol=str(role),
                    )
            self._request_oras_live_auto_apply_since(pending_ids_before)
        except Exception as exc:
            self._registrar_intento_vivo("usum_levelup_backup_sync_error", error=str(exc))

    def _sync_usum_levelup_announcement_cache(
        self, game: SaveGameData | None, roles_by_personal_id: dict, patched_blob: bytes,
    ) -> None:
        """Parchea en vivo el búfer de RAM que decide qué anuncia el diálogo.

        2026-09-04, validado físicamente contra la partida real del
        usuario (Eevee, Asesino→Mago→Asesino): el diálogo "X quiere
        aprender Y" de USUM no relee ``a/0/1/3`` en cada aprendizaje — el
        juego decodifica la tabla de cada Pokémon UNA VEZ en un búfer de
        trabajo (pares movimiento+nivel), y ese búfer es lo que decide el
        anuncio hasta que se reconstruye (al cargar la escena, o al abrir
        la ficha del Pokémon — ninguna de las dos cosas depende de
        RoleRun). Sin esto, el archivo ya queda correcto (Enfoque A) y la
        red de seguridad ya garantiza el resultado final (Enfoque B), pero
        el TEXTO del diálogo puede seguir mostrando el rol anterior hasta
        que el jugador haga algo ajeno a RoleRun.

        Ver ``app/usum_levelup_announcement_cache.py`` para el porqué
        completo de la técnica de localización (ancla por niveles +
        traducción a direcciones reales de Windows, necesaria porque
        Azahar rechaza en silencio las escrituras RPC en este rango de
        memoria). Aquí solo se orquesta: qué especies tocar y con qué
        movimientos, reutilizando el propio ``self.usum_live_reader`` ya
        instanciado para el resto de la app.

        Se ejecuta en un hilo aparte (localizar + traducir + escribir en
        memoria de otro proceso puede tardar 1-2 s por especie) y nunca
        deja una excepción escapar hacia la interfaz: si algo falla aquí,
        el archivo y la red de seguridad ya garantizan que el Pokémon
        termine con el movimiento correcto de todos modos — esto solo
        adelanta que el propio diálogo ya lo anuncie bien.
        """
        if (
            getattr(self.save_engine, "key", "") != "usum"
            or game is None
            or not roles_by_personal_id
            or not getattr(self, "usum_live_reader", None)
        ):
            return
        # 2026-09-04, lag general reportado por el usuario tras probar SM: cada
        # especie puede tardar 1-2s (localizar en RAM huésped + escanear la
        # región FCRAM real, ~decenas de MB, para traducir a Windows) y ese
        # escaneo mantiene el GIL ocupado en ráfagas -no es una llamada de red
        # que lo libere-. Sin este candado, un cambio de rol seguido de otro
        # (o el sondeo periódico) apilaba varios hilos haciendo esas ráfagas a
        # la vez, y la interfaz entera se sentía lenta mientras competían por
        # CPU. Con esto, como mucho hay UNO en curso por juego: el siguiente
        # sondeo que detecte un cambio ya lo recogerá cuando este termine. Solo
        # se marca "en curso" justo antes de lanzar el hilo -no aquí arriba-,
        # para que un `return` temprano (nada que parchear) no lo deje
        # bloqueado para siempre.
        if getattr(self, "_usum_levelup_announcement_cache_running", False):
            return
        try:
            entries_by_species_patched = usum_levelup_moves_mod.parse_levelup_garc(patched_blob)
        except Exception as exc:
            self._registrar_intento_vivo("usum_levelup_announcement_cache_error", error=str(exc))
            return
        targets: list[tuple[tuple, dict[object, int]]] = []
        for personal_id in roles_by_personal_id:
            vanilla_entries = (self._usum_levelup_moves_vanilla_entries or {}).get(personal_id)
            patched_entries = entries_by_species_patched.get(personal_id)
            if not vanilla_entries or not patched_entries:
                continue
            move_ids_by_key = {key: int(move_id) for move_id, _level, key in patched_entries}
            targets.append((vanilla_entries, move_ids_by_key))
        if not targets:
            return
        witnesses = [pokemon for pokemon in game.party if int(getattr(pokemon, "species_id", 0)) > 0][:3]
        if not witnesses:
            return
        reader = self.usum_live_reader

        def worker() -> None:
            try:
                from types import SimpleNamespace

                from .azahar_rpc import AzaharRPCClient
                from .usum_live import USUM_TITLE_IDS
                from .win_process_memory import WindowsProcessMemory
                from .usum_levelup_announcement_cache import patch_species_announcement_cache

                with AzaharRPCClient() as client:
                    usum_processes = [
                        process for process in client.process_list()
                        if int(process.title_id) in USUM_TITLE_IDS
                    ]
                    if len(usum_processes) != 1:
                        return
                    client.set_process(usum_processes[0].process_id)
                    located = reader._scan_reference_window(client, SimpleNamespace(party=witnesses))
                    if located is None:
                        return
                    party_base, _party = located

                    wpm = WindowsProcessMemory()
                    windows_processes = wpm.list_azahar_processes()
                    if not windows_processes:
                        return
                    # Puede haber más de un proceso "azahar.exe" (procesos
                    # auxiliares del propio emulador, no instancias
                    # distintas, confirmado 2026-09-04: uno de los dos nunca
                    # tiene la región FCRAM en cuestión) — se prueba cada
                    # uno; el que no la tenga simplemente no encuentra nada,
                    # sin ambigüedad real: cada escritura ya exige releer y
                    # confirmar el contenido exacto antes de tocar nada (ver
                    # ``patch_species_announcement_cache``).
                    total_patched = 0
                    for windows_process in windows_processes:
                        handle = wpm.open_process(windows_process.pid)
                        try:
                            for vanilla_entries, move_ids_by_key in targets:
                                total_patched += patch_species_announcement_cache(
                                    client, wpm, handle,
                                    party_base=party_base,
                                    entries=vanilla_entries,
                                    move_ids_by_key=move_ids_by_key,
                                )
                        finally:
                            wpm.close_process(handle)
                    if total_patched:
                        self._registrar_intento_vivo(
                            "usum_levelup_announcement_cache_parcheado",
                            especies=len(targets), copias=total_patched,
                        )
            except Exception as exc:
                self._registrar_intento_vivo("usum_levelup_announcement_cache_error", error=str(exc))
            finally:
                self._usum_levelup_announcement_cache_running = False

        self._usum_levelup_announcement_cache_running = True
        threading.Thread(target=worker, daemon=True, name="RoleRunUsumAnnouncementCache").start()

    def _usum_levelup_usable_move_ids(self) -> set[int] | None:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else None
        )

    def _usum_levelup_personal_id_for(self, species_id: int, form: int) -> int | None:
        """``form`` cae a la base si la forma exacta no existe en el mapa.

        2026-09-04: el byte de forma leído en vivo (``usum_live.py``) llegó a
        mostrar valores no nulos para especies sin ninguna forma alternativa
        real (confirmado contra la tabla Personal efectiva) — un Pokémon del
        equipo/PC nunca puede estar realmente en una forma de combate (Mega,
        etc.) fuera de un combate, así que su aprendizaje por nivel es
        siempre el de la forma base independientemente de ese byte.
        """
        if self._usum_levelup_personal_id_map is None:
            return None
        species_id = int(species_id)
        personal_id = self._usum_levelup_personal_id_map.get((species_id, int(form)))
        if personal_id is not None:
            return personal_id
        return self._usum_levelup_personal_id_map.get((species_id, 0))

    def _ensure_sm_levelup_moves_registered(
        self, rom_path: Path, azahar_root: Path | None, process_name: str | None,
    ) -> None:
        """Prepara el mod de aprendizajes por nivel para la ROM SM activa.

        Mirror exacto de ``_ensure_usum_levelup_moves_registered``: SM
        comparte el mismo motor/generación que USUM, confirmado el
        2026-09-04 contra la ROM real del usuario (``a/0/1/3``, GARC válido,
        961 ficheros indexados por ``personal_id`` igual que USUM).
        """
        if getattr(self.save_engine, "key", "") != "sm":
            return
        if azahar_root is None:
            discovered = azahar_user_roots()
            azahar_root = max(
                discovered,
                key=lambda root: (root / "config" / "qt-config.ini").stat().st_mtime
                if (root / "config" / "qt-config.ini").is_file() else -1.0,
                default=None,
            )
        if azahar_root is None:
            return
        try:
            with perf.span("ui.ensure_sm_levelup_moves.load_blob"):
                blob, title_id = load_sm_levelup_moves_blob(
                    rom_path, process_name=process_name, azahar_root=azahar_root,
                )
            with perf.span("ui.ensure_sm_levelup_moves.personal_id_map"):
                personal_id_map = sm_personal_id_map_for_rom(rom_path, azahar_root=azahar_root)
            with perf.span("ui.ensure_sm_levelup_moves.ensure_registered"):
                estado = sm_levelup_moves_mod.ensure_registered(azahar_root, title_id, blob)
        except Exception as exc:
            self._registrar_intento_vivo(
                "sm_levelup_registro_error", error=str(exc), rom_path=str(rom_path),
                azahar_root=str(azahar_root),
            )
            return
        self._sm_levelup_moves_vanilla = blob
        self._sm_levelup_moves_title_id = title_id
        self._sm_levelup_moves_azahar_root = Path(azahar_root)
        self._sm_levelup_moves_last_written = None
        self._sm_levelup_moves_last_roles_key = None
        self._sm_levelup_personal_id_map = personal_id_map
        self._sm_levelup_moves_vanilla_entries = sm_levelup_moves_mod.parse_levelup_garc(blob)
        self._registrar_intento_vivo(
            "sm_levelup_registro_ok", estado=estado, title_id=f"{title_id:016X}",
            azahar_root=str(azahar_root), blob_size=len(blob),
            especies_con_forma=sum(1 for k in personal_id_map if k[1] != 0),
        )

    @perf.timed("ui.sync_sm_levelup_moves_mod")
    def _sync_sm_levelup_moves_mod(self, game: SaveGameData | None) -> None:
        """Ajusta al rol el mod de aprendizajes por nivel de SM, si aplica.

        Mirror exacto de ``_sync_usum_levelup_moves_mod``.
        """
        if (
            getattr(self.save_engine, "key", "") != "sm"
            or game is None
            or self._sm_levelup_moves_vanilla is None
            or self._sm_levelup_moves_title_id is None
            or self._sm_levelup_moves_azahar_root is None
            or self._sm_levelup_personal_id_map is None
        ):
            return
        self._record_sm_levelup_move_history(game)
        try:
            roles_by_personal_id: dict[int, str] = {}
            for pokemon in game.party:
                role, _symbol = self._effective_role(pokemon)
                if role in {"SIN ROL", "Líbero", ""}:
                    continue
                personal_id = self._sm_levelup_personal_id_for(
                    int(pokemon.species_id), int(getattr(pokemon, "form", 0) or 0)
                )
                if personal_id is None:
                    continue
                roles_by_personal_id[personal_id] = role
            roles_key = (
                frozenset(roles_by_personal_id.items()),
                self.engine.allowed_move_ids is not None,
            )
            if roles_key == self._sm_levelup_moves_last_roles_key:
                return
            usable_move_ids = (
                set(int(move_id) for move_id in self.engine.allowed_move_ids)
                if self.engine.allowed_move_ids is not None
                else None
            )
            patched = sm_levelup_moves_mod.build_party_patched_blob(
                self._sm_levelup_moves_vanilla, roles_by_personal_id,
                pools=self.engine.pools,
                damage_classes=self.engine.damage_classes,
                speed_status_moves=self.engine.speed_status_moves,
                self_healing_damage_moves=self.engine.self_healing_damage_moves,
                usable_move_ids=usable_move_ids,
                entries_by_species=self._sm_levelup_moves_vanilla_entries,
            )
            if patched == self._sm_levelup_moves_last_written:
                self._sm_levelup_moves_last_roles_key = roles_key
                return
            sm_levelup_moves_mod.write_blob(
                self._sm_levelup_moves_azahar_root,
                self._sm_levelup_moves_title_id,
                patched,
                expected_size=len(self._sm_levelup_moves_vanilla),
            )
            self._sm_levelup_moves_last_written = patched
            self._sm_levelup_moves_last_roles_key = roles_key
            self._registrar_intento_vivo(
                "sm_levelup_sync_escrito", roles_by_personal_id=roles_by_personal_id,
            )
            self._sync_sm_levelup_announcement_cache(game, roles_by_personal_id, patched)
        except Exception as exc:
            self._registrar_intento_vivo("sm_levelup_sync_error", error=str(exc))
            return

    def _sync_sm_levelup_moves_backup(self, game: SaveGameData | None) -> None:
        """Aprendizajes por rol en SM: red de seguridad tras el parche proactivo.

        Mirror exacto de ``_sync_usum_levelup_moves_backup``: observa qué
        movimiento NUEVO aparece de verdad en los 4 huecos (comparado contra
        el sondeo anterior) y comprueba si es compatible con el rol ACTUAL
        en ese instante, sin importar de dónde viniera. No registra
        historial aquí: ``_record_sm_levelup_move_history`` (llamado antes,
        en ``_sync_sm_levelup_moves_mod``) ya lo hace en el instante del
        cruce de nivel.
        """
        if (
            getattr(self.save_engine, "key", "") != "sm"
            or game is None
            or self.project is None
        ):
            return
        try:
            pending_ids_before = {id(change) for change in self.run.pending_changes}
            usable_move_ids = self._sm_levelup_usable_move_ids()
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                species_id = int(pokemon.species_id)
                form = int(getattr(pokemon, "form", 0) or 0)
                current_ids = [int(move_id or 0) for move_id in pokemon.move_ids[:4]]
                previous_ids = self._sm_levelup_backup_known_moves.get(identity)
                self._sm_levelup_backup_known_moves[identity] = list(current_ids)
                if previous_ids is None:
                    continue
                new_ids = [mid for mid in current_ids if mid > 0 and mid not in previous_ids]
                if not new_ids:
                    continue
                role, _symbol = self._effective_role(pokemon)
                personal_id = self._sm_levelup_personal_id_for(species_id, form)
                pokemon_identity = self._pokemon_identity(pokemon)
                for new_move_id in new_ids:
                    substitute = compute_move_substitute(
                        new_move_id, role,
                        species_id=personal_id if personal_id is not None else species_id,
                        level=level,
                        pools=self.engine.pools, damage_classes=self.engine.damage_classes,
                        speed_status_moves=self.engine.speed_status_moves,
                        self_healing_damage_moves=self.engine.self_healing_damage_moves,
                        exclude=set(current_ids) - {new_move_id},
                        usable_move_ids=usable_move_ids,
                    )
                    if substitute is None:
                        continue
                    move_slot = current_ids.index(new_move_id) + 1
                    move_name = str(self.engine.move(new_move_id).get("name_es") or f"Movimiento #{new_move_id}")
                    substitute_name = str(self.engine.move(substitute).get("name_es") or f"Movimiento #{substitute}")
                    change = PendingChange(
                        role=role,
                        pokemon_slot=pokemon.slot,
                        pokemon=pokemon.nickname or pokemon.species,
                        species=pokemon.species,
                        move_slot=move_slot,
                        old_move=move_name,
                        old_move_id=new_move_id,
                        new_move=substitute_name,
                        new_move_id=substitute,
                        pokemon_identity=pokemon_identity,
                    )
                    self.run.pending_changes = [
                        existing for existing in self.run.pending_changes
                        if not (
                            isinstance(existing, (PendingChange, PendingTMTeach))
                            and getattr(existing, "move_slot", 0) == change.move_slot
                            and getattr(existing, "pokemon_identity", "") == pokemon_identity
                        )
                    ]
                    self.run.pending_changes.append(change)
                    self._registrar_intento_vivo(
                        "sm_levelup_backup_sustitucion_encolada",
                        identidad=identity, hueco=move_slot,
                        aprendido=new_move_id, sustituto=substitute, rol=str(role),
                    )
            self._request_oras_live_auto_apply_since(pending_ids_before)
        except Exception as exc:
            self._registrar_intento_vivo("sm_levelup_backup_sync_error", error=str(exc))

    def _sync_sm_levelup_announcement_cache(
        self, game: SaveGameData | None, roles_by_personal_id: dict, patched_blob: bytes,
    ) -> None:
        """Parchea en vivo el búfer de RAM que decide qué anuncia el diálogo.

        Mirror exacto de ``_sync_usum_levelup_announcement_cache``: mismo
        mecanismo de RAM Gen 7 (``app/usum_levelup_announcement_cache.py``,
        reutilizado tal cual, sin nada específico de USUM), solo cambia el
        Title ID (``sm_live.SM_TITLE_IDS``) y el lector de party en vivo
        (``self.sm_live_reader``).
        """
        if (
            getattr(self.save_engine, "key", "") != "sm"
            or game is None
            or not roles_by_personal_id
            or not getattr(self, "sm_live_reader", None)
        ):
            return
        # Mismo candado que USUM (ver su comentario en
        # ``_sync_usum_levelup_announcement_cache``, 2026-09-04): sin él, un
        # cambio de rol seguido de otro apilaba varios hilos escaneando RAM a
        # la vez y la interfaz entera se sentía lenta mientras competían por
        # CPU. Solo se marca "en curso" justo antes de lanzar el hilo, para
        # que un `return` temprano no lo deje bloqueado para siempre.
        if getattr(self, "_sm_levelup_announcement_cache_running", False):
            return
        try:
            entries_by_species_patched = sm_levelup_moves_mod.parse_levelup_garc(patched_blob)
        except Exception as exc:
            self._registrar_intento_vivo("sm_levelup_announcement_cache_error", error=str(exc))
            return
        targets: list[tuple[tuple, dict[object, int]]] = []
        for personal_id in roles_by_personal_id:
            vanilla_entries = (self._sm_levelup_moves_vanilla_entries or {}).get(personal_id)
            patched_entries = entries_by_species_patched.get(personal_id)
            if not vanilla_entries or not patched_entries:
                continue
            move_ids_by_key = {key: int(move_id) for move_id, _level, key in patched_entries}
            targets.append((vanilla_entries, move_ids_by_key))
        if not targets:
            return
        witnesses = [pokemon for pokemon in game.party if int(getattr(pokemon, "species_id", 0)) > 0][:3]
        if not witnesses:
            return
        reader = self.sm_live_reader

        def worker() -> None:
            try:
                from types import SimpleNamespace

                from .azahar_rpc import AzaharRPCClient
                from .sm_live import SM_TITLE_IDS
                from .win_process_memory import WindowsProcessMemory
                from .usum_levelup_announcement_cache import patch_species_announcement_cache

                with AzaharRPCClient() as client:
                    sm_processes = [
                        process for process in client.process_list()
                        if int(process.title_id) in SM_TITLE_IDS
                    ]
                    if len(sm_processes) != 1:
                        return
                    client.set_process(sm_processes[0].process_id)
                    located = reader._scan_reference_window(client, SimpleNamespace(party=witnesses))
                    if located is None:
                        return
                    party_base, _party = located

                    wpm = WindowsProcessMemory()
                    windows_processes = wpm.list_azahar_processes()
                    if not windows_processes:
                        return
                    # Puede haber más de un proceso "azahar.exe" (procesos
                    # auxiliares del propio emulador, no instancias
                    # distintas — mismo hallazgo que USUM el 2026-09-04) —
                    # se prueba cada uno; el que no tenga la región FCRAM en
                    # cuestión simplemente no encuentra nada.
                    total_patched = 0
                    for windows_process in windows_processes:
                        handle = wpm.open_process(windows_process.pid)
                        try:
                            for vanilla_entries, move_ids_by_key in targets:
                                total_patched += patch_species_announcement_cache(
                                    client, wpm, handle,
                                    party_base=party_base,
                                    entries=vanilla_entries,
                                    move_ids_by_key=move_ids_by_key,
                                )
                        finally:
                            wpm.close_process(handle)
                    if total_patched:
                        self._registrar_intento_vivo(
                            "sm_levelup_announcement_cache_parcheado",
                            especies=len(targets), copias=total_patched,
                        )
            except Exception as exc:
                self._registrar_intento_vivo("sm_levelup_announcement_cache_error", error=str(exc))
            finally:
                self._sm_levelup_announcement_cache_running = False

        self._sm_levelup_announcement_cache_running = True
        threading.Thread(target=worker, daemon=True, name="RoleRunSmAnnouncementCache").start()

    def _sm_levelup_usable_move_ids(self) -> set[int] | None:
        return (
            set(int(move_id) for move_id in self.engine.allowed_move_ids)
            if self.engine.allowed_move_ids is not None
            else None
        )

    def _sm_levelup_personal_id_for(self, species_id: int, form: int) -> int | None:
        """``form`` cae a la base si la forma exacta no existe en el mapa.

        Mismo fallback que ``_usum_levelup_personal_id_for``: un Pokémon del
        equipo/PC nunca puede estar realmente en una forma de combate fuera
        de un combate, así que su aprendizaje por nivel es siempre el de la
        forma base independientemente del byte de forma leído en vivo.
        """
        if self._sm_levelup_personal_id_map is None:
            return None
        species_id = int(species_id)
        personal_id = self._sm_levelup_personal_id_map.get((species_id, int(form)))
        if personal_id is not None:
            return personal_id
        return self._sm_levelup_personal_id_map.get((species_id, 0))

    def _append_sm_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool, personal_id: int | None = None,
    ) -> bool:
        """Calcula la sustitución de ``entries`` para ``role`` y las añade.

        Mirror exacto de ``_append_usum_levelup_history_entries`` —
        ``personal_id`` (si se pasa) es la semilla determinista de
        ``compute_species_patch`` y DEBE coincidir con la que usan
        ``_sync_sm_levelup_moves_mod``/``_sync_sm_levelup_moves_backup`` para
        la MISMA entrada.
        """
        if not entries:
            return False
        # 06-09-2026: se calcula sobre la tabla COMPLETA de la especie, no
        # sobre el subconjunto recién cruzado. `compute_species_patch` excluye
        # los movimientos que la especie ya tiene, así que un subconjunto da
        # otro conjunto de exclusiones y elige OTRO sustituto: el historial
        # acababa registrando un movimiento distinto del que el juego enseña
        # de verdad (bug reportado en quinta; medido: 13 de 14 entradas de
        # Patrat discrepaban). Mismo cálculo que el parche, por construcción.
        completa = (self._sm_levelup_moves_vanilla_entries or {}).get(int(personal_id if personal_id is not None else species_id)) or entries
        patch = sm_levelup_moves_mod.compute_species_patch(
            completa, role, species_id=personal_id if personal_id is not None else species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._sm_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_sm_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Igual que ``_purge_usum_levelup_history_above_level``."""
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    @perf.timed("ui.record_sm_levelup_move_history")
    def _record_sm_levelup_move_history(self, game: SaveGameData) -> None:
        """Recuerda-movimientos para SM. Mirror exacto de
        ``_record_usum_levelup_move_history``: registra en el instante del
        cruce de nivel, sin esperar a que el juego confirme el aprendizaje,
        buscando la tabla vainilla por ``personal_id`` traducido de
        ``(species_id, form)``.
        """
        if (
            getattr(self.save_engine, "key", "") != "sm"
            or self.project is None
            or self._sm_levelup_moves_vanilla_entries is None
            or self._sm_levelup_personal_id_map is None
        ):
            return
        try:
            changed = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._sm_levelup_history_last_levels.get(identity)
                self._sm_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                form = int(getattr(pokemon, "form", 0) or 0)
                personal_id = self._sm_levelup_personal_id_for(species_id, form)
                entries = (
                    self._sm_levelup_moves_vanilla_entries.get(personal_id)
                    if personal_id is not None else None
                )
                if level > 0 and self._purge_sm_levelup_history_above_level(identity, level):
                    changed = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_sm_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True, personal_id=personal_id,
                        ):
                            changed = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                role, _symbol = self._effective_role(pokemon)
                if self._append_sm_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                    personal_id=personal_id,
                ):
                    changed = True
            if changed:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("sm_levelup_history_error", error=str(exc))

    def _revert_sm_levelup_moves_mod(self) -> None:
        """Devuelve el mod de aprendizajes por nivel de SM a la tabla vainilla.

        Igual que ``_revert_usum_levelup_moves_mod`` — se llama al cerrar
        RoleRun.
        """
        if (
            self._sm_levelup_moves_vanilla is None
            or self._sm_levelup_moves_title_id is None
            or self._sm_levelup_moves_azahar_root is None
        ):
            return
        try:
            sm_levelup_moves_mod.write_blob(
                self._sm_levelup_moves_azahar_root,
                self._sm_levelup_moves_title_id,
                self._sm_levelup_moves_vanilla,
                expected_size=len(self._sm_levelup_moves_vanilla),
            )
        except Exception:
            return

    def _append_usum_levelup_history_entries(
        self, identity: str, pokemon: SavePokemon, species_id: int,
        entries: tuple, role: str, *, pre_capture: bool, personal_id: int | None = None,
    ) -> bool:
        """Calcula la sustitución de ``entries`` para ``role`` y las añade.

        Igual que ``_append_oras_levelup_history_entries``: no duplica una
        (nivel, movimiento) ya registrada para esa identidad.

        ``personal_id`` (si se pasa) es la semilla determinista de
        ``compute_species_patch`` — DEBE coincidir con la que usa
        ``_sync_usum_levelup_moves_mod`` (Enfoque A, vía
        ``build_party_patched_blob``) y ``_sync_usum_levelup_moves_backup``
        (Enfoque B) para la MISMA entrada, o el historial podía mostrar un
        sustituto distinto al que de verdad se escribe (bug real,
        2026-09-04: antes se sembraba con ``species_id`` real, que solo
        coincide con ``personal_id`` para especies sin formas). Si no se
        pasa, cae a ``species_id`` (compatibilidad con especies sin forma).
        """
        if not entries:
            return False
        # 06-09-2026: se calcula sobre la tabla COMPLETA de la especie, no
        # sobre el subconjunto recién cruzado. `compute_species_patch` excluye
        # los movimientos que la especie ya tiene, así que un subconjunto da
        # otro conjunto de exclusiones y elige OTRO sustituto: el historial
        # acababa registrando un movimiento distinto del que el juego enseña
        # de verdad (bug reportado en quinta; medido: 13 de 14 entradas de
        # Patrat discrepaban). Mismo cálculo que el parche, por construcción.
        completa = (self._usum_levelup_moves_vanilla_entries or {}).get(int(personal_id if personal_id is not None else species_id)) or entries
        patch = usum_levelup_moves_mod.compute_species_patch(
            completa, role, species_id=personal_id if personal_id is not None else species_id,
            pools=self.engine.pools, damage_classes=self.engine.damage_classes,
            speed_status_moves=self.engine.speed_status_moves,
            self_healing_damage_moves=self.engine.self_healing_damage_moves,
            usable_move_ids=self._usum_levelup_usable_move_ids(),
        )
        history = self.project.oras_levelup_move_history.setdefault(identity, [])
        seen = {(int(item.get("level", -1)), int(item.get("move_id", -1))) for item in history}
        changed = False
        for vanilla_move_id, entry_level, offset in entries:
            actual_move_id = int(patch.get(offset, vanilla_move_id))
            key = (int(entry_level), actual_move_id)
            if key in seen:
                continue
            history.append({
                "level": int(entry_level),
                "move_id": actual_move_id,
                "role": str(role),
                "species_id": species_id,
                "nickname": str(pokemon.nickname or pokemon.species),
                "recorded_at": datetime.now().isoformat(timespec="seconds"),
                "pre_capture": bool(pre_capture),
            })
            seen.add(key)
            changed = True
        return changed

    def _purge_usum_levelup_history_above_level(self, identity: str, level: int) -> bool:
        """Igual que ``_purge_oras_levelup_history_above_level``."""
        history = self.project.oras_levelup_move_history.get(identity)
        if not history:
            return False
        kept = [item for item in history if int(item.get("level", 0)) <= level]
        if len(kept) == len(history):
            return False
        if kept:
            self.project.oras_levelup_move_history[identity] = kept
        else:
            del self.project.oras_levelup_move_history[identity]
        return True

    @perf.timed("ui.record_usum_levelup_move_history")
    def _record_usum_levelup_move_history(self, game: SaveGameData) -> None:
        """Recuerda-movimientos para USUM. Igual que
        ``_record_oras_levelup_move_history``: registra en el instante del
        cruce de nivel, sin esperar a que el juego confirme el aprendizaje.
        Solo cambia cómo se busca la tabla vainilla: por ``personal_id``
        traducido de ``(species_id, form)``, no por species_id directo.
        """
        if (
            getattr(self.save_engine, "key", "") != "usum"
            or self.project is None
            or self._usum_levelup_moves_vanilla_entries is None
            or self._usum_levelup_personal_id_map is None
        ):
            return
        try:
            changed = False
            for pokemon in game.party:
                identity = f"{int(pokemon.pid or 0)}:{int(pokemon.tid or 0)}:{int(pokemon.sid or 0)}"
                level = int(pokemon.level or 0)
                previous = self._usum_levelup_history_last_levels.get(identity)
                self._usum_levelup_history_last_levels[identity] = level
                species_id = int(pokemon.species_id)
                form = int(getattr(pokemon, "form", 0) or 0)
                personal_id = self._usum_levelup_personal_id_for(species_id, form)
                entries = (
                    self._usum_levelup_moves_vanilla_entries.get(personal_id)
                    if personal_id is not None else None
                )
                if level > 0 and self._purge_usum_levelup_history_above_level(identity, level):
                    changed = True
                if previous is None:
                    if identity not in self.project.oras_levelup_move_history and entries:
                        pre_capture = tuple(entry for entry in entries if entry[1] <= level)
                        if self._append_usum_levelup_history_entries(
                            identity, pokemon, species_id, pre_capture, "SIN ROL",
                            pre_capture=True, personal_id=personal_id,
                        ):
                            changed = True
                    continue
                if level <= previous or level <= 0 or not entries:
                    continue
                crossed = tuple(entry for entry in entries if previous < entry[1] <= level)
                if not crossed:
                    continue
                role, _symbol = self._effective_role(pokemon)
                if self._append_usum_levelup_history_entries(
                    identity, pokemon, species_id, crossed, role, pre_capture=False,
                    personal_id=personal_id,
                ):
                    changed = True
            if changed:
                self.project_service.save(self.project)
        except Exception as exc:
            self._registrar_intento_vivo("usum_levelup_history_error", error=str(exc))

    def _revert_usum_levelup_moves_mod(self) -> None:
        """Devuelve el mod de aprendizajes por nivel de USUM a la tabla vainilla.

        Igual que ``_revert_oras_levelup_moves_mod`` — se llama al cerrar
        RoleRun.
        """
        if (
            self._usum_levelup_moves_vanilla is None
            or self._usum_levelup_moves_title_id is None
            or self._usum_levelup_moves_azahar_root is None
        ):
            return
        try:
            usum_levelup_moves_mod.write_blob(
                self._usum_levelup_moves_azahar_root,
                self._usum_levelup_moves_title_id,
                self._usum_levelup_moves_vanilla,
                expected_size=len(self._usum_levelup_moves_vanilla),
            )
        except Exception:
            return

    def _load_oras_rom_tm_source(
        self, source: ORASRomSource | Path, *, show_error: bool = False,
    ) -> ORASTMProfile | None:
        """Lee las tablas reales de una fuente ORAS ya localizada.

        Este método se mantiene deliberadamente separado del selector: la
        detección automática desde Azahar y la elección manual recorren la
        misma ruta de validación nativa.
        """
        if isinstance(source, ORASRomSource):
            path = source.path
            azahar_root = source.azahar_root
        else:
            path = Path(source).expanduser().resolve()
            azahar_root = None
        process_name = self._oras_live_process_name if self._oras_live_active else None
        if (
            self._oras_rom_tm_profile is not None
            and self._oras_rom_tm_profile_source == path
            and self._oras_rom_tm_profile_process == process_name
        ):
            return self._oras_rom_tm_profile
        try:
            with perf.span("ui.load_oras_rom_tm_source.load_oras_rom_tm_profile"):
                profile = load_oras_rom_tm_profile(
                    path, process_name=process_name, azahar_root=azahar_root,
                )
        except (OSError, ORASRomProfileError, ValueError) as exc:
            self._oras_rom_tm_last_error = str(exc)
            if show_error:
                messagebox.showerror(
                    "No se pudieron leer las MT de ORAS",
                    f"RoleRun no usó ninguna tabla ni escribió datos.\n\n{exc}",
                    parent=self._dialog_parent(),
                )
            return None
        self._oras_rom_tm_last_error = None
        return self._remember_oras_rom_tm_profile(profile, process_name, azahar_root)

    def _select_oras_rom_tm_profile(self) -> ORASTMProfile | None:
        """Permite elegir la ROM activa solo si Azahar no pudo delatarla."""
        messagebox.showinfo(
            "Seleccionar ROM de ORAS",
            "RoleRun no necesita el log del randomizer. Selecciona el .cxi, .3ds o .app que estás jugando "
            "solo si Azahar no se pudo detectar automáticamente.\n\n"
            "Se leerá la tabla real de 100 MT desde la ROM. La compatibilidad de especie no limita RoleRun; la limita el rol. "
            "No se modificará ningún archivo.",
            parent=self._dialog_parent(),
        )
        selected = filedialog.askopenfilename(
            title="Selecciona la ROM ORAS que está abierta en Azahar",
            filetypes=[
                ("ROM de Nintendo 3DS", "*.cxi *.3ds *.app"),
                ("Todos los archivos", "*"),
            ],
        )
        if not selected:
            return None
        return self._load_oras_rom_tm_source(Path(selected), show_error=True)

    def _get_oras_rom_tm_profile(self, prompt: bool = False) -> ORASTMProfile | None:
        """Busca la ROM activa y después la que quedó preparada para ORAS."""
        if getattr(self.save_engine, "key", "") != "oras":
            return None

        # El log de Azahar registra la última ROM que arrancó. La aceptamos
        # únicamente si su NCCH coincide con el proceso RPC que F5 ya validó.
        if self._oras_live_active:
            # `discover_azahar_oras_source` abre y lee entera cada ROM candidata
            # (hasta el ExeFS .code completo, para verificar su NCCH) para saber
            # cuál está abierta - medido el 2026-09-03 en ~4.8 s por llamada. Antes
            # se repetía esa lectura completa en cada acción de Equipo/PC de la
            # sesión (recuerda-movimientos y el aprendizaje por rol necesitan este
            # perfil con mucha más frecuencia que antes), aunque Azahar siguiera
            # con el mismo proceso y la misma ROM abiertos. Mientras el proceso RPC
            # no cambie, la fuente descubierta la última vez sigue siendo válida.
            cached_source = getattr(self, "_oras_discovered_rom_source", None)
            cached_process = getattr(self, "_oras_discovered_rom_source_process", None)
            if (
                cached_source is not None
                and cached_process == self._oras_live_process_name
                and cached_source.path.is_file()
            ):
                source = cached_source
            else:
                with perf.span("ui.get_oras_rom_tm_profile.discover_azahar_oras_source"):
                    source = discover_azahar_oras_source(self._oras_live_process_name)
                if source is not None:
                    self._oras_discovered_rom_source = source
                    self._oras_discovered_rom_source_process = self._oras_live_process_name
            if source is not None:
                with perf.span("ui.get_oras_rom_tm_profile.load_oras_rom_tm_source"):
                    profile = self._load_oras_rom_tm_source(source, show_error=False)
                if profile is not None:
                    return profile

        # La pantalla inicial permite asociar una ROM a ORAS una sola vez. Es
        # la ruta preferida si Azahar no expuso su último archivo en el log,
        # por lo que al abrir una MT no se vuelve a preguntar por el .cxi.
        configured_game = self.game_source_profiles.get("oras")
        # Si el usuario acaba de dejar preparada otra Run, esa ROM no se mezcla
        # con la Run actual antes de volver al selector inicial y abrirla.
        if configured_game.game_path and not configured_game.start_new_run:
            path = Path(configured_game.game_path).expanduser()
            if path.is_file():
                profile = self._load_oras_rom_tm_source(path, show_error=False)
                if profile is not None:
                    return profile

        configured = str(getattr(self.project, "oras_tm_rom_path", "") or "").strip()
        if configured:
            path = Path(configured).expanduser()
            if path.is_file():
                profile = self._load_oras_rom_tm_source(path, show_error=False)
                if profile is not None:
                    return profile
            elif prompt:
                messagebox.showwarning(
                    "No se encuentra la ROM recordada",
                    "La ROM asociada a esta Run se movió o eliminó. Puedes elegirla de nuevo; no se usará una tabla genérica.",
                    parent=self._dialog_parent(),
                )

        if prompt:
            return self._select_oras_rom_tm_profile()
        return None

